insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 1, "Según el artículo 137 de la Constitución Española, el Estado se organiza territorialmente:", "En municipios, en provincias y en las comunidades autónomas que se constituyan.", "En municipios, en comarcas, en provincias y en las comunidades autónomas que se constituyan.", "En Áreas metropolitanas, en municipios, en provincias y en las comunidades autónomas que se constituyan.", "En municipios, en islas, en provincias y en las comunidades autónomas que se constituyan."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 2, "El artículo 140 de la Constitución Española garantiza:", "La autonomía de la provincia.", "La autonomía de los municipios.", "La suficiencia de recursos para las entidades locales.", "El derecho a crear agrupaciones de municipios diferentes de la provincia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 3, "¿Qué artículo de la Constitución Española regula el municipio?", "El artículo 137.", "El artículo 138.", "El artículo 139.", "El artículo 140."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 4, "¿Qué artículo de la Constitución Española consagra el principio de suficiencia financiera de las haciendas locales?", "El artículo 140.", "El artículo 142.", "El artículo 156.", "El artículo 158."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 5, "Según el artículo 141 de la Constitución Española, cualquier alteración de los límites provinciales se tiene que aprobar mediante:", "Un Real decreto.", "Una ley de la asamblea legislativa autonómica correspondiente.", "Una Ley Orgánica.", "Un decreto del consejo de gobierno autonómico correspondiente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 6, "De acuerdo con la Constitución Española, la financiación de las haciendas locales tiene que provenir fundamentalmente:", "De los presupuestos generales del Estado.", "De las subvenciones de la Unión Europea, del Estado y de las comunidades autónomas.", "Del importe de las sanciones que impongan.", "De los tributos propios y de la participación en los tributos del Estado y de las comunidades autónomas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 7, "¿Prevé la Constitución Española la forma de administración propia de las islas?", "Sí, prevé que, en los archipiélagos, las islas tendrán además su administración propia en forma de cabildos.", "No, prevé que la forma de administración propia de las islas la determinará, en su caso, una ley orgánica.", "Sí, prevé que, en los archipiélagos, las islas tendrán además su administración propia en forma de consejos.", "Sí, prevé que, en los archipiélagos, las islas tendrán además su administración propia en forma de cabildos o consejos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 8, "De acuerdo con el artículo 141 de la Constitución Española, la provincia es una entidad local con personalidad jurídica propia, determinada por la agrupación de:", "Municipios.", "Comarcas.", "Áreas metropolitanas.", "Mancomunidades de municipios."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 9, "¿Dónde se ubica la regulación de la Administración local en la Constitución Española?", "En el capítulo III del Título VIII.", "En el Título VII.", "En el capítulo II del Título VIII.", "En el capítulo II del Título III."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 10, "¿Qué norma aprueba el Texto refundido de las disposiciones legales vigentes en materia de régimen local?", "La Ley 7/1985, de 2 de abril.", "El Real decreto legislativo 2/2004, de 5 de marzo", "El Real decreto legislativo 781/1986, de 18 de abril.", "La Ley 20/2006, de 15 de diciembre."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 11, "El artículo 140 de la Constitución Española dispone que los alcaldes se tienen que elegir:", "Por consenso entre los concejales y los vecinos.", "Por los concejales.", "Directamente para los vecinos mediante sufragio universal, igual, libre, directo y secreto.", "Por los concejales o por los vecinos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 12, "¿Cuál es la norma reguladora de las bases del régimen local?", "La Ley 7/1985, de 2 de abril.", "El Real decreto legislativo 2/2004, de 5 de marzo.", "La Ley 20/2006, de 15 de diciembre.", "El Real decreto ley 7/1985, de 2 de abril."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 13, "¿Cuál de las normas siguientes aprueba el Texto refundido de la Ley reguladora de las haciendas locales?", "El Real decreto legislativo 2/2004, de 5 de marzo", "El Real decreto ley 2/2004, de 5 de marzo.", "El Decreto ley 2/2004, de 5 de marzo.", "La Ley 7/1985, de 2 de abril."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 14, "Las entidades locales territoriales quedan exentas de los impuestos del Estado y de las comunidades autónomas:", "En todo caso.", "En los términos que establezca el reglamento del impuesto correspondiente.", "Sólo quedan exentas de los impuestos del Estado.", "En los términos que establezca la ley."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 15, "Las competencias de las entidades locales pueden ser:", "Sólo propias.", "Sólo atribuidas por delegación.", "Propias o atribuidas por delegación.", "Las entidades locales carecen de competencias."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 16, "¿Pueden las entidades locales ejercer competencias distintas de las propias y de las atribuidas por delegación?", "Sí, en cualquier caso.", "Sólo cuando<A[cuando|cuándo]> no se ponga en riesgo la sostenibilidad financiera del conjunto de la Hacienda municipal, de acuerdo con los requerimientos de la legislación de estabilidad presupuestaria y sostenibilidad financiera y no se incurra en un supuesto de ejecución simultánea del mismo servicio público con otra Administración", "No, en ningún caso, dado que se pone en riesgo la sostenibilidad financiera del conjunto de la Hacienda municipal.", "Sólo cuándo así lo decida, por motivos de oportunidad, el órgano o entidad delegante y lo acepte la entidad local interesada."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 17, "¿Qué norma lleva a cabo el desarrollo legislativo en materia de régimen local en la Comunidad Autónoma de las Illes Balears?", "La Ley 3/2003, de 26 de marzo, de régimen jurídico de la Administración de la Comunidad Autónoma de las Islas Baleares.", "La Ley 7/2010, de 21 de julio, del sector público instrumental de la Comunidad Autónoma de las Islas Baleares.", "La Ley 20/2006, de 15 de diciembre, municipal y de régimen local de las Islas Baleares.", "La Ley 4/2022, de 28 de junio, de consejos insulares."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 18, "De acuerdo con el Estatuto de autonomía de las Illes Balears, además de las competencias derivadas de la legislación básica del Estado y de la legislación sectorial, corresponde a los municipios:", "El ejercicio de las competencias que puedan ser delegadas por el Estado, por la Comunidad Autónoma, por los consejos insulares y por otras administraciones, siempre que vayan acompañadas de los medios económicos, personal y materiales adecuados y suficientes.", "El ejercicio de las competencias que el Pleno del ayuntamiento considere oportunas.", "El ejercicio de las competencias que, a pesar de sean competencia de otras administraciones, afecten directamente a los intereses del municipio.", "El ejercicio de las competencias que puedan ser delegadas por el Estado, para<A[para|por]> la Comunidad Autónoma, para<A[para|por]> los consejos insulares y para<A[para|por]> otras administraciones, con independencia de la suficiencia y adecuación de los medios económicos, personal y materiales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 19, "Según la Carta Europea de Autonomía Local, se entiende por autonomía local:", "El derecho y la capacidad efectiva de las entidades locales de dictar normas con rango de ley.", "El derecho y la capacidad efectiva de las entidades locales de ordenar y gestionar una parte importante de los asuntos públicos en el marco de la ley, bajo su propia responsabilidad y en beneficio de sus habitantes.", "El derecho y la capacidad efectiva de las entidades locales para convocar referéndums.", "El derecho y la capacidad efectiva de las entidades locales para la autodeterminación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 20, "¿Qué precepto de la Constitución Española garantiza la autonomía de los municipios?", "El artículo 141.", "El artículo 139.", "El artículo 142.", "El artículo 140."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 21, "¿Qué precepto de la Constitución Española consagra la autonomía de los municipios y de las provincias?", "El artículo 141.", "El artículo 137.", "El artículo 142.", "El artículo 140."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 22, "El artículo 137 de la Constitución Española se refiere a:", "La autonomía de los entes territoriales para la gestión de los intereses respectivos.", "La autonomía financiera de las entidades locales.", "El derecho a la autodeterminación.", "La garantía de la realización efectiva del principio de solidaridad."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 23, "¿A qué órgano corresponde resolver los conflictos en defensa de la autonomía local?", "A los juzgados y tribunales de la jurisdicción contenciosa administrativa.", "Al Tribunal Constitucional.", "A la Comisión Bilateral de Cooperación entre la Administración General del Estado y la respectiva entidad local.", "Al Consejo de Ministros."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 24, "¿Quién puede plantear un conflicto en defensa de la autonomía local?", "El Estado.", "Las comunidades autónomas.", "Los municipios, las provincias y las comunidades autónomas.", "Los municipios y las provincias."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 25, "Pueden dar lugar al planteamiento de los conflictos en defensa de la autonomía local:", "Los actos administrativos y las normas reglamentarias del Estado o de las comunidades autónomas que lesionen la autonomía local constitucionalmente garantizada.", "Las normas reglamentarias del Estado o de las comunidades autónomas que lesionen la autonomía local constitucionalmente garantizada.", "Las normas del Estado con rango de ley o las disposiciones con rango de ley de las comunidades autónomas que lesionen la autonomía local constitucionalmente garantizada.", "Los actos administrativos del Estado o de las comunidades autónomas que lesionen la autonomía local constitucionalmente garantizada."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 26, "¿La autonomía local reconocida por la Constitución Española, implica potestad legislativa?", "Si, en todo caso.", "Sólo en determinadas materias.", "Sólo en virtud de una delegación.", "No, en ningún caso."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 27, "¿Qué norma autonómica garantiza a los municipios y a las otras entidades locales que puedan existir en las Illes Balears la plena autonomía para la gestión de sus respectivos intereses, así como para el ejercicio de sus competencias?", "El artículo 3 del Estatuto de Autonomía de las Illes Balears.", "El artículo 3 de la Ley 20/2006, de 15 de diciembre, municipal y de régimen local de las Islas Baleares.", "El artículo 3 de la Ley 3/2003, de 26 de marzo, de régimen jurídico de la Administración de la Comunidad Autónoma de las Illes Balears.", "El artículo 3 de la Ley 7/2010, de 21 de julio, del sector público instrumental de la Comunidad Autónoma de las Illes Balears."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 28, "La autonomía de los municipios:", "Está garantizada por el Gobierno del Estado.", "No existe.", "Está garantizada por la Constitución Española.", "Está garantizada por el Estado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 29, "¿Qué artículo de la Constitución Española garantiza la autonomía financiera de los entes locales?", "El artículo 142.", "El artículo 140.", "El artículo 1.", "El artículo 141."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 30, "La autonomía financiera de los entes locales implica:", "Disponer de tributos propios y participar en los tributos en los del Estado y en los de las comunidades autónomas.", "Disponer de tributos propios.", "Participar en los tribunales del Estado.", "Participar en los tributos de las comunidades autónomas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 31, "¿Según el instrumento de Ratificación, por<A[por|para]> qué precepto de la Carta Europea de la Autonomía Local no se considera vinculado el Reino de España?", "Por el artículo 1.", "Por el apartado 2 del artículo 4.", "Por el apartado 2 del artículo 3.", "Por el apartado 3 del artículo 7."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 32, "El Estado español firmó la Carta Europea de la Autonomía Local el año:", "1978.", "1986.", "1989.", "1985."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 33, "Según la doctrina del Tribunal Constitucional, el concepto de autonomía local hace referencia a:", "Un poder ilimitado.", "Un poder limitado.", "La soberanía.", "La autodeterminación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 34, "Según la doctrina del Tribunal Constitucional, la autonomía local constitucionalmente reconocida no permite:", "La existencia de un control de legalidad sobre el ejercicio de las competencias de las entidades locales.", "La configuración del régimen competencial de las entidades locales por<A[por|para]> la legislación estatal y autonómica.", "La existencia de una dependencia jerárquica de las entidades locales a otras entidades territoriales de ámbito superior.", "La protección de la autonomía local ante el Tribunal Constitucional."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 35, "¿Puede el Consejo de Ministros disolver los órganos de las corporaciones locales?", "No, eso es contrario al principio de autonomía local.", "Sí, mediante un real decreto, a iniciativa propia y con conocimiento del consejo de gobierno de la comunidad autónoma correspondiente o a solicitud de este y, en todo caso, previo acuerdo favorable del Senado, en el supuesto de gestión gravemente dañina para los intereses generales que suponga incumplimiento de las obligaciones constitucionales.", "Sí, mediante un real decreto ley, a iniciativa propia y con conocimiento del consejo de gobierno de la comunidad autónoma correspondiente o a solicitud de este, en el supuesto de gestión gravemente dañina para los intereses generales que suponga incumplimiento de las obligaciones constitucionales.", "Sí, mediante un real decreto, a iniciativa propia y con conocimiento del consejo de gobierno de la comunidad autónoma correspondiente o a solicitud de este y, en todo caso, previo acuerdo favorable del Senado, por razones de oportunidad."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 36, "En los conflictos en defensa de la autonomía local regulados a la Ley orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional:", "La sentencia se limitará, según proceda<A[pegue|ocurra]>, a anular la disposición legislativa objeto del conflicto o a declarar la vigencia de esta..", "La sentencia se limitará a declarar si existe o no vulneración de la autonomía local constitucionalmente garantizada.", "La sentencia se limitará a determinar la titularidad o atribución de la competencia controvertida.", "La sentencia declarará si existe o no vulneración de la autonomía local constitucionalmente garantizada, determinando, según proceda<A[pegue|ocurra]>, la titularidad o atribución de la competencia controvertida, y resolverá, en su caso<A[pega|ocurre]>, lo que sea procedente sobre las situaciones de hecho o de derecho creadas en lesión de la autonomía local."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 37, "Son entidades locales territoriales:", "El municipio y la provincia.", "El ayuntamiento y la diputación provincial.", "El municipio, la provincia y la isla en los archipiélagos balear y canario.", "El municipio, la comarca, la provincia y la isla en los archipiélagos balear y canario."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 38, "De acuerdo con el artículo 2 de la Ley 20/2006, de 15 de diciembre, municipal y de régimen local de las Illes Balears, también tienen la condición de entes locales:", "Las aldeas, las mancomunidades de municipios, las entidades locales menores, las áreas metropolitanas y los consorcios locales constituidos por entes locales entre sí o con otras administraciones públicas que tengan por objeto esencial la prestación de servicios y de obras que sean competencia de los entes locales.", "Las entidades locales menores, las áreas metropolitanas y los consorcios locales constituidos por entes locales entre sí o con otras administraciones públicas que tengan por objeto esencial la prestación de servicios y de obras que sean competencia de los entes locales.", "Las mancomunidades de municipios, las áreas metropolitanas y los consorcios locales constituidos por entes locales entre sí o con otras administraciones públicas que tengan por objeto esencial la prestación de servicios y de obras que sean competencia de los entes locales.", "Las mancomunidades de municipios, las entidades locales menores, las áreas metropolitanas y los consorcios locales constituidos por entes locales entre sí o con otras administraciones públicas que tengan por objeto esencial la prestación de servicios y de obras que sean competencia de los entes locales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 39, "De acuerdo con el artículo 3 de la Ley 7/1985, de 2 de abril, reguladora de las bases del régimen local, no se considera ente local territorial:", "La isla en los archipiélagos balear y canario.", "El municipio.", "Las mancomunidades de municipios.", "La provincia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 40, "¿Cuál de las siguientes afirmaciones es la correcta?", "La provincia es una entidad local, determinada por la agrupación de municipios y la división territorial para el cumplimiento<A[cumplimiento|cumplido]> de las actividades de los vecinos.", "La provincia es una entidad local, determinada por la agrupación de municipios y la división territorial para el cumplimiento<A[cumplimiento|cumplido]> de las actividades del Estado.", "La provincia es una entidad local, determinada por la agrupación de municipios y la división territorial para el cumplimiento<A[cumplimiento|cumplido]> de las actividades del Gobierno.", "La provincia es una entidad local, determinada por la agrupación de municipios y la división territorial para el cumplimiento<A[cumplimiento|cumplido]> de las actividades de la Comunidad Autónoma."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 41, "¿Según la Ley 20/2006, de 15 de diciembre, municipal y de régimen local de las Illes Balears, los entes locales menores están dotados de todas las potestades a que se refiere la legislación básica de régimen local para los municipios?", "Si.", "No.", "Sí, excepto la potestad de expropiación.", "Sí, excepto la potestad de expropiación y la de aprobación de planes<A[planes|planos]> de urbanismo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 42, "De acuerdo con la Ley 7/1985, de 2 de abril, reguladora de las bases del régimen local, las comarcas:", "Son entidades locales territoriales.", "Son entidades locales que agrupan varios municipios, que pueden ser creadas por las comunidades autónomas en su territorio, de acuerdo con lo que dispongan los respectivos estatutos de autonomía.", "Son entidades locales que agrupan varios municipios, que pueden ser creadas por las provincias o las islas en su territorio, de acuerdo con lo que dispongan los respectivos estatutos de autonomía.", "No son entidades locales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 43, "¿Cuál de las afirmaciones siguientes es la correcta?", "El municipio es la entidad local básica de la organización territorial del Estado.", "La provincia es la entidad local básica de la organización territorial del Estado.", "La comarca es la entidad local básica de la organización territorial del Estado.", "El área metropolitana es la entidad local básica de la organización territorial del Estado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 44, "Las mancomunidades de municipios:", "No tienen personalidad jurídica independiente de la de los municipios que la forman", "Tienen personalidad y capacidad jurídicas para el cumplimiento<A[cumplimiento|cumplido]> de sus fines específicos y se rigen por sus Estatutos.", "Tienen personalidad jurídica, pero no capacidad jurídica.", "Sólo tienen capacidad jurídica."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 45, "¿Se pueden crear agrupaciones de municipios diferentes de la provincia?", "Sí, con autorización previa del Senado.", "Sí.", "No, en ningún caso.", "Sólo a iniciativa del Consejo de Ministros."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 46, "De acuerdo con la Ley 20/2006, de 15 de diciembre, municipal y de régimen local de las Illes Balears:", "La creación de entidades locales menores es subsidiaria respecto de las áreas metropolitanas, de los entes autónomos locales, y de los distritos y delegaciones territoriales.", "No es posible, en ningún caso, la creación de entidades locales menores.", "La creación de entidades locales menores se tiene que llevar a cabo a iniciativa de los consejos insulares.", "La creación de entidades locales menores se tiene que llevar a cabo a iniciativa del Gobierno de las Islas Baleares."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 47, "¿Qué son las áreas metropolitanas?", "Son entidades locales territoriales.", "Son entidades locales integradas por<A[para|por]> las mancomunidades de municipios de grandes aglomeraciones urbanas entre cuyos núcleos de población haya vinculaciones económicas y sociales que hagan necesaria la planificación conjunta y la coordinación de determinados servicios y obras.", "Son entidades locales integradas por los municipios de grandes aglomeraciones urbanas entre cuyos núcleos de población haya vinculaciones económicas y sociales que hagan necesaria la planificación conjunta y la coordinación de determinados servicios y obras.", "Son entidades locales integradas por los municipios, cuyas características determinen intereses comunes necesarios de una gestión propia o pidan la prestación de servicios de dicho ámbito."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 48, "De acuerdo con el artículo 54 de la Ley 20/2006, de 15 de diciembre, municipal y de régimen local de las Illes Balears, las entidades locales menores tienen competencia, en coordinación con el municipio, sobre las materias siguientes:", "La administración y la conservación de su patrimonio y la regulación y la ordenación de su aprovechamiento y de su utilización.", "Gestión del padrón municipal de habitantes", "Policía local.", "Normalización lingüística."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 49, "¿Pueden integrarse en la misma mancomunidad municipios pertenecientes a diferentes comunidades autónomas?", "Sí, en todo caso.", "Sí, siempre que lo permitan las normativas de las comunidades autónomas afectadas.", "No, en ningún caso.", "Si, con autorización previa del Senado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 50, "La Ley 20/2006, de 15 de diciembre, municipal y de régimen local de las Illes Balears:", "Regula las comarcas en el artículo 51.", "Prevé su creación a iniciativa de los municipios interesados.", "Prevé su creación a iniciativa de los consejos insulares.", "No regula las comarcas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 51, "De acuerdo con el artículo 3.2 de la Ley 7/1985, de 2 de abril, reguladora de las bases del régimen local, disfrutan, asimismo, de la condición de entidades locales:", "Las mancomunidades de municipios.", "Las entidades públicas empresariales locales.", "Los organismos autónomos locales.", "Las sociedades mercantiles locales"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 52, "¿Qué entidades pueden crear un área metropolitana?", "Los municipios interesados, con audiencia previa de la Administración del Estado y de las diputaciones provinciales afectadas.", "Las comunidades autónomas, con audiencia previa de la Administración del Estado y de los ayuntamientos y las diputaciones afectados, mediante una ley, de acuerdo con lo que disponen los Estatutos respectivos.", "Las provincias, con audiencia previa de la Administración del Estado y de los ayuntamientos afectados.", "En la comunidad autónoma de las Illes Balears, los consejos insulares con audiencia previa de la Administración del Estado y de los ayuntamientos afectados."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 53, "De acuerdo con la Ley 20/2006, de 15 de diciembre, municipal y de régimen local de las Illes Balears, los entes locales autónomos, los distritos y las delegaciones territoriales:", "Tienen la condición de entidades locales.", "Sin tener la condición de entidades locales, son formas de organización descentralizada o desconcentrada del municipio.", "Sin tener la condición de entidades locales, son formas de organización descentralizada o desconcentrada de la isla.", "Son formas de organización descentralizada o desconcentrada de las mancomunidades de municipios."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 54, "La creación de nuevos municipios sólo podrá realizarse:", "Sobre la base de núcleos de población territorialmente diferenciados, de al menos 50.000 habitantes.", "Sobre la base de núcleos de población territorialmente diferenciados, de al menos 500 habitantes.", "Con independencia el número de habitantes, siempre que los municipios resultantes sean financieramente sostenibles.", "Sobre la base de núcleos de población territorialmente diferenciados, de al menos 5.000 habitantes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 55, "De acuerdo con el artículo 4 de la Ley 7/1985, de 2 de abril, reguladora de las bases del régimen local, no corresponde a los municipios, las provincias y las islas:", "La potestad legislativa.", "La potestad reglamentaria.", "Las potestades tributaria y financiera.", "La potestad de programación o planificación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 56, "¿Según la Ley 7/1985, de 2 de abril, reguladora de las bases del régimen local, cuál es la entidad básica de la organización territorial del Estado?", "La provincia.", "La isla.", "El municipio.", "La comarca."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 57, "¿Qué norma puede determinar las competencias propias de las entidades locales territoriales?", "Sólo una ley orgánica.", "Sólo una ley.", "Sólo un real decreto.", "Sólo un real decreto o un decreto del consejo de gobierno autonómico."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 58, "Corresponden a las mancomunidades de municipios, para la prestación de los servicios o la ejecución de las obras de su competencia:", "Las mismas potestades que corresponden a las entidades locales territoriales.", "Las potestades que determinen sus estatutos y, en defecto de previsión estatutaria, las mismas potestades que corresponden a las entidades locales territoriales.", "Las potestades que determinen sus estatutos y, en defecto de previsión estatutaria, las mismas potestades que corresponden a las entidades locales territoriales, siempre que sean necesarias para el cumplimiento<A[cumplimiento|cumplido]> de su finalidad, y de acuerdo con la legislación aplicable a cada una de dichas potestades, en ambos casos.", "Las potestades que determinen sus estatutos y, en defecto de previsión estatutaria, las potestades tributaria y financiera."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 59, "El ejercicio del control de legalidad de los acuerdos y actos de las entidades locales corresponde:", "A los Tribunales.", "Al Consejo de Ministros.", "Al consejo de gobierno autonómico correspondiente.", "Al Tribunal Constitucional."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 60, "Con carácter general, el gobierno y administración de las entidades locales territoriales corresponde:", "En el municipio, al ayuntamiento, integrado por el alcalde y los concejales; en la provincia, a la diputación u otra corporación de carácter representativo; y en la isla, a los cabildos y consejos insulares.", "En el municipio, a una asamblea integrada por todos los electores existentes en el municipio y por<A[para|por]> el alcalde elegido directamente por ellos; en la provincia, a la diputación u otra corporación de carácter representativo; y en la isla, a los cabildos y consejos insulares.", "En el municipio, al ayuntamiento, integrado por el alcalde y los concejales; en la provincia, sólo a la diputación; y en la isla, a los consejos insulares.", "En el municipio, al ayuntamiento, integrado por el alcalde y los concejales; en la provincia y en la isla, a la diputación u otra corporación de carácter representativo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 61, "Las provincias y las islas pueden realizar la gestión ordinaria de servicios propios de la Administración autonómica:", "En todo caso.", "Sólo cuando así lo decida el consejo de gobierno autonómico correspondiente.", "Sólo cuando así esté previsto en el estatuto de autonomía y en la legislación autonómica correspondiente.", "Sólo de forma subsidiaria, para garantizar el desarrollo de las funciones públicas necesarias."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 62, "De acuerdo con el artículo 4 de la Ley 7/1985 de 2 de abril, reguladora de las bases del régimen local, la potestad reglamentaria se atribuye en todo caso a:", "Municipios, provincias e islas, en su calidad de Administraciones públicas territoriales.", "Municipios, provincias e islas, entidades territoriales de ámbito inferior al municipio, así como también a las mancomunidades.", "Municipios, provincias e islas y demás entidades territoriales de ámbito inferior al municipio, así como también a las comarcas y áreas metropolitanas.", "Municipios, provincias e islas y demás entidades territoriales de ámbito inferior al municipio, comarcas, áreas metropolitanas y mancomunidades."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 63, "Para que las entidades locales puedan ejercer competencias diferentes de las propias y de las atribuidas por delegación son necesarios:", "Los informes facultativos de la Administración competente en razón de materia, en la que se señale la inexistencia de duplicidades, y de la Administración que tenga atribuida la tutela financiera sobre la sostenibilidad financiera de las nuevas competencias.", "Los informes previos y vinculantes del secretario y del interventor de la corporación en que se señale la inexistencia de duplicidades, y de la Administración que tenga atribuida la tutela financiera sobre la sostenibilidad financiera de las nuevas competencias.", "Los informes previos y vinculantes de la Administración competente en razón de materia, en la que se señale la inexistencia de duplicidades, y de la Administración que tenga atribuida la tutela financiera sobre la sostenibilidad financiera de las nuevas competencias.", "Los informes previos y vinculantes del interventor de la corporación y de la Administración que tenga atribuida la tutela financiera sobre la sostenibilidad financiera de las nuevas competencias."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 64, "De acuerdo con el artículo 4 de la Ley 7/1985, de 2 de abril, reguladora de las bases del régimen local, corresponde a las comarcas:", "La potestad de revisión de oficio de sus actos y acuerdos.", "Las potestades que concreten las leyes de las comunidades autónomas.", "Las potestades tributaria y financiera.", "La potestad de programación o planificación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 65, "Según el artículo 9 de la Ley 7/1985, de 2 de abril, reguladora de las bases del régimen local:", "Las normas de desarrollo de la Ley reguladora de las bases del régimen local que afecten a los municipios, las provincias, las islas u otras entidades locales territoriales pueden limitar su ámbito de aplicación a una o diversas de estas entidades con carácter singular.", "Las normas de desarrollo de la Ley reguladora de las bases del régimen local que afecten a los municipios, las provincias, las islas u otras entidades locales territoriales no pueden limitar su ámbito de aplicación a una o diversas de estas entidades con carácter singular en ningún caso.", "Las normas de desarrollo de la Ley reguladora de las bases del régimen local que afecten a las entidades locales territoriales no pueden limitar su ámbito de aplicación a una o diversas de estas entidades con carácter singular, sin perjuicio de lo que dispone esta Ley para los municipios.", "Las normas de desarrollo de la Ley reguladora de las bases del régimen local que afecten a los municipios, las provincias, las islas u otras entidades locales territoriales no pueden limitar su ámbito de aplicación a una o diversas de estas entidades con carácter singular, sin perjuicio de lo que dispone esta Ley para los regímenes municipales o provinciales especiales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 66, "¿De acuerdo con el artículo 10 de la Ley 7/1985, de 2 de abril, reguladora de las bases del régimen local, qué tiene por objeto, especialmente, la coordinación de las entidades locales?", "Asegurar el cumplimiento<A[cumplimiento|cumplido]> de la legislación de estabilidad presupuestaria y de sostenibilidad financiera.", "Asegurar el ejercicio de la potestad de programación o planificación.", "Asegurar el cumplimiento<A[cumplimiento|cumplido]> de la legislación en materia urbanística.", "Asegurar el cumplimiento<A[cumplimiento|cumplido]> de la legislación en materia de subvenciones."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 67, "Las funciones de coordinación de las entidades locales:", "Limitan la autonomía de las entidades locales.", "Sólo proceden respecto del ejercicio de las competencias de las entidades locales entre sí.", "Sólo proceden respecto del ejercicio de las competencias de las entidades locales con las del resto de Administraciones públicas.", "Tienen que ser compatibles con la autonomía de las entidades locales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 68, "De acuerdo con el artículo 6 de la Ley 7/1985, de 2 de abril, reguladora de las bases del régimen local, las entidades locales sirven con objetividad los intereses públicos que les están encomendados y actúan:", "De acuerdo con los principios de eficacia y descentralización.", "De acuerdo con los principios de descentralización, desconcentración y coordinación, con plena sumisión a la ley y al derecho.", "De acuerdo con los principios de eficacia, descentralización, desconcentración y coordinación, con plena sumisión a la ley y al derecho.", "De acuerdo con el principio de eficiencia, con plena sumisión a la ley y al derecho."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 69, "La Administración local y las otras administraciones públicas:", "Tienen que ajustar las relaciones recíprocas a los deberes de información mutua, colaboración, coordinación y respeto a los ámbitos competenciales respectivos.", "Se tienen que limitar a ejercer sus competencias.", "No se encuentran sometidas a ningún deber de información.", "Sólo tienen que ajustar las relaciones recíprocas al deber de información mutua."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 70, "De acuerdo con el artículo 4 de la Ley 7/1985, de 2 de abril, reguladora de las bases del régimen local, corresponde en las áreas metropolitanas:", "Las potestades reglamentarias y de auto organización.", "Las potestades de ejecución forzosa y sancionadora.", "La potestad de revisión de oficio de sus actos y acuerdos.", "Las potestades que concreten las leyes de las comunidades autónomas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 71, "¿La disposición o el acuerdo de delegación de competencias a las entidades locales, puede prever técnicas de dirección y control de oportunidad y de eficiencia?", "No, eso sería contrario al principio de autonomía local.", "Sí, en todo caso.", "Sólo puede prever técnicas de dirección.", "Sólo puede prever técnicas de control de oportunidad y de eficiencia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 6, 72, "Las potestades tributaria y financiera corresponden en todo caso:", "Exclusivamente en los municipios.", "Exclusivamente en las provincias.", "A los municipios, a las provincias y a las islas.", "A los municipios y a las comarcas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 1, "La Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, tiene por objeto adaptar el ordenamiento jurídico español al:", "Reglamento (UE) 2016/679 del Parlamento Europeo y el Consejo, de 27 de abril de 2016 relativo a la protección de las personas físicas y jurídicas en lo que respecta al tratamiento de sus datos personales y a la libre circulación de estos datos.", "Reglamento (UE) 2016/679 del Parlamento Europeo y el Consejo, de 27 de abril de 2016 relativo a la protección de las personas físicas en lo que respecta al tratamiento de sus datos personales y a la libre circulación de estos datos.", "Reglamento (UE) 2016/679 del Parlamento Europeo y el Consejo, de 27 de abril de 2016 relativo a la protección de las personas físicas en lo que respecta al tratamiento de sus datos personales y a la libre circulación de estos datos, y completar sus disposiciones.", "Reglamento (UE) 2016/679 del Parlamento Europeo y el Consejo, de 27 de abril de 2016 relativo a la protección de las personas físicas y jurídicas en lo que respecta al tratamiento de sus datos personales y a la libre circulación de estos datos, y completar sus disposiciones."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 2, "¿Cuál de los siguientes tratamientos de datos no le es de aplicación directa el Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo, de 27 de abril de 2016 (Reglamento general de protección de datos), por afectar a actividades no comprendidas en el ámbito de aplicación del Derecho de la Unión Europea?", "Tratamiento de datos de alumnos de un centro educativo.", "Tratamientos realizados en el ámbito de instituciones penitenciarias.", "Tratamiento de datos para fines comerciales.", "Tratamiento de datos realizado por empresas de telecomunicaciones."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 3, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, en relación a los derechos y libertades consagrados en la Constitución y en los tratados y convenios internacionales en que España sea parte, ¿quién contribuirá a garantizar su aplicación?", "Los prestadores de servicios de la sociedad de la información y los proveedores de servicios de Internet.", "Las personas que autoricen el tratamiento de sus datos personales.", "Exclusivamente los proveedores de servicios de Internet.", "Exclusivamente los prestadores de servicios de la sociedad."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 4, "Indique cuál de los siguientes no es un derecho digital reconocido en la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales:", "Derecho a la intimidad frente al uso de dispositivos de videovigilancia y de grabación de sonidos en el hogar.", "Derecho a la intimidad ante la utilización de sistemas de geolocalización en el ámbito laboral.", "Derechos digitales en la negociación colectiva.", "Derecho al olvido en búsquedas de Internet."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 5, "Lo dispuesto en los títulos I a IX y en los artículos 89 a 94 de la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, se aplica a:", "Cualquier tratamiento totalmente automatizado de datos personales, así como al tratamiento automatizado de datos personales contenidos o destinados a ser incluidos en un fichero.", "Cualquier tratamiento total o parcialmente automatizado de datos personales, así como al tratamiento no automatizado de datos personales contenidos o destinados a ser incluidos en un fichero.", "Cualquier tratamiento totalmente automatizado de datos personales, así como al tratamiento no automatizado de datos personales contenidos o destinados a ser incluidos en un fichero.", "Cualquier tratamiento total o parcialmente automatizado de datos personales, así como al tratamiento automatizado de datos personales contenidos o destinados a ser incluidos en un fichero."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 6, "Indique cuál de las siguientes respuestas no es un principio de la protección de datos de acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales.", "Exactitud de los datos, siendo actualizados si fuera necesario.", "Deber de confidencialidad de los responsables y encargados del tratamiento de datos así como todas las personas que intervengan en cualquier fase de este.", "Tratamiento basado en el consentimiento del afectado, siendo aceptado la no existencia de una declaración negativa.", "Consentimiento de los menores de edad, cuando éstos sean mayores de catorce años."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 7, "Indique cual de las siguientes respuestas no es un principio de la protección de datos de acuerdo con el Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo, de 27 de abril de 2016 (Reglamento general de protección de datos).", "Minimización de datos.", "Limitación de la finalidad.", "Licitud, lealtad y opacidad.", "Exactitud."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 8, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, cuando la supresión derive del ejercicio del derecho de oposición con arreglo al artículo 21.2 del Reglamento (UE) 2016/679, el responsable:", "Podrá conservar los datos identificativos del afectado necesarios con el fin de impedir tratamientos futuros para fines de mercadotecnia indirecta.", "No podrá conservar los datos identificativos del afectado necesarios con el fin de impedir tratamientos futuros para fines de mercadotecnia indirecta.", "Podrá conservar los datos identificativos del afectado necesarios con el fin de impedir tratamientos futuros para fines de mercadotecnia directa.", "No podrá conservar los datos identificativos del afectado necesarios con el fin de impedir tratamientos futuros para fines de mercadotecnia directa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 9, "De acuerdo con el Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo, de 27 de abril de 2016 (Reglamento general de protección de datos), ¿cuando no se aplicará el derecho de supresión?", "Cuando el tratamiento de datos personales afecte a menores.", "Cuando el tratamiento sea necesario para ejercer el derecho a la libertad de expresión e información.", "Cuando los datos personales hayan sido tratados ilícitamente.", "Cuando los datos personales ya no sean necesarios en relación con los fines para los que fueron recogidos o tratados de otro modo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 10, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, entre otras exigencias ¿Qué implica el Derecho de acceso universal a Internet?", "Todos tienen derecho a acceder a Internet independientemente de su condición personal, social, económica o geográfica.", "Los proveedores de servicios de Internet proporcionarán una oferta transparente de servicios sin discriminación por motivos técnicos o económicos.", "Se garantizará un acceso universal, gratuito y no discriminatorio para toda la población.", "Todos tienen derecho a la libertad de expresión en Internet."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 11, "De acuerdo con el Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo, de 27 de abril de 2016 (Reglamento general de protección de datos), el encargado del tratamiento puede recurrir a otro encargado:", "En ningún caso.", "Siempre que se lo comunique dentro del siguiente mes natural al responsable, teniendo éste la oportunidad de autorizarlo u oponerse.", "Solo si tiene la autorización previa por escrito del responsable,y siempre que le informe de cualquier cambio previsto en la incorporación o sustitución de otros encargados, dando así al responsable la oportunidad de oponerse.", "Siempre que lo considere oportuno, dado que este reglamento autoriza al encargado a disponer de los recursos que considere mejores para cumplir con su función de acuerdo con la normativa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 12, "De acuerdo con el Título V de la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, los responsables y encargados del tratamiento deberán designar un delegado de protección de datos (señale la respuesta incorrecta):", "Los distribuidores y comercializadores de energía eléctrica y los distribuidores y comercializadores de gas natural.", "Las empresas de servicios de inversión, reguladas por la legislación del Mercado de Valores.", "Los tribunales que actúen en ejercicio de su función judicial.", "Las entidades aseguradoras y reaseguradoras."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 13, "De acuerdo con el Título V de la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, los responsables y encargados del tratamiento comunicarán a la Agencia Española de Protección de Datos o, en su caso, a las autoridades autonómicas de protección de datos, las designaciones, nombramientos y ceses de los delegados de protección de datos:", "En el plazo de diez días, tanto en los supuestos en que se encuentren obligadas a su designación como en el caso en que sea voluntaria.", "En el plazo de diez días en los supuestos en que se encuentren obligadas a su designación pero no en el caso en que sea voluntaria.", "En el plazo de quince días, tanto en los supuestos en que se encuentren obligadas a su designación como en el caso en que sea voluntaria.", "En el plazo de quince días en los supuestos en que se encuentren obligadas a su designación pero no en el caso en que sea voluntaria."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 14, "De acuerdo con el Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo, de 27 de abril de 2016 (Reglamento general de protección de datos), el principio de minimización de datos en el tratamiento de datos supone que los datos personales serán:", "Adecuados, pertinentes y limitados a lo necesario en relación con los fines para los que son tratados.", "Exactos y, si fuera necesario, actualizados.", "Recogidos con fines determinados, explícitos y legítimos, y no serán tratados ulteriormente de manera incompatible con dichos fines.", "Tratados de manera lícita, leal y transparente en relación con el interesado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 15, "Indique cuál de las siguientes respuestas no está incluida entre las exigencias establecidas por la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, para garantizar el Derecho de acceso universal a Internet:", "Todos tienen derecho a acceder a Internet independientemente de su condición personal, social, económica o geográfica.", "El acceso a Internet de hombres y mujeres procurará la superación de la brecha de género tanto en el ámbito personal como laboral.", "La garantía efectiva del derecho de acceso a Internet atenderá la realidad específica de los entornos rurales.", "Todos tienen derecho a la libertad de expresión en Internet."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 16, "De acuerdo con el Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo, de 27 de abril de 2016 (Reglamento general de protección de datos), el derecho a la portabilidad de los datos supone que el interesado tendrá derecho a recibir los datos personales que le incumban, que haya facilitado a un responsable del tratamiento, en un formato estructurado, de uso común y lectura mecánica:", "Para su supresión o modificación sin que lo impida el responsable al que se los hubiera facilitado.", "Y a transmitirlos a otro responsable del tratamiento pudiéndolo impedir el responsable al que se los hubiera facilitado.", "Para su supresión o modificación pudiéndolo impedir el responsable al que se los hubiera facilitado.", "Y a transmitirlos a otro responsable del tratamiento sin que lo impida el responsable al que se los hubiera facilitado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 17, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, la Agencia Española de Protección de Datos tendrá la condición de representante común de las autoridades de protección de datos del Reino de España en:", "el Parlamento Europeo.", "la Comisión Europea.", "el Comité Europeo de Protección de Datos.", "el Consejo Europeo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 18, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, ¿Qué implica el Derecho a la educación digital?", "Que el acceso a Internet deberá garantizar condiciones de igualdad para las personas que cuenten con necesidades especiales.", "Que se garantizará un acceso universal, asequible, de calidad y no discriminatorio para toda la población.", "Que el sistema educativo garantizará la plena inserción del alumnado en la sociedad digital y el aprendizaje de un consumo responsable y un uso crítico y seguro de los medios digitales.", "Que los usuarios tienen derecho a la seguridad de las comunicaciones que transmitan y reciban a través de Internet."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 19, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, el tratamiento de los datos de los menores de catorce años, fundado en su propio consentimiento:", "No será lícito en ningún caso, teniendo especial protección.", "Solo será lícito si consta el del titular de la patria potestad o tutela.", "Será lícito en todo caso.", "Solo será lícito si consta el del titular de la patria potestad o tutela y el del responsable del tratamiento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 20, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, el resultado positivo de sus ingresos se destinará por la Agencia Española de Protección de Datos a:", "La caja única de la Administración del Estado.", "La dotación de sus reservas con el fin de garantizar su plena independencia.", "La dotación de reservas para financiar a las autoridades de control autonómicas.", "El mantenimiento de los registros de actividades de tratamiento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 21, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, los actos y disposiciones dictados por la Presidencia de la Agencia Española de Protección de Datos:", "No ponen fin a la vía administrativa, siendo recurribles mediante un recurso de alzada ante el Ministerio de Justicia.", "No ponen fin a la vía administrativa, siendo recurribles mediante un recurso de alzada ante el Ministerio de Asuntos Económicos y Transformación Digital.", "Ponen fin a la vía administrativa, siendo recurribles, directamente, ante la Sala de lo Contencioso-administrativo de la Audiencia Nacional.", "Ponen fin a la vía administrativa, siendo recurribles, directamente, ante la Sala de lo Social de la Audiencia Nacional."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 22, "De acuerdo con el Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo, de 27 de abril de 2016 (Reglamento general de protección de datos), cuando el tratamiento de datos personales tenga por objeto la mercadotecnia directa:", "El interesado tendrá derecho a oponerse en todo momento al tratamiento de los datos personales que le conciernan, incluida la elaboración de perfiles.", "El interesado tendrá derecho a oponerse en todo momento al tratamiento de los datos personales que le conciernan, excepto la elaboración de perfiles.", "La autoridad de control tendrá derecho a oponerse en todo momento al tratamiento de los datos personales que le conciernan, incluida la elaboración de perfiles.", "La autoridad de control tendrá derecho a oponerse en todo momento al tratamiento de los datos personales que le conciernan, excepto la elaboración de perfiles."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 23, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, ¿Qué implica el derecho a la protección de los menores en Internet?", "La utilización o difusión de imágenes o información personal de menores en las redes sociales y servicios de la sociedad de la información equivalentes que puedan implicar una intromisión ilegítima en sus derechos fundamentales y determinará la intervención del Ministerio Fiscal.", "El sistema educativo garantizará la plena inserción del alumnado en la sociedad digital y el aprendizaje de un consumo responsable y un uso crítico y seguro de los medios digitales.", "Se garantizará un acceso universal, asequible, de calidad y no discriminatorio para toda la población, incluidos los menores.", "Los usuarios menores de edad tienen derecho a la seguridad de las comunicaciones que transmitan y reciban a través de Internet."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 24, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, la Agencia Española de Protección Datos elaborará y aprobará su relación de puestos de trabajo:", "En el marco de los criterios establecidos por el Ministerio de Hacienda.", "En el marco de los criterios establecidos por el Ministerio de Presidencia.", "En el marco de los criterios establecidos por el Ministerio de Justicia.", "En el marco de los criterios establecidos por el Gobierno."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 25, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, las autoridades autonómicas de protección de datos personales podrán ejercer, las funciones y potestades establecidas en los artículos 57 y 58 del Reglamento (UE) 2016/679, de acuerdo con la normativa autonómica, cuando se refieran a (señala la respuesta incorrecta):", "Tratamientos de los que sean responsables las entidades integrantes del sector público de la correspondiente Comunidad Autónoma o de las Entidades Locales incluidas en su ámbito territorial.", "Tratamientos llevados a cabo por personas físicas o jurídicas para el ejercicio de las funciones públicas en materias que sean competencia de la correspondiente Administración Autonómica o Local.", "Tratamientos llevados a cabo por personas físicas o jurídicas para fines de mercadotecnia directa.", "Tratamientos que se encuentren expresamente previstos, en su caso, en los respectivos Estatutos de Autonomía."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 26, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, el tratamiento de datos personales solo podrá considerarse fundado en el cumplimiento de una misión realizada en interés público o en el ejercicio de poderes públicos conferidos al responsable, en los términos previstos en el artículo 6.1 e) del Reglamento (UE) 2016/679:", "Cuando derive de una competencia atribuida por una norma de Derecho de la Unión Europea o una norma con rango de ley.", "Cuando derive una competencia atribuida por una norma reglamentaria de desarrollo de esta ley.", "Cuando derive de una competencia atribuida por una norma de Derecho de la Unión Europea.", "Cuando derive de una competencia atribuida por una norma con rango de ley."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 27, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, ¿Qué implica el Derecho a la actualización de informaciones en medios de comunicación digitales?", "Los responsables de redes sociales y servicios equivalentes adoptarán protocolos adecuados para posibilitar el ejercicio del derecho de rectificación ante los usuarios que difundan contenidos que atenten contra el derecho al honor, la intimidad personal y familiar en Internet y el derecho a comunicar o recibir libremente información veraz.", "Toda persona tiene derecho a que los motores de búsqueda en Internet eliminen de las listas de resultados que se obtuvieran tras una búsqueda efectuada a partir de su nombre.", "Toda persona tiene derecho a solicitar motivadamente de los medios de comunicación digitales la inclusión de un aviso de actualización suficientemente visible junto a las noticias que le conciernan cuando la información contenida en la noticia original no refleje su situación actual como consecuencia de circunstancias que hubieran tenido lugar después de la publicación, causándole un perjuicio.", "Los usuarios tienen derecho a la seguridad de las comunicaciones que transmitan y reciban a través de Internet. Los proveedores de servicios de Internet informarán a los usuarios de sus derechos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 28, "De acuerdo con el Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo, de 27 de abril de 2016 (Reglamento general de protección de datos), ¿cuál de las siguientes condiciones no suponen la licitud del tratamiento de datos personales?", "El tratamiento es necesario para la ejecución de un contrato en el que el interesado es parte o para la aplicación a petición de este de medidas precontractuales.", "El tratamiento es necesario para el cumplimiento de una obligación legal aplicable al particular.", "El tratamiento es necesario para proteger intereses vitales del interesado o de otra persona física.", "El interesado dio su consentimiento para el tratamiento de sus datos personales para uno o varios fines específicos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 29, "De acuerdo con el Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo, de 27 de abril de 2016 (Reglamento general de protección de datos), cuando el interesado es objeto de una decisión basada únicamente en el tratamiento automatizado y la decisión se basa en el consentimiento explícito del interesado, éste tendrá como mínimo el derecho a:", "Obtener intervención humana por parte del responsable, a expresar su punto de vista y a impugnar la decisión.", "Sin obtener intervención humana por parte del responsable, a expresar su punto de vista y a impugnar la decisión.", "Obtener intervención humana por parte del responsable, a expresar su punto de vista pero no a impugnar la decisión.", "Sin obtener intervención humana por parte del responsable, a expresar su punto de vista pero no a impugnar la decisión."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 30, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, indica cuál de las siguientes es una infracción muy grave:", "La resistencia u obstrucción del ejercicio de la función inspectora por la autoridad de protección de datos competente.", "El tratamiento de datos personales de un menor de edad sin recabar su consentimiento, cuando tenga capacidad para ello, o el del titular de su patria potestad o tutela, conforme al artículo 8 del Reglamento (UE) 2016/679.", "El quebrantamiento, como consecuencia de la falta de la debida diligencia, de las medidas técnicas y organizativas que se hubiesen implantado conforme a lo exigido por el artículo 32.1 del Reglamento (UE) 2016/679.", "No cooperar con las autoridades de control en el desempeño de sus funciones en los supuestos no previstos en el artículo 72 de esta ley orgánica."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 31, "De acuerdo con el Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo, de 27 de abril de 2016 (Reglamento general de protección de datos), cuando el tratamiento se base en el consentimiento del interesado:", "El interesado tendrá derecho a retirar su consentimiento a partir de un año desde la concesión.", "El interesado tendrá derecho a retirar su consentimiento a partir de los dos años desde la concesión.", "El interesado tendrá derecho a retirar su consentimiento a partir de los seis meses desde la concesión.", "El interesado tendrá derecho a retirar su consentimiento en cualquier momento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 32, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, ¿Qué implica el derecho a la intimidad y uso de dispositivos digitales en el ámbito laboral?", "En ningún caso se admitirá la instalación de sistemas de grabación de sonidos ni de videovigilancia en lugares destinados al descanso o esparcimiento de los trabajadores o los empleados públicos, tales como vestuarios, aseos, comedores y análogos.", "Los empleadores podrán tratar los datos obtenidos a través de sistemas de geolocalización para el ejercicio de las funciones de control de los trabajadores o los empleados públicos previstas, respectivamente, en el artículo 20.3 del Estatuto de los Trabajadores y en la legislación de función pública, siempre que estas funciones se ejerzan dentro de su marco legal y con los límites inherentes al mismo.", "El empleador podrá acceder a los contenidos derivados del uso de medios digitales facilitados a los trabajadores a los solos efectos de controlar el cumplimiento de las obligaciones laborales o estatutarias y de garantizar la integridad de dichos dispositivos", "Los trabajadores y los empleados públicos tendrán derecho a la desconexión digital a fin de garantizar, fuera del tiempo de trabajo legal o convencionalmente establecido, el respeto de su tiempo de descanso, permisos y vacaciones, así como de su intimidad personal y familiar."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 33, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, indica cuál de las siguientes es una infracción grave:", "La reversión deliberada de un procedimiento de anonimización a fin de permitir la reidentificación de los afectados.", "El incumplimiento del deber del encargado del tratamiento de notificar al responsable del tratamiento las violaciones de seguridad de las que tuviera conocimiento.", "El impedimento o la obstaculización o la no atención reiterada del ejercicio de los derechos establecidos en los artículos 15 a 22 del Reglamento (UE) 2016/679.", "El incumplimiento de la obligación de bloqueo de los datos establecida en el artículo 32 de esta ley orgánica cuando la misma sea exigible."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 34, "De acuerdo con el artículo 7 del Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo, de 27 de abril de 2016 (Reglamento general de protección de datos), al evaluar si el consentimiento se ha dado libremente, se tendrá en cuenta en la mayor medida posible si:", "La ejecución de un contrato, se supedita al consentimiento al tratamiento de datos personales que no son necesarios para la ejecución de dicho contrato.", "El particular interesado es mayor de 65 años.", "La ejecución de un contrato se realiza fuera de la Unión Europea.", "El particular interesado es menor de 18 años."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 35, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, ¿Qué implica el derecho a la intimidad frente al uso de dispositivos de videovigilancia y de grabación de sonidos en el lugar de trabajo?", "Los empleadores podrán tratar las imágenes obtenidas a través de sistemas de cámaras o videocámaras para el ejercicio de las funciones de control de los trabajadores o los empleados públicos previstas, respectivamente, en el artículo 20.3 del Estatuto de los Trabajadores y en la legislación de función pública, siempre que estas funciones se ejerzan dentro de su marco legal y con los límites inherentes al mismo.", "Se permitirá la instalación de sistemas de grabación de sonidos y de videovigilancia en lugares destinados al descanso o esparcimiento de los trabajadores o los empleados públicos, tales como vestuarios, aseos, comedores y análogos.", "Los empleadores no están obligados a informar a los trabajadores o los empleados públicos y, en su caso, a sus representantes, acerca de la medida de tratar las imágenes obtenidas a través de sistemas de cámaras o videocámaras para el ejercicio de las funciones de control de los trabajadores o los empleados públicos.", "Se preservará el derecho a la desconexión digital en los supuestos de realización total o parcial del trabajo a distancia así como en el domicilio del empleado vinculado al uso con fines laborales de herramientas tecnológicas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 36, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, los responsables y encargados, teniendo en cuenta los elementos enumerados en los artículos 24 y 25 del Reglamento (UE) 2016/679, determinarán las medidas técnicas y organizativas apropiadas que deben aplicar a fin de garantizar y acreditar que el tratamiento es conforme, entre otros:", "A la presente ley orgánica y sus normas de desarrollo.", "Al estado de la técnica.", "Al contrato que regule las obligaciones de ambos.", "A la legislación local."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 37, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, indica cual de las siguientes es una infracción leve:", "El tratamiento de datos personales sin llevar a cabo una previa valoración de los elementos mencionados en el artículo 28 de esta ley orgánica.", "No disponer del registro de actividades de tratamiento establecido en el artículo 30 del Reglamento (UE) 2016/679.", "La falta de atención por el representante en la Unión del responsable o del encargado del tratamiento de las solicitudes efectuadas por la autoridad de protección de datos o por los afectados.", "El incumplimiento de la obligación de notificación relativa a la rectificación o supresión de datos personales o la limitación del tratamiento exigida por el artículo 19 del Reglamento (UE) 2016/679."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 38, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, ¿Qué implica el Derecho a la intimidad frente al uso de dispositivos de videovigilancia y de grabación de sonidos en el lugar de trabajo?", "Los trabajadores y los empleados públicos tendrán derecho a la protección de su intimidad en el uso de los dispositivos digitales puestos a su disposición por su empleador.", "Se permitirá la instalación de sistemas de grabación de sonidos y de videovigilancia en lugares destinados al descanso o esparcimiento de los trabajadores o los empleados públicos, tales como vestuarios, aseos, comedores y análogos.", "Los empleadores podrán tratar los datos obtenidos a través de sistemas de geolocalización para el ejercicio de las funciones de control de los trabajadores o los empleados públicos.", "Los empleadores podrán tratar las imágenes obtenidas a través de sistemas de cámaras o videocámaras para el ejercicio de las funciones de control de los trabajadores o los empleados públicos previstas, respectivamente, en el artículo 20.3 del Estatuto de los Trabajadores y en la legislación de función pública, siempre que estas funciones se ejerzan dentro de su marco legal y con los límites inherentes al mismo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 39, "De acuerdo con el Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo, de 27 de abril de 2016 (Reglamento general de protección de datos), el tratamiento de los datos personales de un niño menor de 16 años, únicamente se considerará lícito:", "Si lo consiente el menor mayor de 14 años.", "Si el consentimiento lo dio o autorizó el titular de la patria potestad o tutela sobre el niño.", "Si lo consiente el menor mayor de 12 años.", "No puede realizarse tratamiento de datos personales de menores de 16 años."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 40, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, interrumpirá la prescripción de la infracción:", "La iniciación, aun sin el conocimiento del interesado, del procedimiento sancionador.", "La iniciación, con conocimiento del interesado, del procedimiento sancionador.", "La iniciación, con conocimiento del interesado, del procedimiento de cobro ejecutivo de la sanción.", "La iniciación, aun sin el conocimiento del interesado, del procedimiento de cobro ejecutivo de la sanción."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 41, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, una vez interrumpida la prescripción de la infracción por la iniciación, con conocimiento del interesado, del procedimiento sancionador, se reinicirá el plazo de prescripción:", "Si el expediente sancionador estuviere paralizado durante más de nueve meses por causas no imputables al presunto infractor.", "Si el expediente sancionador estuviere paralizado durante más de tres meses por causas no imputables al presunto infractor.", "Si el expediente sancionador estuviere paralizado durante más de seis meses por causas no imputables al presunto infractor.", "Si el expediente sancionador estuviere paralizado durante más de nueve meses, siempre que lo solicite el interesado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 42, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, indique la respuesta incorrecta en relación al derecho digital de protección de datos de los menores en Internet:", "Los centros educativos garantizarán la protección del interés superior del menor y sus derechos fundamentales.", "La publicación o difusión de datos personales del menor a través de servicios de la sociedad de la información deberán contar con el consentimiento del Ministerio Fiscal.", "Cualesquiera personas físicas o jurídicas que desarrollen actividades en las que participen menores de edad garantizarán la protección del interés superior del menor y sus derechos fundamentales.", "Cualesquiera personas físicas o jurídicas que desarrollen actividades en las que participen menores de edad garantizarán especialmente el derecho a la protección de datos personales, en la publicación o difusión de sus datos personales a través de servicios de la sociedad de la información."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 43, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, para la adopción de las medidas técnicas y organizativas apropiadas que deben aplicar los responsables y encargados del tratamiento tendrán en cuenta, en particular, los mayores riesgos que podrían producirse cuando (señala la incorrecta):", "Cuando el tratamiento implicase una evaluación de aspectos personales de los afectados con el fin de crear o utilizar perfiles personales de los mismos.", "Cuando se produzca un tratamiento masivo que implique a un gran número de afectados.", "Cuando los datos personales fuesen a ser objeto de transferencia, con carácter habitual, a Estados de la Unión respecto de los que no se hubiese declarado un nivel adecuado de protección", "Cuando el tratamiento pudiera generar situaciones de discriminación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 44, "Cuando los datos personales sean obtenidos del afectado, el responsable del tratamiento podrá dar cumplimiento al deber de información establecido en el artículo 13 del Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo, de 27 de abril de 2016 (Reglamento general de protección de datos):", "Facilitando al afectado la información básica del tratamiento de esos datos.", "Indicando al afectado una dirección electrónica u otro medio que permita acceder de forma sencilla e inmediata a la información básica.", "Indicando al afectado un correo postal que permita acceder de forma inmediata a la información básica.", "Facilitando al afectado una dirección electrónica que permita acceder en el futuro a la información básica."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 45, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, indica cual de las siguientes es una infracción leve:", "No cooperar con las autoridades de control en el desempeño de sus funciones en los supuestos no previstos en el artículo 72 de esta ley orgánica.", "No disponer del registro de actividades de tratamiento establecido en el artículo 30 del Reglamento (UE) 2016/679.", "No posibilitar la efectiva participación del delegado de protección de datos en todas las cuestiones relativas a la protección de datos personales, no respaldarlo o interferir en el desempeño de sus funciones.", "El incumplimiento de la obligación de suprimir los datos referidos a una persona fallecida cuando ello fuera exigible conforme al artículo 3 de esta ley orgánica."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 46, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, cuando los datos personales sean obtenidos del afectado, el responsable del tratamiento deberá facilitar al afectado la información básica del tratamiento de esos datos, que debe contener:", "La identidad del responsable del tratamiento y de su representante, en su caso.", "La posibilidad de ejercer los principios de protección de datos establecidos en los artículos 15 a 22 del Reglamento (UE) 2016/679.", "Los resultados del tratamiento.", "Los medios de consentimiento del tratamiento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 47, "Indique cuál de las siguientes respuestas no está incluida entre las exigencias establecidas por la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, para garantizar el derecho al olvido en búsquedas de Internet.", "El ejercicio del derecho al olvido en búsquedas de Internet debe impedir el acceso a la información publicada en el sitio web a través de la utilización de otros criterios de búsqueda distintos del nombre de quien ejerciera el derecho.", "El Derecho al olvido en búsquedas de Internet subsistirá aun cuando fuera lícita la conservación de la información publicada en el sitio web al que se dirigiera el enlace y no se procediese por la misma a su borrado previo o simultáneo", "Toda persona tiene derecho a que los motores de búsqueda en Internet eliminen de las listas de resultados que se obtuvieran tras una búsqueda efectuada a partir de su nombre cuando las circunstancias personales que invocase el afectado evidenciasen la prevalencia de sus derechos sobre el mantenimiento de los enlaces por el servicio de búsqueda en Internet.", "Toda persona tiene derecho a que los motores de búsqueda en Internet eliminen de las listas de resultados que se obtuvieran tras una búsqueda efectuada a partir de su nombre los enlaces publicados que contuvieran información relativa a esa persona cuando fuesen no pertinentes, entre otros motivos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 48, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, el registro de actividades, deberá especificar, según sus finalidades:", "Los perfiles llevados a cabo y las demás circunstancias establecidas en el citado reglamento.", "Los datos personales tratados y las demás circunstancias establecidas en el citado reglamento.", "Las personas cuyos datos personales han sido tratados y las demás circunstancias establecidas en el citado reglamento.", "Las actividades de tratamiento llevadas a cabo y las demás circunstancias establecidas en el citado reglamento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 49, "De acuerdo con el Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo, de 27 de abril de 2016 (Reglamento general de protección de datos), cada autoridad de control garantizará que la imposición de las multas administrativas con arreglo al presente Reglamento sean en cada caso individual:", "Eficientes, justas y disuasorias.", "Justas, disuasorias y correctivas.", "Efectivas, proporcionadas y disuasorias.", "Eficientes, proporcionadas y correctivas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 50, "Cuando el responsable o encargado de un tratamiento sea la administración de una comunidad autónoma y cometiesen alguna de las infracciones a las que se refiere la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, siendo la infracción imputable a autoridades o directivos y se acredite la existencia de informes técnicos o recomendaciones para el tratamiento que no hubieran sido debidamente atendidos:", "En la resolución en la que se imponga la sanción se incluirá una amonestación con denominación del cargo responsable y se ordenará la publicación en el Boletín Oficial autonómico que corresponda.", "En la resolución en la que se imponga la sanción se incluirá el cese del cargo responsable y se ordenará la publicación en el Boletín Oficial autonómico que corresponda.", "En la resolución se impondrá la sanción directamente al cargo responsable y se ordenará la publicación en el Boletín Oficial autonómico que corresponda.", "En la resolución en la que se imponga la sanción se incluirá el cese del cargo responsable pero no se publicará para no vulnerar la propia ley orgánica de protección de datos personales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 51, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, indica la respuesta incorrecta en relación a las disposiciones generales sobre ejercicio de los derechos de las personas en relación al tratamiento de sus datos personales.", "Los medios deberán ser fácilmente accesibles para el afectado.", "El encargado del tratamiento deberá facilitar un e-mail de contacto.", "El responsable del tratamiento estará obligado a informar al afectado sobre los medios a su disposición para ejercer los derechos que le corresponden.", "El ejercicio del derecho no podrá ser denegado por el solo motivo de optar el afectado por otro medio."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 52, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, indica la respuesta correcta en relación a la prescripción de las sanciones impuestas en aplicación del Reglamento (UE) 2016/679 y de esta ley orgánica:", "Las sanciones por importe comprendido entre 40.001 y 300.000 euros prescriben a los tres años.", "Las sanciones impuestas por infracciones graves prescriben en el plazo de 2 años.", "Las sanciones por importe comprendido entre 40.001 y 300.000 euros prescriben a los dos años.", "Las sanciones impuestas por infracciones graves prescriben en el plazo de 3 años."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 53, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, los responsables y encargados del tratamiento de datos así como todas las personas que intervengan en cualquier fase de este estarán sujetas:", "Al deber de custodia.", "Al deber de confianza.", "Al deber de confidencialidad.", "Al deber de sigilo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 54, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, el responsable del tratamiento estará obligado a bloquear los datos cuando:", "Cuando proceda a realizar actuaciones de mantenimiento.", "Cuando contrate a otro encargado.", "Cuando contrate a otro delegado de protección de datos.", "Cuando lleve a cabo la rectificación o supresión."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 55, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, el tratamiento de datos personales relativos a condenas e infracciones penales, solo podrá llevarse a cabo cuando se encuentre amparado en:", "Una norma de Derecho de la Unión o en esta ley orgánica.", "Esta ley orgánica o en otras normas de rango legal.", "En esta ley orgánica..", "Una norma de Derecho de la Unión, en esta ley orgánica o en otras normas de rango legal."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 56, "El derecho a la transparencia de la información regulado en el Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo, de 27 de abril de 2016 (Reglamento general de protección de datos), establece las formas en que puede ser facilitada la información (indica la incorrecta):", "Por escrito.", "Por medios electrónicos.", "Verbalmente, si lo ha solicitado el interesado y se identifica por otro medio.", "Verbalmente, si es el medio elegido por el encargado del tratamiento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 57, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, y en relación al Derecho al testamento digital, indica la respuesta correcta.", "Las personas legitimadas al acceso a contenidos gestionados por prestadores de servicios de la sociedad de la información sobre personas fallecidas podrán decidir en cualquier caso acerca del mantenimiento o eliminación de los perfiles personales de personas fallecidas en redes sociales o servicios equivalentes.", "La persona fallecida no puede prohibir el acceso, por parte de personas vinculadas al fallecido o herederos, a contenidos gestionados por prestadores de servicios de la sociedad de la información.", "En caso de personas fallecidas menores de edad, las facultades de acceso a contenidos gestionados por prestadores de servicios de la sociedad de la información  podrán ejercerse también por el Ministerio Fiscal, que siempre actuará de oficio.", "Las personas legitimadas al acceso a contenidos gestionados por prestadores de servicios de la sociedad de la información sobre personas fallecidas podrán decidir acerca del mantenimiento o eliminación de los perfiles personales de personas fallecidas en redes sociales o servicios equivalentes, a menos que el fallecido hubiera decidido acerca de esta circunstancia, en cuyo caso se estará a sus instrucciones."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 58, "De acuerdo con el Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo, de 27 de abril de 2016 (Reglamento general de protección de datos), el tratamiento de los datos personales de un niño se considerará lícito cuando tenga como mínimo:", "14 años, pudiendo los Estados miembros establecer por ley una edad inferior a tales fines, siempre que esta no sea inferior a 12 años.", "16 años, pudiendo los Estados miembros establecer por ley una edad inferior a tales fines, siempre que esta no sea inferior a 12 años.", "14 años, pudiendo los Estados miembros establecer por ley una edad inferior a tales fines, siempre que esta no sea inferior a 13 años.", "16 años, pudiendo los Estados miembros establecer por ley una edad inferior a tales fines, siempre que esta no sea inferior a 13 años."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 59, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, al decidir la imposición de una multa administrativa y su cuantía se tendrá en cuenta (indica la respuesta incorrecta):", "La existencia de un proceso de fusión por absorción posterior a la comisión de la infracción, que no puede imputarse a la entidad absorbente.", "La afectación a los derechos de las personas vulnerables y de edad avanzada.", "Disponer, cuando no fuere obligatorio, de un delegado de protección de datos.", "La posibilidad de que la conducta del afectado hubiera podido inducir a la comisión de la infracción."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 60, "De acuerdo con el derecho a la transparencia de la información regulado en el Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo, de 27 de abril de 2016 (Reglamento general de protección de datos), si el responsable del tratamiento no da curso a la solicitud del interesado:", "Le informará sin dilación, y a más tardar transcurridos 15 días de la recepción de la solicitud, de las razones de su no actuación y de la posibilidad de presentar otra solicitud.", "Le informará sin dilación, y a más tardar transcurridos 15 días de la recepción de la solicitud, de las razones de su no actuación y de la posibilidad de presentar una reclamación ante una autoridad de control y de ejercitar acciones judiciales.", "Le informará sin dilación, y a más tardar transcurrido un mes de la recepción de la solicitud, de las razones de su no actuación y de la posibilidad de presentar otra solicitud.", "Le informará sin dilación, y a más tardar transcurrido un mes de la recepción de la solicitud, de las razones de su no actuación y de la posibilidad de presentar una reclamación ante una autoridad de control y de ejercitar acciones judiciales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 61, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, la Presidencia y el Adjunto de la Agencia Española de Protección de Datos serán nombrados por el Consejo de Ministros mediante:", "Un real decreto.", "Una ley ordinaria", "Una orden ministerial.", "Un acuerdo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 62, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, el acceso por parte de un encargado de tratamiento a los datos personales que resulten necesarios para la prestación de un servicio al responsable:", "No se considerará comunicación de datos en todo caso.", "No se considerará comunicación de datos siempre que se cumpla lo establecido en el Reglamento (UE) 2016/679, en la presente ley orgánica y en sus normas de desarrollo.", "Se considerará comunicación de datos en todo caso.", "Se considerará comunicación de datos siempre que se cumpla lo establecido en el Reglamento (UE) 2016/679, en la presente ley orgánica y en sus normas de desarrollo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 63, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, la Presidencia de la Agencia Española de Protección de Datos estará asesorada por un Consejo Consultivo compuesto por los siguientes miembros (señala la incorrecta):", "Un experto propuesto por la Federación Española de Municipios y Provincias.", "Dos expertos propuestos por las Organizaciones Empresariales.", "Dos expertos propuestos por el Consejo de Consumidores y Usuarios.", "Un Diputado, propuesto por el Congreso de los Diputados"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 64, "De acuerdo con el derecho a la transparencia de la información regulado en el Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo, de 27 de abril de 2016 (Reglamento general de protección de datos), cuando el responsable del tratamiento tenga dudas razonables en relación con la identidad de la persona física que cursa la solicitud de acceso a los datos personales:", "Puede cobrar por facilitar dicha información.", "Puede dar respuesta a dicha solicitud en un plazo mas amplio.", "Tendrá que comunicar con el afectado para que de su consentimiento.", "Podrá solicitar que se facilite la información adicional necesaria para confirmar la identidad del interesado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 65, "De acuerdo con el Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo, de 27 de abril de 2016 (Reglamento general de protección de datos), si un responsable o un encargado del tratamiento incumpliera de forma intencionada o negligente, para las mismas operaciones de tratamiento u operaciones vinculadas, diversas disposiciones del presente Reglamento, la cuantía total de la multa administrativa:", "No será superior a la cuantía prevista para las infracciones más graves.", "No será superior al doble de la cuantía prevista para todas las infracciones.", "Será la suma de las cuantías previstas para todas las infracciones.", "No será superior al triple de la cuantía prevista para todas las infracciones."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 66, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, el derecho de acceso se entenderá otorgado si el responsable del tratamiento facilita al afectado un sistema de acceso remoto, directo y seguro a los datos personales:", "Que garantice de modo temporal por un mínimo de 6 meses, el acceso a su totalidad.", "Que garantice de modo permanente, el acceso a su totalidad.", "Que garantice de modo temporal por el plazo solicitado con un mínimo de 6 meses, el acceso a su totalidad.", "Que garantice de modo temporal, el acceso parcial a la información."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 67, "De acuerdo con el Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo, de 27 de abril de 2016 (Reglamento general de protección de datos), al decidir la imposición de una multa administrativa y su cuantía en cada caso individual se tendrá debidamente en cuenta (indica la respuesta incorrecta):", "Cualquier medida tomada por el responsable o encargado del tratamiento para paliar los daños y perjuicios sufridos por los interesados.", "La intencionalidad o negligencia en la infracción.", "Toda infracción anterior cometida por el responsable o el encargado del tratamiento.", "El grado de responsabilidad del delegado de protección de datos del tratamiento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 68, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, el responsable del tratamiento determinará si, cuando finalice la prestación de los servicios del encargado, los datos personales deben ser (indica la incorrecta):", "Destruidos.", "Devueltos al responsable.", "Entregados a un nuevo encargado.", "Devueltos a los interesados."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 69, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, a los efectos establecidos en el artículo 12.5 del Reglamento (UE) 2016/679 se podrá considerar repetitivo el ejercicio del derecho de acceso:", "Cuando del derecho de acceso sea ejercido en más de una ocasión durante el plazo de tres meses, a menos que exista causa legítima para ello.", "Cuando del derecho de acceso sea ejercido en más de una ocasión durante el plazo de cuatro meses, a menos que exista causa legítima para ello.", "Cuando del derecho de acceso sea ejercido en más de una ocasión durante el plazo de seis meses, a menos que exista causa legítima para ello.", "Cuando del derecho de acceso sea ejercido en más de una ocasión durante el plazo de un año, a menos que exista causa legítima para ello."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 70, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, y en relación a las políticas de impulso de los derechos digitales:", "El Gobierno, mediante decreto del Consejo de Gobierno, elaborará un plan de acceso a Internet.", "El Gobierno, en colaboración con las comunidades autónomas, elaborará un plan de acceso a Internet.", "El Consejo Consultivo de la Agencia Española de Protección de Datos elaborará un plan de acceso a Internet.", "La Agencia Española de Protección de Datos, en colaboración con las Autoridades autonómicas de protección de datos, elaborará un plan de acceso a Internet."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 71, "De acuerdo con el Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo, de 27 de abril de 2016 (Reglamento general de protección de datos), al decidir la imposición de una multa administrativa y su cuantía en cada caso individual se tendrá debidamente en cuenta (indica la respuesta incorrecta):", "La intencionalidad o negligencia en la infracción.", "Cualquier medida tomada por el responsable o encargado del tratamiento para paliar los daños y perjuicios sufridos por los interesados.", "Cualquier medida tomada por el delegado de protección de datos para paliar los daños y perjuicios sufridos por los interesados.", "La adhesión a códigos de conducta en virtud del artículo 40 o a mecanismos de certificación aprobados con arreglo al artículo 42."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 72, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, cuando finalice la prestación de los servicios del encargado, no procederá la destrucción de los datos:", "Cuando exista una previsión legal que obligue a su conservación.", "Cuando la situación de la tecnología no lo permita.", "Cuando exista una previsión de poder reutilizar estos datos por parte del encargado.", "Cuando exista una previsión de poder reutilizar estos datos por parte del responsable de protección de datos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 73, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, la actividad de investigación de la Agencia Española de Protección de Datos se llevará a cabo por:", "Los funcionarios de la Agencia Española de Protección de Datos o por funcionarios ajenos a ella habilitados expresamente por su Presidencia.", "Exclusivamente por los funcionarios de la Agencia Española de Protección de Datos.", "Los funcionarios de la Agencia Española de Protección de Datos o por funcionarios ajenos a ella habilitados expresamente por el Ministerio de Justicia.", "Exclusivamente por funcionarios ajenos a ella habilitados expresamente por su Presidencia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 74, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, estarán obligados a proporcionar a la Agencia Española de Protección de Datos los datos, informes, antecedentes y justificantes necesarios para llevar a cabo su actividad de investigación:", "Las Administraciones Públicas, excluidas las tributarias y de la Seguridad Social, y los particulares.", "Las Administraciones Públicas, incluidas las tributarias y de la Seguridad Social, y los particulares.", "Solo los particulares.", "Solo las Administraciones  Públicas, incluidas las tributarias y de la Seguridad Social."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 20, 75, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, cuando el afectado elija un medio distinto al que se le ofrece, que suponga un coste desproporcionado, para ejercer el derecho de acceso:", "La solicitud será considerada excesiva, por lo que dicho afectado asumirá el exceso de costes que su elección comporte.", "La solicitud será considerada excesiva, por lo que dicho afectado asumirá el 50% del exceso de costes que su elección comporte.", "La solicitud será considerada excesiva, por lo que el responsable del tratamiento debe informarle de los medios disponibles para ejercer su derecho.", "La solicitud será considerada excesiva, por lo que  el responsable del tratamiento está facultado a no responderla."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 1, "Indique la normativa en la que se establecen las premisas fundamentales de la normativa presupuestaria local", "Orden EHA/3565/2008, de 3 de diciembre, por la que se aprueba la estructura de los presupuestos de las Entidades Locales.", "Ley 7/1985, de 2 de abril, Reguladora de las Bases del Régimen Local.", "RD 500/1990, de 20 de abril, por el que se desarrolla el Capítulo Primero del Titulo Sexto de la Ley 39/1988, de 26 de diciembre, reguladora de las Haciendas Locales, en materia de presupuestos.", "Real Decreto Legislativo 2/2004, de 5 de mayo, por el que se aprueba el texto refundido de la Ley Reguladora de las Haciendas Locales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 2, "Se establece como una de las premisas fundamentales", "La aprobación de un presupuesto anual por parte del Pleno de la Corporación.", "La inclusión en el proyecto de presupuesto anual de todas las previsiones de ingresos y gastos del ejercicio.", "La aprobación de unas Bases de Ejecución por las que se regirá el Presupuesto General de la Corporación, en cuanto a la aprobación, ejecución y liquidación del presupuesto.", "La existencia de un presupuesto único integrado por el de la propia entidad y los de sus organismos autónomos dependientes y empresas municipales participadas íntegramente por la entidad local."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 3, "El Presupuesto General de una Entidad Local constituye la expresión cifrada, conjunta y sistemática de:", "El total de gastos e ingresos que se prevé liquidar durante el ejercicio presupuestario, a partir de la experiencia de ejercicios presupuestarios anteriores.", "Las operaciones de endeudamiento a corto plazo (pólizas de crédito) y a largo plazo (préstamos) que se prevé suscribir durante el ejercicio presupuestario por parte de la entidad local, de los organismos autónomos dependientes y de las empresas municipales participadas íntegramente por la entidad local.", "Las obligaciones que como máximo se podrán reconocer y los derechos que se prevé liquidar por la Entidad Local y sus Organismos Autónomos y las previsiones de ingresos y gastos de las Sociedades Mercantiles cuyo capital social pertenezca íntegramente a la Entidad Local.", "Las obligaciones que como máximo se podrán reconocer y los derechos que se prevé liquidar por la Entidad Local y sus Organismos Autónomos y las previsiones de ingresos y gastos de las Sociedades Mercantiles participadas por la entidad local en más de un 50% de su capital social."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 4, "El principio de anualidad supone:", "Que el presupuesto coincida con el año natural y que se le imputen los derechos liquidados de cualquier periodo y las obligaciones reconocidas durante el mismo periodo del ejercicio presupuestario.", "Que el presupuesto coincida con el año natural y que se le imputen los derechos liquidados y las obligaciones reconocidas del propio ejercicio presupuestario.", "Que la vigencia del presupuesto sea de un año, a contar desde el día siguiente a la inserción en el Boletín Oficial de la Comunidad Autónoma (BOIB) del presupuesto definitivamente aprobado por el Pleno de la Corporación.", "Que el presupuesto tenga una duración de doce meses y que se le imputen los derechos liquidados y las obligaciones reconocidas derivados del propio ejercicio presupuestario."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 5, "¿Qué implica el principio de universalidad?", "Que el Presupuesto de la Corporación recoge todas las obligaciones que como máximo puede reconocer y los derechos que prevé liquidar durante el ejercicio presupuestario.", "Que el Presupuesto General integra el presupuesto de la propia Entidad Local y el de los Organismos Autónomos de carácter administrativo, comercial, industrial y financiero, dependientes de la misma.", "Que el Presupuesto General integra el presupuesto de la propia Entidad Local y el de los Organismos Autónomos y los estados de previsión de ingresos y gastos de las sociedades mercantiles participadas íntegramente por la entidad local.", "Que el Presupuesto General integra el presupuesto de la propia Entidad Local y el de los Organismos Autónomos y los estados de previsión de ingresos y gastos de las sociedades mercantiles con capital social participado en más del 50% por la entidad local."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 6, "El principio de unidad de caja supone que", "Los derechos liquidados por operaciones corrientes se destinarán a financiar las obligaciones reconocidas por operaciones corrientes.", "Los recursos de las Entidades Locales, de los Organismos Autónomos y de las Sociedades Municipales se destinarán a satisfacer, sin excepción, el conjunto de las obligaciones que como máximo se podrán reconocer.", "Los derechos liquidados de las partidas de financiación afectada se destinarán a satisfacer el conjunto de las obligaciones reconocidas.", "Los recursos de las Entidades Locales, de los Organismos Autónomos y de las Sociedades Municipales se destinarán a satisfacer el conjunto de las obligaciones que como máximo se podrán reconocer, salvo en el caso de ingresos específicos afectados a fines determinados."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 7, "El principio de equilibrio presupuestario supone que", "Todos los presupuestos que integran el Presupuesto General deberán aprobarse sin déficit inicial.", "El Presupuesto General de la Entidad Local, en su conjunto, debe estar equilibrado.", "El equilibrio presupuestario obliga a que, en atención a lo dispuesto en la Ley Orgánica 2/2017, de Estabilidad Presupuestaria, la liquidación del Presupuesto General aprobado, presente un superávit.", "Los presupuestos de las sociedades mercantiles cuyo capital social esté participado al 100% por la Entidad Local, presenten un beneficio inicial."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 8, "El principio de publicidad del presupuesto implica que", "El Presupuesto General definitivamente aprobado será insertado en el Boletín Oficial de la Comunidad Autónoma con antelación al 31 de diciembre.", "El Presupuesto General inicialmente aprobado se expondrá al público, previo anuncio en el Boletín Oficial de la Comunidad Autónoma, durante el plazo de un mes para que los interesados puedan examinarlo y presentar alegaciones al mismo.", "El Presupuesto General definitivamente aprobado entrará en vigor, en el ejercicio correspondiente, una vez publicado en el Boletín Oficial de la Comunidad Autónoma.", "En atención a lo dispuesto en la Ley 19/2013, de 9 de diciembre, de Transparencia, acceso a la información pública y buen gobierno, la Corporación municipal podrá sustituir la publicación de la aprobación inicial del Presupuesto General en el Boletín Oficial de la Comunidad Autónoma, por la publicación de dicha aprobación inicial en el Portal de Transparencia de la página web municipal."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 9, "Una modificación del presupuesto mediante la generación de crédito por un ingreso de naturaleza no tributaria puede financiarse mediante", "El reembolso de préstamos concedidos por la Entidad Local.", "La suscripción de una operación de préstamo a largo plazo destinada a financiar una inversión no prevista.", "La liquidación complementaria de una Tasa de recogida de residuos de una vivienda destinada al turismo vacacional.", "La suscripción de una póliza de crédito a corto plazo para cubrir un déficit transitorio de tesorería."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 10, "Para realizar una ampliación de crédito del presupuesto se requerirá", "La aprobación del expediente de ampliación de crédito mediante la adopción de un acuerdo por parte del Pleno municipal.", "Que los recursos afectados procedan de una operación de endeudamiento a largo plazo.", "Que la aplicación presupuestaria ampliable y el ingreso afectado se relacionen expresamente en las Bases de Ejecución del presupuesto definitivamente aprobado.", "Que el importe efectivamente recaudado en concepto del ingreso afectado sea igual al importe previsto en el presupuesto definitivamente aprobado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 11, "En la tramitación de un expediente de Incorporación de Remanentes de Crédito, se podrán incorporar", "Las obligaciones reconocidas aprobadas por los órganos competentes de la Corporación con antelación al 31 de diciembre de cada ejercicio presupuestario.", "Las transferencias de crédito aprobadas en el último trimestre del ejercicio presupuestario.", "Los créditos por operaciones corrientes disponibles al 31 de diciembre.", "Todos los suplementos de crédito aprobados durante el ejercicio presupuestario."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 12, "La competencia para la disposición y la autorización de gastos de carácter plurianual corresponderá", "Al Pleno municipal cuando su duración sea superior a cuatro años y el importe acumulado de todas las anualidades supere el 10% de los recursos ordinarios del presupuesto del primer ejercicio de la plurianualidad.", "Al Alcalde cuando su duración sea superior a cuatro años y el importe acumulado de todas las anualidades no supere el 10% de los recursos ordinarios del presupuesto del primer ejercicio de la plurianualidad.", "Al Alcalde cuando su duración sea inferior a cuatro años y el importe acumulado de todas las anualidades supere el 10% de los recursos ordinarios del presupuesto del primer ejercicio de la plurianualidad.", "Al Pleno municipal cuando su duración sea inferior a cuatro años y el importe acumulado de todas las anualidades supere el 10% de los recursos ordinarios del presupuesto del primer ejercicio de la plurianualidad."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 13, "La competencia para la concertación de operaciones de endeudamiento a corto plazo compete al Alcalde cuando", "El importe acumulado de las operaciones vivas, incluida la nueva operación de endeudamiento, no supera el 15% de los recursos corrientes del presupuesto actual.", "El importe acumulado de las operaciones vivas, incluida la nueva operación de endeudamiento, no supera el 15% de los recursos corrientes liquidados en el ejercicio presupuestario anterior.", "El importe acumulado de las operaciones vivas, incluida la nueva operación de endeudamiento, no supera el 25% de los recursos corrientes liquidados en el ejercicio presupuestario anterior.", "El importe acumulado de las operaciones vivas, incluida la nueva operación de endeudamiento, en ningún caso supone un límite a la autorización por parte del Alcalde de la nueva operación de endeudamiento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 14, "La competencia para la concertación de operaciones de endeudamiento a largo plazo previstas en el presupuesto compete al Pleno de la Corporación cuando", "El importe acumulado de las operaciones de endeudamiento a largo plazo dentro de cada ejercicio económico no supera el 15% de los recursos corrientes liquidados en el ejercicio presupuestario anterior.", "El importe acumulado de las operaciones de endeudamiento a largo plazo dentro de cada ejercicio económico no supera el 10% de los recursos de carácter ordinario previstos en el presupuesto aprobado.", "El importe acumulado de las operaciones de endeudamiento a largo plazo dentro de cada ejercicio económico no podrá superar el importe previsto para el capítulo de inversiones del presupuesto actual.", "El importe acumulado de las operaciones de endeudamiento a largo plazo dentro de cada ejercicio económico supera el 10% de los recursos de carácter ordinario previstos en el presupuesto aprobado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 15, "De los siguientes presupuestos, ¿cuál de ellos no se integrará en el Presupuesto General de la Entidad Local?", "El presupuesto de un organismo autónomo para la gestión y recaudación de los tributos municipales.", "El presupuesto de una sociedad mercantil cuyo capital social está participado en un 75% por el Ente Local.", "El presupuesto de un Consorcio adscrito a la EL para el fomento del empleo local.", "El presupuesto de una sociedad mercantil cuyo capital social esté íntegramente participado por el Ente Local."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 16, "Indique que límite opera para los créditos de las partidas del presupuesto de gastos", "El límite cuantitativo; importe que como máximo se puede gastar.", "El límite cualitativo; destino o finalidad del crédito presupuestario", "El límite temporal; determinado por el propio principio de anualidad del presupuesto", "Los límites cuantitativo, cualitativo y temporal en su conjunto."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 17, "La elaboración del Presupuesto General de una Entidad Local se realiza bajo un criterio", "Jurídico, en atención a los compromisos legales-contractuales adquiridos o que se prevé adquirir (contratos, préstamos, pactos, ), normativa tributaria de aplicación, concesiones administrativas.", "De caja, a partir de la corriente real de cobros y pagos que se prevé liquidar y reconocer.", "Del devengo económico, de acuerdo con lo que dispone la contabilidad económico-patrimonial.", "Tributario, de acuerdo con lo que disponen las ordenanzas fiscales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 18, "El presupuesto de ingresos de la Entidad Local tiene carácter estimativo, ello implica que", "La estimación del ingreso previsto se realiza a partir de la información histórica disponible.", "La cifra de ingreso presupuestada supone un tope en el importe de ingreso anual.", "Los derechos que se reconozcan en el ejercicio pueden ser superiores a los contenidos en el presupuesto definitivamente aprobado.", "En caso que los derechos liquidados en el ejercicio sean superiores a los contenidos en el presupuesto aprobado, deberá incorporarse el preceptivo informe del Interventor municipal."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 19, "De la siguiente documentación referida a la Entidad local, indique cuál de ellas no se requiere su incorporación al Presupuesto General", "Estado de consolidación del presupuesto.", "Bases de ejecución del presupuesto.", "Documento con la proyección del estado de ingresos y gastos del Presupuesto General para los próximos años.", "Documento Anexo con las inversiones previstas en el ejercicio."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 20, "¿Cómo se clasifica el presupuesto de gastos?", "Mediante una clasificación Orgánica, por Programas y Económica.", "Mediante una clasificación Económica.", "Mediante una clasificación conjunta por Programas y Económica.", "Mediante una clasificación Orgánica y Económica."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 21, "¿Cómo se clasifica el presupuesto de ingresos?", "De idéntica manera que el presupuesto de gastos.", "Mediante una clasificación Orgánica.", "Mediante una clasificación Económica.", "Mediante una clasificación Orgánica y Económica."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 22, "¿A qué órgano o departamento municipal le corresponde la formación del Presupuesto General?", "A la Junta de Gobierno Local.", "Al Director de los Servicios Económicos municipales.", "Al Presidente de la Corporación Local.", "Al Pleno de la Corporación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 23, "¿Contra el acuerdo de aprobación definitiva del Presupuesto General, podrá interponerse?", "Recurso Contencioso Administrativo.", "Recurso ante el Tribunal Económico-Administrativo Regional de las Illes Balears.", "Recurso ante el Tribunal de Cuentas.", "Recurso de Reposición previo al Recurso Contencioso Administrativo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 24, "Podrá adquirirse un compromiso de gasto de carácter plurianual en el siguiente caso:", "Para atender los acuerdos recogidos en el Pacto de Funcionarios relativos a incrementos de remuneraciones al cuerpo de funcionarios municipales.", "Para atender las cargas financieras de las deudas de la entidad local y de sus organismos autónomos.", "Para atender los compromisos económicos adquiridos con los acuerdos de la carrera profesional.", "Para atender el contrato para la compra de un vehículo moto-bomba para el parque de bomberos municipal."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 25, "Podrán darse bajas por anulación de créditos en los siguientes casos:", "Mediante informe previo motivado suscrito por la Dirección de los Servicios Económicos municipales.", "A petición del responsable del Área gestora del crédito presupuestario.", "Por no estar al 31 de diciembre afecto al cumplimiento de obligaciones ya reconocidas.", "Por incluirse en el expediente de incorporación de créditos al ejercicio presupuestario siguiente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 26, "Siempre y cuando existan recursos financieros disponibles, podrán incorporarse a los correspondientes créditos del presupuesto de gastos del ejercicio inmediato siguiente", "Los créditos presupuestarios por operaciones de capital.", "Las retenciones de crédito de los créditos presupuestarios por operaciones corrientes.", "Las modificaciones de crédito que hayan sido concedidas o autorizadas a lo largo del ejercicio presupuestario.", "Todos los créditos disponibles a la finalización del ejercicio presupuestario."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 27, "La Cuenta General formada por la Intervención Municipal será sometida a informe por parte de:", "La Junta de Gobierno Local.", "La Comisión Informativa de Asuntos Generales.", "El Tesorero municipal, de acuerdo con lo que dispone el RD 128/2018, de 16 de marzo, por el que se regula el régimen jurídico de los funcionarios de Administración Local con habilitación de carácter nacional.", "La Comisión Especial de Cuentas de la Entidad Local."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 28, "En qué momento deberá la Cuenta General ser sometida a Informe:", "Al día siguiente de su formación por la Intervención municipal.", "En el plazo de 15 días hábiles a contar desde el día siguiente a su formación por la Intervención municipal.", "Antes del día 1 de junio de cada año.", "No existe un plazo determinado para ser sometida a informe."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 29, "De las siguientes políticas de gasto, ¿cuál de ellas se incluye en el Área de Producción de Bienes y Servicios de Carácter Preferente?", "Transporte público.", "Deportes.", "Comercio y turismo.", "Servicios sociales y promoción social."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 30, "La política de gasto de Bienestar Comunitario se halla incluida dentro del Área de gasto de:", "Servicios públicos básicos.", "Actuaciones de protección y promoción social.", "Actuaciones de carácter general.", "Actuaciones de carácter económico."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 31, "Se entiende por incorporación de crédito la operación mediante la cual", "Se autorizan créditos ordinarios.", "Se aprueban suplementos de crédito.", "Se agregan remanentes de crédito al presupuesto ordinario.", "Se autorizan créditos extraordinarios."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 32, "La acumulación de las distintas fases de ejecución del presupuesto de gastos obedece a criterios de", "Oportunidad.", "Racionalidad en el pago de las obligaciones.", "Economía y agilidad administrativa.", "No se pueden acumular las distintas fases de ejecución del prepuesto de gastos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 33, "El principio de universalidad aplicado al presupuesto general de una Entidad Local implica que:", "Solo existe un presupuesto.", "Todos los ingresos y gastos han de figurar en el presupuesto.", "Es un presupuesto general.", "Únicamente contempla el presupuesto de la Corporación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 34, "Las estimaciones de los distintos recursos económicos a liquidar durante el ejercicio presupuestario se contienen en", "El estado de previsión de ingresos y gastos.", "La previsión de ingresos.", "El estado de ingresos.", "El estado de gastos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 35, "El remanente liquido de tesorería con el que se financia un crédito extraordinario o un suplemento de crédito está integrado por", "Los mayores ingresos efectivamente recaudados respecto de los previstos.", "El saldo de las retenciones de crédito pendientes de aplicar.", "Las anulaciones o bajas de créditos.", "Los derechos pendientes de cobro, las obligaciones pendientes de pago y los fondos líquidos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 36, "Una vez aprobado inicialmente el Presupuesto General de la Entidad Local, este se expondrá al público por un plazo de", "Diez días naturales.", "Quince días.", "Un mes hábil.", "Un mes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 37, "Según la Orden EHA/3565/2008, por la que se aprueba la estructura de presupuestos de las Entidades Locales, en la clasificación económica de los gastos, el capitulo 3 se refiere", "Transferencias corrientes.", "Activos financieros.", "Pasivos Financieros.", "Gastos financieros."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 38, "El ciclo presupuestario de las Entidades Locales, tienen una duración de", "Un año.", "Desde el momento de la entrada en vigor hasta la finalización del ejercicio presupuestario.", "Hasta el final del periodo de legislatura.", "Desde el momento de incorporación de remanentes hasta la liquidación del presupuesto."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 39, "Cuál es el quórum requerido para la aprobación del Presupuesto General de la Entidad Local", "Una mayoría cualificada.", "Por mayoría absoluta del número legal de miembros de la Corporación.", "Por mayoría simple.", "Por una mayoría de dos tercios del número legal de miembros de la Corporación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 40, "A la fase de ejecución presupuestaria con la que se procede a la Ordenación del Pago se denomina", "Fase OR.", "Fase P.", "Fase OP.", "Fase RP."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 41, "Dentro del proceso de ejecución presupuestaria, la fase correspondiente al Reconocimiento de la Obligación es", "Anterior a la ordenación del pago y posterior al compromiso del gasto.", "Posterior a la ordenación del pago y anterior a la liquidación del gasto.", "Anterior a la autorización del gasto y posterior a la disposición del mismo.", "Posterior a la retención del crédito y anterior a la disposición del gasto ."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 42, "Las reglas que deben seguirse en el ejecución del presupuesto están contenidas en", "La Memoria explicativa del contenido del Presupuesto General de la Entidad Local.", "Las delegaciones de gastos con la asignación de competencias al Pleno, al Alcalde o a los Tenientes de Alcalde, según sea la cuantía del gasto a incurrir.", "Las Bases de Ejecución del presupuesto, adaptando las disposiciones legales en materia presupuestaria a la organización y circunstancias de la propia Entidad Local.", "El Informe Económico-Financiero donde se recogen las bases utilizadas para la elaboración y ejecución del presupuesto."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 43, "Dentro de la clasificación económica del estado de gastos, las partidas presupuestarias  se desarrollan por", "Los subprogramas.", "Las subfunciones.", "Los programas.", "Los subconceptos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 44, "En el proceso de ejecución del presupuesto no se podrán acumular las fases de", "Autorización y disposición de créditos.", "Autorización y disposición de créditos y reconocimiento de la obligación.", "Retención y autorización del crédito.", "Autorización, disposición de créditos, reconocimiento de la obligación y ordenación del pago."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 45, "La función fiscalizadora a cargo de la Intervención Municipal se producirá en la fase de", "Autorización del gasto.", "Reconocimiento de la obligación.", "Ordenación del pago.", "La función fiscalizadora se producirá en todas las fases de la ejecución del presupuesto."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 46, "En el supuesto de que el Pleno de la Corporación no resuelva las reclamaciones presentadas en el periodo de exposición al público del presupuesto inicialmente aprobado,", "Se entenderán desestimadas las reclamaciones presentadas.", "Se relegará la aprobación definitiva del presupuesto hasta su resolución.", "Se incorporarán las mismas al presupuesto.", "Se entenderán estimadas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 47, "Una vez aprobado definitivamente el Presupuesto General de la Entidad Local, deberá existir una copia a disposición del público", "Durante el plazo de dos meses a contar desde su publicación.", "Durante el plazo de quince días a contar desde su aprobación definitiva.", "Por el plazo de un año.", "Hasta la finalización del ejercicio presupuestario."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 48, "Finalizado el plazo de exposición al público del presupuesto inicialmente aprobado, no se requerirá acuerdo expreso de aprobación definitiva cuando:", "Exista un informe favorable del Interventor Municipal y así lo proponga al Presidente de la Corporación.", "Al término del periodo de exposición se hubiesen presentado alegaciones y/o reclamaciones al mismo.", "Exista el pleno consenso entre los diferentes grupos políticos que conforman el Consistorio.", "Al término del periodo de exposición no se hubiesen presentado alegaciones y/o reclamaciones al mismo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 49, "La aprobación de los presupuestos que integran el Presupuesto General de una Entidad Local con déficit inicial", "Se admite de manera excepcional.", "Se permite cuando a lo largo del ejercicio al que se refieran pueda producirse la nivelación de todos los presupuestos.", "No se permite la aprobación inicial de los presupuestos con déficit inicial.", "Obliga a una inmediata compensación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 50, "Una vez emitido el informe del presupuesto por la Intervención Municipal, el Presidente de la Entidad Local lo remitirá al Pleno de la Corporación", "Antes del 15 de noviembre para su aprobación, enmienda o devolución.", "Antes del 31 de octubre para su aprobación, enmienda o devolución.", "Podrá remitirlo en cualquier momento, siempre y cuando sea antes del 31 de diciembre, para su aprobación, enmienda o devolución.", "Antes del 15 de octubre para su aprobación, enmienda o devolución."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 51, "El control interno del gasto público de la Entidad Local será ejercido", "Por la Comisión Especial de Cuentas.", "Por el Tribunal de Cuentas.", "Por la Intervención local.", "Por el Pleno de la Corporación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 52, "El informe del Tribunal de Cuentas está previsto para el supuesto en que:", "Se lo requiera un órgano jurisdiccional competente cuando la impugnación se refiera a la nivelación presupuestaria.", "El presupuesto se apruebe fuera del plazo señalado para ello.", "Se haya prescindido del periodo de exposición al público del presupuesto inicialmente aprobado.", "Se cometa cualquier irregularidad en el proceso de elaboración y aprobación del presupuesto."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 53, "En la clasificación económica de los ingresos, la Enajenación de Inversiones Reales tiene la consideración de:", "Una operación económica.", "Una operación de capital.", "Una operación financiera.", "Una operación corriente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 54, "De entre las siguientes opciones, indíquese cuál de ellas no constituye uno de los objetivos del Control Interno", "Corregir las deficiencias detectadas.", "Exigir las correspondientes responsabilidades.", "Tomar decisiones para la elaboración y aprobación del Presupuesto General de la Entidad Local.", "Reforzar la necesaria transparencia en la gestión pública."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 55, "El control interno se concreta en la vigilancia de los aspectos formales y materiales de", "Todas las operaciones y las fases de ejecución de los créditos del presupuesto de gastos.", "La suscripción de las operaciones de endeudamiento a largo plazo previstas en el estado de ingresos del Presupuesto General.", "Todas las operaciones que puedan generar un gasto o bien el reconocimiento de un derecho para la Entidad Local.", "Únicamente se realizará un control interno sobre la recaudación de los tributos municipales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 56, "El control que se realiza sobre la actividad económico-financiera de una Entidad Local contempla", "Un control interno realizado por un órgano de la propia Administración Local.", "Un control interno realizado por un órgano de la propia Administración Local y un control externo realizado por una institución pública ajena a la Entidad Local.", "Un control externo realizado por el Tribunal de Cuentas.", "Un control externo realizado por un auditor de cuentas contratado por la Entidad Local al efecto."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 57, "Constituye un órgano de control externo de las Comunidades Autónomas", "Las Sindicaturas de Cuentas.", "La Intervención General de la Comunidad Autónoma.", "Los Consejos Consultivos.", "El Tribunal Económico-Administrativo Regional."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 58, "El control realizado por la Intervención local se realiza a través de", "La función interventora y el control de eficacia.", "El control financiero y el control de eficiencia.", "La fiscalización de todas las operaciones de Pago del presupuesto de gasto Fase P de la ejecución presupuestaria.", "La función interventora, el control financiero y el control de eficacia y eficiencia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 59, "El control al que se refiere el título VI del RDL 2/2004 del TRLRHL será ejercido sobre todas las entidades que conforman el sector público local, con excepción de:", "Los organismos autónomos dependientes de la Entidad Local.", "Los consorcios dotados de personalidad jurídica propia adscritos a la Entidad Local.", "Las entidades con o sin personalidad jurídica con participación minoritaria de la Entidad Local.", "Las sociedades mercantiles dependientes íntegramente de la Entidad Local."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 60, "En el ejercicio de la función interventora, se comprobará:", "Que el expediente se ajusta a la legalidad aplicable en cada caso.", "Que el expediente se ajusta a la legalidad aplicable en cada caso y a los principios de buena gestión económica.", "La conveniencia u oportunidad de llevar a cabo una actuación municipal con contenido económico.", "La adecuación de la actuación prevista a los principios de economía, eficacia y eficiencia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 61, "¿Qué fase de la función interventora corresponde realizar en el momento previo a la adjudicación de un contrato de servicios?", "La intervención previa.", "La toma de razón en la contabilidad presupuestaria.", "El compromiso del gasto Fase D de la ejecución presupuestaria.", "La fiscalización previa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 62, "El control financiero de la actividad económico-financiera del sector público local se ejercerá a través de sus dos modalidades, a saber:", "El control permanente y la auditoría pública.", "La función interventora y la auditoría de cuentas.", "La auditoría de cumplimiento y la auditoría operativa.", "El control interno planificado y el control permanente no planificado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 63, "En el ejercicio de la función interventora, la fiscalización previa de gastos propiamente dicha se realizará sobre los actos que den lugar a:", "Al reconocimiento de una obligación Fase O de la ejecución presupuestaria.", "A la ordenación del pago contra los recursos disponibles en la Tesorería de la Entidad Local Fase O de la ejecución presupuestaria.", "A la autorización del gasto y compromiso del mismo Fase A y D de la ejecución presupuestaria.", "A la disposición del gasto Fase D de la ejecución presupuestaria."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 64, "Las Administraciones Públicas que propongan el establecimiento de subvenciones deberán concretar con carácter previo", "Un plan estratégico de subvenciones.", "El crédito presupuestario necesario y suficiente para atender las subvenciones previstas.", "Las bases de ejecución del presupuesto conteniendo el detalle de las subvenciones previstas.", "El expediente administrativo de concesión de la subvención."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 65, "¿Cuál de las siguientes opciones no reúne los requisitos para ser considerada una subvención?", "Que la entrega se realice sin contraprestación directa de los beneficiarios.", "Que la entrega esté sujeta al cumplimiento de un determinado objetivo, la ejecución de un proyecto, la realización de una actividad, la adopción de un comportamiento singular, ya realizados o por desarrollar, o la concurrencia de una situación, debiendo el beneficiario cumplir las obligaciones materiales y formales que se hubieran establecido.", "Las aportaciones dinerarias a un Organismo Autónomo dependiente de la Entidad Local.", "Que el proyecto, la acción, conducta o situación financiada tenga por objeto el fomento de una actividad de utilidad pública o interés social o de promoción de una finalidad pública."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 66, "¿Cuál es el órgano competente para iniciar el procedimiento sancionador en materia de subvenciones?", "El órgano que hubiera formulado la propuesta de concesión de la subvención.", "El Pleno de la Corporación.", "Los Servicios Jurídicos de la Corporación.", "El Interventor municipal."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 67, "De acuerdo con la Ley General de Subvenciones, ¿cuál de los siguientes principios no es un principio general de las subvenciones públicas?", "Publicidad, trasparencia, concurrencia, objetividad, igualdad, no discriminación.", "Eficacia en el cumplimiento de los objetivos marcados por la Administración otorgante.", "Agilidad de los procedimientos administrativos y de las actividades materiales de gestión.", "Eficiencia en la asignación y utilización de los recursos públicos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 68, "De acuerdo con la Ley General de Subvenciones, se establece como procedimiento ordinario de concesión el de:", "Procedimiento negociado.", "Concurrencia competitiva.", "Subasta pública.", "Adjudicación directa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 69, "¿Pueden realizarse pagos a cuenta de subvenciones aun cuando no se hayan justificado los pagos anticipados?", "Sí, cuando así esté previsto en las bases de la correspondiente convocatoria.", "No, en ningún caso.", "Sí, siempre que se garantice el pago a cuenta por parte del beneficiario mediante un aval bancario.", "No, salvo autorización expresa del órgano concedente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 70, "En un expediente de concesión de subvención, ¿qué trámite sigue inmediatamente a la propuesta de resolución definitiva?", "La aceptación de la subvención.", "El trámite de audiencia al interesado.", "La resolución de la concesión.", "La justificación de la subvención."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 71, "¿Cuál es la normativa general mediante la cual se regulan las subvenciones?", "La Ley 28/2013, de 17 de diciembre, de Subvenciones Generales.", "La Ley 38/2006, de 17 de octubre, General de Subvenciones Públicas.", "La Ley 38/2003, de 17 de noviembre, General de Subvenciones.", "La Ley 38/2006, de 17 de noviembre, de Subvenciones Generales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 72, "En el ámbito de las subvenciones públicas, ¿en qué caso podrán imponerse sanciones no pecuniarias?", "En el caso de infracciones leves o graves.", "En el caso de infracciones muy graves.", "En el caso de infracciones leves, graves y muy graves.", "En el caso de infracciones graves o muy graves."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 73, "¿Qué es la Base de Datos Nacional de Subvenciones BDNS?", "Es el sistema que regula la concesión de subvenciones.", "Es el sistema nacional de publicidad de subvenciones.", "Es el sistema de control presupuestario de las subvenciones.", "Es el sistema de control financiero de las subvenciones."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 74, "¿Qué subvenciones tienen la consideración de nominativas?", "Las previstas como tales en las Bases de Ejecución del Presupuesto General de la Entidad Local.", "Las que resultan de una convocatoria pública.", "Las que no requieren de una aceptación por parte de beneficiario.", "Las que así se determinen por el Presidente de la Corporación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", None, 75, "En un expediente de concesión de subvención, ¿qué trámite sigue inmediatamente a la propuesta de resolución provisional?", "La propuesta de resolución definitiva.", "La resolución de la concesión de la subvención.", "La aceptación de la subvención.", "El trámite de audiencia al interesado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 1, "La sede electrónica de una Administración Pública es:", "La dirección electrónica de una Administración disponible para la ciudadanía a través de redes de telecomunicaciones.", "La red de telecomunicaciones de la Administración que ofrece los servicios a toda la ciudadanía.", "El conjunto agrupado de todos los procedimientos administrativos inventariados y clasificados por unidades orgánicas pertenecientes a una Administración.", "El punto de acceso para la ciudadanía a las actuaciones que puede realizar con la Administración por medio de una autenticación electrónica."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 2, "¿Qué actuaciones y trámites se efectúan mediante la sede electrónica de una Administración Pública?", "Todas las actuaciones y trámites referidos a procedimientos o servicios que requieran la identificación de la Administración Pública y, en su caso, la identificación o firma electrónica de las personas interesadas.", "Todas las actuaciones y trámites referidos a procedimientos que requieran la identificación de la Administración Pública o aquellos servicios que requieran un asiento de registro de entrada dentro de la Administración Pública y, en su caso, la identificación o firma electrónica de la ciudadanía.", "Únicamente aquellas actuaciones y trámites referidos a procedimientos o servicios que estén implantados sobre una plataforma de tramitación telemática. Aquellas actuaciones o trámites que no dispongan de tramitación telemática, no tienen cabida en la sede electrónica.", "Todas las actuaciones y trámites referidos a procedimientos o servicios que requieran un asiento de registro de entrada dentro de la Administración Pública y, en su caso, la identificación o firma electrónica de la ciudadanía."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 3, "¿Puede corresponder la titularidad de una sede electrónica a más de un organismo público?", "No, puesto que siempre corresponde a una Administración Pública.", "No, puede corresponder a un organismo público, pero no a más de uno.", "Sí, en el ámbito de sus competencias.", "Sí, siempre que sea titular a la vez la Administración Pública de la que depende."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 4, "Señale la respuesta incorrecta, en materia de sede electrónica:", "El establecimiento de una sede electrónica conlleva la responsabilidad del titular respecto de la integridad, veracidad y actualización de la información y servicios a los que se pueda acceder a través de la sede.", "Las sedes electrónicas deben disponer de sistemas que permitan siempre establecer comunicaciones seguras.", "Las sedes electrónicas deben utilizar, para identificarse y garantizar una comunicación segura con estas sedes, certificados reconocidos o cualificados de autenticación de sitio web o medio equivalente.", "La publicación en las sedes electrónicas de informaciones, servicios y transacciones debe respetar los principios de accesibilidad y uso de acuerdo con las normas establecidas al respecto, estándares abiertos y, en su caso, aquellos otros que sean de uso generalizado por parte de los ciudadanos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 5, "Cada Administración Pública determinará las condiciones y los instrumentos de creación de las sedes electrónicas con sujeción, entre otros, a los principios de:", "Transparencia, publicidad, responsabilidad, calidad, seguridad, disponibilidad, accesibilidad, neutralidad e interoperabilidad.", "Transparencia, publicidad, responsabilidad, eficacia, seguridad, disponibilidad, accesibilidad, coordinación e interoperabilidad.", "Transparencia, desconcentración, responsabilidad, eficacia, seguridad, disponibilidad, accesibilidad, coordinación e interoperabilidad.", "Transparencia, publicidad, responsabilidad, calidad, seguridad, disponibilidad, accesibilidad, coordinación e interoperabilidad."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 6, "En materia de funcionamiento del sector público por medios electrónicos, ¿se pueden crear sedes electrónicas paralelas?", "No, este concepto no existe.", "Sí, por razones técnicas y organizativas; además, una vez creadas se pueden suprimir.", "Sí, por razones técnicas y procedimentales; sin embargo, una vez creadas no se pueden suprimir.", "No, la sede electrónica es única."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 7, "El proceso para crear una sede electrónica asociada es:", "La publicación del acto o resolución de creación de la sede electrónica asociada en el boletín oficial que corresponda en función de cuál sea la Administración Pública titular de la sede.", "La publicación en el directorio del Punto de Acceso General Electrónico que corresponda.", "La sede electrónica asociada no requiere ningún acto o resolución de creación, ya que únicamente se crea por razones técnicas y organizativas.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 8, "No forma parte de los elementos obligatorios que deben constar en el acto o resolución de creación de una sede electrónica de una Administración Pública:", "La identificación del titular del órgano responsable de la sede electrónica.", "La identificación del órgano u órganos encargados de la gestión y servicios puestos a disposición en la sede.", "La identificación de la dirección de la sede electrónica de referencia de la sede electrónica o sede electrónica asociada que se cree.", "El ámbito de aplicación de la sede electrónica o sede electrónica asociada."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 9, "¿Cuál de las siguientes normas técnicas de interoperabilidad hace referencia a la interconexión con la sede electrónica?", "Norma Técnica de Interoperabilidad del modelo de datos y condiciones de interoperabilidad de los registros de funcionarios habilitados.", "Norma Técnica de Interoperabilidad del modelo de datos y condiciones de interoperabilidad de los registros electrónicos de apoderamientos.", "Norma Técnica de Interoperabilidad de las condiciones de interconexión con las sedes  electrónicas.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 10, "No forma parte del contenido mínimo que toda sede electrónica o sede electrónica asociada debe poner a disposición de las personas interesadas:", "La identificación del acto o disposición de creación.", "El acceso al acto o disposición de creación.", "El ámbito de aplicación de la sede electrónica o sede electrónica asociada.", "La identificación de la dirección electrónica de referencia de la sede electrónica."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 11, "Cuanto a aspectos temporales, ¿cuál de los siguientes elementos es un contenido mínimo que debe disponer toda sede electrónica?", "La fecha oficial, así como el calendario de días inhábiles a efectos de comprobar la validez de un registro.", "La fecha y hora oficial, y, en su caso, el calendario de días inhábiles a efectos de comprobar la validez de un registro.", "El calendario de días hábiles a efectos del cómputo de plazos.", "La fecha y hora oficial, así como el calendario de días inhábiles a efectos del cómputo de plazos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 12, "¿Cuál de las siguientes no forma parte de la información necesaria que toda sede electrónica debe publicar para su correcta utilización?", "Mapa de la sede o información equivalente.", "Especificación de la estructura de navegación.", "Especificación de las distintas secciones disponibles.", "Mapa interactivo del menú."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 13, "El sistema de verificación de los certificados de la sede electrónica:", "Es un contenido que la sede puede poner a disposición de las personas interesadas.", "Es un contenido mínimo que toda sede electrónica o sede electrónica asociada debe poner a disposición de las personas interesadas.", "Es un servicio que la sede puede poner a disposición de las personas interesadas.", "Es un servicio mínimo que toda sede electrónica o sede electrónica asociada debe poner a disposición de las personas interesadas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 14, "La fecha y hora oficial, como un elemento mínimo que debe formar parte de la sede electrónica, ¿con qué organismo se sincronizará?", "Con el Centro Español de Predicción Metrológica.", "Con el Registro de Control Metrológico.", "Con el Real Instituto y Observatorio de la Armada.", "Con el Ministerio de Ciencia y Tecnología."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 15, "¿Quién es el responsable de los procedimientos que figuren en una sede electrónica asociada a la que se haya accedido a través de un enlace publicado en una sede electrónica?", "El titular de la sede electrónica contenida en el enlace, en todo caso.", "El titular de la sede electrónica asociada, en todo caso.", "El titular de la sede electrónica asociada, sin perjuicio de la debida diligencia del titular de la sede electrónica contenida en el enlace respecto de la incorporación de los contenidos en esta sede.", "Tanto el titular de la sede electrónica contenida en el enlace como el titular de la sede electrónica asociada."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 16, "¿Puede una sede electrónica contener procedimientos o servicios cuya competencia corresponda a un órgano de otra Administración?", "Sí, siempre que se indique explícitamente que el titular de esta sede no se hace responsable de la integridad, veracidad y actualización de lo referente a estos procedimientos o servicios.", "No, una sede sólo puede publicar procedimientos o servicios cuya competencia sea de un órgano de la propia Administración.", "Sí, y así mismo, la responsabilidad de la integridad, veracidad y actualización de lo referente a estos procedimientos o servicios es del titular de la competencia de estos procedimientos, sin perjuicio de la debida diligencia del titular de la sede electrónica respecto de la incorporación de los contenidos en esta sede.", "No, si quiere publicarlos debe poner un enlace o vínculo a la sede propietaria de los procedimientos o servicios."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 17, "Si una administración pública opta por utilizar un sistema de código seguro de verificación de documentos en el ejercicio de actuaciones automatizadas, este código:", "Permitirá en todo caso la comprobación de la integridad del documento en la sede electrónica o sede electrónica asociada correspondiente, y en su caso, en el portal del registro electrónico general, mediante un procedimiento de verificación directo y gratuito para las personas interesadas.", "Permitirá en todo caso la comprobación de la integridad del documento en la sede electrónica o sede electrónica asociada correspondiente mediante un procedimiento de verificación directo y gratuito para las personas interesadas.", "Permitirá en todo caso la comprobación de la integridad del documento en la sede electrónica o sede electrónica asociada correspondiente, y en su caso, con el sistema de custodia documental, mediante un procedimiento de verificación indirecto y gratuito para las personas interesadas.", "Permitirá en todo caso la comprobación de la integridad del documento en la sede electrónica o sede electrónica asociada correspondiente mediante un procedimiento de verificación indirecto y gratuito para las personas interesadas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 18, "Señale la respuesta incorrecta respecto a la relación de sellos electrónicos utilizados por cada Administración Pública:", "Esta relación incluirá las características de los certificados electrónicos.", "Esta relación será pública y accesible por medios electrónicos.", "Esta relación se publicará en la sede electrónica o sede asociada, y en el portal de internet correspondiente.", "Esta relación incluirá las características de los prestadores que los expiden."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 19, "El nivel de seguridad en la identificación electrónica exigido en los procedimientos y servicios que gestiona una entidad perteneciente al sector público:", "Se definirá y publicará en la sede electrónica.", "Se determinará en base a la accesibilidad universal, de acuerdo con el Esquema Nacional de Seguridad y la normativa correspondiente.", "Se determinará sobre la base del análisis de riesgos, de acuerdo con el Esquema Nacional de Interoperabilidad y la normativa correspondiente.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 20, "En una actuación administrativa automatizada llevada a cabo mediante un sistema de firma basado en un código seguro de verificación, ¿cómo debe garantizarse la interoperabilidad en las comunicaciones de documentos electrónicos a otros órganos, organismos o entidades?", "Con la superposición de un sello electrónico al código seguro de verificación.", "Con un sello electrónico seguro adjunto al documento electrónico.", "Con la superposición de una firma electrónica al código seguro de verificación.", "Con una firma electrónica del titular del órgano competente que ha elaborado el documento electrónico."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 21, "En materia de sistemas de firma electrónica del personal al servicio de las Administraciones Públicas, ¿cómo deben ser los certificados electrónicos de empleado público?", "Cualificados.", "Ajustados a lo establecido en el Esquema Nacional de Seguridad.", "Ajustados a la legislación vigente en materia de identidad y firma electrónica.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 22, "Dentro del conjunto de principios que el sector público debe respetar en sus actuaciones y relaciones electrónicas, ¿qué es el principio de interoperabilidad?", "La capacidad de los sistemas de información y, por ende, de los procedimientos a los que estos dan soporte, de compartir datos y posibilitar el intercambio de información entre ellos.", "La capacidad de los sistemas de información y, por ende, de los procedimientos a los que estos dan soporte, de compartir información y posibilitar el intercambio de datos entre ellos.", "La capacidad de los sistemas de información y, por ende, de los procedimientos a los que éstos dan soporte, de compartir datos o posibilitar el intercambio de información entre ellos.", "La capacidad de los sistemas de información y, por ende, de los procedimientos a los que estos dan soporte, de compartir información o posibilitar el intercambio de datos entre ellos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 23, "¿Cuál es el órgano técnico de cooperación de las administraciones públicas en materia de administración electrónica que asegura la compatibilidad e interoperabilidad de los sistemas y aplicaciones que utilizan las Administraciones Públicas?", "El Comité Sectorial de Administración Electrónica.", "La Comisión Sectorial de Administración Electrónica.", "La Conferencia Sectorial de Administración Electrónica.", "La Comisión Ministerial de Administración Electrónica."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 24, "¿Cuál de las siguientes funciones no desarrolla la Comisión Sectorial de Administración Electrónica?", "Asegurar la compatibilidad de los sistemas utilizados por las administraciones públicas.", "Preparar planes y programas conjuntos de actuación para impulsar el desarrollo de la administración electrónica en España.", "Asegurar la interoperabilidad de las aplicaciones utilizadas por las administraciones públicas.", "Asegurar la interconexión entre las administraciones públicas para proporcionar información administrativa clara, actualizada e inequívoca."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 25, "¿Cuál es el órgano competente para garantizar la interoperabilidad en materia de ciberseguridad y criptografía?", "Centro Criptográfico Nacional, adscrito al Centro Nacional de Inteligencia.", "Centro Criptológico Nacional, adscrito al Centro Nacional de Interoperabilidad.", "Centro Criptológico Nacional, adscrito al Centro Nacional de Inteligencia.", "Centro Criptográfico Nacional, adscrito al Centro Nacional de Interoperabilidad."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 26, "¿Cuál de las siguientes opciones no se considera un principio específico del Esquema Nacional de Interoperabilidad?", "El enfoque de soluciones multidimensionales.", "El carácter multilateral de la interoperabilidad.", "La interoperabilidad como elemento integrado con la calidad.", "Todas las respuestas son incorrectas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 27, "En el ámbito de la administración electrónica y de acuerdo con la Norma Técnica del Expediente Electrónico, señale la opción incorrecta sobre el índice electrónico de un expediente electrónico:", "El índice electrónico debe garantizar la integridad del expediente electrónico.", "El índice electrónico debe permitir la recuperación del expediente electrónico, siempre que sea necesario.", "El índice electrónico recoge el conjunto de documentos electrónicos asociados al expediente y se crea una vez que el expediente se cierra.", "El índice electrónico es uno de los componentes del expediente electrónico."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 28, "En materia de interoperabilidad, ¿cómo se aprueba una Norma Técnica de Interoperabilidad?", "Mediante una Resolución.", "Mediante una Orden Ministerial.", "Mediante un Real Decreto.", "Mediante un Acuerdo de Consejo de Ministros."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 29, "¿Cuál de las siguientes opciones no es una Norma Técnica de Interoperabilidad?", "Catálogo de estándares.", "Política de firma electrónica y de certificados de la administración.", "Relación de modelos de datos.", "Reutilización de datos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 30, "En el ámbito de la administración electrónica y de acuerdo con la Norma Técnica de Digitalización de Documentos, ¿cuál es uno de los requisitos de la imagen electrónica?", "La imagen electrónica respetará la geometría del documento origen en tamaño, sin perjuicio de que pueda tener proporciones distintas.", "La imagen electrónica no puede contener caracteres o gráficos que no figuren en el documento origen.", "La resolución máxima de la imagen electrónica será de 200 píxeles por pulgada.", "La imagen electrónica debe aplicar los formatos establecidos para ficheros de imagen en la Norma Técnica de Interoperabilidad de Catálogo de Formatos Estándares."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 31, "La red SARA es la red de comunicaciones establecida para conectar e intercomunicar a las Administraciones Públicas Españolas. ¿Dónde están establecidas las condiciones para que una Administración Pública pueda acceder a ella?", "En el Esquema Nacional de Interoperabilidad.", "En el Esquema Nacional de Seguridad.", "En una Norma Técnica de Interoperabilidad.", "En una guía de aplicación de una norma técnica."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 32, "Señale la respuesta correcta en relación con las Normas Técnicas de Interoperabilidad:", "El registro electrónico de apoderamientos está tratado en la misma Norma Técnica de Interoperabilidad que trata el registro electrónico general.", "Existe una Norma Técnica de Interoperabilidad que trata el registro electrónico de apoderamientos.", "Existe una Norma Técnica de Interoperabilidad conjunta que trata tanto el registro electrónico de apoderamientos y como el de funcionarios habilitados.", "No existe ninguna Norma Técnica de Interoperabilidad que trate el registro electrónico de apoderamientos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 33, "De acuerdo con el Real Decreto 203/2021, de 30 de marzo, por el que se aprueba el Reglamento de actuación y funcionamiento del sector público por medios electrónicos, ¿qué no trata la Norma Técnica de Modelo de Datos para el intercambio de asentamientos entre las Entidades Registrales?", "Los aspectos funcionales y técnicos para el intercambio de asientos registrales.", "La gestión de errores y excepciones.", "La gestión de anexos.", "La digitalización."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 34, "De acuerdo con la Norma Técnica de Documento Electrónico, ¿cuáles son los componentes obligatorios de un documento electrónico?", "Contenido, firma electrónica y metadatos del documento electrónico.", "Contenido y metadatos del documento electrónico.", "Contenido, índice electrónico, firma electrónica y metadatos del documento electrónico.", "Contenido y sello electrónico del órgano responsable del documento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 35, "De acuerdo con el Real Decreto 203/2021, de 30 de marzo, por el que se aprueba el Reglamento de actuación y funcionamiento del sector público por medios electrónicos, ¿cuál es la definición de Sistema de Interconexión de Registros?", "La infraestructura básica que permite el intercambio de asientos electrónicos de registro entre las Administraciones Públicas.", "El instrumento que presta servicios de interconexión técnica, organizativa y jurídica entre sistemas de información para un conjunto de Administraciones Públicas bajo las condiciones que estas administraciones fijen.", "La infraestructura que permita la integración, como servicio o como producto, tanto de carácter horizontal como sectorial, entre las distintas plataformas registrales de simplificación administrativa.", "El instrumento que tiene por objeto definir la forma correcta de intercambiar o almacenar los datos de un asiento registral y garantizar su seguridad, conservación e interoperabilidad."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 36, "De acuerdo con la normativa Real Decreto 203/2021, de 30 de marzo, por el que se aprueba el Reglamento de actuación y funcionamiento del sector público por medios electrónicos, las aplicaciones para el tratamiento del Registro Electrónico General, ¿tendrán que permitir interoperabilidad con las herramientas de gestión de expedientes?", "Sí, en el ámbito de la Administración General del Estado.", "No, la ley no hace referencia a ésta de interoperabilidad.", "Sí, en el ámbito de todas las Administraciones Públicas.", "No, la ley recomienda esta interoperabilidad pero no la requiere."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 37, "De forma general, ¿qué versión del protocolo SCSP (Sustitución de Certificados en Soporte Papel) se usa en los servicios de intercambio de datos y documentos entre administraciones públicas?", "La versión 1.", "La versión 2.", "La versión 3.", "Las versiones 2 o 3, de acuerdo con las capacidades técnicas del agente Cedente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 38, "En materia de los intercambios intermediados de datos entre Administraciones Públicas, ¿cuál es el agente que colabora en las tareas de auditoría cuando sea requerido para ello, y facilita al Cedente la información o documentos necesarios para el control de las consultas?", "El cedente", "El emisor.", "El cesionario.", "El requirente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 39, "En materia de los intercambios intermediados de datos entre Administraciones Públicas y referente a las autorizaciones de acceso a los servicios, ¿cuál es el agente que define la política de auditoría y realizará auditorías periódicas sobre el uso del sistema relativo a las consultas de sus datos?", "El cedente", "El emisor.", "El cesionario.", "El requirente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 40, "En materia de los intercambios intermediados de datos entre Administraciones Públicas, ¿qué agente actúa como emisor a la vez que como cedente?", "Un cedente que facilita la cesión de sus propios datos.", "Un emisor que facilita la cesión de sus propios datos.", "Un cesionario que realiza directamente la consulta de sus propios datos.", "Un requirente que realiza directamente la consulta de sus propios datos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 41, "En materia de los intercambios intermediados de datos entre Administraciones Públicas, ¿qué agente mantendrá la traza de todas las peticiones recibidas y respuestas generadas?", "El cedente", "El emisor.", "El cesionario.", "El requirente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 42, "¿Quién puede adherirse al convenio de colaboración en materia de interoperabilidad telemática entre las administraciones públicas del ámbito territorial de las Illes Balears?", "Es un convenio cerrado, sin posibilidad de adherirse al mismo.", "Cualquier administración pública del estado español.", "Los organismos públicos y las entidades de derecho público vinculados o dependientes de las administraciones públicas, en todo caso.", "Todas son incorrectas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 43, "¿Quién no forma parte de la Comisión de Seguimiento del convenio de colaboración en materia de interoperabilidad telemática entre las administraciones públicas del ámbito territorial de las Illes Balears?", "El coordinador del departamento de Nuevas Tecnologías del Consell de Formentera.", "El Director General de Modernización y Administración Digital de la Comunidad Autónoma de las Illes Balears.", "El jefe de la Sección de Sistemas de Información y Seguridad del Consell de Eivissa.", "Todos los anteriores cargos forman parte de la misma."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 44, "En materia de interoperabilidad telemática, ¿qué son los servicios propios?", "Son aquellos que permiten a los entes adscritos al convenio de colaboración en materia de interoperabilidad telemática entre las administraciones públicas del ámbito territorial de las Iles Baleare, compartir e intercambiar información mediante la Plataforma de Interoperabilidad de las Illes Balears .", "Son aquellos servicios que ofrece la Administración General del Estado y que pueden consultarse mediante la Plataforma de Interoperabilidad de las Illes Balears.", "Son aquellos servicios cuya consulta no requiere acceder a la Plataforma de Interoperabilidad de las Illes Balears, ya que son accesibles directamente a través de la intranet.", "Son aquellos servicios de verificación y consulta de datos prestados por un órgano de la propia Administración Pública."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 45, "¿Cómo se aprueba la Norma Técnica de Interoperabilidad de Protocolos de intermediación de datos?", "Mediante la resolución de 28 de junio de 2010, de la Secretaría de Estado de Administraciones Públicas.", "Mediante el Real Decreto 4/2010 de 8 de enero de 2010.", "Mediante la resolución de 28 de junio de 2012, de la Secretaría de Estado de Administraciones Públicas.", "Mediante el Real Decreto 203/2010 de 30 de marzo de 2021."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 46, "Indique la respuesta incorrecta en relación con la aportación de documentos por parte de las personas interesadas:", "La Administración de la Comunidad Autónoma de las Illes Balears no debe exigir la aportación de documentos si éstos están incorporados a la carpeta documental.", "Las administraciones públicas no deben exigir a la ciudadanía la presentación de documentación si ésta consta en el Catálogo de simplificación documental.", "Los interesados tienen derecho a no aportar documentos que ya se encuentren en poder de la Administración actuante.", "Las copias que aporten los interesados en el procedimiento administrativo tendrán eficacia, exclusivamente, en el ámbito de la actividad de las administraciones públicas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 47, "Indique la respuesta correcta en relación con la aportación de documentos en un procedimiento administrativo:", "Los ciudadanos deben aportar los datos y los documentos exigidos por las administraciones públicas de acuerdo con lo dispuesto en la normativa aplicable.", "Los interesados deben aportar los datos y los documentos exigidos por las administraciones públicas de acuerdo con lo dispuesto en la normativa aplicable.", "Los interesados deben aportar los datos y los documentos exigidos por las administraciones públicas.", "Los ciudadanos deben aportar los datos y los documentos exigidos por las administraciones públicas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 48, "En relación con los documentos que el interesado no debe aportar a un procedimiento, ¿cómo debe obtener la Administración actuante estos datos que están en poder de otra administración?", "Mediante la consulta a las plataformas de intermediación de datos u otro sistema electrónico habilitado al efecto, por este orden.", "Mediante los sistemas electrónicos habilitados al efecto, la consulta a las plataformas de intermediación de datos o las redes corporativas, indistintamente.", "Mediante las redes corporativas, la consulta a las plataformas de intermediación de datos u otros sistemas electrónicos habilitados al efecto, por este orden.", "Mediante la plataforma de intermediación de datos y, en su defecto, el envío de oficios con el sistema VALIB."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 49, "Indique la respuesta correcta. ¿En qué casos el interesado no puede oponerse a que la Administración actuante obtenga los datos en poder de otra administración?", "Cuando la aportación del documento se exige en el marco del ejercicio de potestades sancionadoras.", "Cuando la aportación del documento se exige en el marco del ejercicio de potestades tributarias.", "Cuando la aportación del documento se exige en el marco del ejercicio de potestades de inspección.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 50, "Indique la respuesta incorrecta:", "Las administraciones públicas pueden exigir la presentación de documentos originales a los interesados, en determinados casos.", "Las administraciones públicas no podrán exigir, en ningún caso, la presentación de documentos originales a los interesados.", "Excepcionalmente, la normativa reguladora del procedimiento puede establecer la exigencia de presentar documentos originales a los interesados.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 51, "Si un ciudadano que tiene la condición de interesado en un procedimiento no quiere aportar un determinado documento por el hecho de haberlo presentado antes ante otra Administración:", "Debe indicar día y hora en el que presentó el documento ante la otra Administración.", "Debe indicar cuándo, dónde y por qué presentó el documento ante la otra Administración.", "Debe indicar en qué momento y ante qué órgano administrativo presentó el documento.", "Debe indicar ante qué órgano administrativo presentó el documento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 52, "En relación con el derecho a no aportar documentos a la Administración Pública:", "Es un derecho de los ciudadanos que tienen reconocida su condición de interesados en el procedimiento.", "Es un derecho de los ciudadanos, en general.", "Es un derecho de las personas interesadas.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 53, "¿Puede oponerse un interesado a aportar determinada documentación en el procedimiento administrativo?", "No, los interesados deben aportar al procedimiento los datos y documentos exigidos por las administraciones públicas de acuerdo con lo establecido en la normativa aplicable.", "Sí, en cualquier caso.", "Hay casos en los que el interesado tiene derecho a no aportar documentos.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 54, "Si un interesado tiene derecho a no aportar un determinado documento en el procedimiento porque éste está en poder de otra administración:", "La Administración actuante debe consultar los datos por medios telemáticos, siempre que tenga el consentimiento expreso del interesado.", "La Administración actuante debe consultar los datos por medios telemáticos, siempre que tenga el consentimiento tácito del interesado.", "La Administración actuante debe consultar los datos por medios telemáticos, aunque el interesado se oponga a ellos.", "La Administración actuante debe consultar los datos por medios telemáticos, salvo que el interesado se oponga."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 55, "Cuando la Administración actuante debe recabar un documento en poder de otra administración presentado por el interesado en un procedimiento anterior y no puede conseguirlo:", "El interesado está obligado a presentar de nuevo el documento.", "Si el interesado es persona jurídica, puede requerirla para que presente nuevamente el documento.", "Excepcionalmente, puede requerir nuevamente el documento al interesado.", "No puede requerir de nuevo el documento al interesado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 56, "Indique la respuesta correcta. Con carácter general, el ciudadano está obligado a presentar los documentos ante una Administración cuando:", "Exista un procedimiento administrativo.", "Se oponga a la consulta de los datos por parte de la Administración actuante.", "Lo exija una administración pública de acuerdo con la normativa aplicable.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 57, "Excepcionalmente, cuando la relevancia del documento en el procedimiento lo exija o existan dudas derivadas de la calidad de la copia:", "La Administración pública actuante no puede requerir al interesado para que aporte más documentación.", "La Administración pública actuante puede requerir al interesado para que exhiba el documento original, por lo que le solicitará motivadamente el cotejo de las copias.", "La Administración pública actuante puede requerir al interesado para que presente nuevamente copia del documento.", "La Administración pública actuante puede requerir al interesado para que comparezca ante las oficinas públicas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 58, "¿Cuándo puede el órgano instructor de un procedimiento requerir al interesado para que aporte un documento original?", "Excepcionalmente, cuando la copia aportada por el interesado es de muy mala calidad y tiene dudas sobre su contenido.", "Con carácter general, cuando se trate de un documento clave para resolver el procedimiento.", "Cuando el interesado haya aportado la documentación en papel y ésta no está digitalizada.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 59, "Indique la respuesta correcta en relación con la aportación de documentos por los interesados:", "Los documentos que aporten los interesados al procedimiento administrativo, tanto originales como copias de éstos, tendrán eficacia en el ámbito de la actividad de las administraciones públicas.", "Las copias que aporten los interesados al procedimiento administrativo tienen eficacia exclusivamente en el ámbito de la actividad de las administraciones públicas.", "Los documentos que aporten los interesados al procedimiento administrativo tendrán eficacia exclusivamente en el ámbito de la actividad de las administraciones públicas.", "Las copias que aporten los ciudadanos tienen eficacia frente a cualquier administración pública."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 60, "Señale la respuesta correcta en relación con el Catálogo de simplificación documental:", "El Catálogo contiene documentos de los interesados cuya aportación no es obligatoria en el procedimiento administrativo.", "El Catálogo contribuye a hacer efectivo el derecho de las personas interesadas a no aportar documentación elaborada por las administraciones públicas.", "Los documentos incluidos en el Catálogo serán susceptibles de ser consultados a través de plataformas interoperables.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 61, "¿En qué año se creó el Catálogo de simplificación documental?", "El 2013.", "El 2011.", "El 2015.", "El 2017."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 62, "En el momento de entrar en vigor el Catálogo de simplificación documental, ¿sobre qué documentos se suprimió la obligación de presentarlos?", "Obligaciones tributarias frente a la Hacienda autonómica.", "Datos de residencia.", "Datos de identidad.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 63, "En materia de actuación y funcionamiento del sector público por medios electrónicos, una sede electrónica es:", "La dirección electrónica disponible para la ciudadanía por medio de redes de telecomunicaciones, cuya titularidad corresponde a una Administración Pública, o bien a uno o varios organismos públicos o entidades de derecho público en el ejercicio de sus competencias.", "El punto de acceso electrónico que permite el acceso a través de internet a la información publicada, cuya titularidad corresponde a una Administración Pública, o bien a uno o varios organismos públicos o entidades de derecho público en el ejercicio de sus competencias.", "La dirección electrónica disponible para la ciudadanía que agrupa a un conjunto ordenado de documentos y actuaciones relativos a la resolución administrativa, así como las diligencias encaminadas a ejecutarla.", "El punto de acceso electrónico que engloba un escenario de comunicaciones delimitado, controlado y protegido en el que los participantes se relacionan mediante medios electrónicos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 64, "En materia de funcionamiento del sector público por medios electrónicos, ¿se pueden crear sedes electrónicas asociadas?", "Sí, por razones técnicas y organizativas se puede crear una sede asociada a la sede electrónica. La sede electrónica asociada tendrá consideración de sede electrónica durante el período de tiempo que la sede electrónica principal esté inaccesible.", "Sí, por razones técnicas y organizativas se pueden crear una o varias sedes electrónicas asociadas a la sede electrónica. Las sedes electrónicas asociadas tendrán consideración de sede electrónica a todos los efectos.", "Sí, por razones técnicas y de seguridad se puede crear una sede asociada a la sede electrónica. La sede electrónica asociada tendrá consideración de sede electrónica durante el período de tiempo que la sede electrónica principal esté inaccesible.", "Sí, por razones técnicas y de seguridad se pueden crear una o varias sedes electrónicas asociadas a la sede electrónica. Las sedes electrónicas asociadas tendrán consideración de sede electrónica a todos los efectos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 65, "¿Dónde está alojada la Dirección Electrónica Habilitada única (DEHú) a que se refiere el artículo 43 de la Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas?", "En la sede electrónica de cada Administración Pública.", "En la sede electrónica del Punto de Acceso General electrónico de la Administración General del Estado.", "En la sede electrónica de cada Administración Pública y en todas sus sedes electrónicas asociadas.", "En la sede electrónica de la Administración General del Estado y en todas sus sedes electrónicas asociadas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 66, "¿Es necesario poner el acto o disposición de creación de una sede electrónica de una Administración Pública a disposición de las personas interesadas?", "Sí, tanto su identificación como su acceso directo, ya que forman parte del contenido mínimo que toda sede electrónica debe disponer.", "Sí, tanto su identificación como su enlace a su publicación en el Boletín Oficial correspondiente, ya que forman parte del contenido mínimo que toda sede electrónica debe disponer.", "Sí, tanto su identificación como su acceso, ya sea directo o con su enlace a su publicación en el Boletín Oficial correspondiente, puesto que forman parte del contenido mínimo que toda sede electrónica debe disponer.", "Sí, con su directo o con su enlace a su publicación en el Boletín Oficial correspondiente. Sin embargo, la identificación del acto o disposición no forma parte del contenido mínimo que toda sede electrónica debe disponer."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 67, "¿Podrá adherirse una entidad de derecho público vinculado o dependiente a la sede electrónica titularidad de otra administración pública?", "No, sólo podrá adherirse si su sede es titularidad de la propia administración pública.", "No, primero deberá constituirse como sede electrónica asociada.", "Sí, de forma voluntaria y mediante la formalización del instrumento de adhesión correspondiente, y en todo caso, constituyéndose como sede electrónica asociada.", "Sí, de forma voluntaria y mediante la formalización del correspondiente instrumento de adhesión, sin que se constituya como sede electrónica asociada."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 68, "En materia de interoperabilidad, ¿qué es la superposición de un sello electrónico al código seguro de verificación, en las comunicaciones de documentos electrónicos a otros órganos?", "Es un mecanismo de validación automática del origen e integridad de los documentos electrónicos en los términos establecidos por la Norma Técnica de Interoperabilidad de Expediente Electrónico, usado en las actuaciones administrativas automatizadas.", "Es un mecanismo de validación manual del origen e integridad de los documentos electrónicos en los términos establecidos por la Norma Técnica de Interoperabilidad de Expediente Electrónico, usado en las actuaciones administrativas manuales.", "Es un mecanismo de verificación automática del origen e integridad de los documentos electrónicos en los términos establecidos por la Norma Técnica de Interoperabilidad de Documento Electrónico, usado en las actuaciones administrativas automatizadas.", "Es un mecanismo de verificación manual del origen e integridad de los documentos electrónicos en los términos establecidos en la Norma Técnica de Interoperabilidad de Documento Electrónico, usado en las actuaciones administrativas manuales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 69, "¿Qué relación tiene el Centro Criptológico Nacional con la interoperabilidad en las Administraciones Públicas?", "No tiene ninguna relación. El Centro Criptológico Nacional vela por la seguridad de las redes y sistemas de información, sin tener en cuenta la interoperabilidad.", "El Centro Criptológico Nacional debe garantizar la interoperabilidad en materia de ciberseguridad y criptografía.", "El Centro Criptológico Nacional debe asegurar la compatibilidad de los sistemas y aplicaciones criptográficas utilizadas por las administraciones públicas.", "No tiene ninguna relación. El Centro Criptológico Nacional vela por la defensa nacional a nivel militar."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 70, "Señale la respuesta correcta:", "El Esquema Nacional de Interoperabilidad se regula con el Real Decreto 4/2010, de 8 de enero, y no se ha visto afectado por ninguna norma posterior.", "El Esquema Nacional de Interoperabilidad se establece en la Ley 11/2007, de 22 de junio, de acceso electrónico de los ciudadanos a los servicios públicos.", "El Esquema Nacional de Seguridad se remite al Esquema Nacional de Interoperabilidad para cuestiones relativas en materia de interoperabilidad que vayan más allá de los aspectos necesarios para garantizar la seguridad.", "El Esquema Nacional de Interoperabilidad se modifica con la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 71, "Señala la respuesta correcta en relación con los principios específicos del Esquema Nacional de Interoperabilidad:", "La interoperabilidad debe estar presente a lo largo de todo el ciclo de vida de los servicios y sistemas, excepto en su concepción.", "La cadena de interoperabilidad se manifiesta en el despliegue de los sistemas y servicios, entre otros.", "El acceso a la información a lo largo del tiempo no es un principio que deba garantizar este esquema.", "Se deberá favorecer la aproximación multilateral a la interoperabilidad de forma que se puedan obtener las ventajas derivadas de la aplicación de arquitecturas integradas y centralizadas, entre otras."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 17, 72, "¿Cuál es el procedimiento vigente para aprobar y publicar una Norma Técnica de Interoperabilidad?", "El Ministerio de la Presidencia, a propuesta del Comité Sectorial de Administración Electrónica, aprueba la norma técnica de interoperabilidad y la publica mediante Resolución de la Secretaría de Estado para la Función Pública.", "El Ministerio de Asuntos Económicos y Transformación Digital, a propuesta de la Comisión Sectorial de Administración Electrónica, aprueba la norma técnica de interoperabilidad y la publica mediante Resolución de la Secretaría de Estado de Digitalización e Inteligencia Artificial.", "El Ministerio de la Presidencia, a propuesta de la Comisión Sectorial de Administración Electrónica, aprueba la norma técnica de interoperabilidad y la publica mediante Resolución de la Secretaría de Estado para la Función Pública.", "El Ministerio de Asuntos Económicos y Transformación Digital, a propuesta del Comité Sectorial de Administración Electrónica, aprueba la norma técnica de interoperabilidad y la publica mediante Resolución de la Secretaría de Estado de Digitalización e Inteligencia Artificial."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 1, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, ¿cuál de las siguientes respuestas no está incluida en el ámbito de aplicación de esta ley?", "La Administración General del Estado.", "La administración de la comunidad autónoma de las Illes Balears.", "Las sociedades mercantiles cuando, como mínimo, un 25% de su capital esté en manos de administraciones públicas.", "El Congreso de los diputados."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 2, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, el derecho de acceso a la información pública cuando la información contuviera datos especialmente protegidos", "El derecho de acceso se ejercerá bajo declaración responsable de deber de sigilo.", "La publicidad sólo se llevará a cabo previa disociación de estos datos.", "La publicidad se llevará a cabo después del transcurso de 4 años.", "La publicidad se llevará a cabo en todo caso, dado que el derecho de acceso es preferente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 3, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, las Administraciones Públicas publicarán:", "Los planes y programas anuales y plurianuales en los que se fijen objetivos concretos, aunque no las actividades y medios para su consecución.", "Los planes y programas anuales y plurianuales en los que se fijen objetivos genéricos, aunque no las actividades y medios para su consecución.", "Los planes y programas anuales y plurianuales en los que se fijen objetivos concretos, así como las actividades y medios para su consecución.", "Los planes y programas anuales y plurianuales en los que se fijen objetivos genéricos, así como las actividades y medios para su consecución."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 4, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, señale que información pública se corresponde a Información de relevancia jurídica que deben publicar las administraciones públicas:", "La relación de los convenios suscritos.", "La información estadística necesaria para valorar el grado de cumplimiento y calidad de los servicios públicos que sean de su competencia.", "Las retribuciones percibidas anualmente por los altos cargos.", "Las directrices, instrucciones, acuerdos o circulares en la medida en que supongan una interpretación del Derecho o tengan efectos jurídicos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 5, "De acuerdo con la Constitución Española, la ley regulará el acceso de los ciudadanos a los archivos y registros administrativos salvo:", "En lo que afecte a la seguridad y defensa del Estado, la averiguación de los delitos y la intimidad de las personas.", "En lo que afecte a los secretos de estado, la averiguación de los delitos y la intimidad de las personas.", "En lo que afecte a la seguridad y defensa del Estado, la averiguación de los delitos y al honor de las personas.", "En lo que afecte a los secretos de estado, la averiguación de los delitos y al honor de las personas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 6, "De acuerdo con la Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas, entre los derechos de las personas en sus relaciones con las Administraciones Públicas se encuentra:", "El acceso a la información pública, archivos y registros.", "El derecho a solicitud y acceso a los expedientes y registros.", "El acceso a la información pública, expedientes y circulares.", "El derecho a solicitud y acceso a los archivos y circulares."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 7, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, si la información solicitada contuviera datos personales que revelen la ideología, afiliación sindical, religión o creencias, y el afectado no hubiese hecho manifiestamente públicos los datos con anterioridad:", "El acceso únicamente se podrá autorizar en caso de tener el consentimiento expreso y por escrito del afectado.", "El acceso únicamente se podrá autorizar en caso de tener el consentimiento expreso por cualquier medio del afectado.", "El acceso únicamente se podrá autorizar en caso de tener el consentimiento expreso y en escritura pública del afectado.", "El acceso únicamente se podrá autorizar en caso de tener el consentimiento expreso y por escrito del afectado o por comparecencia apud acta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 8, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, si la información solicitada incluye datos personales que incluyesen datos genéticos o biométricos:", "El acceso únicamente se podrá autorizar en caso de tener el consentimiento expreso y por escrito del afectado, o que dicho afectado hubiese hecho manifiestamente públicos los datos con anterioridad.", "El acceso solo se podrá autorizar en caso de que se cuente con el consentimiento expreso del afectado o si el acceso estuviera amparado por una norma con rango de ley.", "El acceso solo se podrá autorizar en caso de que se cuente con el consentimiento expreso y por escrito del afectado.", "El acceso solo se podrá autorizar en caso de que se cuente con el consentimiento expreso, por escrito o por comparecencia apud acta del afectado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 9, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, ¿qué entidades están obligadas a publicar de forma periódica y actualizada la información relevante para garantizar la transparencia de su actividad?", "Cuando al menos el 50 % del total de sus ingresos anuales tengan carácter de ayuda o subvención pública, siempre que alcancen como mínimo la cantidad de 10.000 euros.", "Cuando al menos el 40 % del total de sus ingresos anuales tengan carácter de ayuda o subvención pública, siempre que alcancen como mínimo la cantidad de 10.000 euros.", "Cuando al menos el 50 % del total de sus ingresos anuales tengan carácter de ayuda o subvención pública, siempre que alcancen como mínimo la cantidad de 5.000 euros.", "Cuando al menos el 40 % del total de sus ingresos anuales tengan carácter de ayuda o subvención pública, siempre que alcancen como mínimo la cantidad de 5.000 euros."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 10, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, señale que información pública se corresponde a Información institucional, organizativa y de planificación que deben publicar las administraciones públicas:", "Las cuentas anuales que deban rendirse.", "Información relativa a las funciones que desarrollan y la normativa que les sea de aplicación.", "La información estadística necesaria para valorar el grado de cumplimiento y calidad de los servicios públicos que sean de su competencia.", "La relación de los convenios suscritos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 11, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, indique cual de las siguientes respuestas no supondrá una limitación para ejercer el derecho de acceso.", "Los intereses económicos y comerciales.", "La política de alianzas militares.", "Las relaciones exteriores.", "La seguridad pública."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 12, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, la aplicación de los límites al derecho de acceso:", "Siempre será justificada y se aplicará por igual a todos los casos, de acuerdo con el principio constitucional de igualdad.", "No siempre necesitará justificación y atenderá a las circunstancias del caso concreto.", "Siempre será justificada y atenderá a las circunstancias del caso concreto.", "No siempre necesitará justificación y se aplicará por igual a todos los casos, de acuerdo con el principio constitucional de igualdad."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 13, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, cuando la información solicitada contenga datos personales pero estos datos no se encuentren especialmente protegidos, el órgano al que se dirija la solicitud:", "Concederá el acceso de inmediato sin posibilidad de recurso administrativo por parte de los afectados.", "Concederá el acceso si éste se efectúa previa disociación de los datos de carácter personal de modo que se impida la identificación de las personas afectadas.", "Concederá el acceso de inmediato con posibilidad de recurso administrativo por parte de los afectados.", "No concederá el acceso."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 14, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, el procedimiento para el ejercicio del derecho de acceso se iniciará con la presentación de la correspondiente solicitud, que deberá dirigirse:", "Al Portal de Transparencia de cada administración.", "Al Portal de Transparencia del Estado.", "Al Consejo de Transparencia y Buen Gobierno.", "Al titular del órgano administrativo o entidad que posea la información."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 15, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, ¿Debe motivarse la solicitud de acceso a la información?", "Deberá estar motivada.", "No debe motivarse en ningún caso.", "No es obligatorio a motivar la solicitud, sin embargo, se puede motivar.", "La ausencia de motivación puede ser por si sola causa de rechazo de la solicitud."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 16, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, si la solicitud de información no identifica de forma suficiente la información solicitada:", "Se pedirá al solicitante que la concrete en un plazo de quince días, con indicación de que, en caso de no hacerlo, se le tendrá por desistido, y de que no se suspende el plazo para dictar resolución.", "Se pedirá al solicitante que la concrete en un plazo de diez días, con indicación de que, en caso de no hacerlo, se le tendrá por desistido, y de que no se suspende el plazo para dictar resolución.", "Se pedirá al solicitante que la concrete en un plazo de quince días, con indicación de que, en caso de no hacerlo, se le tendrá por desistido, así como de la suspensión del plazo para dictar resolución.", "Se pedirá al solicitante que la concrete en un plazo de diez días, con indicación de que, en caso de no hacerlo, se le tendrá por desistido, así como de la suspensión del plazo para dictar resolución."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 17, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, el derecho de acceso podrá ser limitado cuando acceder a la información suponga un perjuicio:", "Para la seguridad internacional.", "Para los intereses económicos y comerciales.", "Para los intereses políticos del gobierno.", "Para la igualdad de genero."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 18, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, si la información solicitada pudiera afectar a derechos o intereses de terceros:", "Si están debidamente identificados, se les concederá un plazo de quince días para que puedan realizar las alegaciones que estimen oportunas.", "En todo caso, aun sin estar identificados, se les concederá un plazo de quince días para que puedan realizar las alegaciones que estimen oportunas.", "Si están debidamente identificados, se les concederá un plazo de diez días para que puedan realizar las alegaciones que estimen oportunas.", "En todo caso, aun sin estar identificados, se les concederá un plazo de diez días para que puedan realizar las alegaciones que estimen oportunas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 19, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, transcurrido el plazo máximo para resolver las solicitudes de información pública sin que se haya dictado y notificado resolución expresa:", "Se entenderá que la solicitud ha sido estimada.", "Se entenderá que la solicitud ha caducado.", "Se entenderá que la solicitud ha sido desestimada.", "Se entenderá que el solicitante ha renunciado a su solicitud."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 20, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, la reclamación ante el Consejo de Transparencia y Buen Gobierno:", "Tendrá la consideración de sustitutiva de la rectificación de errores.", "Tendrá la consideración de sustitutiva del recurso de reposición.", "Tendrá la consideración de sustitutiva del recurso de alzada.", "Tendrá la consideración de sustitutiva del recurso extraordinario de revisión."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 21, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, ¿Cual de las siguientes solicitudes de información se inadmitirán a trámite?", "Las dirigidas a un órgano que no disponga de la información cuando se conozca el competente.", "Las relativas a información para cuya divulgación sea necesaria una acción previa de reelaboración.", "Las que contengan datos personales que incluyesen datos genéticos o biométricos.", "Las que contengan datos personales relativos a la comisión de infracciones penales o administrativas que no conllevasen la amonestación pública al infractor."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 22, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, la formalización del acceso a la información pública:", "Se realizará preferentemente por vía electrónica. Cuando no pueda darse el acceso en el momento de la notificación de la resolución deberá otorgarse, en cualquier caso, en un plazo no superior a diez días.", "Se realizará preferentemente por vía electrónica. Cuando no pueda darse el acceso en el momento de la notificación de la resolución deberá otorgarse, en cualquier caso, en un plazo no superior a un mes.", "Se realizará preferentemente por escrito en papel. Cuando no pueda darse el acceso en el momento de la notificación de la resolución deberá otorgarse, en cualquier caso, en un plazo no superior a diez días.", "Se realizará preferentemente por escrito en papel. Cuando no pueda darse el acceso en el momento de la notificación de la resolución deberá otorgarse, en cualquier caso, en un plazo no superior a un mes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 23, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, a los efectos de la aplicación a sus responsables del régimen disciplinario, el incumplimiento de la obligación de resolver en plazo las resoluciones dictadas en materia de acceso a la información pública:", "Tendrá en todo caso la consideración de infracción muy grave.", "Tendrá en todo caso la consideración de infracción grave.", "Solo el incumplimiento reiterado se establece como infracción, que tendrá la consideración de grave.", "Tendrá la consideración de infracción grave pero si el incumplimiento es reiterado tendrá la consideración de infracción muy grave."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 24, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, la reclamación ante el Consejo de Transparencia y Buen Gobierno se interpondrá:", "en el plazo de un mes a contar desde el día siguiente al de la notificación del acto impugnado o desde el día siguiente a aquel en que se produzcan los efectos del silencio administrativo.", "en el plazo de un mes a contar desde el día siguiente al de la notificación del acto impugnado o de tres meses desde el día siguiente a aquel en que se produzcan los efectos del silencio administrativo.", "en el plazo de un mes a contar desde el día siguiente al de la notificación del acto impugnado o de seis meses desde el día siguiente a aquel en que se produzcan los efectos del silencio administrativo.", "en el plazo de un mes a contar desde el día siguiente al de la notificación del acto impugnado o de dos meses desde el día siguiente a aquel en que se produzcan los efectos del silencio administrativo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 25, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, el plazo máximo para resolver y notificar la resolución de la reclamación ante el Consejo de Transparencia y Buen Gobierno:", "Será de dos meses, transcurrido el cual, la reclamación se entenderá estimada.", "Será de dos meses, transcurrido el cual, la reclamación se entenderá desestimada.", "Será de tres meses, transcurrido el cual, la reclamación se entenderá estimada.", "Será de tres meses, transcurrido el cual, la reclamación se entenderá desestimada."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 26, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, las resoluciones del Consejo de Transparencia y Buen Gobierno se publicarán:", "Por medios electrónicos y en los términos en que se establezca reglamentariamente.", "Por medios electrónicos y en los términos en que se establezca legalmente.", "En el diario oficial correspondiente y en los términos en que se establezca reglamentariamente.", "En el diario oficial correspondiente y en los términos en que se establezca legalmente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 27, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, las resoluciones de las reclamaciones ante el Consejo de Transparencia y Buen Gobierno se comunicarán:", "Por el presidente del Consejo de Transparencia y Buen Gobierno al Defensor del Pueblo.", "Por el secretario del Consejo de Transparencia y Buen Gobierno al Gobierno.", "Por el presidente del Consejo de Transparencia y Buen Gobierno al Gobierno.", "Por el secretario del Consejo de Transparencia y Buen Gobierno al Defensor del Pueblo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 28, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, las comunidades autónomas, para la resolución de la reclamación prevista en relación al derecho de acceso a la información pública:", "Deberán crear un órgano propio para resolverla.", "Podrán no ajustar su actuación a lo establecido en esta ley.", "Atribuirán esta competencia al Consejo de Transparencia y Buen Gobierno.", "Podrán atribuir esta competencia al Consejo de Transparencia y Buen Gobierno."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 29, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno,¿cuándo podrá ser limitado el derecho de acceso a la información pública relacionada con las relaciones exteriores?", "En ningún caso, prevaleciendo el derecho a la información.", "En todo caso, dado el carácter de las relaciones exteriores.", "Cuando la embajada del país afectado se oponga a ese derecho de acceso.", "Cuando acceder a la información suponga un perjuicio para las propias relaciones exteriores."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 30, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, el derecho de acceso a la información pública se ejercerá:", "Sin límite dado que es un derecho constitucional.", "Tiene solo los límites regulados en la Constitución Española, ya que cualquier otra limitación vulneraría la Constitución.", "Tiene el límite derivado de la protección de datos de carácter personal.", "Tiene el límite temporal de 4 años desde que se resuelve el expediente al cual se pretende acceder."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 31, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, si la información solicitada pudiera afectar a derechos o intereses de terceros, debidamente identificados, y se les ha concedido un plazo para presentar alegaciones:", "Se suspende el plazo para dictar resolución hasta que se hayan recibido las alegaciones o haya transcurrido el plazo de veinte días para su presentación.", "Se suspende el plazo para dictar resolución hasta que se hayan recibido las alegaciones o haya transcurrido el plazo de quince días para su presentación.", "No es obligatorio suspender el plazo para dictar resolución hasta que se hayan recibido las alegaciones o haya transcurrido el plazo de veinte días para su presentación.", "No es obligatorio suspender el plazo para dictar resolución hasta que se hayan recibido las alegaciones o haya transcurrido el plazo de quince días para su presentación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 32, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, la resolución en la que se conceda o deniegue el acceso a la información pública deberá notificarse:", "Al solicitante y a los terceros afectados que así lo hayan solicitado en el plazo máximo de tres meses desde la recepción de la solicitud.", "Unicamente al solicitante en el plazo máximo de tres meses desde la recepción de la solicitud.", "Unicamente al solicitante en el plazo máximo de un mes desde la recepción de la solicitud.", "Al solicitante y a los terceros afectados que así lo hayan solicitado en el plazo máximo de un mes desde la recepción de la solicitud."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 33, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, las comunidades autónomas, para atribuir la competencia para la resolución de la reclamación prevista en relación al derecho de acceso al Consejo de Transparencia y Buen Gobierno:", "Deberán celebrar el correspondiente convenio con la Administración General del Estado.", "Deberán celebrar el correspondiente contrato con la Administración General del Estado.", "Deberán realizar la correspondiente encomienda de gestión con la Administración General del Estado.", "No pueden atribuir dicha competencia al Consejo de Transparencia y Buen Gobierno."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 34, "Según la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, en relación a la protección de los datos de carácter personal, será necesario el consentimiento expreso y por escrito del afectado para datos relativos a:", "Origen racial.", "Salud.", "Ideología.", "Vida sexual"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 35, "Según la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, ¿cual de las siguientes respuestas no indica un miembro de la Comisión de Transparencia y Buen Gobierno?", "Un representante de la Autoridad Independiente de Responsabilidad Fiscal.", "Un representante de la Agencia Española de Protección de Datos.", "Un representante del Instituto de las Mujeres.", "Un Senador."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 36, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, indique la respuesta falsa:", "La publicidad activa y el derecho de acceso fomentan la transparencia y la participación en la actividad pública.", "En la publicidad activa la Administración pone los datos a disposición de la ciudadanía, en portales y páginas web, siempre que los ciudadanos los demanden, proactivamente.", "En el derecho de acceso a la información pública la Administración responde a las demandas de información por parte de los ciudadanos.", "El derecho de acceso a la información pública podrá ser limitado de forma justificada y proporcionada a su objeto y finalidad."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 37, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, el Consejo de Transparencia y Buen Gobierno, se configura como:", "Órgano incardinado en la estructura del Ministerio competente en Función Pública.", "Organismo público adscrito al actual Ministerio de Hacienda y Función Pública.", "Órgano previsto en el Título IV de la Constitución Española.", "Consejo interterritorial en el que están representados el Estado y las Comunidades Autónomas y las entidades locales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 38, "De acuerdo con la Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas, entre los principios de buena regulación se encuentran:", "Els de transparencia y eficiencia.", "El de eficiencia pero no el de transparencia.", "El de transparencia pero no el de eficiencia.", "Ninguno de los dos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 39, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, indique cual de las siguientes respuestas no supondrá una limitación para ejercer el derecho de acceso.", "La política económica y monetaria.", "Las funciones administrativas de vigilancia, inspección y control.", "La protección del medio ambiente.", "La garantía de la confidencialidad en los procesos penales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 40, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, ¿cual de los siguientes datos personales se podrían revelar sin autorización del afectado si una norma con rango de ley lo amparara?", "Datos personales que hagan referencia a la salud.", "Datos personales que revelen la ideología.", "Datos personales que revelen la afiliación sindical.", "Datos personales que revelen la religión o creencias."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 41, "Señale la respuesta correcta respecto a la solicitud de acceso a la información pública según la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno:", "La resolución en la que se conceda o deniegue el acceso a deberá notificarse al solicitante y a los terceros afectados que así lo hayan solicitado en el plazo máximo de un mes desde la recepción de la solicitud por el órgano competente para resolver.", "Transcurrido el plazo máximo para resolver sin que se haya dictado y notificado resolución expresa se entenderá que la solicitud ha sido estimada.", "Las resoluciones dictadas en materia de acceso a la información pública no son recurribles directamente ante la Jurisdicción Contencioso-administrativa.", "El incumplimiento reiterado de la obligación de resolver en plazo tendrá la consideración de infracción muy grave a los efectos de la aplicación a sus responsables del régimen disciplinario previsto en la correspondiente normativa reguladora."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 42, "Si un ciudadano solicita información a la Administración y son de aplicación los límites de derecho de acceso previstos en el artículo 14 de la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno pero estos límites no afectan a la totalidad de la información:", "Se ofrecerá acceso parcial sin indicar al solicitante que parte de la información ha sido omitida.", "Nunca se concederá el acceso parcial a la información.", "Se concederá el acceso parcial previa omisión de la información afectada por el límite de acceso, salvo que de ello resulte una información distorsionada o que carezca de sentido.", "Siempre se concederá acceso parcial a la información a la que no le afecte la limitación prevista en el artículo 14."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 43, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, el Consejo de Transparencia y Buen Gobierno:", "No tiene personalidad propia por ser un órgano dependiente del Ministerio competente en Función Pública.", "Tiene personalidad jurídica propia pero no plena capacidad de obrar", "Tiene personalidad jurídica propia y plena capacidad de obrar.", "No tiene personalidad jurídica propia pero sí independencia funcional."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 44, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, indique cual de las siguientes respuestas no supondrá una limitación para ejercer el derecho de acceso:", "La política económica y monetaria.", "Los intereses económicos y comerciales.", "Las funciones administrativas de vigilancia, inspección y control.", "La protección de la agricultura."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 45, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, si la información solicitada incluyese datos personales que hagan referencia a datos relativos a la comisión de infracciones penales o administrativas que no conllevasen la amonestación pública al infractor:", "El acceso solo se podrá autorizar en caso de que se cuente con el consentimiento expreso del afectado o si aquel estuviera amparado por una norma con rango de ley.", "El acceso solo se podrá autorizar en caso de que se cuente con el consentimiento expreso y por escrito del afectado.", "El acceso solo se podrá autorizar en caso de que aquel estuviera amparado por una norma con rango de ley.", "El acceso no se podrá autorizar."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 46, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, ¿Cual de las siguientes solicitudes de información se inadmitirán a trámite?", "Las que contengan datos personales relativos a la comisión de infracciones penales o administrativas que no conllevasen la amonestación pública al infractor.", "Las que sean manifiestamente repetitivas.", "Las que contengan datos personales que incluyesen datos genéticos o biométricos.", "Las que contengan datos personales que hagan referencia a la vida sexual."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 47, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, ¿Cual es el plazo máximo para notificar la resolución en la que se conceda o deniegue el acceso a la información pública?", "Un mes desde la recepción de la solicitud por el órgano competente para resolver, sin posibilidad de ampliación de plazo.", "Tres meses desde la recepción de la solicitud por el órgano competente para resolver, sin posibilidad de ampliación de plazo.", "Un mes desde la recepción de la solicitud por el órgano competente para resolver, con posibilidad de ampliarse por otro mes de acuerdo con la ley.", "Tres meses desde la recepción de la solicitud por el órgano competente para resolver, con posibilidad de ampliarse por otros 3 meses de acuerdo con la ley."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 48, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, ¿Cual de los siguientes es un motivo para ampliar el plazo máximo para notificar la resolución en la que se conceda o deniegue el acceso a la información pública?", "Falta de medios materiales para resolver en plazo.", "Tener acumulación de expedientes.", "Falta de medios personales.", "La complejidad de la información que se solicita."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 49, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, la reclamación ante el Consejo de Transparencia y Buen Gobierno:", "Podrá interponerse con carácter obligatorio y previo a su impugnación en vía contencioso-administrativa.", "Podrá interponerse con carácter obligatorio y previo al recurso de alzada o de reposición que corresponda.", "Podrá interponerse con carácter potestativo y previo al recurso de alzada o de reposición que corresponda.", "Podrá interponerse con carácter potestativo y previo a su impugnación en vía contencioso-administrativa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 50, "La Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, establece que el incumplimiento reiterado de las obligaciones de publicidad activa reguladas en el capitulo II del título I de la Ley, tendrá la consideración:", "De infracción muy grave a los efectos de aplicación, a sus responsables, del régimen disciplinario previsto en la correspondiente normativa reguladora.", "De infracción grave a los efectos de aplicación, a sus responsables, del régimen disciplinario previsto en la correspondiente normativa reguladora.", "De infracción leve a los efectos de aplicación, a sus responsables, del régimen disciplinario previsto en la correspondiente normativa reguladora.", "De amonestación a sus responsables, a los efectos del régimen disciplinario previsto en la correspondiente normativa reguladora."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 51, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, señale que información pública se corresponde a Información económica, presupuestaria y estadística que deben publicar las administraciones públicas:", "Las resoluciones de autorización o reconocimiento de compatibilidad que afecten a los empleados públicos.", "Información relativa a las funciones que desarrollan.", "Los planes y programas anuales y plurianuales en los que se fijen objetivos concretos.", "Los Anteproyectos de Ley y los proyectos de Decretos Legislativos cuya iniciativa les corresponda."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 52, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, indique la respuesta correcta:", "La publicidad activa responde a las demandas de información por parte de los ciudadanos.", "La Transparencia pública puede ser por publicidad activa y publicidad pasiva.", "La Transparencia pública puede ser por publicidad activa y por derecho de acceso a la información pública.", "La publicidad pasiva no responde a demandas de información, ya que la ciudadanía toma un papel pasivo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 53, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, la aplicación de los límites al derecho de acceso:", "Deberán aplicarse de la misma forma a todas las solicitudes por el principio de interdicción de la arbitrariedad de los poderes públicos.", "Atenderá a las circunstancias del caso concreto, especialmente a la concurrencia de interéses exclusivamente públicos.", "Atenderá a las circunstancias del caso concreto, especialmente a la concurrencia de un interés público o privado.", "Atenderá a las circunstancias del caso concreto, sin atender a otros posibles intereses."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 54, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, la solicitud de acceso a la información deberá permitir tener constancia en todo caso de la siguiente información:", "La identidad del solicitante e información que se solicita.", "La identidad del solicitante, información que se solicita y una dirección de contacto.", "La identidad del solicitante, información que se solicita, motivación de la consulta y una dirección de contacto.", "La identidad del solicitante, información que se solicita, los afectados por la revelación de los datos y una dirección de contacto."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 55, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, ¿cual de los siguientes datos personales se podrían revelar sin autorización del afectado si una norma con rango de ley lo amparara?", "Datos personales que revelen el origen racial.", "Datos personales que revelen la afiliación sindical.", "Datos personales que revelen la religión o creencias.", "Datos personales que revelen la ideología."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 56, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, el derecho de acceso a la información pública significa:", "Que todos los ciudadanos de la Unión Europea tienen derecho a acceder a la información pública.", "Que todos los españoles tienen derecho a acceder a la información pública.", "Que todas las personas tienen derecho a acceder a la información pública.", "Que todos los ciudadanos de la Unión Europea y de aquellos países, que hayan subscrito un convenio, tienen derecho a acceder a la información pública."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 57, "El derecho de acceso a la información pública regulado en la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, supone para las administraciones públicas la obligación:", "De hacer públicas determinadas informaciones de forma proactiva y gratuita.", "De atender las solicitudes de información que hagan los ciudadanos de forma gratuita.", "De hacer públicas determinadas informaciones de forma proactiva, pudiendo establecer una tasa.", "De atender las solicitudes de información que hagan los ciudadanos, pudiendo establecer una tasa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 58, "La Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, en su artículo 36 indica que en la composición de la Comisión de Transparencia y Buen Gobierno se incluye:", "Un representante de la Intervención General de la Administración del Estado.", "Un representante de la Agencia Española de Protección de Datos.", "Un representante de la Secretaría de Estado de Políticas Públicas.", "Un representante de la Autoridad Independiente de Responsabilidad Fiscal."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 59, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, señale que información pública se corresponde a Información económica, presupuestaria y estadística que deben publicar las administraciones públicas:", "Las subvenciones y ayudas públicas concedidas.", "Los proyectos de reglamentos cuya iniciativa les corresponda.", "Las memorias e informes que conformen los expedientes de elaboración de los textos normativos.", "Los anteproyectos de ley y los proyectos de decretos legislativos cuya iniciativa les corresponda."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 60, "Según la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, en relación a la protección de los datos de carácter personal, se podrá acceder cuando este acceso estuviera amparado por una norma con rango de ley para datos relativos a:", "Afiliación sindical.", "Religión.", "Ideología.", "Vida sexual."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 61, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, si la solicitud de información no identifica de forma suficiente la información solicitada:", "Se pedirá al solicitante que la concrete en un plazo de diez días.", "Se pedirá al solicitante que la concrete en un plazo de quince días.", "Se pedirá al solicitante que la concrete en un plazo de un mes.", "Se inadmitirá la solicitud, sin perjuicio de poder volver a presentarla."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 62, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, ¿cual de los siguientes datos personales se podrían revelar si el afectado los hubiese hecho manifiestamente públicos con anterioridad?", "Datos personales que incluyesen datos genéticos o biométricos.", "Datos personales que hagan referencia a la vida sexual.", "Datos personales relativos a la comisión de infracciones penales o administrativas que no conllevasen la amonestación pública al infractor.", "Datos personales que revelen la religión o creencias."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 63, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, señale que información pública se corresponde a Información de relevancia jurídica que deben publicar las administraciones públicas:", "Las memorias e informes que conformen los expedientes de elaboración de los textos normativos.", "Información relativa a su estructura organizativa.", "Las cuentas anuales que deban rendirse.", "Información relativa a las funciones que desarrollan."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 64, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, cuál de las siguientes respuestas no está incluida en el ámbito de aplicación de esta ley?", "Las entidades gestoras y los servicios comunes de la Seguridad Social.", "La Casa de su Majestad el Rey.", "El Senado.", "Las fundaciones cuya actividad se realiza en territorio español."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 65, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, el derecho de acceso a la información pública se ejercerá:", "Sin límite dado que es un derecho constitucionalmente garantizado.", "Tiene el límite derivado de los secretos políticos.", "Tiene el límite derivado de la protección de datos de carácter personal.", "Tiene el límite temporal de diez años desde que se resuelve el expediente al cual se pretende acceder."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 66, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, toda la información estará a disposición de las personas con discapacidad en una modalidad suministrada por medios o en formatos adecuados:", "De manera que resulten accesibles y comprensibles, conforme al principio de accesibilidad universal y diseño para todos.", "De manera que resulten accesibles y comprensibles, siempre que la tecnología lo permita.", "De manera que resulten accesibles y comprensibles, en el plazo de dos años desde la publicación de esta ley.", "De manera que resulten accesibles y comprensibles, conforme al principio de accesibilidad para la mayoría."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 67, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, ¿qué entidades privadas están obligadas a publicar de forma periódica y actualizada la información, cuyo conocimiento sea relevante para garantizar la transparencia de su actividad?", "Las que perciban durante el período de un año ayudas o subvenciones públicas en una cuantía superior a 100.000 euros.", "Las que perciban durante el período de un año ayudas o subvenciones públicas en una cuantía superior a 10.000 euros.", "Las que perciban durante el período de tres años ayudas o subvenciones públicas en una cuantía superior a 100.000 euros.", "Las que perciban durante el período de tres años ayudas o subvenciones públicas en una cuantía superior a 10.000 euros."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 68, "La Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, ¿cómo denomina a los dos tipos de transparencia que regula?", "Publicidad activa y derecho de solicitud de la información pública.", "Publicidad informativa y derecho de acceso a la información pública.", "Publicidad informativa y derecho de solicitud de la información pública.", "Publicidad activa y derecho de acceso a la información pública."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 69, "De acuerdo con la Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas, en aplicación del principio de transparencia entre los principios de buena regulación, las administraciones públicas:", "Posibilitarán el acceso a la normativa en vigor y los documentos propios de su proceso de elaboración, pero no se prevé que los potenciales destinatarios puedan tener una participación activa en la elaboración de las normas.", "Posibilitarán el acceso exclusivamente a los procesos de elaboración de las leyes, ya que el acceso a la normativa en vigor se obliga por el principio de seguridad jurídica.", "Posibilitarán el acceso a la normativa en vigor a través de sus paginas web pero no están obligadas a hacerlo en los procesos de elaboración de las leyes.", "Posibilitarán el acceso a la normativa en vigor y los documentos propios de su proceso de elaboración y posibilitaran que los potenciales destinatarios tengan una participación activa en la elaboración de las normas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 70, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, señala qué información pública se corresponde a información institucional, organizativa y de planificación que deben publicar las administraciones públicas:", "información relativa a su estructura organizativa.", "Las directrices, instrucciones, acuerdos o circulares que tengan efectos jurídicos.", "Los proyectos de Reglamentos cuya iniciativa les corresponda.", "La información estadística necesaria para valorar el grado de cumplimiento y calidad de los servicios públicos que sean de su competencia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 71, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, ¿que se entiende por información pública?", "Los contenidos, pero no los documentos, que obren en poder de alguno de los sujetos incluidos en el ámbito de aplicación de esta ley, elaborados o adquiridos en el ejercicio de sus funciones.", "Los contenidos, pero no los documentos, que obren en poder de alguno de los sujetos incluidos en el ámbito de aplicación de esta ley, siempre que hayan sido elaborados por estos sujetos.", "Los contenidos o documentos que obren en poder de alguno de los sujetos incluidos en el ámbito de aplicación de esta ley, siempre que hayan sido elaborados por estos sujetos.", "Los contenidos o documentos que obren en poder de alguno de los sujetos incluidos en el ámbito de aplicación de esta ley, elaborados o adquiridos en el ejercicio de sus funciones."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 72, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, el derecho de acceso podrá ser limitado cuando acceder a la información suponga un perjuicio para:", "Las relaciones interiores.", "La igualdad de las partes en los procesos judiciales y la tutela judicial efectiva.", "La seguridad internacional.", "La geopolítica."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 15, 73, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, la aplicación de los límites al derecho de acceso:", "Atenderá a las circunstancias del caso concreto, especialmente a la concurrencia de un interés público o privado.", "Atenderá a las circunstancias del caso concreto, especialmente a la concurrencia de interéses exclusivamente públicos.", "Atenderá a las circunstancias del caso concreto, especialmente a la concurrencia de interéses exclusivamente privados.", "Atenderá a las circunstancias del caso concreto, sin atender a otros posibles intereses."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 1, "Según  la Ley 7/85, de 2 de abril, Reguladora de las bases de régimen local, el personal al servicio de las Entidades locales estará integrado por", "Funcionarios de carrera, contratados en régimen de derecho laboral y personal eventual que desempeña puestos de confianza o asesoramiento especial.", "Funcionarios de carrera, funcionarios interinos y contratados en régimen de derecho laboral.", "Funcionarios de carrera, funcionarios interinos y personal eventual", "Funcionarios de carrera, funcionarios interinos, personal eventual y personal directivo"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 2, "Según la Ley 20/2006, municipal y de régimen local de las Illes Balears, tienen la consideración de personal al servicio de las entidades locales de las Illes Balears", "El personal funcionario de carrera, funcionario interino, personal eventual y personal directivo.", "El personal funcionario de carrera, funcionario interino, personal laboral fijo y personal eventual.", "El personal funcionario, el personal eventual y el personal laboral al servicio de las entidades locales.", "El personal funcionario de carrera, funcionario interino, personal laboral fijo, el personal eventual y el personal directivo"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 3, "Qué personal al servicio de las entidades locales se rige por la Ley 3/2007 de 27 de marzo, de Función pública de la Comunidad autónoma de las Illes Balears, en las materias no reservadas a la legislación básica?", "El personal funcionario, personal laboral y el personal eventual", "El personal funcionario y el personal laboral", "Únicamente el personal funcionario", "El personal funcionario y el personal eventual"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 4, "¿En virtud de qué competencia exclusiva del Estado, se dicta el Estatuto básico del empleado público?", "En virtud del artículo 149.1º.7ª de la Constitución Española", "En virtud del artículo 149.1º.13º de la Constitución Española", "En virtud del artículo 149.1º.18º de la Constitución Española", "En virtud de la regulación de las condiciones económicas básicas que garantizan la igualdad de todos los españoles en el ejercicio de los derechos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 5, "La Ley 3/2007 de 27 de marzo, de Función pública de la Comunidad autónoma de las Illes Balears será aplicable a los funcionarios de las entidades locales:", "De manera supletoria", "En todo caso, puesto que es una norma con rango de Ley", "En las materias no reservada a la legislación básica estatal.", "En ningún caso resulta de aplicación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 6, "Según el sistema de fuentes de la función pública local, será de aplicación directa:", "El Estatuto básico del empleado público, la legislación básica estatal y la  Ley 20/2006, municipal y de régimen local de las Illes Balears", "La ley de función pública de la CAIB y su normativa de desarrollo.", "La normativa de desarrollo estatal.", "El TREBEP y la Ley de función pública de la CAIB."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 7, "Según el Estatuto básico del empleado público, los empleados públicos se clasifican en:", "Funcionarios de carrera y funcionarios interinos.", "Funcionarios de carrera, funcionarios interinos y personal laboral", "Funcionarios de carrera, funcionarios interinos, personal laboral y personal eventual.", "Funcionarios de carrera, funcionarios interinos, personal laboral y personal eventual y personal directivo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 8, "Son funcionarios de carrera quienes:", "En virtud de nombramiento legal están vinculados a una Administración Pública por una relación estatutaria regulada por el Derecho Administrativo para el desempeño de servicios profesionales de carácter permanente.", "En virtud de nombramiento legal están vinculados a una Administración Pública por una relación laboral regulada por el Derecho Administrativo para el desempeño de servicios profesionales de carácter permanente.", "En virtud de nombramiento legal están vinculados a una Administración Pública por una relación estatutaria regulada por el Derecho laboral para el desempeño de servicios profesionales de carácter permanente.", "En virtud de nombramiento legal están vinculados a una Administración Pública por una relación estatutaria regulada por el Derecho Administrativo para el desempeño de servicios profesionales de carácter variable."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 9, "El nombramiento de un funcionario interino:", "No podrá tener una duración superior a 3 años.", "Tendrá lugar siempre que haya una vacante.", "Tendrá lugar siempre que haya un exceso o acumulación de tareas.", "Tendrá que justificarse siempre por razones de necesidad y urgencia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 10, "Según el Estatuto básico del empleado público el personal laboral es aquel que:", "En virtud de contrato de trabajo formalizado tanto por escrito como verbalmente, presta servicio retribuido por las Administraciones Públicas.", "En virtud de contrato de trabajo fijo formalizado  por escrito, presta servicio retribuido por las Administraciones Públicas", "En virtud de contrato de trabajo formalizado  por escrito,  en cualquiera de las modalidades de contratación previstas en la legislación laboral, presta servicio retribuido por las Administraciones Públicas.", "En virtud de contrato de trabajo formalizado  por escrito,  en cualquiera de las modalidades previstas en el Estatuto básico del empleado público, presta servicio retribuido por las Administraciones Públicas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 11, "Según la Ley 3/2007 de 27 de marzo, de Función pública de la Comunidad autónoma de las Illes Balears, qué funciones podría llevar a cabo el personal laboral", "Funciones atribuidas a un funcionario de carrera", "Funciones atribuidas a un funcionario de carrera, excepto las que impliquen ejercicio de la autoridad.", "Las funciones previstas en el convenio colectivo que le sea de aplicación", "Las funciones de los puestos correspondientes a las áreas de mantenimiento y conservación de edificios, equipos y de instalaciones."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 12, "El nombramiento interino para la ejecución de programas de carácter temporal no podrá tener una duración de:", "3 años.", "9 meses dentro de un periodo de 18 meses.", "3 años ampliables por 12 meses más.", "Hasta que finalice la ejecución del programa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 13, "El nombramiento interino por exceso o acumulación de tareas tendrá una duración de:", "9 meses dentro de un periodo de 18 meses.", "3 meses dentro de un periodo de 9 meses.", "12 meses prorrogables por 6 meses más.", "Por el tiempo estrictamente necesario"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 14, "El nombramiento interino por sustitución transitoria de los titulares tendrá una duración de:", "Hasta que se incorpore el titular del puesto.", "3 años como máximo.", "9 meses dentro de un periodo de 18 meses.", "Por el tiempo estrictamente necesario."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 15, "El nombramiento interino para cubrir puestos vacantes:", "Tiene una duración máxima de tres años, excepto que  el proceso selectivo quede desierto, en cuyo caso podrá continuar ocupando el puesto.", "El personal interino puede continuar ocupando el puesto  hasta que se resuelva la convocatoria con derecho a compensación económica, siempre que se haya publicado la convocatoria dentro de los tres años desde su nombramiento.", "El personal interino  puede continuar ocupando el puesto hasta que se resuelva la convocatoria sin derecho a compensación económica, siempre que se haya publicado la convocatoria dentro de los tres años desde la fecha de su nombramiento.", "En ningún caso podrá superar el plazo de 3 años."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 16, "Es personal eventual:", "En virtud de nombramiento y con carácter  permanente, sólo realiza funciones expresamente calificadas como de confianza especial.", "En virtud de nombramiento y con carácter no permanente, sólo realiza funciones expresamente calificadas como de confianza especial.", "En virtud de nombramiento, previo proceso de provisión por concurso, y carácter no permanente, sólo realiza funciones expresamente calificadas como de confianza especial.", "En virtud de nombramiento y carácter no permanente,  realiza entre otras, funciones calificadas como de confianza especial."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 17, "Para designar al personal directivo:", "Se atenderá a principios de igualdad, mérito y capacidad y a criterios de idoneidad.", "Tanto su nombramiento como su cese serán libres.", "Deberán tener la condición de funcionario de carrera del subgrupo A1", "Se llevará a cabo mediante procedimientos que garanticen la publicidad y la concurrencia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 18, "¿En cuál de estos supuestos, la finalización del nombramiento interino origina el derecho a compensación económica?", "Por supresión o amortización del puesto asignado por razones organizativas.", "Por haber transcurrido más de 3 años en los casos de ejecución de programas de carácter temporal.", "Por el transcurso de 3 años sin que se haya procedido a publicar la convocatoria en ese plazo.", "Por el transcurso de 3 años sin que se haya cubierto el puesto por un funcionario de carrera."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 19, "¿Cuál de las siguientes subescalas no pertence a la escala de la Administración general?", "Técnica", "Subalterna", "Servicios especiales", "De gestión"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 20, "El personal funcionario con habilitación de carácter nacional, se rige por:", "El Estatuto básico del empleado público.", "La ley 20/2006 municipal y de régimen local de les Illes Balears.", "La ley 7/85 de bases de régimen local", "Por su normativa específica."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 21, "La oferta de ocupación pública es:", "El conjunto de puestos de trabajo vacantes cuya cobertura resulte necesaria, con dotación presupuestaria", "El conjunto de puestos de trabajo que van dejando vacantes las jubilaciones producidas el ejercicio anterior.", "El conjunto de plazas vacantes de personal funcionario y de personal laboral cuya cobertura es necesaria, con dotación presupuestaria.", "El conjunto de plazas vacantes de personal funcionario cuya cobertura es necesaria, con dotación presupuestaria."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 22, "Indique la correcta:", "La oferta pública tiene que publicarse en el BOIB", "La oferta pública de empleo tiene que indicar la titulación requerida para su acceso.", "Será objeto de la oferta pública todos los puestos vacantes cuya cobertura sea necesaria.", "El Gobierno de las Illes Balears podrá acordar la ejecución conjunta de las ofertas de públicas de empleo de diversas entidades locales, a solicitud de éstas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 23, "¿Qué plazo tiene la Administración pública ejecutar la oferta pública de empleo?", "1 año improrrogable", "3 años improrrogables", "3 años prorrogables por uno más", "1 año prorrogable por uno más"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 24, "¿En qué caso la condición de personal eventual podrá constituir mérito para el acceso a la función pública?", "Sólo podrá ser mérito para la promoción interna.", "Solo podrá ser mérito para el acceso al subgrupo A1", "En ningún caso", "Siempre, por considerarse tiempo de servicio prestado en la Administración."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 25, "Las necesidades reales de recursos humanos se concretan en:", "La relación de puestos de trabajo", "En los planes de ordenación", "En la oferta pública de empleo", "En la plantilla presupuestaria."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 26, "Según la Ley de bases del régimen local, las plantillas deberán responder a los siguientes principios:", "Principios de igualdad, capacidad y mérito", "Principios de igualdad, capacidad, mérito y publicidad.", "Principio de eficiencia, economía y sostenibilidad financiera.", "Principio de racionalidad, economía y eficiencia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 27, "Según la Ley de bases de régimen local, las corporaciones locales formarán públicamente su oferta pública de empleo ajustándose a los criterios establecidos en:", "La mesa general de negociación", "Acuerdo plenario.", "Acuerdo de Junta de Gobierno.", "A lo aprobado por el Estado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 28, "¿Cuál de estos conceptos retributivos no tiene la consideración de retribución básica?", "Sueldo.", "Trienios.", "Servicios extraordinarios.", "Pagas extraordinarias."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 29, "El complemento específico está destinado a retribuir:", "La especial dificultad técnica, dedicación, incompatibilidad, responsabilidad, peligrosidad o penosidad.", "El especial rendimiento, actividad extraordinaria y el interés e iniciativa con que el funcionario desempeña su trabajo.", "La especialización, responsabilidad, competencia y mando.", "La progresión alcanzada por el funcionario dentro del sistema de carrera administrativa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 30, "Según el Estatuto básico del empleado público, la carrera horizontal es:", "El conjunto ordenado de oportunidades de ascenso y expectativas de progreso profesional conforme a los principios de igualdad, mérito y capacidad.", "Consiste en la progresión de grados, categorías, escalones u otros conceptos análogos, sin necesidad de cambiar de puestos.", "El conjunto ordenado de oportunidades de ascenso en la estructura de puestos de trabajo.", "El conjunto ordenado de oportunidades de ascenso desde un cuerpo o escala de un subgrupo o grupo de clasificación profesional en el supuesto que no tenga subgrupo, a otro superior."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 31, "En la carrera horizontal debe valorarse:", "La trayectoria y actuación profesional, la calidad de los trabajos realizados, los conocimientos adquiridos y el resultado de la evaluación del desempeño", "Solo la evaluación del desempeño", "La conducta profesional y el rendimiento  o logro de resultado.", "La trayectoria y actuación profesional y el resultado de la evaluación del desempeño"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 32, "La evaluación del desempeño atenderá a criterios de:", "Transparencia, objetividad, imparcialidad y no discriminación.", "Privacidad, subjetividad, imparcialidad y no discriminación.", "Publicidad, igualdad, mérito y capacidad.", "Privacidad, subjetividad, mérito y capacidad."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 33, "La carrera profesional es una retribución de carácter:", "Básica.", "Complementaria.", "Extraordinaria.", "Indemnizatoria."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 34, "De acuerdo con el Estatuto básico del empleado público, ¿cuál de estos principios no rige en la actuación de los empleados públicos?", "Objetividad.", "Accesibilidad.", "Ejemplaridad.", "Publicidad.."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 35, "Por fallecimiento, accidente o enfermedad grave de un abuelo que vive en diferente localidad, a la persona empleada pública le corresponde un permiso de:", "5 días.", "4 días.", "3 días.", "2 días."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 36, "¿Cuál de estas materias no son objeto de negociación según el Estatuto básico del empleado público?", "La determinación y aplicación de las retribuciones complementarias.", "Los planes de previsión social complementaria.", "Las propuestas sobre derechos sindicales y de participación.", "El incremento de las retribuciones de personal."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 37, "¿Puede una persona extranjera de un país que no pertenezca a la UE participar en un proceso selectivo de una corporación local?", "No, se requiere que tenga nacionalidad española.", "Sí, puede presentarse en igualdad de condiciones.", "Sí puede presentarse, con excepción del acceso a las plazas que impliquen participación directa en los poderes públicos.", "Sí, si su cónyuge tiene nacionalidad española o tiene nacionalidad de otro Estado miembro."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 38, "¿Cuál de las siguientes situaciones no es una situación recogida en el título VI del Estatuto básico del empleado público?", "Servicios especiales.", "Servicios en otras administraciones.", "Jubilación parcial.", "Suspensión de funciones."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 39, "Si una persona funcionaria de carrera de otra administración es designado personal eventual en un Ayuntamiento, ¿en qué situación administrativa será declarada en su Administración de origen?)", "Servicio en otras administraciones.", "Servicios especiales.", "Excedencia voluntaria por interés particular.", "Excedencia voluntaria por prestación de servicios en el sector público."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 40, "La excedencia voluntaria por interés particular:", "Puede concederse por un período mínimo de 2 años.", "Puede concederse por un período mínimo de 5 años.", "Puede concederse por un período mínimo de 2 años.", "Puede concederse por un período máximo de 5 años."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 41, "Si una persona funcionaria de carrera, obtiene una plaza por concurso-oposición en otra Administración, en qué situación será declarado en su Administración de origen:", "Excedencia voluntaria por prestación de servicios en el sector público.", "Servicio en otras administraciones", "Servicio especiales", "Suspensión de funciones."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 42, "Mediante qué instrumento jurídico se podrán regular otras situaciones administrativas para los funcionarios de carrera, según el Estatuto básico del empleado público:", "Mediante Acuerdo de los órganos de gobierno de las Administraciones Públicas.", "Mediante Decreto acordado en el Consejo de Ministros", "Mediante reglamento de desarrollo.", "Mediante leyes de función pública."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 43, "En qué situación administrativa se computa el tiempo a efectos de ascensos, reconocimiento de trienios, promoción interna y derechos en el régimen de la seguridad social:", "Servicio en otras administraciones.", "Servicio especiales pero sin el cómputo de tiempo para ascensos.", "Servicios especiales.", "Excedencia por cuidado de familiares."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 44, "Si una persona funcionaria de carrera obtiene un puesto de trabajo en otra Administración por concurso de mérito, en qué situación quedaría respecto a su Administración de origen:", "Servicio en otras administraciones.", "Excedencia voluntaria por prestación de servicios en el sector público.", "Servicios especiales.", "Suspensión de funciones."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 45, "El Estatuto básico del empleado público regula expresamente, como situación administrativa, y sin perjuicio de otras situaciones que se establezcan en las correspondientes leyes de función pública:", "Expectativa de destino.", "Excedencia forzosa.", "Suspensión de funciones.", "Excedencia voluntaria."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 46, "En las excedencia por razón de violencia de género, se tendrá derecho a percibir las retribuciones íntegras durante:", "Los 6 primeros meses.", "Los 2 primeros meses.", "Los 3 primeros meses.", "El primer año."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 47, "En las excedencia por razón de violencia de género, tendrán derecho a la reserva del puesto de trabajo que desempeñaban durante:", "Los 2 primeros meses.", "Los 3 primeros meses.", "Los 6 primeros meses", "Durante el primer año."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 48, "La suspensión firme por sanción disciplinaria no podrá exceder de:", "6 meses.", "6 años", "12 meses.", "3 meses."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 49, "Según la Ley 20/2006, Municipal y de Régimen local , podrán proveerse mediante libre designación los puestos de:", "Jefes de departamento.", "Jefes de servicio.", "Jefes de sección.", "Chófer."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 50, "El régimen disciplinario del personal laboral se regirá:", "Por lo que disponga la legislación laboral, en lo no previsto en el Estatuto básico del empleado público.", "Por lo que disponga el Estatuto básico del empleado público.", "Por lo que disponga el convenio colectivo que sea de aplicación.", "Por lo que disponga el reglamento disciplinario en de la CAIB."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 51, "El periodo máximo de duración de la situación de declaración de expectativa de destino es:", "2 años", "1 año.", "6 meses.", "3 meses."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 52, "El reingreso en el servicio activo del personal funcionario que no tiene reserva de puesto de trabajo se efectúa:", "Por adscripción provisional.", "Por declaración de expectativa de destino.", "Por comisión de servicios.", "A través de la participación en las convocatorias de provisión."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 53, "El reingreso se llevará a cabo respetando el siguiente orden de prelación de situación de procedencia:", "Expectativa de destino, excedencia forzosa, suspensión de funciones y excedencia voluntaria.", "Excedencia  voluntaria, expectativa de destino, excedencia forzosa y suspensión de funciones.", "Expectativa de destino, excedencia forzosa, excedencia voluntaria y suspensión de funciones.", "Expectativa de destino, excedencia voluntaria, excedencia forzosa y suspensión de funciones."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 54, "Cuando un puesto de trabajo quede vacante de forma temporal y definitiva, puede ocuparse en comisión de servicios:", "Por el personal funcionario de carrera o funcionario interino del mismo cuerpo.", "Por el personal funcionario de carrera que pertenezca al mismo subgrupo y cumpla los requisitos del puesto.", "Por el personal funcionario de carrera del mismo cuerpo, escala o especialidad que cumpla los requisitos del puesto.", "Por el personal de la letra c), y si no lo hubiera podrá ser personal funcionario interino que cumpla los mismos requisitos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 55, "La duración de la comisión de servicios es:", "Por el tiempo estrictamente necesario.", "Por un año.", "Hasta que vuelve el titular del puesto.", "No podrá autorizarse la prórroga de las comisiones de servicios en puestos vacantes más allá de 1 año."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 56, "En que supuestos podrá efectuarse un nombramiento por mejora de empleo en un puesto singularizado:", "Cuando resulte dos veces desierto en un proceso de provisión por concurso abierto y permanente específico.", "Cuando resulte dos veces desierto en una convocatoria de comisión de servicios.", "Cuando no sea posible su cobertura mediante nombramiento interino.", "Cuando haya funcionario de carrera de subgrupo inmediatamente inferior disponible para su nombramiento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 57, "El régimen de incompatibilidades del empleado público local está regulado en:", "El Estatuto básico del empleado público.", "En la ley 20/2006, de municipal y de régimen local de las Illes Balears", "En la Ley 7/85, de 2 de abril, Reguladora de las bases de régimen local.", "En la ley 53/1984, de 26 de diciembre de Incompatibilidades del personal al servicio de las Administraciones públicas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 58, "El personal al servicio de las corporaciones locales podrá desempeñar un segundo puesto o actividad en el sector público:", "En ningún caso.", "En los supuestos previstos para funcionarios docentes y sanitarios.", "Si así lo determina el Pleno de la Corporación", "Por razones de interés público que así lo determine la Junta de Gobierno"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 59, "Será requisito para autorizar a un funcionario del grupo A la compatibilidad de actividades públicas, que la cantidad total percibida por ambas prestaciones", "No supere la remuneración para el cargo de Director/a General ni supere la retribución de la actividad principal incrementada en un 45%", "No supere la remuneración para el cargo de Director/a General ni supere la retribución de la actividad principal incrementada en un 40%", "No supere la remuneración para el cargo de Director/a General ni supere la retribución de la actividad principal incrementada en un 35%", "No supere la remuneración para el cargo de Director/a General ni supere la retribución de la actividad principal incrementada en un 30%"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 60, "La autorización o denegación de compatibilidad pública para un segundo puesto o actividad en el sector público del personal funcionario de una corporación local corresponde:", "Al Pleno", "Junta de Gobierno", "Al Alcalde", "Al Regidor del Área competente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 61, "Cuando el incumplimiento injustificado del horario de trabajo constituye falta grave:", "Si acumulado supone un mínimo de 5 horas dentro del mes natural.", "Si acumulado supone un mínimo de 10 horas dentro de un mes natural.", "Si acumulado supone un mínimo de 8 horas dentro de un mes natural.", "Si acumulado supone un mínimo de 3 horas dentro de un mes natural."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 62, "Cuál de estos principios no rige en la potestad disciplinaria:", "Principio de retroactividad", "Principio de culpabilidad", "Principio de presunción de inocencia", "Principio de celeridad"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 63, "El incumplimiento de las normas de incompatibilidad constituye:", "Falta grave", "Falta muy grave, cuando dé lugar a una situación de incompatibilidad", "Falta leve, si se ha comunicado la incompatibilidad antes del inicio del correspondiente procedimiento disciplinario.", "Falta muy grave"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 64, "La separación del servicio es una sanción que se podrá imponer para:", "Falta graves", "Falta muy graves", "Falta leves", "No constituye una sanción, puesto que es una situación administrativa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 65, "Las infracciones graves prescriben a:", "Los 2 años", "Los 3 años", "Los 4 años", "Al año"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 66, "El plazo de prescripción de la sanciones disciplinarias impuestas son:", "3 años para las muy graves, 2 años para las graves y 6 meses para las leves.", "3 años para las muy graves, 2 años para las graves y 1 año para las leves.", "3 años para las muy graves, 1 año para las graves y 6 meses para las leves.", "4 años para las muy graves, 3 años para las graves y 1 año para las leves."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 67, "El plazo de prescripción de las faltas empezará a contarse desde:", "La notificación del inicio del procedimiento disciplinario.", "Desde que el órgano competente para iniciar el procedimiento tiene conocimiento de la comisión de la falta.", "Desde que se comete la falta.", "Desde la aprobación del acuerdo de iniciación del procedimiento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 68, "El plazo de prescripción de las sanciones empieza a contarse desde:", "La firmeza de la resolución.", "La notificación de la resolución sancionadora.", "La aprobación de la resolución sancionadora.", "El transcurso de 1 mes desde la resolución sancionadora."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 69, "¿Cuál de estos principios no rige en el procedimiento en un procedimiento disciplinario?", "Principio de celeridad.", "Principio de eficacia.", "Principio de economía procesal.", "Principio de retroactividad."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 70, "La suspensión provisional como medida cautelar en un procedimiento disciplinario no podrá tener una duración superior a:", "6 meses.", "6 meses, salvo en caso de paralización del procedimiento imputable al interesado.", "3 meses.", "2 meses."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 71, "El funcionario suspenso provisional tendrá derecho a percibir:", "El 75% de las retribuciones básicas y, en su caso, las prestaciones por hijo a cargo.", "El 100% de las retribuciones básicas y, en su caso, las prestaciones por hijo a cargo.", "Las retribuciones íntegras y, en su caso, las prestaciones por hijo a cargo.", "El sueldo base y, en su caso, las prestaciones por hijo a cargo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 13, 72, "La incoación de un expediente disciplinario al personal de la Administración Local  corresponde a:", "Al presidente/a  de la Corporación o el órgano a quien delegue.", "A la Junta de Gobierno o el órgano a quien delegue.", "Al Pleno de la Corporación", "Al Regidor/a competente por razón de materia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 1, "La normativa sobre prevención de riesgos laborales queda constituida por:", "Por la Ley 31/1995, de 8 de noviembre, de prevención de riesgos laborales.", "Por la Ley 31/1995, de 8 de noviembre, de prevención de riesgos laborales y las disposiciones de desarrollo o complementarias.", "Por la Ley 31/1995, de 8 de noviembre, de prevención de riesgos laborales, las disposiciones de desarrollo o complementarias, y las normas internacionales.", "Por la Ley 31/1995, de 8 de noviembre, de prevención de riesgos laborales, disposiciones de desarrollo o complementarias, y todas aquellas otras normas legales o convencionales, que contengan prescripciones relativas a la adopción de medidas preventivas en el ámbito laboral."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 2, "La Ley 31/1995, de 8 de noviembre, de prevención de riesgos laborales tiene por objeto:", "Mejorar las condiciones laborales de los trabajadores.", "Promover la seguridad y la salud de las personas trabajadoras.", "Disponer las medidas preventivas adecuadas a los puestos de trabajo.", "Establecer la forma de evaluación de los riesgos en los puestos de trabajo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 3, "Las disposiciones de carácter laboral que contiene la Ley 31/1995, de 8 de noviembre, de prevención de riesgos laborales tendrán el carácter de:", "De derecho necesario mínimo indisponible, y pueden ser mejoradas y desarrolladas en los convenios colectivos.", "De derecho mínimo indisponible, pero no se pueden desarrollar con los convenios colectivos.", "Carecen de carácter de derecho mínimo.", "Tienen carácter de máximo derecho."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 4, "La Ley 31/1995, de 8 de noviembre, de prevención de riesgos laborales es de aplicación en el ámbito de:", "Policía, seguridad y resguardo aduanero.", "Las relaciones laborales reguladas por el Estatuto de los trabajadores y en las relaciones de carácter administrativo o estatutario del personal al servicio de las administraciones públicas.", "Servicios operativos de protección civil y peritaje forense en los casos de grave riesgo, catástrofe y calamidad pública.", "Fuerzas Armadas y actividades militares de la Guardia Civil."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 5, "De acuerdo con el artículo 4 de la Ley de Prevención de riesgos laborales, el riesgo laboral es:", "Las enfermedades, patologías o lesiones sufridas con motivo u ocasión del trabajo.", "El conjunto de actividades o medidas adoptadas o previstas en todas las fases de actividad de la empresa.", "La posibilidad de que un trabajador sufra un determinado daño derivado del trabajo.", "Cualquier máquina, aparato, instrumento o instalación que se utiliza en el trabajo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 6, "La Ley 31/1995, de 8 de noviembre, de Prevención de riesgos laborales no es aplicable en las actividades cuyas particularidades lo impidan en el ámbito de las funciones públicas de:", "Policía, seguridad y resguardo aduanero.", "Servicios operativos de protección civil, peritaje forense en los casos de grave riesgo, catástrofe y calamidad pública.", "Fuerzas armadas y actividades militares de la Guardia Civil.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 7, "¿Cuál es la definición de daños derivados del trabajo según la Ley de Prevención de riesgos laborales?", "Los problemas de salud relacionados con las condiciones de trabajo.", "Las enfermedades, patologías o lesiones sufridas con motivo u ocasión del trabajo.", "Cualquier alteración de la salud relacionada, causada o agravada por las condiciones de trabajo.", "Las lesiones corporales y psíquicas que el trabajador sufra con ocasión o por consecuencia del trabajo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 8, "¿Cuál es la definición de prevención según la Ley 31/1995, de 8 de noviembre, de Prevención de riesgos laborales?", "El conjunto de actividades o medidas adoptadas o previstas en todas las fases de la actividad de la empresa con el fin de evitar o disminuir los riesgos derivados del trabajo.", "El conjunto de medios disponibles para ayudar en el desarrollo de la labor laboral.", "El conjunto de medios auxiliares y equipos de protección individual.", "Los procedimientos de trabajo y normativas derivadas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 9, "¿Cuál es la definición de riesgo laboral según la Ley 31/1995, de 8 de noviembre, de Prevención de riesgos laborales?", "Es el foco de emisión de gases y vapores.", "Es la casualidad de que una persona trabajadora sufra un accidente.", "Es la gravedad de un daño en la salud.", "Es la posibilidad de que un trabajador sufra un determinado daño derivado del trabajo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 10, "Para calificar un riesgo laboral desde el punto de vista de su gravedad debe valorarse conjuntamente:", "El grado de afectación a la persona trabajadora.", "La probabilidad de que se produzca el daño y su severidad.", "Sólo se valora la severidad.", "La probabilidad de que haya sufrimiento físico y no psicológico."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 11, "¿Cuál es la definición de riesgo laboral grave e inminente según la Ley 31/1995, de 8 de noviembre, de Prevención de riesgos laborales?", "Es aquél en el que las consecuencias y el daño tienen lugar a corto plazo.", "Es el hecho en el que la gravedad hace que el riesgo sea imposible prevenir.", "Es aquel que racionalmente se materializa en un futuro inmediato y pueda suponer un grave daño para la salud de la persona trabajadora.", "Es la situación inesperada que tiene graves consecuencias para la seguridad y salud de los trabajadores."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 12, "¿Cuál es la definición de equipo de trabajo según la Ley 31/1995, de 8 de noviembre, de Prevención de riesgos laborales?", "Es cualquier máquina, aparato, instrumento o instalación utilizada en el trabajo.", "Es todo aparato con el que se desarrolla el trabajo diario.", "Es todo sistema con el que se desarrolla el trabajo.", "Son las instalaciones de los centros de trabajo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 13, "¿Cuál es la definición de condición de trabajo según la Ley 31/1995, de 8 de noviembre, de Prevención de Riesgos Laborales?", "Son todas las circunstancias derivadas del trabajo.", "Es la situación más habitual en el entorno laboral.", "Son las características inherentes al desarrollo de la labor diaria.", "Es cualquier característica del trabajo que pueda tener una influencia significativa en la generación de riesgos para la seguridad y salud del trabajador o trabajadora."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 14, "¿Cuál es la definición de equipo de protección individual según la Ley 31/1995 de Prevención de riesgos laborales?", "Es todo ese equipamiento destinado a proteger la seguridad y salud del personal.", "Es cualquier equipo destinado a ser llevado o sujetado por el trabajador o trabajadora para que lo proteja de uno o varios riesgos que puedan amenazar su seguridad o salud en el trabajo, así como cualquier complemento o accesorio destinado a tal fin.", "Es cualquier elemento que protege de un riesgo laboral a varios trabajadores.", "Todo sistema de sujeción individual con el fin de evitar las caídas a nivel."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 15, "La política en materia de prevención de riesgos laborales tiene como objetivo:", "Promover la mejora de las condiciones de trabajo a fin de elevar el nivel de protección de la seguridad y la salud de los trabajadores en el trabajo.", "Mejorar las condiciones salariales y sociales de los trabajadores afiliados a la seguridad social.", "Alcanzar unas condiciones dignas de trabajo.", "Respetar la salud de los trabajadores en el trabajo adoptando medidas preventivas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 16, "Las administraciones públicas competentes en materia laboral deben llevar a cabo las funciones de:", "Promoción de la seguridad y asesoramiento jurídico en su ámbito de aplicación.", "Prevención de accidentes laborales y enfermedades profesionales.", "Promoción de la prevención, asesoramiento técnico, vigilancia y control del cumplimiento por los sujetos comprendidos en su ámbito de aplicación de la normativa de prevención de riesgos laborales, y sanción de las infracciones en caso necesario.", "Sanción de las infracciones administrativas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 17, "En relación al Instituto Nacional de Seguridad y Salud en el Trabajo (anteriormente, Instituto Nacional de Seguridad e Higiene en el Trabajo), cuál no es una función de este organismo:", "Apoyo técnico y colaboración con la Inspección de Trabajo y Seguridad Social.", "Promoción y, en su caso, realización de actividades de formación, información, investigación, estudio y divulgación en materia de prevención de riesgos laborales.", "Asesoramiento técnico en la elaboración de la normativa legal y en el desarrollo de la normalización, tanto en el ámbito nacional como internacional.", "Vigilancia del cumplimiento de la normativa sobre prevención de riesgos laborales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 18, "De acuerdo con la Ley 31/1995, de 8 de noviembre, de prevención de riesgo laborales, la función de la Inspección de Trabajo y Seguridad Social es:", "Desarrollar la normativa que incide en las condiciones de trabajo.", "Evaluar las condiciones de seguridad y salud.", "Vigilar y controlar el cumplimiento de la normativa en prevención de riesgos laborales.", "Sancionar en temas relativos a la seguridad social exclusivamente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 19, "Es un principio básico de la política de prevención de riesgos laborales", "La participación de empresarios y de trabajadores, mediante las organizaciones empresariales y sindicales más representativas, en la planificación, programación, organización y control de la gestión relacionadas con la mejora de las condiciones de trabajo y la protección de la seguridad y salud de los trabajadores.", "La elaboración de normativa laboral.", "La conciliación de la vida familiar y laboral.", "Sólo la mejora de las condiciones de trabajo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 20, "El artículo 14 de la Ley de Prevención de Riesgos Laborales establece:", "Que cuando se haya producido un daño para la salud (física o psíquica) debe investigarse.", "Que el empresario debe garantizar la seguridad y la salud de los trabajadores en todos los aspectos relacionados con el trabajo.", "Que como acción preventiva debe promocionarse la salud.", "Que debe atenuarse el trabajo monótono y repetitivo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 21, "Señale la respuesta correcta en relación al Plan de Prevención de riesgos laborales:", "Deben realizarlo aquellas empresas de más de cincuenta trabajadores.", "Las empresas, según el número de trabajadores y la naturaleza y peligrosidad de las actividades realizadas, pueden realizar el Plan de prevención de riesgos laborales de forma simplificada.", "Deben realizarlo aquellas empresas de más de cien trabajadores.", "Las empresas, según el número de trabajadores y la naturaleza y peligrosidad de las actividades realizadas, pueden realizar el Plan de prevención de riesgos laborales de forma extensa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 22, "El artículo 15 de la Ley 31/1995, de 8 de noviembre, de Prevención de riesgos laborales establece que:", "El empresario no tendrá en cuenta la capacitación profesional de los trabajadores.", "Las empresas de más de 150 empleados deben disponer de plan de emergencias.", "El diseño del puesto de trabajo no se contempla en la prevención de riesgos laborales.", "El empresario debe aplicar los principios de la acción preventiva."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 23, "El principio de sustituir lo que sea peligroso por lo que comporte poco peligro o no comporte ninguno es:", "Un principio de la acción preventiva.", "Una acción del estudio inicial.", "Un caso aplicable a productos químicos.", "No es un principio de acción preventiva."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 24, "De acuerdo con el artículo 16 de la Ley de Prevención de Riesgos Laborales, cuando se haya producido un daño para la salud de los trabajadores, el empresario:", "Debe realizar un nuevo Plan de Prevención que incluya los daños de los trabajadores.", "Debe llevar a cabo una investigación sobre el caso, a fin de detectar las causas de los hechos.", "Debe comunicar los hechos a la fiscalía.", "Debe llevar a cabo el seguimiento de la actividad preventiva a fin de perfeccionar de forma continua las actividades de identificación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 25, "El artículo 17 de la Ley 31/1995, de 8 de noviembre, de prevención de riesgos laborales dice que:", "El empresario debe proporcionar a sus empleados sólo equipos de protección individual.", "El empresario debe velar para que se haga un uso efectivo de los equipos de protección individual.", "El empresario debe proporcionar a sus empleados equipos de protección individual adecuados para el ejercicio de sus funciones y velar para que se haga un uso efectivo cuando sea necesario.", "Son necesarios los equipos de trabajo y los equipos de protección individual."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 26, "De acuerdo con el artículo 18 de la Ley de Prevención de Riesgos Laborales, el empresario debe adoptar las medidas adecuadas para que los trabajadores reciban todas las informaciones necesarias en relación con:", "Los derechos laborales que les corresponden.", "Las obligaciones en referencia a la prevención de riesgos laborales.", "Los riesgos, las medidas y las actividades de protección y prevención y las medidas adoptadas.", "El empresario no tiene ninguna obligación de informar a los trabajadores."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 27, "En relación a la información a la que se refiere el artículo 18 de la Ley de Prevención de Riesgos Laborales establece que:", "Si hay representantes de los trabajadores, debe proporcionarlo el empresario a los trabajadores a través de los representantes; no obstante, se informará directamente a cada trabajador de los riesgos específicos que afecten a su puesto de trabajo o función y de las medidas de protección y prevención aplicables a los riesgos.", "El empresario únicamente debe darlo a los representantes de los trabajadores que la harán llegar a los trabajadores.", "El empresario siempre debe darlo a los trabajadores sin la intermediación de los representantes de los trabajadores.", "La información se establece en el artículo 23 de la Ley de prevención de riesgos laborales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 28, "La formación en el ámbito de la prevención de riesgos laborales debe ser:", "Voluntaria para el empresario, pero obligatoria por el personal.", "Voluntaria para el empresario y voluntaria por el personal.", "El empresario debe garantizar para todo el personal la formación teórica y práctica en materia preventiva.", "La formación no debe centrarse específicamente en el puesto de trabajo o la función del personal."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 29, "La formación en materia preventiva de riesgos laborales debe impartirse:", "Dentro de la jornada laboral siempre que sea posible, o si no fuera posible en otras horas descontándolas de la jornada laboral.", "Fuera de la jornada laboral.", "En el período de vacaciones.", "Los cuatro primeros meses del año en curso."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 30, "Indique la afirmación correcta en relación con las situaciones de emergencia:", "Sobre las medidas de emergencia el empresario no debe hacer nada porque es competencia exclusiva de los servicios de emergencia de la Comunidad Autónoma.", "El empresario encargará siempre a una empresa la evaluación de las situaciones de emergencia, independientemente de las dimensiones y la actividad de la empresa y de la presencia de personas ajenas a la misma.", "Las situaciones de emergencia quedan fuera de las obligaciones del empresario establecidas en la Ley de Prevención de Riesgos Laborales", "El empresario, teniendo en cuenta las dimensiones y la actividad de la empresa, así como la posible presencia de personas ajenas a la misma, debe analizar las posibles situaciones de emergencia y adoptar las medidas necesarias en materia de primeros auxilios, lucha contra incendios y evacuación de los trabajadores."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 31, "Cuando el personal esté o puedan estar expuesto a un riesgo grave e inminente a causa de su trabajo, el empresario está obligado a:", "A dar aviso a la Inspección de trabajo y a la seguridad social.", "Informar de esta situación a todo el personal afectado lo antes posible, adoptar las medidas para que se pueda interrumpir la actividad laboral inmediatamente y disponer de lo necesario para adoptar las medidas necesarias para evitar las consecuencias de dicho peligro.", "Precintar el centro de trabajo.", "Dar aviso con el tiempo suficiente para aplicar las medidas preventivas necesarias."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 32, "En referencia a lo establecido en el artículo 22 de la Ley de Prevención de Riesgos Laborales en cuanto a la vigilancia de la salud, señale la respuesta incorrecta:", "Los datos relativos a la vigilancia de la salud de los trabajadores no se pueden realizar servir con fines discriminatorios ni en perjuicio del trabajador.", "El empresario debe garantizar a los trabajadores a su servicio la vigilancia periódica de su estado de salud en función de los riesgos inherentes al trabajo.", "Los resultados de la vigilancia se comunicarán a los trabajadores afectados, al empresario ya los representantes de los trabajadores.", "Las medidas de vigilancia y control de la salud deben llevarse a cabo respetando siempre el derecho a la intimidad ya la dignidad de la persona y la confidencialidad de toda la información relacionada con su estado de salud."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 33, "En relación al derecho a la vigilancia de la salud:", "Siempre debe prolongarse más allá de la finalización de la relación laboral.", "Se prolongará más allá de la finalización de la relación laboral sólo cuando el trabajador lo solicite expresamente.", "En ningún caso debe prolongarse más allá de la finalización de la relación laboral.", "Se debe prolongar en los supuestos en los que la naturaleza de los riesgos inherentes al trabajo lo haga necesario."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 34, "¿Qué documentación debe elaborar y conservar el empresario de acuerdo con la Ley 31/1995, de 8 de noviembre, de prevención de riesgos laborales?", "La evaluación de riesgos laborales de cada puesto de trabajo específico y la documentación relativa al estado de salud del personal.", "El plan de prevención y la relación de accidentes laborales, pero no la de enfermedades profesionales.", "El plan de prevención y la relación de accidentes laborales y la de enfermedades profesionales.", "El plan de prevención, la evaluación de riesgos para la seguridad y la salud del personal, la planificación preventiva, la práctica de los controles del estado de salud del personal y la relación de accidentes de trabajo y enfermedades profesionales que hayan causado al trabajador una incapacidad laboral superior a un día de trabajo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 35, "De acuerdo con el artículo 26 de la Ley de Prevención de Riesgos Laborales, las mujeres embarazadas tienen derecho:", "A ausentarse del trabajo, con derecho a remuneración, para realizar exámenes prenatales y técnicas de preparación al parto, con aviso previo al empresario y justificando la necesidad de hacerlo dentro de la jornada de trabajo.", "A ausentarse del trabajo, sin derecho a remuneración, para realizar exámenes prenatales y técnicas de preparación al parto, con aviso previo al empresario y con la justificación de la necesidad de hacerlo dentro de la jornada de trabajo.", "A ausentarse del trabajo, con derecho a remuneración, para realizar exámenes prenatales y técnicas de preparación al parto, sin la obligación de avisar previamente al empresario.", "No tienen derecho a ausentarse del trabajo, para realizar exámenes prenatales y técnicas de preparación al parto."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 36, "La coordinación de actividades empresariales implica que:", "En uno o más centros de trabajo haya más de dos empresas implicadas en el desarrollo laboral.", "En un centro de trabajo hay más de tres empresas trabajando a la vez, pero no implica ninguna responsabilidad al titular del centro.", "Cuando en un mismo centro de trabajo lleven a cabo actividades el personal de dos o más empresas, éstas deben cooperar en la aplicación de la normativa sobre prevención de riesgo laborales.", "Sólo es necesaria la cooperación documental del plan de prevención."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 37, "El artículo 25 de la Ley 31/1995, de 8 de noviembre, de prevención de riesgos laborales establece que:", "El plan de prevención debe revisarse anualmente.", "La evaluación de riesgos laborales debe revisarse anualmente.", "El plan de prevención y la evaluación de riesgos laborales caducan a los tres años.", "El empresario debe garantizar específicamente la protección del personal que por sus características personales o su estado biológico conocido sean especialmente sensibles a los riesgos derivados del trabajo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 38, "¿Qué actuaciones preventivas deben realizarse antes de la incorporación al trabajo de jóvenes menores de dieciocho años?", "Se realizará una evaluación del puesto de trabajo que éstos deban ocupar con el fin de determinar la naturaleza, el grado y la duración de su exposición a los riesgos específicos, a agentes, procesos o condiciones de trabajo que puedan poner en peligro la seguridad o salud de este trabajador.", "Deben incluirse en el plan de prevención y establecer formación específica.", "Se debe hacer una evaluación global del puesto de trabajo.", "Se tendrán sólo en cuenta las condiciones de seguridad del puesto de trabajo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 39, "¿Cuándo es necesaria la presencia de los recursos preventivos?", "Cuando se realicen actividades o procesos que por reglamento sean considerados como peligrosos o con riesgos especiales.", "Cuando los riesgos puedan verse agravados o modificados en el desarrollo del proceso o la actividad, por la concurrencia de operaciones diversas que se llevan a cabo sucesiva o simultáneamente y que hagan necesario el control de la aplicación correcta de los métodos de trabajo.", "Cuando la necesidad de esta presencia sea requerida por la Inspección de Trabajo y Seguridad Social, si las circunstancias del caso así lo exigen debido a las condiciones de trabajo detectadas.", "Todas las anteriores respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 40, "Las obligaciones del personal en materia de prevención de riesgos laborales son:", "Velar por la seguridad y salud de uno mismo.", "Velar por su propia seguridad y salud en el trabajo y por la de aquellas otras personas cuya actividad profesional pueda afectar, debido a sus actos y omisiones en el trabajo.", "Adoptar las medidas preventivas necesarias del plan de prevención.", "Implantar las instrucciones de seguridad y salud en el puesto de trabajo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 41, "El derecho de participación regulado en el Capítulo V de la Ley de Prevención de Riesgos Laborales:", "Se ejerce en el ámbito de las administraciones públicas con las adaptaciones que sean procedentes atendiendo a la diversidad de las actividades que llevan a cabo y las diferentes condiciones en que éstas se realizan, la complejidad y dispersión de la estructura organizativa y sus peculiaridades en materia de representación colectiva.", "Se ejerce de igual forma en el ámbito de la empresa privada y en el ámbito de las administraciones públicas sin adaptaciones particulares en ninguno de ambos ámbitos.", "Se ejerce siempre y únicamente a través de los representantes de los trabajadores, tanto en el ámbito de la empresa privada como en el ámbito de las administraciones públicas.", "Se ejerce siempre y únicamente a través de los trabajadores, tanto en el ámbito de la empresa privada como en el ámbito de las administraciones públicas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 42, "¿Cuál de las siguientes no es una competencia de los delegados de prevención?", "Ejercer una labor de vigilancia y control sobre el cumplimiento de la normativa de prevención de riesgos laborales.", "Promover y fomentar la cooperación de los trabajadores en la ejecución de la normativa sobre prevención de riesgos laborales", "Informar a la autoridad laboral sobre los accidentes de trabajo.", "Colaborar con la dirección de la empresa en la mejora de la acción preventiva."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 43, "Los delegados de prevención están facultados para:", "Realizar visitas a los puestos de trabajo para desempeñar una tarea de vigilancia y control del estado de las condiciones de trabajo.", "Ser informados por las autoridades laborales sobre los daños producidos en la salud de los trabajadores.", "Paralizar la actividad laboral cuando se detecten riesgos muy graves para la salud de los trabajadores", "Tener acceso, sin limitación alguna, a la información y la documentación relativa a las condiciones de trabajo y de los trabajadores."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 44, "El comité de seguridad y salud:", "Es el órgano científico y técnico especializado cuya misión es el análisis y estudio de las condiciones de seguridad y salud en el trabajo.", "Es el órgano paritario y colegiado de participación destinado a la consulta regular y periódica de las actuaciones de la empresa en materia de prevención de riesgos.", "Es el órgano al que le corresponde la función de la vigilancia y el control de la normativa sobre prevención de riesgos laborales.", "Es el órgano colegiado asesor de las administraciones públicas en la formulación de las políticas de prevención."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 45, "Indique la respuesta incorrecta en referencia al Comité de Seguridad y Salud:", "Se debe constituir un comité de seguridad y salud en todas las empresas o centros de trabajo que dispongan de cincuenta o más trabajadores.", "El Comité está formado por los delegados de prevención, por un lado, y por el empresario y/o sus representantes en número igual al de los delegados de prevención, por otro.", "El comité de seguridad y salud debe reunirse trimestralmente y siempre que lo solicite alguna de las representaciones en el mismo Comité.", "Las normas de funcionamiento del Comité de Seguridad y Salud las adopta el empresario."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 46, "El incumplimiento por parte de los empresarios de las obligaciones en materia de prevención de riesgos laborales, ¿a qué tipo de responsabilidades puede dar lugar?", "Administrativas, penales y civiles.", "Sólo penales y civiles.", "Sólo penales y administrativas.", "Sólo civiles y administrativas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 47, "¿Qué es un servicio de prevención de acuerdo con el artículo 31 de la Ley de Prevención de riesgos laborales?", "Es el conjunto de medios humanos y materiales necesarios para llevar a cabo las actividades preventivas a fin de garantizar la protección adecuada de la seguridad y la salud del personal.", "Es una empresa que se contrata para gestionar los reconocimientos médicos y la asistencia a accidentes de trabajo y enfermedades profesionales.", "Es un conjunto de medios auxiliares para establecer el plan de prevención.", "Es la empresa que se encarga de la gestión de accidentes y enfermedades profesionales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 48, "De acuerdo con el artículo 32 de la Ley 31/1995, de 8 de noviembre, de prevención de riesgos laborales, las mutuas de accidentes de trabajo y enfermedades profesionales", "Tienen prohibido la participación en actividades mercantiles de prevención.", "Pueden ejercer actividades preventivas sólo en casos concretos.", "Ejercen sus funciones de acuerdo con lo establecido en la ley.", "Las mutuas y los servicios de prevención son lo mismo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 49, "El empresario debe consultar a los trabajadores de acuerdo con:", "El artículo 1 de la Ley 31/1995, de 8 de noviembre, de prevención de riesgos laborales.", "El artículo 33 de consulta de los trabajadores de la Ley 31/1995, de 8 de noviembre, de prevención de riesgos laborales.", "El artículo 55 de la Ley 31/1995, de 8 de noviembre, de Prevención de Riesgos Laborales.", "El artículo 2 de la Ley 31/1995, de 8 de noviembre, de prevención de riesgos laborales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 50, "¿Qué son los delegados de prevención?", "Son elegidos en las elecciones sindicales.", "Son los representantes de los trabajadores con funciones específicas en materia de prevención de riesgos en el trabajo.", "Son las personas que realizan las evaluaciones de riesgos laborales.", "Los elige el empresario entre los representantes sindicales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 51, "¿Cuántos delegados de prevención son necesarios en la Administración Autonómica de las Islas Baleares con más de 5000 trabajadores?", "Al menos un delegado de prevención.", "Entre cuatro a cinco delegados de prevención.", "Ocho delegados de prevención.", "Sólo es necesario un delegado de personal."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 52, "¿A qué están obligados los delegados de prevención con arreglo al artículo 37 de la Ley 31/1995, de prevención de riesgos laborales?", "A cumplir el deber de ejecución de las medidas preventivas.", "A cumplir con secreto profesional respecto a las informaciones a las que tengan acceso como consecuencia de su actuación en la empresa.", "Están obligados a formarse por cuenta propia.", "A seguir las indicaciones y instrucciones del empresario."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 53, "¿Cuáles son las competencias y facultades del Comité de Seguridad y Salud?", "Elaborar el plan de prevención y evaluar las consecuencias en la aplicación.", "Evaluar los riesgos inherentes a los puestos de trabajo.", "Promover la aplicación de medidas correctoras.", "Participar en la elaboración, puesta en práctica y evaluación de los planes y programas de prevención de riesgos de la empresa, y promover iniciativas sobre métodos y procedimientos para la prevención de los riesgos en la empresa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 54, "¿Cuándo podrá el personal y sus representantes acudir a la Inspección de trabajo y seguridad social?", "Cuando consideren que las medidas adoptadas y los medios utilizados por el empresario no son suficientes para garantizar la seguridad y salud en el trabajo.", "No pueden recurrir porque no es función de la Inspección de trabajo y seguridad social.", "Cuando hayan pasado tres días desde el último día sometidos a riesgo grave e inminente.", "Siempre que aporten el plan de prevención implementado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 55, "¿Qué establece el artículo 41 de la Ley 31/1995, de 8 de noviembre, de Prevención de Riesgos Laborales?", "Los fabricantes, pero no los importadores deben cumplir con la Ley 31/1995, de 8 de noviembre, de prevención de riesgo laborales.", "Los fabricantes, los importadores y suministradores de maquinaria, equipos, productos y útiles de trabajo están obligados a asegurar que éstos no constituyan una fuente de peligro para el trabajador.", "Los fabricantes y suministradores deben cumplir con las disposiciones reglamentarias.", "El empresario debe hacer cumplir la ley a los fabricantes, importadores y suministradores de herramientas y servicios."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 56, "El Real decreto 486/1997, de 14 de abril, por el que se establecen las disposiciones mínimas de seguridad y salud en los puestos de trabajo no es aplicable:", "A los medios de transporte, las obras de construcción, temporales o móviles, las industrias de extracción, los buques de pesca ni campos de cultivo, bosques u otros terrenos que se encuentren fuera de la zona edificada de estos terrenos.", "A los centros de trabajo de la administración pública.", "A los centros de trabajo del ámbito hospitalario.", "A los centros de trabajo de hostelería y restauración."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 57, "¿Qué se entiende por puesto de trabajo?", "El espacio que hay de 2 metros cuadrados libres de objetos en torno al trabajador.", "Se entiende por puesto de trabajo las áreas del centro de trabajo, edificadas o no, en las que los trabajadores deben permanecer o a las que pueden acceder por razón de su trabajo.", "Sólo es el espacio en torno a la maquinaria móvil.", "Se entiende por puesto de trabajo el espacio mínimo para trabajar con una mesa y un ordenador."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 58, "¿Cómo deben ser las puertas de emergencia de un centro de trabajo?", "Las puertas de emergencia deben abrirse hacia el interior y deben estar cerradas con cerradura.", "El Real decreto 486/1997, no regula cómo son las puertas de emergencia.", "Las puertas de emergencia deben abrirse hacia el exterior y no deben estar cerradas, por lo que cualquier persona que necesite usarlas en caso de urgencia pueda abrirlas fácil e inmediatamente.", "Tienen que ser de color rojo y pueden ser correderas o giratorias."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 59, "En cuanto al orden, limpieza y mantenimiento de un centro de trabajo debe tenerse en cuenta que:", "El mantenimiento preventivo será realizado por el personal no especializado.", "Las zonas de paso, salidas y vías de circulación de los puestos de trabajo y, en especial, las salidas y vías de circulación previstas para la evacuación en casos de emergencia, deben permanecer libres de obstáculos de forma que sea posible utilizarlas en todo momento sin dificultades.", "La instalación eléctrica no debe revisarse periódicamente.", "La limpieza de centros de trabajo no es ámbito de aplicación de la ley de prevención de riesgo laborales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 60, "¿A qué riesgos laborales se ve sometido al personal que utiliza pantallas de visualización de datos?", "Solo fatiga visual.", "Fatiga física y visual.", "Somnolencia y sordera.", "Las principales alteraciones de la salud se deben, básicamente, a riesgos para la vista y los problemas físicos y de carga mental, así como el posible efecto combinado de los mismos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 61, "La iluminación de los puestos de trabajo debe cumplir con las condiciones siguientes:", "La distribución de los niveles de iluminación debe ser lo más uniforme posible y adecuado a la exigencia visual.", "No existen condiciones mínimas de iluminación.", "Con 500 lux es insuficiente para sitios administrativos.", "No es necesario tener en cuenta la iluminación en los puestos de trabajo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 62, "¿Cómo debe ser el material de primeros auxilios de un centro de trabajo?", "No es necesario el material porque el trabajador accidentado debe dirigirse a la Mutua de trabajo.", "Si el acceso al centro de asistencia médica es cercano no es necesario disponer de material de primeros auxilios.", "Debe ser adecuado, en cuanto a su cantidad y características, al número de trabajadores, a los riesgos a los que estén expuestos ya las facilidades de acceso al centro de asistencia médica más cercano.", "La Mutua de trabajo no proporciona el material necesario para actuar en caso de primeros auxilios."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 63, "En la manipulación manual de cargas, ¿que características del medio laboral pueden aumentar el riesgo dorsolumbar?", "El estado de salud del personal.", "El espacio de trabajo es insuficiente, el terreno es irregular y la iluminación es escasa.", "La carga a trasladar.", "La carencia de información y formación al personal."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 64, "¿Qué condiciones deben cumplir los equipos de protección individual?", "Deben de adecuarse al portador, después de los ajustes necesarios.", "Deben de tener en cuenta las condiciones anatómicas y fisiológicas y el estado de salud del trabajador", "Tienen que cumplir con la normativa vigente.", "Deben responder a las condiciones existentes en el puesto de trabajo, tener en cuenta las condiciones anatómicas y fisiológicas y el estado de salud del trabajador y adecuarse al portador, después de los ajustes necesarios."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 65, "¿Qué disposiciones mínimas deben cumplir los puestos de trabajo?", "Las de orden y limpieza.", "Las condiciones constructivas, orden, limpieza y mantenimiento, señalización, instalaciones de servicio o protección, condiciones ambientales, iluminación, servicios higiénicos y locales de descanso; y material y locales de primeros auxilios.", "La iluminación y puertas de emergencia.", "Las condiciones ambientales y sonoras."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 66, "El diseño y las características constructivas de los puestos de trabajo deben ofrecer seguridad frente a los riesgos:", "Sólo por riesgos higiénicos.", "De fatiga visual y postural.", "De trauma auditivo.", "De los riesgos de resbalones o caídas, choques o golpes contra objetos y derrumbes o caída de materiales sobre los trabajadores."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 67, "La exposición a los agentes físicos, químicos y biológicos del ambiente de trabajo se rige:", "Por normativa específica.", "Sólo por normativa internacional.", "Por normativa autonómica.", "Por la Ley 31/1995, de 8 de noviembre, de prevención de riesgos laborales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 68, "Las condiciones ambientales y termo higrométricas de los puestos de trabajo:", "Son valores mínimos y máximos sólo de humedad.", "No pueden ocasionar ningún riesgo para la seguridad y salud del personal.", "Son la temperatura absoluta.", "Son la humedad relativa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 69, "¿Qué aspectos de los puestos de trabajo deben tenerse en cuenta para que el personal con diversidad funcional se incorpore al puesto de trabajo teniendo en cuenta su seguridad y salud?", "Sólo se tienen en cuenta las rampas de acceso.", "Los servicios higiénicos deben estar adaptados.", "Las puertas, las vías de circulación, las escaleras, los servicios higiénicos y los puestos de trabajo, utilizados u ocupados por personal con diversidad funcional, deben estar condicionados para que estos trabajadores puedan utilizarlos.", "No es necesario realizar adaptaciones."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 70, "La instalación de ventilación de un centro de trabajo debe:", "No es necesario realizar ninguna actuación.", "Sólo debe actuar después de una avería.", "Mantener en buen estado de funcionamiento y un sistema de control debe indicar cualquier avería, siempre que sea necesario para la salud de los trabajadores.", "Cambiar anualmente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 71, "¿Deben los puestos de trabajo disponer de vestuarios cuando los trabajadores tengan que llevar ropa especial de trabajo?", "No.", "Sí.", "Nunca porque no es necesario.", "La ropa especial de trabajo no es ámbito de la prevención de riesgos laborales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 72, "¿Qué artículo de la Ley 31/1995, de prevención de riesgos laborales establece la información, consulta y participación del personal?", "El artículo 118.", "Los artículos 5 y 8.", "Los artículos 1 y 3.", "El artículo 18."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 73, "El artículo 17 de la Ley 31/1995, de 8 de noviembre, de prevención de riesgos laborales hace referencia:", "A los equipos de trabajo y medios de protección.", "A la promoción de la salud.", "Al personal sensible.", "A la formación e información a los trabajadores."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 74, "¿Es necesario disponer de servicios externos a la empresa para aplicar las medidas de emergencia?", "Sí. En particular en materia de primeros auxilios, asistencia médica de urgencia, salvamento y lucha contra incendios para garantizar la rapidez y eficacia de las mismas.", "No es necesario.", "Se establece en el artículo 22 de la Ley 31/1995, de Prevención de Riesgos Laborales.", "Sí pero no es necesario tener en cuenta ninguna particularidad."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 19, 75, "La vigilancia y el control de la salud del personal se llevará a cabo:", "Al finalizar la relación laboral con la empresa.", "Respetando siempre el derecho a la intimidad, a la dignidad de la persona y confidencialidad de la información relacionada con su estado de salud.", "La Ley 31/1995, de prevención de riesgos laborales no establece ningún criterio.", "A criterio técnico."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 1, "¿De cuántos títulos consta la Constitución española de 1978?", "De un título preliminar y VIII títulos.", "De un título preliminar y IX títulos.", "De un título preliminar y X títulos.", "De un título preliminar y XI títulos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 2, "¿Qué título de la Constitución española regula los derechos y los deberes fundamentales?", "El título preliminar.", "título I.", "título II.", "título III."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 3, "¿Qué título de la Constitución española regula el poder judicial?", "El título IV.", "El título V.", "El título VI.", "El título VII."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 4, "¿Qué título de la Constitución española regula la reforma constitucional?", "El título X.", "El título IX.", "El título VIII.", "El título VII."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 5, "¿Dónde se regula que España se constituye en un Estado social y democrático de derecho?", "En el preámbulo de la Constitución española.", "En el título preliminar de la Constitución española.", "En el título I de la Constitución española.", "En el título II de la Constitución española."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 6, "Según el artículo 1 de la Constitución española, la soberanía nacional reside :", "En las Cortes Generales.", "En el rey.", "En el pueblo español.", "En los ciudadanos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 7, "Según el artículo 1 de la Constitución española, ¿cuál es la forma política del Estado español?", "La monarquía parlamentaria.", "La democracia popular.", "La monarquía presidencialista.", "La democracia parlamentaria."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 8, "Según el artículo 2 de la Constitución española, ¿en qué se fundamenta la Constitución?", "En los principios de libertad, la justicia y la igualdad.", "En la indisoluble unidad de la nación española.", "En la soberanía nacional.", "En el principio democrático."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 9, "Según el artículo 3 de la Constitución española, las diferentes modalidades lingüísticas de España son:", "Un valor fundamental de protección.", "Un patrimonio cultural.", "Objeto de especial respeto y protección", "Las respuestas b) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 10, "Según el artículo 8 de la Constitución española, ¿qué norma ha de regular las bases de la organización militar?", "Una ley ordinaria.", "Un reglamento del ministerio competente en materia de defensa.", "Una ley orgánica.", "Un decreto ley."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 11, "Según el artículo 10 de la Constitución española, las normas relativas a los derechos fundamentales y a las libertades que la Constitución reconoce se interpretan de conformidad:", "Con la Carta de derechos sociales.", "Con la Declaración universal de derechos humanos.", "Con los tratados y los acuerdos internacionales sobre estas materias ratificados por España.", "Las respuestas b) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 12, "Según el artículo 11 de la Constitución española, ¿el Estado español puede  concertar tratados de doble nacionalidad con los países iberoamericanos?", "No.", "Sí.", "Sólo con los que hayan tenido una vinculación histórica con España.", "Sólo con los que tengan una vinculación histórica con España."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 13, "Según el artículo 18 de la Constitución española, se garantiza:", "El derecho al honor y a la intimidad.", "El derecho al honor, a la intimidad personal y a la propia imagen.", "El derecho al honor, a la intimidad personal y familiar y a la propia imagen.", "El derecho al honor y a la propia imagen."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 14, "Según el artículo 20 de la Constitución española, ¿se puede acordar el secuestro de publicaciones, grabaciones y otros medios de información?", "No, nunca.", "Sólo en virtud de resolución judicial.", "Sólo en virtud de resolución policial.", "Sólo en virtud del interés general."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 15, "Según el artículo 22 de la Constitución española, ¿se reconoce el derecho de asociación?", "Sí, sin excepciones.", "No.", "Sí, pero se prohíben las asociaciones secretas y las de carácter paramilitar.", "Sí, sólo se prohíben las de carácter paramilitar."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 16, "Según el artículo 25 de la Constitución española, ¿a qué están orientadas las penas privativas de libertad?", "Al castigo.", "A la reeducación.", "A la reinserción social.", "Las respuestas b) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 17, "Según el artículo 28 de la Constitución española, se reconoce a los trabajadores:", "El derecho a la huelga.", "El derecho a fundar sindicatos.", "El derecho a sindicarse libremente.", "Las respuestas a) b) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 18, "Según el artículo 31 de la Constitución española, el gasto público ha de llevar a cabo una asignación equitativa de los recursos públicos y la programación y la ejecución han de responder:", "A los criterios de sostenibilidad.", "A los criterios de eficiencia y economía.", "Al principio de solidaridad.", "Al principio de gasto sostenible."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 19, "Según el artículo 37 de la Constitución española, sobre el derecho a la negociación colectiva del trabajo, se garantiza:", "La fuerza vinculante de los convenios.", "La fuerza vinculante del Estatuto de los trabajadores.", "La fuerza vinculante de los contratos de trabajo.", "La revisión anual de los convenios."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 20, "Según el artículo 54 de la Constitución española, ¿qué norma regula la institución del Defensor del Pueblo?", "Una ley ordinaria.", "Un reglamento del ministerio competente en materia de justicia.", "Un decreto ley.", "Una ley orgánica."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 21, "Según el artículo 54 de la Constitución española, el Defensor del Pueblo es:", "Un alto comisionado de las Cortes Generales.", "Un miembro del Congreso de los Diputados.", "Un membre del Senado.", "Un miembro elegido por el Consejo del Estado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 22, "Según el artículo 54 de la Constitución española, ¿qué institución es la encargada de defender los derechos y los deberes fundamentales establecidos en el título I de la Constitución?", "El Consejo General del Poder Judicial.", "El Defensor del Pueblo.", "El Tribunal Constitucional.", "El Tribunal Supremo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 23, "Según el artículo 55 de la Constitución española, ¿ puede ser suspendido el derecho de los trabajadores y de los empresarios a adoptar medidas de conflicto colectivo?", "No, es un derecho fundamental.", "Sólo cuando haya sido acordada la declaración del estado de excepción.", "Sólo cuando haya sido acordada la declaración del estado de excepción o de sitio.", "Sólo cuando haya sido acordada la declaración del estado de sitio."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 24, "Según el artículo 117 de la Constitución española, los jueces y los magistrados que integran el poder judicial son:", "Independientes.", "Inamovibles.", "Responsables y sometidos únicamente al imperio de la ley.", "Las respuestas a) b) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 25, "Según el artículo 117 de la Constitución española, la justicia:", "Emana del pueblo.", "Emana de las Cortes Generales, como órgano representativo del pueblo.", "Es administrada en nombre del rey.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 26, "Según el artículo 117 de la Constitución española, ¿cuál es la base de la organización y del funcionamiento de los tribunales judiciales?", "El principio de unidad jurisdiccional.", "El principio de garantía constitucional.", "El principio de legalidad.", "El principio de publicidad e igualdad."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 27, "Según el artículo 117 de la Constitución española, ¿qué tipo de tribunales quedan prohibidos?", "Los tribunales militares.", "Los tribunales de excepción.", "Los tribunales de guerra.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 28, "Según el artículo 119 de la Constitución española, ¿la Justicia es gratuita?", "Siempre, en cualquier caso.", "Cuando la ley lo disponga.", "En cualquier caso para aquellos que acrediten insuficiencia de recursos para litigar.", "Las respuestas b) y c) son correctos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 29, "Según el artículo 120 de la Constitución española, ¿ las actuaciones judiciales tienen que ser públicas?", "Siempre, sin excepciones.", "Siempre, con algunas excepciones.", "No, siempre a puerta cerrada.", "Sólo en materia criminal."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 30, "Según el artículo 120 de la Constitución española, los procedimientos judiciales serán predominantemente orales, ¿ sobre todo, en qué materia?", "En materia criminal.", "En materia civil", "En materia mercantil.", "En materia laboral."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 31, "Según el artículo 120 de la Constitución española, las sentencias judiciales han de ser  siempre:", "Notificadas al interesado.", "Motivadas.", "Publicadas.", "Pronunciadas en audiencia privada."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 32, "Según el artículo 121 de la Constitución española, como consecuencia del funcionamiento anormal de la Administración de justicia, los daños causados por error judicial:", "Dan derecho a la repetición del proceso judicial.", "Dan derecho a reclamar al tribunal correspondiente.", "Dan derecho a una indemnización a cargo del Estado.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 33, "Según el artículo 122 de la Constitución española, ¿qué norma ha de determinar la constitución, el funcionamiento y el gobierno de los juzgados y de los tribunales?", "La ley orgánica del poder judicial.", "Una ley del ministerio competente en materia de Justicia.", "Un reglamento del Consejo del Estado.", "Un reglamento del Consejo General del Poder Judicial."); 
