insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 35, "Según el artículo 122 de la Constitución española, el Consejo General del Poder Judicial lo integran:", "El presidente del Tribunal Constitucional y  veinte miembros.", "El presidente del Tribunal Supremo y  veinte miembros.", "El presidente del Tribunal Constitucional y  quince miembros.", "El presidente del Tribunal Supremo y  quince miembros."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 36, "Según el artículo 122 de la Constitución española, el mandato de los miembros que integran el Consejo General del Poder Judicial ha de durar un periodo:", "De cuatro años.", "De cinco años.", "De seis años.", "De ocho años."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 37, "Según el artículo 122 de la Constitución española, ¿cuántos miembros del Consejo General del Poder Judicial son elegidos por el Congreso de los Diputados?", "Tres miembros.", "Cinco miembros.", "Seis miembros.", "Cuatro miembros."); 
