insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 39, "Según el artículo 123 de la Constitución española, ¿quién nombra al presidente del Tribunal Supremo?", "El rey.", "El presidente del Consejo General del Poder Judicial.", "El presidente del Gobierno.", "El presidente del Tribunal Constitucional."); 
