insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 41, "Según el artículo 124 de la Constitución española, ¿qué órgano tiene la misión de promover la acción de la justicia en defensa del interés público?", "El Tribunal Supremo.", "El Defensor del Pueblo.", "El ministerio fiscal.", "El Consejo General del Poder Judicial."); 
