insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 43, "Según el artículo 125 de la Constitución española, ¿ los ciudadanos pueden ejercer la acción popular y participar en la Administración de justicia?", "Sí, mediante la creación de jurados.", "Sí, en los tribunales consuetudinarios y tradicionales.", "No.", "Las respuestas a) y b) son correctas."); 
