insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 52, "Según el artículo 159 de la Constitución española, ¿qué se requiere para ser nombrado miembro del Tribunal Constitucional?", "Ser juristas de alto prestigio reconocido.", "Ser juristas con experiencia en otros tribunales.", "Ser juristas de competencia reconocida en más de quince años de ejercicio profesional.", "Ser juristas de competencia reconocida en más de diez años de ejercicio profesional."); 
