insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 58, "Según el artículo 161 de la Constitución española, ¿qué órgano jurisdiccional es competente para conocer de los conflictos de competencia entre el Estado y las Comunidades Autónomas?", "El Tribunal Supremo.", "El Tribunal Constitucional.", "La Audiencia Provincial.", "El Tribunal Superior de Justicia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 59, "Según el artículo 161 de la Constitución española, ¿qué órgano jurisdiccional el competente para conocer de los conflictos de competencia entre las comunidades autónomas?", "El Tribunal Supremo.", "El Tribunal Constitucional.", "La Audiencia Provincial.", "El Tribunal Superior de Justicia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 60, "Según el artículo 161 de la Constitución española, ¿qué órgano jurisdiccional es competente para conocer de los recursos de inconstitucionalidad contra leyes y disposiciones normativas con fuerza de ley?", "El Tribunal Supremo.", "El Tribunal Constitucional.", "La Audiencia Provincial.", "El Tribunal Superior de Justicia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 61, "Según el artículo 162 de la Constitución española, ¿las Cortes Generales tienen legitimidad para interponer un recurso de inconstitucionalidad?", "No.", "Sí. Se requieren cincuenta diputados o cincuenta senadores.", "Sí, con mayoría simple del Congreso.", "Sí, con mayoría absoluta del Congreso."); 
