insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 64, "Según el artículo 162 de la Constitución española, ¿quién tiene legitimidad para interponer un recurso de amparo ante el Tribunal Constitucional?", "El Defensor del Pueblo.", "El ministerio fiscal.", "Toda persona natural o jurídica que invoque un interés legítimo.", "Las respuestas a) b) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 65, "Según el artículo 164 de la Constitución española, ¿dónde se publican las sentencias del Tribunal Constitucional?", "En el Boletín Oficial del Estado.", "No se publican.", "En el boletín oficial de la comunidad autónoma.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 66, "Según el artículo 165 de la Constitución española, ¿qué norma regula el funcionamiento del Tribunal Constitucional?", "Un reglamento del Tribunal Constitucional.", "Una ley ordinaria del Gobierno.", "Una ley orgánica.", "Un reglamento del Consejo General del Poder Judicial."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 67, "Según el artículo 164 de la Constitución española, ¿es posible interponer un recurso contra una sentencia del Tribunal Constitucional?", "No.", "Sí, ante el Tribunal Supremo.", "No, con alguna excepción.", "Sí, un recurso de amparo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 68, "Según el artículo 166 de la Constitución española, ¿a quién corresponde la iniciativa de reforma constitucional?", "Al Gobierno.", "Al Congreso y al Senado.", "A les asambleas legislativas autonómicas.", "Las respuestas a) b) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 69, "Según el artículo 167 de la Constitución española, ¿qué mayoría de cada una de las cámaras se requiere para aprobar un proyecto de reforma constitucional no esencial?", "Mayoría absoluta.", "Mayoría de las tres quintas partes.", "Mayoría de las dos terceras partes.", "Mayoría simple."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 70, "Según el artículo 168 de la Constitución española, ¿es obligatorio un referéndum para ratificar una reforma total constitucional una vez que haya sido aprobada por las Cortes Generales?", "No.", "No, salvo excepciones.", "Sí.", "Sí, salvo excepciones."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 71, "Según el artículo 169 de la Constitución española, ¿cuándo no se puede iniciar una reforma constitucional?", "Durante los  estados de alarma, de excepción o de sitio vigentes.", "Durante un proceso electoral.", "En tiempos de guerra.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 72, "Según el artículo 168 de la Constitución española, si se propone la revisión total de la Constitución, se ha de proceder:", "A la aprobación por mayoría de los dos tercios de cada cámara.", "A la aprobación por mayoría absoluta de cada cámara.", "A la disolución inmediata de las Cortes.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 73, "Según el artículo 168 de la Constitución española, si se propone una revisión parcial de la Constitución que afecta al título II, se procede:", "A la aprobación por mayoría de los dos tercios de cada cámara.", "A la aprobación por mayoría absoluta de cada cámara.", "A la disolución inmediata de las Cortes.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 74, "Según el artículo 167 de la Constitución española, ¿la reforma de partes no esenciales de la Constitución se ha de someter a referéndum?", "No, nunca.", "Sí, siempre que lo pida una décima parte de los miembros de cualquiera de las cámaras.", "Sí, siempre que lo pida una tercera parte de los miembros de cualquiera de las cámaras.", "Sí, siempre que lo pida una quinta parte de los miembros de cualquiera de las cámaras."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 1, 75, "Según el artículo 168 de la Constitución española, sobre la reforma constitucional ,no se considera una parte esencial de la misma:", "El título preliminar.", "El capítulo II, sección primera del título I.", "El título II.", "El título III."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 25, "1 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, las Entidades Locales ejercen la potestad sancionadora de conformidad con lo dispuesto en:", "El Título XI de la Ley 39/2015, de 1 de octubre.", "El Título IX de la Ley 7/1985, de 2 de abril.", "El Título IX de la Ley 39/2015, de 1 de octubre.", "El Título XI de la Ley 7/1985, de 2 de abril."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 25, "2 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, dispone que el ejercicio de la potestad sancionadora corresponde a los órganos administrativos que la tengan expresamente atribuida:", "Por la Constitución.", "Por una norma con rango de Ley.", "Por disposición de rango legal o reglamentario.", "Por las normas específicas de cada órgano."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 26, "2 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, las disposiciones sancionadoras:", "Podrán producir efecto retroactivo en cuanto favorezcan al presunto infractor.", "Producirán efecto irretroactivo en cuanto favorezcan al presunto infractor.", "No producirán efecto retroactivo en cuanto favorezcan al presunto infractor.", "Producirán efecto retroactivo en cuanto favorezcan al presunto infractor."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 27, "3 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, las disposiciones reglamentarias:", "Podrán introducir especificaciones o graduaciones al cuadro de las infracciones o sanciones establecidas legalmente.", "Podrán introducir infracciones y sanciones de carácter leve.", "Podrán regular infracciones y sanciones administrativas en defecto de ley.", "Únicamente podrán regular el procedimiento sancionador."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 28, "1 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, los grupos de afectados:", "Podrán ser sancionados por hechos constitutivos de infracción administrativa.", "Podrán ser sancionados por hechos constitutivos de infracción administrativa cuando una ley les reconozca capacidad de obrar.", "No podrán ser sancionados por hechos constitutivos de infracción administrativa.", "No podrán ser sancionados por hechos constitutivos de infracción administrativa cuando una ley les reconozca capacidad de obrar."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 28, "1 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, ¿cuándo pueden ser sancionados los patrimonios independientes o autónomos?", "Cuando una ley les reconozca capacidad de obrar.", "Cuando su estatuto les reconozca capacidad de obrar.", "Cuando una ley o un reglamento les reconozca capacidad de obrar.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 28, "1 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, las personas jurídicas podrán ser sancionadas:", "Por hechos constitutivos de infracción administrativa.", "Por hechos constitutivos de infracción administrativa, cuando una Ley les reconozca capacidad de obrar.", "Por hechos constitutivos de sanción administrativa.", "Por hechos constitutivos de infracción administrativa, salvo que una Ley limite su capacidad de obrar."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 28, "1 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, los infractores son responsables a título de:", "Dolo o culpa.", "Dolo.", "Culpa.", "Dolo, culpa o imprudencia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 28, "2 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, las responsabilidades administrativas que se deriven de la comisión de una infracción:", "Serán compatibles con la exigencia al infractor de la reposición de la situación alterada por el mismo a su estado originario.", "Serán compatibles con la indemnización por los daños y perjuicios causados.", "Serán incompatibles con la indemnización por los daños y perjuicios causados.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 28, "3 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, cuando el cumplimiento de una obligación establecida por una norma con rango de Ley corresponda a varias personas conjuntamente:", "Responderán de forma solidaria de las infracciones que, en su caso, se cometan y de las sanciones que se impongan.", "Responderán de forma mancomunada de las infracciones que, en su caso, se cometan y de las sanciones que se impongan.", "Responderán de forma subsidiaria de las infracciones que, en su caso, se cometan y de las sanciones que se impongan.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 28, "3 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, cuando se imponga una sanción pecuniaria a varias personas conjuntamente, si es posible:", "Se tendrá en cuenta la capacidad económica de los responsables.", "Se individualizará en la resolución en función de la capacidad económica de cada responsable.", "No se debe valorar el grado de participación de cada responsable.", "Se individualizará en la resolución en función del grado de participación de cada responsable."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 28, "4 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, las leyes reguladoras de los distintos regímenes sancionadores:", "Deberán prever los supuestos en que determinadas personas responderán del pago de las sanciones pecuniarias impuestas a quienes de ellas dependan o estén vinculadas.", "Podrán prever los supuestos en que determinadas personas responderán del pago de las sanciones pecuniarias impuestas a quienes de ellas dependan o estén vinculadas.", "Deberán prever los supuestos en que determinadas personas responderán de las sanciones impuestas a quienes de ellas dependan o estén vinculadas.", "Podrán prever los supuestos en que determinadas personas responderán de las sanciones impuestas a quienes de ellas dependan o estén vinculadas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 29, "3 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, es un criterio de graduación de la sanción:", "La reincidencia, por comisión en el término de un año de más de una infracción de la misma naturaleza cuando así haya sido declarado por resolución firme en vía administrativa.", "La reiteración, por comisión en el término de un año de más de una infracción de la misma naturaleza cuando así haya sido declarado por resolución firme en vía administrativa.", "La reincidencia, por comisión en el término de un año de más de una infracción cuando así haya sido declarado por resolución firme en vía administrativa.", "La reiteración, por comisión en el término de un año de más de una infracción cuando así haya sido declarado por resolución firme en vía administrativa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 29, "3 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público?", "El grado de culpabilidad.", "La existencia de intencionalidad.", "La capacidad económica.", "La continuidad o persistencia en la conducta infractora."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 29, "4 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, se podrá imponer la sanción en el grado inferior:", "Cuando las circunstancias lo aconsejen y lo solicite el interesado.", "Cuando haya razones de interés público.", "Cuando lo justifique la debida adecuación entre la sanción que deba aplicarse con la gravedad del hecho constitutivo de la infracción y las circunstancias concurrentes.", "Todas las respuestas son incorrectas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 29, "5 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, cuando de la comisión de una infracción derive necesariamente la comisión de otra u otras:", "Se podrá calificar únicamente la infracción más grave cometida.", "Se deberá imponer únicamente la sanción correspondiente a la infracción más grave cometida.", "Se deberá calificar únicamente la infracción más grave cometida.", "Se podrá imponer únicamente la sanción correspondiente a la infracción más leve cometida."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 30, "1 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, en defecto de una ley específica las infracciones muy graves prescriben:", "A los seis meses.", "Al año.", "A los dos años.", "A los tres años."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 30, "1 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, las sanciones impuestas por faltas leves prescriben:", "Según lo dispuesto en las leyes que las establezcan o, en su defecto, al año.", "Al año.", "Según lo dispuesto en las leyes que las establezcan o, en su defecto, a los seis meses.", "A los seis meses."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 30, "1 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, en defecto de una ley específica las sanciones impuestas por faltas graves prescriben:", "A los seis meses.", "Al año.", "A los dos años.", "A los tres años."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 30, "1 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, ¿es posible aumentar el plazo de prescripción de las infracciones graves a hasta los tres años?", "Sí, mediante una ley.", "No, únicamente se pueden reducir los plazos de prescripción.", "Sí, mediante una ley específica o un reglamento sectorial.", "No, los plazos de prescripción no pueden ser modificados."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 30, "2 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, el plazo de prescripción de las infracciones comenzará a contarse:", "Desde el día en que la infracción se hubiera cometido.", "Desde el día siguiente a aquel en que la resolución sea ejecutable.", "Desde el día siguiente a aquel en que la infracción se hubiera cometido.", "Desde el día en que la resolución sea ejecutable."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 30, "2 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, la iniciación, con conocimiento del interesado, de un procedimiento administrativo de naturaleza sancionadora:", "Interrumpe el plazo de prescripción de la sanción.", "Interrumpe el plazo de prescripción de la infracción.", "Interrumpe el plazo de prescripción de la infracción y de la sanción.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 30, "2 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, el plazo de prescripción de la infracción se reinicia si el expediente sancionador:", "Estuviera paralizado durante menos de un mes.", "Estuviera paralizado durante menos de un mes por causa no imputable al presunto responsable.", "Estuviera paralizado durante más de un mes.", "Estuviera paralizado durante más de un mes por causa no imputable al presunto responsable."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 30, "3 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, el plazo de prescripción de las sanciones comenzará a contarse:", "Desde el día en que sea ejecutable la resolución por la que se impone la sanción o haya transcurrido el plazo para recurrirla.", "Desde el día en que la infracción se hubiera cometido.", "Desde el día siguiente a aquel en que sea ejecutable la resolución por la que se impone la sanción o haya transcurrido el plazo para recurrirla.", "Desde el día siguiente a aquel en que la infracción se hubiera cometido."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 30, "3 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, el plazo la prescripción de las sanciones vuelve a transcurrir cuando el procedimiento esté paralizado:", "Durante menos de un mes por causa no imputable al infractor.", "Durante más de un mes.", "Durante más de un mes por causa imputable al infractor.", "Durante más de un mes por causa no imputable al infractor."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 30, "3 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, en el caso de desestimación presunta del recurso de alzada interpuesto contra la resolución por la que se impone la sanción, el plazo de prescripción de la sanción comenzará a contarse:", "Desde el día siguiente a aquel en que finalice el plazo legalmente previsto para la resolución de dicho recurso.", "Desde el día siguiente a aquel en que sea ejecutable la resolución por la que se impone la sanción o haya transcurrido el plazo para recurrirla.", "Desde el día en que finalice el plazo legalmente previsto para la resolución de dicho recurso.", "Desde el día en que sea ejecutable la resolución por la que se impone la sanción o haya transcurrido el plazo para recurrirla."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 31, "1 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, dispone que:", "No podrán sancionarse los hechos que lo hayan sido penalmente, en los casos en que se aprecie identidad del sujeto, hecho y fundamento.", "No podrán sancionarse los hechos que lo hayan sido penalmente.", "No podrán sancionarse los hechos que lo hayan sido penal o administrativamente, en los casos en que se aprecie identidad del sujeto, hecho y fundamento.", "No podrán sancionarse los hechos que lo hayan sido penal o administrativamente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 31, "2 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, cuando un órgano de la Unión Europea hubiera impuesto una sanción por los mismos hechos, y siempre que no concurra la identidad de sujeto y fundamento, el órgano competente para resolver:", "Podrá tenerla en cuenta a efectos de graduar la que, en su caso, deba imponer, pudiendo minorarla, sin perjuicio de declarar la comisión de la infracción.", "Deberá archivar el procedimiento.", "Deberá tenerla en cuenta a efectos de graduar la que, en su caso, deba imponer, pudiendo minorarla, sin perjuicio de declarar la comisión de la infracción.", "Podrá archivar el procedimiento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 32, "1 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, no hay responsabilidad patrimonial de las administraciones públicas por daños que el particular:", "Tenga el deber jurídico de soportar de acuerdo con la Ley.", "Tenga el deber jurídico de soportar de acuerdo con las normas.", "No tenga el deber jurídico de soportar de acuerdo con la Ley.", "No tenga el deber jurídico de soportar de acuerdo con las normas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 32, "1 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, la anulación en vía administrativa o por el orden jurisdiccional contencioso administrativo de los actos o disposiciones administrativas:", "No presupone, por sí misma, derecho a la indemnización.", "Presupone el derecho a la indemnización.", "No presupone, por sí misma, derecho a la sanción.", "Presupone el derecho al reconocimiento de la situación jurídica individualizada del particular afectado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 32, "2 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, en los supuestos de responsabilidad patrimonial el daño alegado debe ser:", "Efectivo.", "Evaluable económicamente.", "Individualizado con relación a una persona o grupo de personas.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 32, "3 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, ¿en cuál de los siguientes supuestos puede surgir la responsabilidad patrimonial del Estado legislador?", "Cuando los daños deriven de la aplicación de una norma contraria al Derecho de la Unión Europea.", "Cuando los daños deriven de la aplicación de una norma comunitaria contraria al derecho interno.", "Cuando los daños deriven de la aplicación de una ley o una disposición general contraria al ordenamiento jurídico.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 32, "4 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, ¿qué requisitos deben cumplirse para obtener una indemnización por una lesión que sea consecuencia de la aplicación de una norma con rango de ley declarada inconstitucional?", "Que el particular haya obtenido, en cualquier instancia, sentencia firme desestimatoria de un recurso contra la actuación administrativa que ocasionó el daño.", "Que se hubiera alegado la inconstitucionalidad posteriormente declarada.", "Que el incumplimiento esté suficientemente caracterizado.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 32, "6 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, ¿desde cuándo producirá efectos la sentencia que declare la inconstitucionalidad de una norma con rango de ley?", "Desde la fecha de la notificación a los interesados.", "Desde la fecha de su publicación en el «Boletín Oficial del Estado», salvo que en la sentencia se establezca otra cosa.", "Desde la fecha de su publicación en el «Boletín Oficial del Estado» o en el boletín oficial correspondiente, salvo que en ella se establezca otra cosa.", "Desde la fecha de su publicación en el «Boletín Oficial del Estado»."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 32, "8 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, cuando el Tribunal Constitucional haya declarado, a instancia de parte interesada, la existencia de un funcionamiento anormal en la tramitación de los recursos de amparo o de las cuestiones de inconstitucionalidad, ¿qué órgano fijará el importe de las indemnizaciones que proceda abonar?", "El Consejo de Ministros.", "El Consejo de Ministros o el órgano de gobierno de la comunidad autónoma.", "El Tribunal Constitucional.", "El Ministerio de Justicia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 32, "8 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, cuando el Tribunal Constitucional haya declarado, a instancia de parte interesada, la existencia de un funcionamiento anormal en la tramitación de los recursos de amparo o de las cuestiones de inconstitucionalidad, el procedimiento para fijar el importe de las indemnizaciones se tramitará por:", "El Consejo de Estado, con audiencia al Consejo de Ministros.", "El Ministerio de Justicia, con audiencia al Consejo de Estado.", "El Consejo General del Poder Judicial, con audiencia al Consejo de Estado.", "El Consejo de Ministros o el órgano de gobierno de la comunidad autónoma, con audiencia al Consejo de Estado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 32, "9 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, habrá responsabilidad de las Administraciones Públicas por los daños y perjuicios causados a terceros durante la ejecución de contratos cuando sean consecuencia:", "De una orden inmediata y directa de la Administración.", "De los vicios del proyecto elaborado por el contratista.", "De los vicios del proyecto elaborado por la Administración.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 33, "1 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, el instrumento jurídico regulador de la actuación conjunta de diversas Administraciones públicas:", "Deberá determinar la distribución de la responsabilidad entre las diferentes Administraciones públicas.", "Podrá determinar la distribución de la responsabilidad entre las diferentes Administraciones públicas.", "Deberá determinar la distribución de la responsabilidad en función de la capacidad económica de las diferentes Administraciones públicas.", "Podrá determinar la exención de la responsabilidad de las diferentes Administraciones públicas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 33, "2 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, ¿qué criterios se tendrán en cuenta para fijar la responsabilidad patrimonial en caso de concurrencia de varias Administraciones públicas?", "Competencia.", "Interés público tutelado.", "Intensidad de la intervención.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 34, "1 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, no serán indemnizables los daños que se deriven de hechos o circunstancias:", "Que no se hubiesen podido prever o evitar según el estado de los conocimientos de la ciencia o de la técnica existentes en el momento de producción de aquéllos.", "Que se hubiesen podido prever o evitar según el estado de los conocimientos de la ciencia o de la técnica existentes en el momento de producción de aquéllos.", "Que no se hubiesen podido prever o evitar según el estado de los conocimientos de la ciencia o de la técnica existentes en el momento de la tasación de aquéllos.", "Que se hubiesen podido prever o evitar según el estado de los conocimientos de la ciencia o de la técnica existentes en el momento de la tasación de aquéllos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 34, "2 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, en los casos de responsabilidad patrimonial la indemnización se calculará con arreglo a los criterios de valoración establecidos en la legislación fiscal, de expropiación forzosa y demás normas aplicables:", "Y subsidiariamente se aplicarán las valoraciones predominantes en el mercado.", "Ponderándose, en su caso, las valoraciones predominantes en el mercado.", "Ponderándose, en su caso, las valoraciones realizadas por un perito judicial.", "Y subsidiariamente se realizará una tasación judicial."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 34, "2 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, ¿qué valoración se podrá tomar como referencia para calcular la indemnización en los casos de muerte o lesiones corporales?", "La incluida en los baremos del anexo II de la Ley 40/2015.", "La incluida en los baremos de la normativa vigente en materia de Seguros obligatorios y de la Seguridad Social.", "La incluida en los baremos de la Ley sobre responsabilidad civil y seguro en la circulación de vehículos a motor.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 34, "4 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, en los casos de responsabilidad patrimonial, ¿cuándo se puede abonar la indemnización mediante pagos periódicos?", "Cuando no haya disponibilidad presupuestaria para abonar la indemnización durante el año en curso.", "Cuando se prevea en las normas sectoriales específicas.", "Cuando resulte más adecuado para lograr la reparación debida y convenga al interés público.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 36, "2 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, ¿qué criterios se ponderarán para cuantificar la indemnización que deben abonar los empleados de la Administración en los casos de responsabilidad patrimonial?", "Incluso cuando la responsabilidad se exija directamente a la entidad de derecho privado a través de la cual actúe la Administración.", "Salvo cuando la responsabilidad se exija directamente a la entidad de derecho privado a través de la cual actúe la Administración.", "Salvo cuando la responsabilidad se exija directamente a la entidad que cubra la responsabilidad.", "Incluso cuando la responsabilidad se exija indirecta y subsidiariamente a la entidad de derecho privado a través de la cual actúe la Administración."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 36, "3 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, ¿en qué casos se debe exigir responsabilidad a los empleados públicos por los daños y perjuicios causados en los bienes o derechos de la Administración?", "El resultado dañoso producido.", "El grado de culpabilidad.", "La responsabilidad profesional del personal al servicio de las Administraciones públicas y su relación con la producción del resultado dañoso.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 36, "4 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, el plazo de alegaciones y el plazo de audiencia en los procedimientos de responsabilidad patrimonial a las autoridades y personal al servicio de las Administraciones Públicas es de:", "Cuando concurra dolo, o culpa o negligencia graves.", "Cuando concurra dolo o negligencia graves.", "Cuando concurra dolo o culpa graves.", "Cuando concurra dolo, culpa o imprudencia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 36, "4 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, el plazo para practicar pruebas en los procedimientos de responsabilidad patrimonial a las autoridades y personal al servicio de las Administraciones Públicas es:", "Diez días en ambos casos.", "Diez días para presentar alegaciones y quince días para realizar la audiencia.", "Quince días para presentar alegaciones y diez días para realizar la audiencia.", "Quince días en ambos casos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 36, "4 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, el plazo de audiencia en los procedimientos de responsabilidad patrimonial a las autoridades y personal al servicio de las Administraciones Públicas es:", "De diez días.", "No inferior a diez días ni superior a treinta.", "De quince días.", "No inferior a quince días."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 36, "4 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, en los procedimientos de responsabilidad patrimonial a las autoridades y personal al servicio de las Administraciones Públicas, ¿en qué plazo se formulará la propuesta de resolución?", "De diez días.", "No inferior a diez días.", "De quince días.", "No inferior a quince días."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 36, "4 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, ¿cuál es el plazo para dictar resolución en los procedimientos de responsabilidad patrimonial a las autoridades y personal al servicio de las Administraciones Públicas?", "Diez días a contar desde la conclusión de la fase de prueba.", "Cinco días a contar desde la finalización del trámite de audiencia.", "Diez días a contar desde la finalización del trámite de audiencia.", "No hay ningún plazo específico para formular la propuesta de resolución."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 36, "5 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, la resolución declaratoria de responsabilidad en los procedimientos de responsabilidad patrimonial a las autoridades y personal al servicio de las Administraciones Públicas:", "Cinco días a contar desde la finalización del trámite de audiencia.", "Diez días.", "Diez días a contar desde la finalización del trámite de audiencia.", "Todas las respuestas son incorrectas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 64, "2.c) de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, el acuerdo de iniciación de los procedimientos de naturaleza sancionadora contendrá:", "No podrá fin a la vía administrativa.", "Pondrá fin a la vía administrativa.", "Pondrá o no fin a la vía administrativa en función del órgano que la dicta.", "Todas las respuestas son incorrectas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 65, "1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, relativo al inicio de oficio de los procedimientos de responsabilidad patrimonial:", "Identificación del instructor y, en su caso, Secretario del procedimiento, con expresa indicación del régimen de recusación de los mismos.", "Identificación del instructor y, en su caso, Secretario del procedimiento.", "Identificación del instructor y del Secretario del procedimiento, con expresa indicación del régimen de recusación de los mismos.", "Identificación del instructor, con expresa indicación del régimen de recusación del mismo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 65, "2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, el plazo para presentar alegaciones en los procedimientos de responsabilidad patrimonial será de:", "El procedimiento iniciado se archivará si los particulares presuntamente lesionados no se personan en el plazo establecido.", "El plazo de alegaciones no será inferior a diez días.", "Para iniciar el procedimiento será necesario que no haya prescrito el derecho a la reclamación del interesado al que se refiere el artículo 67.", "El acuerdo de iniciación se notificará al instructor y al secretario del procedimiento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 67, "1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, los interesados sólo podrán solicitar el inicio de un procedimiento de responsabilidad patrimonial:", "Cinco días.", "Diez días.", "Quince días.", "Todas las respuestas son incorrectas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 67, "1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, en caso de daños de carácter físico o psíquico a las personas, el plazo para reclamar responsabilidad patrimonial empezará a computarse:", "Cuando no haya prescrito su derecho a reclamar.", "Cuando no haya caducado su derecho a reclamar.", "Cuando no haya prescrito o caducado su derecho a reclamar.", "Cuando haya prescrito o caducado su derecho a reclamar."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 67, "1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, en los casos en que proceda reconocer derecho a indemnización por anulación en vía administrativa o contencioso-administrativa de un acto o disposición de carácter general, el derecho a reclamar:", "Desde la curación o la determinación del alcance de las secuelas.", "Desde la fecha de producción de los daños.", "Desde que se manifieste el efecto lesivo.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 67, "1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, ¿cuál es el plazo de prescripción del derecho para reclamar responsabilidad patrimonial?", "Caducará al año de haberse notificado la resolución administrativa o la sentencia definitiva.", "Prescribirá al año de haberse dictado la resolución administrativa o la sentencia definitiva.", "Caducará al año de haberse dictado la resolución administrativa o la sentencia definitiva.", "Prescribirá al año de haberse notificado la resolución administrativa o la sentencia definitiva."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 67, "2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, las solicitudes de responsabilidad patrimonial deben especificar:", "Un mes.", "Seis meses.", "Un año.", "Tres años."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 81, "2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, el plazo para emitir el dictamen del Consejo de Estado en los procedimientos de responsabilidad patrimonial:", "Las lesiones producidas.", "La presunta relación de causalidad entre las lesiones y el funcionamiento del servicio público.", "El momento en que la lesión efectivamente se produjo.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 81, "2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, ¿en qué casos es preceptivo solicitar dictamen del Consejo de Estado o, en su caso, del órgano consultivo de la Comunidad Autónoma en los procedimientos de responsabilidad patrimonial?", "No podrá ser inferior a dos meses.", "Es de dos meses.", "Es de un mes.", "No podrá ser inferior a un mes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 81, "2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, en los procedimientos de responsabilidad patrimonial el órgano instructor remitirá al órgano competente para solicitar el dictamen una propuesta de resolución:", "Cuando las indemnizaciones reclamadas sean de cuantía igual o superior a 50.000 euros o a la que se establezca en la correspondiente legislación autonómica.", "En aquellos casos que disponga la Ley Orgánica 3/1980, de 22 de abril, del Consejo de Estado.", "Cuando las indemnizaciones reclamadas sean de cuantía igual o superior a 30.000 euros o a la que se establezca en la correspondiente legislación autonómica.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 81, "2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, ¿sobre cuál de los siguientes aspectos debe pronunciarse el dictamen del Consejo de Estado emitido en los procedimientos de responsabilidad patrimonial?", "En el plazo de diez días a contar desde la finalización del trámite de audiencia.", "En un plazo no superior a diez días.", "En el plazo de diez días a contar desde la emisión de la propuesta de resolución.", "En un plazo no inferior a diez días."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 81, "3 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, en los procedimientos de responsabilidad patrimonial del Estado por el funcionamiento anormal de la Administración de Justicia, el plazo para dictar resolución:", "La continuidad o persistencia en la conducta infractora.", "La valoración del daño causado y la cuantía y modo de la indemnización.", "El grado de culpabilidad o la existencia de intencionalidad.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 81, "3 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, en el caso de reclamaciones en materia de responsabilidad patrimonial del Estado por el funcionamiento anormal de la Administración de Justicia, el informe del Consejo General del Poder Judicial será emitido:", "Podrá quedar suspendido por el tiempo que medie entre la solicitud del informe del Consejo General del Poder Judicial y su recepción.", "Quedará suspendido por el tiempo que medie entre la solicitud del informe del Consejo General del Poder Judicial y su recepción.", "Podrá quedar suspendido por el tiempo que medie entre la solicitud del informe del Consejo de Estado y su recepción.", "Quedará suspendido por el tiempo que medie entre la solicitud del informe del Consejo de Estado y su recepción."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 85, "3 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, las reducciones del importe de la sanción por reconocimiento de la responsabilidad y por pago voluntario anterior a la resolución:", "En el plazo máximo de dos meses.", "En un plazo no inferior a dos meses.", "En el plazo máximo de un mes.", "En un plazo no inferior a un mes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 85, "3 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, ¿es posible modificar los porcentajes de reducción de la sanción previstos en esta la Ley?", "Serán acumulables entre sí.", "Serán acumulables entre sí cuando el interesado desista de ejercer cualquier recurso en vía administrativa o judicial contra la sanción.", "No serán acumulables entre sí.", "Serán acumulables entre sí cuando el interesado desista de ejercer cualquier recurso en vía judicial contra la sanción."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 90, "2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, relativo a las especialidades de la resolución en los procedimientos sancionadores:", "No, dado que la Ley tiene carácter básico.", "Sí, podrán ser incrementados reglamentariamente.", "Sí, pero únicamente pueden ser incrementados mediante ley específica.", "No, dado que la Ley lo prohíbe expresamente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 90, "3 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, se podrá suspender la ejecución de la sanción si el interesado manifiesta a la Administración su intención de interponer:", "En la resolución se podrán aceptar hechos distintos de los determinados en el curso del procedimiento, con un trámite de audiencia a los interesados no inferior a siete días.", "En la resolución se podrán aceptar hechos distintos de los determinados en el curso del procedimiento.", "En la resolución no se podrán aceptar hechos distintos de los determinados en el curso del procedimiento.", "En la resolución se podrán aceptar hechos distintos de los determinados en el curso del procedimiento, con un trámite de audiencia a los interesados no inferior a diez días."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 90, "4 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, la resolución del procedimiento complementario para fijar la cuantía de los daños o perjuicios causados a la Administración:", "Recurso contencioso-administrativo contra la resolución firme en vía administrativa.", "Recurso administrativo contra la sanción contra la sanción definitiva.", "Recurso administrativo contra la sanción firme en vía administrativa.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 91, "1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, relativo a la resolución de los procedimientos de responsabilidad patrimonial, ¿cuándo se someterá la propuesta de acuerdo para su formalización por el interesado y por el órgano administrativo competente para suscribirlo?", "No pondrá fin a la vía administrativa.", "No pondrá fin a la vía administrativa, salvo que por ley específica se disponga otra cosa.", "Pondrá fin a la vía administrativa.", "Pondrá fin a la vía administrativa, salvo que por ley específica se disponga otra cosa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 91, "2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, en los procedimientos de responsabilidad patrimonial será necesario que la resolución se pronuncie sobre:", "Una vez finalizado el trámite de audiencia.", "Una vez recibido, en su caso, el dictamen al que se refiere el artículo 81.2 o, cuando éste no sea preceptivo, una vez finalizado el trámite de audiencia.", "Una vez notificada la propuesta de resolución.", "Una vez iniciado el trámite de audiencia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 91, "3 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, ¿cuál es el plazo para resolver los procedimientos de responsabilidad patrimonial?", "La cuantía y el modo de la indemnización, cuando proceda.", "La existencia o no de la relación de causalidad entre el funcionamiento del servicio público y la lesión producida.", "La continuidad o persistencia en la conducta infractora.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 11, 91, "3 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, transcurridos seis meses desde que se inició el procedimiento de responsabilidad patrimonial sin que haya recaído y se notifique resolución expresa o, en su caso, se haya formalizado el acuerdo:", "Un mes.", "Tres meses.", "Seis meses.", "Un año."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 1, "De acuerdo con el artículo 116.3 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, los pliegos de cláusulas administrativas y de prescripciones técnicas serán sustituidos por el documento descriptivo:", "En el caso de que el procedimiento elegido para adjudicar el contrato sea el procedimiento abierto simplificado.", "En el caso de que el procedimiento elegido para adjudicar el contrato sea el de negociado sin publicidad.", "En el caso de que el procedimiento elegido para adjudicar el contrato sea el  de negociación con publicidad.", "En el caso de que el procedimiento elegido para adjudicar el contrato sea el de diálogo competitivo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 2, "De acuerdo con el artículo 3.1 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, se considera que no forman parte del sector público las siguientes entidades:", "La Administración General del Estado, las Administraciones de las Comunidades Autónomas, las Ciudades Autónomas de Ceuta y Melilla y las Entidades que integran la Administración Local.", "Las Entidades Gestoras y los Servicios Comunes de la Seguridad Social.", "Los Organismos Autónomos, las Universidades Públicas y las autoridades administrativas independientes.", "Los consorcios sin personalidad jurídica propia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 3, "Son competencia del orden jurisdiccional contencioso-administrativo las siguientes cuestiones:", "Las relativas a la preparación, adjudicación, efectos, modificación y extinción de los contratos administrativos.", "Las que se susciten en relación con la preparación y la adjudicación de los contratos privados de las Administraciones Públicas.", "Las relativas a la preparación y la adjudicación de los contratos de entidades del sector público que no tengan el carácter de poderes adjudicadores.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 4, "Los contratos menores, de acuerdo con el artículo 29.8 de la  Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014:", "No podrán tener una duración superior a dos años.", "No podrán tener una duración superior a un año.", "No podrán tener una duración superior a un año, pero pueden ser objeto de prórroga por un año más.", "No podrán tener una duración superior a seis meses, prorrogables por seis meses más."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 5, "Se consideran contratos menores, de acuerdo con el artículo 118 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014:", "Los de valor estimado inferior a 15.000 euros cuando se trate de suministros.", "Los de valor estimado inferior a 45.000 euros cuando se trate de obras.", "Los de valor estimado inferior a 50.000 euros cuando se trate de obras.", "Los de valor estimado inferior a 20.000 euros cuando se trate de servicios."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 6, "Los contratos  administrativos se califican en:", "Contratos de obras , servicios y gestión de servicios públicos.", "Contratos de obras, servicios , suministros, concesión de obras y concesión de servicios.", "Contratos de servicios , suministros y concesión de obras.", "Contratos de obras, servicios, concesión de obras y concesión de servicios."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 7, "Tendrán carácter privado, de acuerdo con el artículo 25 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, los siguientes contratos:", "Los contratos de servicios que tengan por objeto servicios financieros con número de referencia CPV de 66100000-1 a 66720000-3.", "Los que tengan por objeto la creación e interpretación artística y literaria  y los de espectáculos con número de referencia CPV de 79995000-5 a 79995200-7, y de 92000000-1 a 92700000-8, excepto 92230000-2, 92231000-9 y 92232000-6.", "Aquellos cuyo objeto sea la suscripción a revistas, publicaciones periódicas y bases de datos.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 8, "De acuerdo con el artículo 25.2 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, los contratos administrativos se regirán:", "En cuanto a su preparación, adjudicación, efectos, modificación y extinción, por esta Ley y sus disposiciones de desarrollo; supletoriamente se aplicarán las restantes normas de derecho administrativo y, en su defecto, las normas de derecho privado.", "En cuanto a su preparación, adjudicación, efectos y modificación por la Ley de contratos y sus disposiciones de desarrollo; y en cuanto a su extinción por las normas de derecho privado.", "En cuanto a su preparación y adjudicación por esta Ley y sus disposiciones de desarrollo; supletoriamente se aplicarán las restantes normas de derecho administrativo y, en cuanto a sus efectos, modificación y extinción por las normas de derecho privado.", "En cuanto a su preparación, adjudicación, efectos, modificación y extinción, por esta Ley y sus disposiciones de desarrollo y supletoriamente se aplicarán las normas de derecho privado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 9, "De acuerdo con el artículo 27 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, las cuestiones relativas a la preparación y adjudicación de los contratos privados de las Administraciones públicas, serán competencia de:", "El ordenamiento jurisdiccional civil.", "El ordenamiento jurisdiccional penal.", "El ordenamiento jurisdiccional laboral.", "El ordenamiento jurisdiccional contencioso-administrativo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 10, "El contrato de mantenimiento de un centro público educativo es un contrato:", "De obras.", "De servicios.", "De suministros.", "De gestión de servicios públicos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 11, "De acuerdo con el artículo 34 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, en los contratos del sector público podrán incluirse cualesquiera pactos, cláusulas y condiciones, siempre que:", "No sean contrarios al interés público, al ordenamiento jurídico y a los principios de buena administración.", "No sean contrarios a la moral y al principio de igualdad.", "No sean contrarios al principio de proporcionalidad y de igualdad.", "No sean contrarios al principio de lealtad institucional."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 12, "De acuerdo con el artículo 19 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, no se consideran sujetos a regulación armonizada, cualquiera que sea su valor estimado, los contratos siguientes:", "Los que tengan por objeto la adquisición, el desarrollo, la producción o la coproducción de programas destinados a servicios de comunicación audiovisual o servicios de comunicación radiofónica.", "Los incluidos dentro del ámbito definido por el artículo 346 del Tratado de Funcionamiento de la Unión Europea que se concluyan en el sector de la inmigración.", "Aquellos que tengan por objeto los servicios de certificación y autenticación de documentos que deban ser prestados por un notario público.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 13, "Señale la respuesta incorrecta. De acuerdo con el artículo 152.4  de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014:", "El desistimiento del procedimiento deberá estar fundado en una infracción no subsanable de las normas de preparación del contrato o de las reguladoras del procedimiento de adjudicación.", "Se deberá justificar  en el expediente la concurrencia de la causa del desistimiento.", "El desistimiento no impedirá la iniciación inmediata de un procedimiento de licitación.", "El desistimiento impedirá la iniciación inmediata de un procedimiento de licitación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 14, "Indique cuál de los siguientes no es un procedimiento de adjudicación de los contratos administrativos:", "Diálogo competitivo.", "Asociación para la innovación.", "Procedimiento con negociación.", "Asociación para la investigación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 15, "De acuerdo con el artículo 96 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, la inscripción en el Registro Oficial de Licitadores y Empresas Clasificadas del Sector Público acreditará frente a todos los órganos de contratación del sector público, a tenor de lo en él reflejado y salvo prueba en contrario:", "La solvencia económica y financiera y técnica o profesional y la clasificación.", "Las condiciones de aptitud del empresario en cuanto a su personalidad y capacidad de obrar, representación, habilitación profesional o empresarial.", "La concurrencia o no concurrencia de las prohibiciones de contratar.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 16, "En el procedimiento abierto simplificado previsto en el artículo 159.6  de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014:", "Solo se eximirá a los licitadores de la acreditación de la solvencia económica.", "Se eximirá a los licitadores de la acreditación de la solvencia económica y financiera y técnica o profesional.", "La oferta se entregará en tres sobres o archivos electrónicos.", "Se requerirá constitución de garantía definitiva."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 17, "De acuerdo con el artículo 26 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, tendrán la consideración de contratos privados:", "Los que celebren las Administraciones Públicas que tengan por objeto servicios financieros con número de referencia CPV de 66100000-1 a 66720000-3.", "Los celebrados por entidades del sector público que siendo poder adjudicador reúnan la condición de Administraciones Públicas.", "Los celebrados por entidades del sector público que no reúnan la condición de poder adjudicador.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 18, "De acuerdo con el artículo 72 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, los órganos de contratación apreciarán directamente las prohibiciones de contratar de las personas en quienes concurran algunas de las circunstancias siguientes:", "Haber sido condenadas mediante sentencia firme por delitos de terrorismo.", "Haber sido sancionadas con carácter firme por infracción grave en materia profesional que ponga en entredicho su integridad, de disciplina de mercado, o de falseamiento de la competencia.", "Haber solicitado la declaración de concurso voluntario.", "Haber incurrido en falsedad al facilitar cualesquiera otros datos relativos a su capacidad y solvencia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 19, "De acuerdo con el artículo 36.4  de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, salvo que se indique otra cosa en su clausulado, los contratos del sector público se entenderán celebrados:", "En el lugar donde se encuentre la sede del órgano de contratación.", "En el lugar donde se encuentre la sede del contratista.", "En el lugar donde se lleve a cabo la ejecución del contrato.", "En el lugar donde se recepcione el contrato."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 20, "Señale la respuesta incorrecta. De acuerdo con el artículo 11 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, quedan excluidos del ámbito de aplicación de la Ley:", "Los contratos relativos a servicios de arbitraje y conciliación.", "Los contratos que tengan por objeto servicios relacionados con campañas políticas.", "Los contratos regulados en la legislación laboral.", "Los contratos de servicios de limpieza."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 21, "De acuerdo con el artículo 198.4 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, la Administración tendrá la obligación de abonar el precio:", "Dentro de los treinta días siguientes a la fecha de aprobación de las certificaciones de obra o de los documentos que acrediten la conformidad con lo dispuesto en el contrato de los bienes entregados o servicios prestados.", "Dentro de los cuarenta días siguientes a la fecha de aprobación de las certificaciones de obra o de los documentos que acrediten la conformidad con lo dispuesto en el contrato de los bienes entregados o servicios prestados.", "Dentro de los sesenta días siguientes a la fecha de aprobación de las certificaciones de obra o de los documentos que acrediten la conformidad con lo dispuesto en el contrato de los bienes entregados o servicios prestados.", "Dentro de los quince días siguientes a la fecha de aprobación de las certificaciones de obra o de los documentos que acrediten la conformidad con lo dispuesto en el contrato de los bienes entregados o servicios prestados."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 22, "De acuerdo con el artículo 65 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, solo podrán contratar con el sector público:", "Las personas naturales o jurídicas, españolas o extranjeras, que tengan plena capacidad de obrar.", "Las personas naturales o jurídicas, españolas o extranjeras, que no estén incursas en alguna prohibición de contratar.", "Las personas naturales o jurídicas, españolas o extranjeras, que acrediten su solvencia económica y financiera y técnica o profesional o, en los casos en que así lo exija esta Ley, se encuentren debidamente clasificadas.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 23, "La construcción de una presa es un contrato administrativo:", "De servicios.", "De suministros.", "De obras.", "De concesión de servicios."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 24, "Señale la respuesta correcta, cuando al vencimiento de un contrato no se hubiera formalizado el nuevo contrato que garantice la continuidad de la prestación a realizar por el contratista como consecuencia de incidencias resultantes de acontecimientos imprevisibles para el órgano de contratación producidas en el procedimiento de adjudicación y existan razones de interés público para no interrumpir la prestación:", "Se podrá prorrogar el contrato originario hasta que comience la ejecución del nuevo contrato y en todo caso por un periodo máximo de doce meses, sin modificar las restantes condiciones del contrato, siempre que el anuncio de licitación del nuevo contrato se haya publicado con una antelación mínima de tres meses respecto de la fecha de finalización del contrato originario.", "Se podrá prorrogar el contrato originario hasta que comience la ejecución del nuevo contrato y en todo caso por un periodo máximo de nueve meses, sin modificar las restantes condiciones del contrato, siempre que el anuncio de licitación del nuevo contrato se haya publicado con una antelación mínima de tres meses respecto de la fecha de finalización del contrato originario.", "Se podrá prorrogar el contrato originario hasta que comience la ejecución del nuevo contrato y en todo caso por un periodo máximo de doce meses, sin modificar las restantes condiciones del contrato, aunque el anuncio de licitación del nuevo contrato no se haya publicado.", "Se podrá prorrogar el contrato originario hasta que comience la ejecución del nuevo contrato y en todo caso por un periodo máximo de nueve meses, sin modificar las restantes condiciones del contrato, siempre que el anuncio de licitación del nuevo contrato se haya publicado con una antelación mínima de seis meses respecto de la fecha de finalización del contrato originario."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 25, "De acuerdo con el artículo 32.2 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, para la condición de medio propio personificado de la entidad destinataria del encargo respecto del poder adjudicador concreto que hace el encargo, ¿qué requisitos, entre otros, se deben cumplir?", "Deberá reconocerse expresamente en sus estatutos o actos de creación.", "Será necesaria la conformidad o autorización expresa del poder adjudicador respecto del que vaya a ser medio propio.", "Será necesaria la verificación por la entidad pública de que dependa el ente que vaya a ser medio propio, de que cuenta con medios personales y materiales apropiados para la realización de los encargos de conformidad con su objeto social.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 26, "De acuerdo con el artículo 99  de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014:", "El objeto de los contratos deberá ser indeterminado.", "Podrá fraccionarse un contrato con la finalidad de disminuir la cuantía del mismo.", "Deberá preverse siempre la realización independiente de cada una de sus partes mediante su división en lotes.", "No podrá fraccionarse un contrato con la finalidad de disminuir la cuantía del mismo y eludir así los requisitos de publicidad o los relativos al procedimiento de adjudicación que correspondan."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 27, "De acuerdo con el artículo 27 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, las cuestiones relativas a la preparación y adjudicación de los contratos de entidades del sector público que no tengan el carácter de poderes adjudicadores, serán competencia:", "Del ordenamiento jurisdiccional civil.", "Del ordenamiento jurisdiccional penal.", "Del ordenamiento jurisdiccional laboral.", "Del ordenamiento jurisdiccional contencioso-administrativo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 28, "De acuerdo con el artículo 63.3 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, en el caso de la información relativa a los contratos, deberá publicarse en el perfil del contratante:", "La memoria justificativa del contrato, el informe de insuficiencia de medios en el caso de contratos de servicios, la justificación del procedimiento utilizado para su adjudicación cuando se utilice un procedimiento distinto del abierto o del restringido.", "El objeto detallado del contrato, su duración, el presupuesto base de licitación y el importe de adjudicación, incluido el Impuesto sobre el Valor Añadido.", "El pliego de cláusulas administrativas particulares y el de prescripciones técnicas que hayan de regir el contrato o documentos equivalentes, en su caso, y el documento de aprobación del expediente.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 29, "De acuerdo con el artículo 103.5 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, salvo en los contratos de suministro de energía, cuando proceda, la revisión periódica y predeterminada de precios en los contratos del sector público tendrá lugar:", "Cuando el contrato se hubiese ejecutado, al menos, en el 20 por ciento de su importe y hubiesen transcurrido dos años desde su formalización. No obstante, la condición relativa al porcentaje de ejecución del contrato no será exigible en los contratos de concesión de servicios.", "En todo caso cuando el contrato se hubiese ejecutado, al menos, en el 25 por ciento de su importe y hubiesen transcurrido dos años desde su formalización.", "Cuando el contrato se hubiese ejecutado, al menos, en el 30 por ciento de su importe y hubiesen transcurrido dos años desde su formalización. No obstante, la condición relativa al porcentaje de ejecución del contrato no será exigible en los contratos de concesión de servicios.", "En todo caso cuando el contrato se hubiese ejecutado, al menos, en el 15 por ciento de su importe y hubiesen transcurrido dos años desde su formalización."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 30, "De acuerdo con el artículo 107 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, en casos especiales, el órgano de contratación podrá establecer en el pliego de cláusulas administrativas particulares que, además de la garantía a que se refiere el apartado anterior, se preste una garantía complementaria:", "De hasta un 5 por 100 del precio final ofertado por el licitador que presentó la mejor oferta, excluido el Impuesto sobre el Valor Añadido, pudiendo alcanzar la garantía total un 10 por 100 del precio.", "De hasta un 3 por 100 del precio final ofertado por el licitador que presentó la mejor oferta, excluido el Impuesto sobre el Valor Añadido, pudiendo alcanzar la garantía total un 8 por 100 del precio.", "De hasta un 5 por 100 del precio final ofertado por el licitador que presentó la mejor oferta, excluido el Impuesto sobre el Valor Añadido, pudiendo alcanzar la garantía total un 8 por 100 del precio.", "De hasta un 3 por 100 del precio final ofertado por el licitador que presentó la mejor oferta, excluido el Impuesto sobre el Valor Añadido, pudiendo alcanzar la garantía total un 10 por 100 del precio."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 31, "De acuerdo con el artículo 29.4 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, como regla general, los contratos de suministros y de servicios de prestación sucesiva tendrán un plazo máximo de duración de:", "Cinco años, incluyendo las posibles prórrogas.", "Cinco años más prórroga de cinco años más.", "Tres años incluyendo las posibles prórrogas.", "Tres años más prórroga de hasta tres años más."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 32, "De acuerdo con el artículo 111.2 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, el acuerdo de devolución de la garantía constituida:", "Deberá adoptarse y notificarse al interesado en el plazo de tres meses desde la finalización del plazo de garantía.", "Deberá adoptarse y notificarse al interesado en el plazo de seis meses desde la finalización del plazo de garantía.", "Deberá adoptarse y notificarse al interesado en el plazo de dos meses desde la finalización del plazo de garantía.", "Deberá adoptarse y notificarse al interesado en el plazo de un mes desde la finalización del plazo de garantía."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 33, "De acuerdo con el artículo 116 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, en el expediente de contratación se deberá justificar:", "La elección del procedimiento de licitación.", "Los criterios de solvencia técnica o profesional, y económica y financiera, y los criterios que se tendrán en consideración para adjudicar el contrato, pero no la clasificación que se exija a los participantes.", "El presupuesto de licitación del contrato sin incluir el valor estimado del contrato.", "El informe de suficiencia de medios."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 34, "Cuando la Administración tenga que contratar de manera inmediata a causa de acontecimientos catastróficos, de situaciones que supongan un grave peligro o de necesidades que afecten a la defensa nacional, se estará ante una tramitación:", "De emergencia.", "De excepción.", "De urgencia.", "De riesgo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 35, "De acuerdo con el artículo 122 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, en los pliegos de cláusulas administrativas particulares se incluirán:", "Los criterios de solvencia y de adjudicación del contrato.", "Las consideraciones sociales, laborales y ambientales que se establezcan como criterios de solvencia, de adjudicación o como condiciones especiales de ejecución.", "Los pactos y condiciones definidores de los derechos y obligaciones de las partes del contrato.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 36, "Los expedientes de contratación administrativa pueden ser de tramitación:", "Ordinaria y urgente.", "Ordinaria y por emergencia.", "Ordinaria.", "Ordinaria, por urgencia y por emergencia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 37, "Si un licitador suscribe una propuesta en unión temporal con otros y, además, suscribe una propuesta de forma individual o figura en más de una unión temporal, la infracción de estas normas:", "Dará lugar a la admisión sólo de una de las propuestas por él suscritas.", "Dará lugar a la no admisión de todas las propuestas por él suscritas.", "Dará lugar a la admisión de la propuesta que elija el licitador de entre todas las presentadas.", "Dará lugar a la admisión de la primera propuesta que el licitador hubiera presentado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 38, "De acuerdo con el artículo 140 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, en relación con la presentación de la documentación acreditativa del cumplimiento de los requisitos previos:", "Las proposiciones en el procedimiento abierto deberán ir acompañadas de una declaración responsable que se ajustará al formulario de documento europeo único de contratación.", "En los casos en que el empresario recurra a la solvencia y medios de otras empresas de conformidad con el artículo 75 de la Ley, cada una de ellas también deberá presentar una declaración responsable.", "En todos los supuestos en que en el procedimiento se exija la constitución de garantía provisional, se aportará el documento acreditativo de haberla constituido.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 39, "De acuerdo con el artículo 145.3 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, la aplicación de más de un criterio de adjudicación procederá, en todo caso, en la adjudicación de los siguientes contratos:", "Cuando el órgano de contratación considere que la definición de la prestación no es susceptible de ser mejorada por otras soluciones técnicas.", "Aquellos que no requieran el empleo de tecnología especialmente avanzada o cuya ejecución sea particularmente compleja.", "Contratos de concesión de obras y de concesión de servicios.", "Contratos de servicios con prestaciones indefinidas técnicamente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 40, "La evaluación de las ofertas conforme a los criterios cuantificables mediante la mera aplicación de fórmulas:", "En todo caso se realizará previamente a la de aquellos otros criterios en que no concurra esta circunstancia.", "En todo caso se realizará tras efectuar previamente la de aquellos otros criterios en que no concurra esta circunstancia, dejándose constancia documental de ello.", "Podrá realizarse previamente a la de aquellos otros criterios en que no concurra esta circunstancia.", "Podrá realizarse previamente o con posterioridad a la de aquellos otros criterios en que no concurra esta circunstancia a elección del órgano de contratación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 41, "Señale la respuesta correcta, de acuerdo con el artículo 153.3 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, si el contrato es susceptible de recurso especial en materia de contratación conforme al artículo 44:", "La formalización no podrá efectuarse antes de que transcurran diez días hábiles desde que se remita la notificación de la adjudicación a los licitadores y candidatos. Las Comunidades Autónomas podrán incrementar este plazo, sin que exceda de dos meses.", "La formalización no podrá efectuarse antes de que transcurran diez días hábiles desde que se remita la notificación de la adjudicación a los licitadores y candidatos. Las Comunidades Autónomas podrán incrementar este plazo, sin que exceda de un mes.", "La formalización no podrá efectuarse antes de que transcurran quince días hábiles desde que se remita la notificación de la adjudicación a los licitadores y candidatos. Las Comunidades Autónomas podrán incrementar este plazo, sin que exceda de un mes.", "La formalización no podrá efectuarse antes de que transcurran quince días hábiles desde que se remita la notificación de la adjudicación a los licitadores y candidatos. Las Comunidades Autónomas solo podrán incrementar este plazo en diez días."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 42, "La tramitación del procedimiento abierto simplificado se ajustará a las siguientes especialidades:", "La oferta se presentará en dos o tres sobres o archivos electrónico en los supuestos en que en el procedimiento se contemplen criterios de adjudicación cuya cuantificación dependa de un juicio de valor. En caso contrario, la oferta se presentará en dos sobres o archivos electrónicos.", "La oferta se presentará en un único sobre o archivo electrónico en todo caso.", "La oferta se presentará en un único sobre o archivo electrónico en los supuestos en que en el procedimiento no se contemplen criterios de adjudicación cuya cuantificación dependa de un juicio de valor. En caso contrario, la oferta se presentará en dos sobres o archivos electrónicos.", "La oferta se presentará en dos sobres o archivos electrónicos en todo caso."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 43, "Cuando el órgano de contratación proceda a la división en lotes del objeto del contrato, éste podrá introducir las siguientes limitaciones, justificándolas debidamente en el expediente:", "Podrá limitar el número de lotes para los que un mismo candidato o licitador puede presentar oferta.", "Podrá limitar el número de lotes para los que un mismo candidato o licitador puede presentar oferta, pero no podrá limitar el número de lotes que pueden adjudicarse a cada licitador.", "Podrá limitar el número de lotes que pueden adjudicarse a cada licitador.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 44, "Señale la respuesta incorrecta. En los contratos de obras de valor estimado inferior a 80.000 euros, y en contratos de suministros y de servicios de valor estimado inferior a 60.000 euros, excepto los que tengan por objeto prestaciones de carácter intelectual a los que no será de aplicación el apartado 6 del artículo 159 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, el procedimiento abierto simplificado podrá seguir la siguiente tramitación:", "El plazo para la presentación de proposiciones no podrá ser inferior a diez días hábiles, a contar desde el siguiente a la publicación del anuncio de licitación en el perfil de contratante. No obstante lo anterior, cuando se trate de compras corrientes de bienes disponibles en el mercado el plazo será de cinco días hábiles.", "Se eximirá a los licitadores de la acreditación de la solvencia económica y financiera y técnica o profesional.", "La oferta se entregará en un único sobre o archivo electrónico y se evaluará, en todo caso, con arreglo a criterios de adjudicación cuantificables mediante la mera aplicación de fórmulas establecidas en los pliegos.", "Se requerirá la constitución de garantía definitiva y la formalización del contrato podrá efectuarse mediante la firma de aceptación por el contratista de la resolución de adjudicación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 45, "De acuerdo con el artículo 80 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, los acuerdos relativos a la clasificación de las empresas se adoptarán  por las Comisiones Clasificadoras de la Junta Consultiva de Contratación Pública del Estado:", "Con eficacia general frente a todos los órganos de contratación.", "Con eficacia limitada al territorio sede del órgano de contratación.", "Con eficacia limitada al procedimiento de licitación en cuestión.", "Con eficacia limitada a seis meses."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 46, "Cuando en la tramitación de un procedimiento negociado sin publicidad únicamente participe un candidato, la mesa de contratación, o en su defecto, el órgano de contratación:", "Negociará con el candidato en todo caso.", "Podrá negociar con el candidato.", "No tendrá que negociar con el candidato.", "Deberá negociar con el candidato siempre y cuando sea posible."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 47, "Señale la respuesta incorrecta. De acuerdo con el articulo 180 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, el procedimiento de contratación de asociación para la innovación:", "Se estructurará en fases sucesivas siguiendo la secuencia de las etapas del proceso de investigación e innovación, que podrá incluir la fabricación de los productos, la prestación de los servicios o la realización de las obras.", "Se estructurará en fases independientemente de que sean sucesivas de acuerdo con una serie de etapas del proceso de investigación e innovación, que podrá incluir la fabricación de los productos, la prestación de los servicios o la realización de las obras.", "La asociación para la innovación fijará unos objetivos intermedios que deberán alcanzar los socios y proveerá el pago de la retribución en plazos adecuados.", "En ningún caso, la resolución de la asociación para la innovación o la reducción del número de candidatos participantes dará lugar a indemnización, sin perjuicio de la contraprestación que, en las condiciones establecidas en el pliego, corresponda por los trabajos realizados."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 48, "De acuerdo con el articulo 190 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, el órgano de contratación no ostenta las siguientes prerrogativas:", "Interpretar los contratos administrativos y resolver las dudas que ofrezca su cumplimiento.", "Modificar los contratos administrativos por razones de interés público.", "Declarar la responsabilidad imputable al contratista a raíz de la ejecución del contrato.", "Inspeccionar las instalaciones, oficinas y demás emplazamientos en los que el contratista desarrolle sus actividades, aunque no sean determinantes para el desarrollo de las prestaciones objeto del contrato."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 49, "De acuerdo con el artículo 191.3 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, será preceptivo el dictamen del Consell Consultiu en el ámbito de la Comunitat Autònoma de les Illes Balears:", "En el caso de que el órgano de contratación ejerza la prerrogativa de  interpretar el contrato.", "En el caso de que el órgano de contratación ejerza la prerrogativa de anular el contrato.", "En el caso de que el órgano de contratación ejerza la prerrogativa de  resolver el contrato, cuando se formule oposición por parte del contratista.", "En el caso de las modificaciones de los contratos cuando no estuvieran previstas en el pliego de cláusulas administrativas particulares y su cuantía, aislada o conjuntamente, sea superior a un 40 por ciento del precio inicial del contrato, IVA excluido, y su precio sea igual o superior a 8.000.000 de euros."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 50, "De acuerdo con el artículo 204 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, los contratos de las Administraciones Públicas podrán modificarse durante su vigencia cuando en los pliegos de cláusulas administrativas particulares se hubiere advertido expresamente de esta posibilidad:", "Hasta un máximo del veinte por ciento del precio inicial.", "Hasta un máximo del diez por ciento del precio inicial.", "Hasta un máximo del quince por ciento del precio inicial.", "Hasta un máximo del treinta por ciento del precio inicial."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 51, "En los contratos se fijará un plazo de garantía a contar desde:", "La fecha de recepción o conformidad del contrato.", "La fecha de formalización del contrato.", "La fecha de aprobación del contrato.", "La fecha de pago del contrato."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 52, "No son causa de resolución del contrato:", "La prórroga del contrato.", "La declaración de concurso o la declaración de insolvencia en cualquier otro procedimiento.", "El mutuo acuerdo entre la Administración y el contratista.", "El incumplimiento de la obligación principal del contrato."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 53, "Señale la respuesta incorrecta:", "Los subcontratistas quedarán obligados solo ante el contratista principal que asumirá, por tanto, la total responsabilidad de la ejecución del contrato frente a la Administración, con arreglo estricto a los pliegos de cláusulas administrativas particulares o documento descriptivo, y a los términos del contrato.", "Si así se prevé en los pliegos, los licitadores deberán indicar en la oferta la parte del contrato que tengan previsto subcontratar, señalando su importe, y el nombre o el perfil empresarial, definido por referencia a las condiciones de solvencia profesional o técnica, de los subcontratistas a los que se vaya a encomendar su realización.", "En todo caso, el contratista deberá comunicar por escrito, tras la adjudicación del contrato y, a más tardar, cuando inicie la ejecución de este, al órgano de contratación la intención de celebrar los subcontratos, señalando la parte de la prestación que se pretende subcontratar y la identidad, datos de contacto y representante o representantes legales del subcontratista, y justificando suficientemente la aptitud de éste para ejecutarla.", "El subcontratista deberá notificar por escrito al órgano de contratación cualquier modificación que sufra."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 54, "De acuerdo con el artículo 68 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, respecto de las empresas no comunitarias:", "Adicionalmente, el pliego de cláusulas administrativas particulares podrá exigir a las empresas no comunitarias que resulten adjudicatarias de contratos de obras que abran una sucursal en España, con designación de apoderados o representantes para sus operaciones.", "Adicionalmente, el pliego de cláusulas administrativas particulares podrá exigir a las empresas no comunitarias que resulten adjudicatarias de contratos de obras que estén inscritas en el Registro Mercantil.", "Adicionalmente, el pliego de cláusulas administrativas particulares podrá exigir a las empresas no comunitarias que resulten adjudicatarias de contratos de obras que tributen en España.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 55, "De acuerdo con el artículo 219.2 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, la duración de un acuerdo marco:", "No podrá exceder de cinco años.", "No podrá exceder de tres años.", "No podrá exceder de seis años.", "No podrá exceder de cuatro años."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 56, "Señale la respuesta incorrecta. De acuerdo con el artículo 232 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, a los efectos de elaboración de los proyectos se clasificarán las obras, según su objeto y naturaleza, en los grupos siguientes:", "Obras de primer establecimiento, reforma, restauración, rehabilitación o gran reparación.", "Obras de reparación simple.", "Obras de conservación y mantenimiento.", "Obras de desgaste."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 57, "De acuerdo con el artículo 82 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, la clasificación de las empresas:", "Tendrá una vigencia indefinida en todo caso.", "Tendrá una vigencia indefinida en tanto se mantengan por el empresario las condiciones y circunstancias en que se basó su concesión.", "Tendrá una vigencia anual.", "Tendrá una vigencia por tres años."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 58, "La ejecución del contrato de obras comenzará:", "Con la formalización del contrato.", "Con el acta de comprobación del replanteo.", "Con la supervisión del proyecto.", "Con la aprobación del contrato."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 59, "Los contratos administrativos se califican en:", "Servicios, obras, suministros, concesión de obras y concesión de servicios.", "Suministros y obras.", "Servicios, obras y suministros.", "Obras y servicios."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 60, "De acuerdo con el artículo 284 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, la Administración podrá gestionar indirectamente, mediante contrato de concesión de servicios, los servicios de su titularidad o competencia siempre que sean susceptibles de explotación económica por particulares. En ningún caso podrán prestarse mediante concesión de servicios los que impliquen:", "Efectos económicos.", "Ejercicio de la autoridad inherente a los poderes públicos.", "Riesgo operacional.", "Riesgo y ventura."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 61, "Señale la respuesta incorrecta. De acuerdo con el artículo 16 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, son contratos de suministro:", "Los que tienen por objeto la adquisición, el arrendamiento financiero, o el arrendamiento, con o sin opción de compra, de productos o bienes muebles.", "Los contratos relativos a propiedades incorporales o valores negociables.", "Los que tengan por objeto la adquisición de energía primaria o energía transformada.", "Aquellos en los que el empresario se obligue a entregar una pluralidad de bienes de forma sucesiva y por precio unitario."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 62, "De acuerdo con el artículo 302 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, cuando razones técnicas o económicas debidamente justificadas en el expediente lo aconsejen, podrá establecerse en el pliego de cláusulas administrativas particulares que el pago del precio total de los bienes a suministrar consista parte en dinero y parte en la entrega de otros bienes de la misma clase, sin que, en ningún caso, el importe de éstos:", "Pueda superar el 50 por cien del precio total.", "Pueda superar el 20 por cien del precio total.", "Pueda superar el 30 por cien del precio total.", "Pueda superar el 40 por cien del precio total."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 63, "Una entidad contratante podrá instrumentar la contratación de personal a través del contrato de servicios:", "Sólo mediante un contrato menor.", "En ningún caso.", "Sólo en determinados casos siempre que el órgano de contratación lo autorice.", "Cuando concurran circunstancias sobrevenidas e imprevistas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 64, "De acuerdo con el artículo 131 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, la adjudicación se realizará, ordinariamente:", "Utilizando una pluralidad de criterios de adjudicación basados en el principio de mejor relación calidad-precio, y utilizando el procedimiento abierto o el procedimiento restringido.", "Utilizando un único criterio de adjudicación basado en el precio y utilizando el procedimiento restringido.", "Utilizando un único criterio de adjudicación basado en el precio y utilizando el procedimiento abierto.", "Utilizando una pluralidad de criterios de adjudicación basados en el principio de mejor relación calidad-precio, y utilizando el procedimiento negociado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 65, "La redacción de un proyecto de obras es un contrato de:", "Suministro.", "Concesión de obras.", "Obras.", "Servicios."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 66, "De acuerdo con el artículo 69.1 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, podrán contratar con el sector público las uniones de empresarios que se constituyan temporalmente al efecto, sin que sea necesaria la formalización de las mismas en escritura pública:", "Hasta que se haya efectuado la adjudicación del contrato a su favor.", "Hasta que se haya publicado la formalización del contrato en la Plataforma de contratación correspondiente.", "Hasta que no se haya efectuado la aprobación del expediente.", "Hasta que no se haya publicado la licitación del contrato."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 67, "La constitución de la Mesa de contratación será potestativa:", "En los procedimientos abiertos y abierto simplificado.", "En los procedimientos restringidos y de diálogo competitivo.", "En los procedimientos de licitación con negociación y de asociación para la innovación, los órganos de contratación de las administraciones públicas estarán asistidos por una mesa de contratación.", "En los procedimientos abiertos simplificados abreviados a los que se refiere el artículo 159.6 de la Ley 9/2017,de 8 de noviembre, de Contratos del Sector Público."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 68, "De acuerdo con el artículo 156.6 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, en el procedimiento abierto en el caso de los contratos de las Administraciones Públicas que no estén sujetos a regulación armonizada:", "El plazo de presentación de proposiciones no será inferior a quince días, contados desde el día siguiente al de la publicación del anuncio de licitación del contrato en el perfil del contratante. En los contratos de obras y de concesión de obras y concesión de servicios, el plazo será, como mínimo, de veintiséis días.", "El plazo de presentación de proposiciones no será inferior a veinte días, contados desde el día siguiente al de la publicación del anuncio de licitación del contrato en el perfil del contratante. En los contratos de obras y de concesión de obras y concesión de servicios, el plazo será, como mínimo, de treinta días.", "En todo caso el plazo de presentación de proposiciones no será inferior a veinte días, contados desde el día siguiente al de la publicación del anuncio de licitación del contrato en el perfil del contratante.", "El plazo de presentación de proposiciones no será inferior a quince días, contados desde el día siguiente al de la publicación del anuncio de licitación del contrato en el perfil del contratante. En los contratos de obras y de concesión de obras y concesión de servicios, el plazo será, como mínimo, de treinta días."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 69, "La Oficina Independiente de Regulación y Supervisión de la Contratación elaborará un informe de supervisión que remitirá a la Junta Consultiva de Contratación Pública del Estado, que se integrará en el informe nacional a remitir a la Comisión Europea:", "Cada tres años.", "Cada dos años.", "Cada cinco años.", "Cada cuatro años."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 70, "De acuerdo con el artículo 198.5 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, el contratista podrá proceder, en su caso, a la suspensión del cumplimiento del contrato:", "Si la demora en el pago fuese superior a cinco meses.", "Si la demora en el pago fuese superior a cuatro meses.", "Si la demora en el pago fuese superior a tres meses.", "Si la demora en el pago fuese superior a seis meses."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 71, "Señale la respuesta incorrecta. Con relación al Registro de Contratos del Sector Público, que constituye el sistema oficial central de información sobre la contratación pública en España:", "Los poderes adjudicadores comunicarán al Registro de Contratos del Sector Público, para su inscripción, los datos básicos de los contratos por ellos adjudicados, entre los que figurará la identidad del adjudicatario, y el importe de adjudicación de los mismos, junto con el desglose correspondiente del Impuesto sobre el Valor Añadido.", "Los poderes adjudicadores comunicarán al Registro de Contratos del Sector Público, para su inscripción, los datos básicos de los contratos por ellos adjudicados, entre los que figurará la identidad del adjudicatario, el objeto y el importe de adjudicación de los mismos sin el desglose del Impuesto sobre el Valor Añadido.", "Los poderes adjudicadores comunicarán, en su caso, las modificaciones, prórrogas, variaciones de plazos o de precio, importe final y extinción de los contratos.", "Las comunicaciones de datos de contratos al Registro de Contratos del Sector Público se efectuarán por medios electrónicos, informáticos o telemáticos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 72, "De acuerdo con el artículo 101 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, para el cálculo del valor estimado de los contratos de obras, suministros y servicios, se tendrá en cuenta:", "El importe total, sin incluir el Impuesto sobre el Valor Añadido.", "La totalidad de las modificaciones al alza previstas.", "Cualquier forma de opción eventual y las eventuales prórrogas del contrato.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 73, "Los órganos de contratación de las Administraciones locales, así como los de sus entidades vinculadas o dependientes:", "Podrán optar bien por alojar la publicación de sus perfiles de contratante en el servicio de información que a tal efecto estableciera la Comunidad Autónoma de su ámbito territorial, o bien por alojarlos en la Plataforma de Contratación del Sector Público.", "Deberán de forma exclusiva alojar la publicación de sus perfiles de contratante en el servicio de información que a tal efecto estableciera la Comunidad Autónoma de su ámbito territorial.", "Podrán optar de forma excluyente, bien por alojar la publicación de sus perfiles de contratante en el servicio de información que a tal efecto estableciera la Comunidad Autónoma de su ámbito territorial, o bien por alojarlos en la Plataforma de Contratación del Sector Público.", "Deberán, de forma excluyente y exclusiva, alojar la publicación de sus perfiles de contratante en el servicio de información que a tal efecto estableciera la Comunidad Autónoma de su ámbito territorial."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 74, "Señale la respuesta incorrecta. De acuerdo con la disposición adicional cuadragésima primera de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, se reconoce la naturaleza de prestaciones de carácter intelectual a los servicios:", "De arquitectura.", "De consultoría y urbanismo.", "De ingeniería.", "De investigación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 12, 75, "De acuerdo con el artículo 36.1 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, los contratos que celebren los poderes adjudicadores, a excepción de los contratos menores y de los contratos basados en un acuerdo marco y los contratos específicos en el marco de un sistema dinámico de adquisición a los que se refiere el apartado 3 de este artículo 36, se perfeccionan:", "Con su adjudicación.", "Con su formalización.", "Con su publicación.", "Con su aprobación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 1, "La Constitución española de 1978 garantiza el derecho a la autonomía de las nacionalidades y regiones que integran la Nación española en:", "El artículo 148.", "El artículo 2.", "El artículo 146.", "El artículo 12."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 2, "De acuerdo con la Constitución española, pueden acceder al autogobierno y constituirse en comunidad autónoma:", "Las provincias limítrofes con características históricas, culturales y económicas comunes, los territorios insulares y las provincias con entidad regional histórica.", "Las provincias con características históricas comunes, los territorios insulares y las provincias con entidad regional histórica, cultural o económica.", "Las provincias limítrofes con características históricas, culturales o económicas comunes, los territorios insulares y las provincias con entidad cultural histórica.", "Las provincias, los territorios insulares y las provincias con características históricas, culturales y económicas comunes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 3, "¿En qué título de la Constitución se regula el acceso a la autonomía de las provincias y regiones de España y la distribución competencial entre el Estado y las comunidades autónomas?", "En el título VII.", "En el título VI.", "En el título VIII.", "En el título III."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 4, "La organización institucional de las comunidades autónomas constituidas de acuerdo con el artículo 152 de la Constitución se basa en:", "Un parlamento, un consejo de gobierno, un presidente y un tribunal de justicia.", "Una asamblea legislativa, un consejo de gobierno presidido por un presidente y un tribunal superior de justicia.", "Una asamblea legislativa, un consejo de gobierno y un presidente.", "Un parlamento, un consejo de Gobierno y un presidente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 5, "La Constitución española de 1978, respecto de las comunidades autónomas, prohíbe:", "El desarrollo de competencias atribuidas al Estado.", "La federación entre comunidades autónomas.", "La regulación de las instituciones propias.", "Los convenios entre comunidades autónomas para la gestión y la prestación de servicios propios."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 6, "En cuanto a los convenios entre comunidades autónomas, la Constitución establece:", "Que es imprescindible la autorización de las Cortes Generales cuando se trate de convenios para la gestión y prestación de servicios propios de las comunidades que lleven a cabo el convenio.", "Que sólo se comunican al Congreso de los Diputados si se trata de convenios distintos de los de gestión y prestación de servicios propios.", "Que los ha de autorizar  el Congreso de los Diputados con independencia del objeto del convenio.", "Que han de comunicarse a las Cortes Generales cuando  se trate de convenios para la gestión y prestación de servicios propios de las comunidades que llevan a cabo el convenio."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 7, "La delimitación del territorio de las comunidades autónomas se regula:", "En la Constitución española de 1978.", "En una ley aprobada por el Senado.", "En una ley aprobada por la asamblea legislativa correspondiente.", "En el Estatuto de autonomía."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 8, "La Constitución española define los estatutos de autonomía:", "Como la norma fundacional básica de cada comunidad autónoma.", "Como la norma orgánica básica de cada comunidad autónoma.", "Como la norma institucional básica de cada comunidad autónoma.", "Como la norma institucional básica de las regiones y nacionalidades que han accedido a la autonomía por la vía del artículo 151 de la Constitución."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 9, "De acuerdo con la Constitución española de 1978, las competencias que asume cada comunidad autónoma se establecen:", "En las leyes de transferencias de competencias.", "En las leyes de traspaso de competencias.", "En los estatutos de autonomía.", "En la Constitución española."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 10, "La distribución de competencias entre el Estado y las comunidades autónomas se establece:", "En los artículos 149 y 150 de la Constitución española, respectivamente.", "En los artículos 148 y 149 de la Constitución española, respectivamente.", "En los artículos 149 y 148 de la Constitución española, respectivamente.", "En los artículos 150 y 149 de la Constitución española, respectivamente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 11, "De acuerdo con el sistema de distribución competencial entre el Estado y las comunidades autónomas, podemos distinguir las materias siguientes:", "Materias que corresponden exclusivamente al Estado; materias en que el Estado legisla y las comunidades autónomas ejecutan esta legislación, y materias que corresponden exclusivamente a las comunidades autónomas.", "Materias que corresponden exclusivamente al Estado; materias en que el Estado legisla y las comunidades autónomas ejecutan esta legislación; materias en que el Estado aprueba la legislación básica, mientras que el desarrollo legislativo y la ejecución corresponde a las comunidades autónomas, y materias que corresponden exclusivamente a las comunidades autónomas.", "Hay materias en que el Estado y las comunidades autónomas tienen indistintamente competencias legislativas y ejecutivas.", "Las respuestas b) y c)  son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 12, "Se entiende que una competencia es concurrente:", "Cuando el Estado ostenta la facultad de dictar las bases sobre una materia y la comunidad autónoma puede asumir la legislación de desarrollo.", "Cuando el Estado y la comunidad autónoma tienen la posibilidad de concurrir con idénticas facultades en la regulación de una materia.", "Cuando el Estado ostenta todas las facultades sobre una materia, excepto la de ejecución, que corresponde a las comunidades autónomas.", "Cuando los estatutos de autonomía les atribuye ese carácter."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 13, "Respecto de las competencias exclusivas del Estado que establece el artículo 149:", "Las comunidades autónomas no pueden ostentar ninguna facultad.", "Las comunidades autónomas pueden dictar normas legislativas, para sí mismas, en el marco de los principios, bases y directrices fijadas por una ley estatal, siempre que las Cortes Generales les atribuya esta facultad.", "Las comunidades autónomas tienen competencias de desarrollo normativo, si la competencia estatal exclusiva es sobre las bases.", "Los estatutos de autonomía pueden asumir algunas de ellas en virtud del principio dispositivo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 14, "En cuanto al sistema de distribución de competencias entre el Estado y las comunidades autónomas encontramos:", "Las competencias exclusivas del Estado, de acuerdo con el artículo 148 de la Constitución.", "Las competencias que pueden ser asumidas por las comunidades autónomas, según el artículo 149 de la Constitución.", "El resto de competencias, de las que la facultad o la materia no se menciona expresamente como exclusiva del Estado, que pueden ser asumidas por las comunidades autónomas, según el apartado 3 del artículo 149 de la Constitución.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 15, "Di cuál de las competencias siguientes es concurrente entre el Estado y las comunidades autónomas:", "Defensa.", "Medio ambiente.", "Cultura.", "Legislación sobre productos farmacéuticos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 16, "En los Estatutos aprobados por el procedimiento del artículo 151, la organización institucional autonómica se basa, entre otros, en una asamblea legislativa elegida por sufragio:", "Universal, con arreglo a un sistema de representación proporcional que asegure, además, la representación de las diversas zonas del territorio.", "Universal, con arreglo a un sistema de representación proporcional que asegure, además, la representación de las diversas culturas del territorio.", "Proporcional, con arreglo a un sistema de representación universal que asegure, además, la representación de las diversas zonas del territorio.", "Ninguna de las respuestas anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 17, "¿Por qué una comunidad autónoma puede tener competencia exclusiva en materias que no están incluidas en la lista del artículo 148 de la Constitución española?", "Las comunidades autónomas no pueden tener competencia exclusiva en materias que no están incluidas en el artículo 148.", "Porque el sistema de distribución de competencias en la Constitución no es un sistema cerrado, por lo que las comunidades autónomas pueden asumir competencias en aquellas materias no atribuidas al Estado.", "Porque la Constitución prevé que el Senado, por mayoría absoluta, puede atribuir a las comunidades autónomas competencias no incluidas en el artículo 148.", "Porque la Constitución prevé que el Congreso de los Diputados, en materias de competencia estatal, atribuya a las Comunidades Autónomas la facultad de dictar, para sí mismas, normas legislativas en del marco de los principios, las bases y las  directrices fijados por una ley estatal."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 18, "Son competencias compartidas:", "Aquellas en las que las facultades de Estado y las de las comunidades autónomas son coincidentes.", "Aquellas que los estatutos de autonomía les atribuya ese carácter.", "Aquellas que la Constitución atribuye al Estado la función legislativa y a las comunidades autónomas únicamente la función ejecutiva.", "Aquellas en las que determinadas facultades corresponden al Estado y otras corresponden a las comunidades autónomas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 19, "Según la doctrina, una competencia es exclusiva:", "Cuando un ente aglutina todas las facultades posibles sobre una materia determinada.", "Cuando un ente se atribuye con exclusividad una facultad sobre una materia.", "Cuando un ente conserva todas las facultades de la misma calidad sobre una materia.", "Todas las respuestas anteriores son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 20, "La tenencia y el uso de armas y explosivos:", "Es competencia exclusiva de las comunidades autónomas en su territorio.", "Se trata de una competencia compartida entre el Estado y las comunidades autónomas.", "Es competencia de la Administración local.", "Es competencia exclusiva del Estado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 21, "¿Cuál de las siguientes competencias es exclusiva del Estado?:", "La asistencia social.", "La determinación de las fuentes del derecho, con respeto a las normas de derecho foral o especial.", "La determinación de las fuentes del derecho, excepto las normas autonómicas, en cuyo caso la competencia corresponde a la comunidad autónoma.", "Los puertos y aeropuertos deportivos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 22, "¿Cuál de las siguientes competencias corresponde al Estado, según la Constitución española?", "Las alteraciones de los términos municipales comprendidos en el territorio de las comunidades autónomas.", "El fomento y la coordinación general de la búsqueda científica y técnica.", "La ordenación del territorio, el urbanismo y la vivienda.", "La agricultura y la ganadería, de acuerdo con la ordenación general de la economía."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 23, "¿Cuál de las siguientes competencias pueden asumir las comunidades autónomas?:", "Las bases y la coordinación de la planificación general de la actividad económica.", "La iluminación de costas y señales marítimas.", "Las obras públicas de interés general.", "Los aprovechamientos forestales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 24, "¿Es posible que las comunidades autónomas legislen sobre las relaciones laborales de trabajadores y empresarios radicados en el territorio respectivo?", "Sí, porque se trata de una competencia compartida entre el Estado y las comunidades autónomas.", "Sí, porque las comunidades autónomas tienen competencias de desarrollo en materia laboral.", "No, se trata de una competencia exclusiva del Estado; las comunidades autónomas sólo tienen competencias de ejecución.", "No, salvo que lo hayan asumido en los estatutos de autonomía correspondientes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 25, "¿A quien corresponde la competencia en materia de legislación procesal?", "Al Estado, como competencia exclusiva, incluida la ejecución en el territorio de las comunidades autónomas.", "Al Estado, como competencia exclusiva.", "A las comunidades autónomas en caso de haberse recogido en los respectivos estatutos de autonomía.", "A las comunidades autónomas en cuanto a la normativa de desarrollo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 26, "¿Mediante qué instrumento del Estado puede una comunidad autónoma  asumir competencias en materia de justicia?", "Mediante una ley marco.", "Mediante una ley ordinaria.", "Mediante una ley de armonización.", "Mediante una ley orgánica."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 27, "En el supuesto de que una comunidad autónoma no cumpla las obligaciones que la Constitución u otras leyes le imponen, o bien actúe de forma que atente gravemente contra el interés general de España:", "El Gobierno, previo requerimiento al presidente de la comunidad autónoma, puede adoptar las medidas necesarias para obligarla al cumplimiento forzoso de dichas obligaciones o para la protección del interés general mencionado.", "El Gobierno, con requerimiento previo al presidente de la asamblea legislativa de la comunidad autónoma, con la mayoría absoluta del Senado, puede adoptar las medidas necesarias para obligar a la comunidad autónoma al cumplimiento de dichas obligaciones o para la protección del interés general mencionado.", "El Gobierno, previo requerimiento al presidente de la comunidad autónoma y, en el caso de no ser atendido, con la aprobación por mayoría absoluta del Senado, puede adoptar las medidas necesarias para obligarla al cumplimiento forzoso de dichas obligaciones o para la protección del mencionado interés general.", "El Gobierno, con requerimiento previo al presidente de la comunidad autónoma y, en el caso de no ser atendido, con la aprobación por mayoría absoluta del Congreso de los Diputados, puede adoptar las medidas necesarias para obligarla al cumplimiento forzoso de dichas obligaciones o para la protección del mencionado interés general."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 28, "Señala la respuesta correcta:", "Las comunidades autónomas pueden convocar referéndums en su territorio.", "Las comunidades autónomas pueden convocar referéndums siempre que la consulta no afecte a las instituciones de autogobierno.", "La competencia para autorizar convocatorias de consultas populares por vía de un referéndum corresponde siempre al Estado.", "La Constitución no prevé esta competencia en su título VIII."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 29, "De acuerdo con el artículo 155 de la Constitución, cuando el Gobierno adopte las medidas que corresponda:", "Puede dar instrucciones exclusivamente a la administración de la comunidad autónoma afectada.", "Puede dar instrucciones exclusivamente al personal de la Delegación del Gobierno en la comunidad autónoma afectada.", "Sólo puede dar instrucciones al gobierno de la comunidad autónoma afectada.", "Puede dar instrucciones a todas las autoridades de la comunidad autónoma afectada."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 30, "La finalidad del Fondo de Compensación que prevé el título VIII de la Constitución es:", "Garantizar un nivel mínimo en la prestación de servicios públicos.", "Compensar servicios estatales asumidos por las comunidades autónomas.", "Corregir desequilibrios económicos interterritoriales y hacer efectivo el principio de solidaridad.", "Ninguna de las respuestas es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 31, "¿Qué ley regula el Fondo de Compensación previsto en el artículo 158 de la Constitución?", "La Ley 22/2003, de 26 de diciembre, reguladora de los Fondos de Compensación Interterritorial.", "La Ley 21/2004, de 27 de diciembre, reguladora de los Fondos de Compensación Constitucional.", "La Ley 22/2001, de 27 de diciembre, reguladora de los Fondos de Compensación Interterritorial.", "No hay ninguna ley que regule el Fondo de Compensación previsto en la Constitución."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 32, "El artículo 147 de la Constitución indica que los estatutos de autonomía deberán contener:", "La denominación de la comunidad que acuerden las entidades que hayan iniciado el procedimiento de autonomía.", "La denominación de la comunidad que mejor corresponda a su identidad histórica.", "La denominación, organización y sede de las instituciones estatales en su territorio.", "Las competencias asumidas y asumibles dentro del marco establecido en la Constitución."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 33, "Indica cuál de las respuestas siguientes no forma parte del contenido que el artículo 147 de la Constitución establece para los estatutos de autonomía.", "Las competencias asumidas dentro del marco que establece la Constitución.", "Las competencias asumidas por el Estado dentro del marco que establece la Constitución.", "Las bases para el traspaso de los servicios correspondientes a estas competencias.", "La delimitación del territorio de la comunidad autónoma."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 34, "De acuerdo con la Constitución española, los recursos de las comunidades autónomas están constituidos:", "Por sus propios impuestos, tasas y contribuciones especiales.", "Por las transferencias de un fondo de compensación interterritorial y otras asignaciones con cargo a los Presupuestos Generales del Estado.", "El producto de las operaciones de crédito.", "Todas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 35, "Con el fin de corregir desequilibrios económicos interterritoriales y hacer efectivo el principio de solidaridad, la Constitución prevé un Fondo de Compensación con destino a gastos de inversión, cuyos recursos serán distribuidos:", "Por las Cortes Generales entre las comunidades autónomas y provincias, en su caso.", "Por el Gobierno entre las comunidades autónomas.", "Por el Gobierno entre las comunidades autónomas y provincias, en su caso.", "Por las Cortes Generales entre las comunidades autónomas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 36, "De acuerdo con la Constitución, el Estado puede dictar leyes que establezcan los principios necesarios para armonizar las disposiciones normativas de las comunidades autónomas:", "En materias atribuidas a la competencia del Estado, cuando así lo exija el interés general.", "Incluso en el caso de materias atribuidas a la competencia de las comunidades autónomas, cuando así lo exija el interés general.", "En materias atribuidas a la competencia del Estado, cuando así lo exija la seguridad del Estado.", "Incluso en el caso de materias atribuidas a la competencia de las comunidades autónomas, cuando así lo exija la seguridad del Estado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 37, "El artículo 150 de la Constitución dispone que el Estado puede dictar leyes que establezcan los principios necesarios para armonizar las disposiciones normativas de las comunidades autónomas cuando así lo exija el interés general. ¿A quien corresponde apreciar esta necesidad?", "Al Congreso de los Diputados, por mayoría absoluta.", "A las Cortes Generales, por mayoría absoluta de cada Cámara.", "A las Cortes Generales, por mayoría de dos tercios de los miembros de cada Cámara.", "Al Congreso de los Diputados, por mayoría de dos tercios de sus miembros."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 38, "Señala la respuesta incorrecta:", "Las diferencias entre los estatutos de las diferentes comunidades autónomas no pueden implicar privilegios económicos o sociales.", "Todos los españoles tienen los mismos derechos y obligaciones en cualquier parte del territorio del Estado.", "Ninguna autoridad, excepto el Gobierno de la nación, puede adoptar medidas que directa o indirectamente obstaculicen la libertad de circulación y el establecimiento de las personas y la libre circulación de bienes en todo el territorio español.", "Los municipios disfrutan de autonomía para gestionar sus respectivos intereses."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 39, "De acuerdo con la Constitución española, ¿quién puede adoptar medidas que obstaculicen la libertad de circulación y de establecimiento de las personas y la libre circulación de bienes en todo el territorio nacional?", "Las Cortes Generales, en cualquier caso.", "El Gobierno, mediante la correspondiente delegación legislativa.", "Ninguna autoridad puede adoptar medidas que directa o indirectamente lo obstaculicen.", "Las asambleas legislativas u órganos colegiados superiores de las diferentes comunidades autónomas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 40, "¿Cuál de las siguientes competencias corresponde al Estado, según la Constitución española?", "Las alteraciones de los términos municipales comprendidos en el territorio de las comunidades autónomas.", "El fomento y la coordinación general de la búsqueda científica y técnica.", "La ordenación del territorio, el urbanismo y la vivienda.", "La agricultura y la ganadería, de acuerdo con la ordenación general de la economía."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 41, "La Constitución atribuye al Estado la competencia exclusiva sobre contratos. Esto implica:", "Que las comunidades autónomas no pueden regular la contratación pública que lleven a cabo sus instituciones.", "Que las comunidades autónomas tendrán que regular mediante un reglamento aquellos aspectos no considerados básicos por la normativa estatal.", "Que las comunidades autónomas pueden regular mediante una ley aquellos aspectos no considerados básicos por la normativa estatal.", "Ninguna de las respuestas es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 42, "¿Cuál de las siguientes competencias pueden asumir las comunidades autónomas?", "Bases y coordinación de la planificación general de la actividad económica.", "Iluminación de costas y señales marítimas.", "Obras públicas de interés general.", "Sanidad e higiene."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 43, "Una de las siguientes fuentes no constituye un recurso económico de las comunidades autónomas:", "Los ingresos de derecho privado.", "Los rendimientos procedentes de su patrimonio.", "El producto de las operaciones bursátiles.", "El producto de las operaciones de crédito."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 44, "Indica cuál de las siguientes competencias no es exclusiva del Estado:", "La legislación laboral, en todas sus manifestaciones, incluso las de ejecución.", "Las bases y la coordinación de la planificación general de la actividad económica.", "La defensa y las fuerzas armadas.", "La hacienda general y la deuda del Estado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 45, "¿Cómo denomina la Constitución al órgano de gobierno de la comunidad autónoma?", "Consejo colegiado.", "Consejo.", "Consejo ejecutivo.", "Consejo de Gobierno."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 46, "De acuerdo con la Constitución, los Estatutos pueden establecer circunscripciones territoriales propias:", "Mediante la agrupación de municipios, aunque no sean limítrofes.", "Sin personalidad jurídica propia.", "Mediante la agrupación de municipios limítrofes.", "En ningún caso."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 47, "Según la Constitución española, las comunidades autónomas no pueden en ningún caso adoptar medidas tributarias:", "Sobre bienes situados en el interior de su territorio de propiedad privada.", "Sobre bienes situados fuera de su territorio, o que supongan un obstáculo para la libre circulación de mercancias o servicios.", "Que supongan un obstáculo para la competencia regulada.", "Que impidan la creación de multinacionales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 48, "¿Qué facultades pueden asumir las comunidades autónomas en materia de derecho de asilo?", "Ninguna.", "Legislación de desarrollo.", "De ejecución.", "Ninguna de las respuestas es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 49, "La organización judicial en el ámbito de las comunidades autónomas la culminan:", "Las audiencias provinciales correspondientes, sin perjuicio de la jurisdicción que corresponde al Tribunal Supremo.", "Un Tribunal Superior de Justicia, sin perjuicio de la jurisdicción que corresponde al Tribunal Supremo.", "Un Tribunal Superior de Justicia, que asumirá en el ámbito territorial de la Comunidad Autónoma la jurisdicción que sobre este mismo tribunal ejercía el Tribunal Supremo.", "Por una audiencia territorial, sin perjuicio de la jurisdicción que corresponde al Tribunal Supremo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 50, "¿Cuál de las materias siguientes no pueden asumir inicialmente las comunidades autónomas?", "La artesanía.", "La administración de justicia.", "El ordenamiento del territorio, el urbanismo y la vivienda.", "La organización de las instituciones básicas de autogobierno de las comunidades autónomas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 51, "Las comunidades autónomas, respecto de los recursos tributarios del Estado:", "No pueden asumir ningún tipo de competencias.", "Pueden actuar como delegados del Estado en cuanto a la recaudación y la gestión, pero no la liquidación.", "Pueden actuar como delegados o colaboradores del Estado en cuanto a la recaudación, la gestión y la liquidación.", "Pueden actuar como delegados o colaboradores del Estado exclusivamente para la recaudación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 52, "Para garantizar, entre otros, un nivel mínimo en la prestación de servicios públicos fundamentales en todo el territorio español:", "El Estado y las comunidades autónomas pueden establecer tributos especiales.", "Una ley orgánica establecerá el nivel mínimo y la forma de financiación para conseguirlo.", "Puede establecerse una asignación a las comunidades autónomas en los presupuestos generales del Estado.", "El Estado puede asumir directamente el ejercicio de competencias autonómicas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 53, "En cuanto a la organización territorial del poder judicial, las comunidades autónomas:", "Pueden participar en la organización de las demarcaciones judiciales de su territorio al margen de lo que dispone la Ley Orgánica del Poder Judicial, en aquellas instancias procesales que se agoten en el ámbito territorial de las comunidades autónomas.", "No pueden proponer al gobierno la fijación de los partidos judiciales de su ámbito territorial, de acuerdo con la independencia del poder judicial.", "No pueden participar en la organización de las demarcaciones judiciales de su territorio porque es una competencia reservada al Estado.", "Pueden participar en la organización de las demarcaciones judiciales de su territorio, de acuerdo con los supuestos y en las formas que indiquen en sus estatutos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 54, "En materia de propiedad intelectual e industrial corresponde a las comunidades autónomas:", "El desarrollo legislativo y la ejecución.", "La legislación y la ejecución.", "La ejecución.", "Las bases."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 55, "Las leyes marco que atribuyen a las comunidades autónomas la facultad de dictar, para sí mismas, normas legislativas en materias de competencia estatal:", "Establecen la modalidad de control que los tribunales tienen que ejercer sobre las normas que dicten las comunidades.", "Establecen la modalidad de control que las Cortes Generales tienen que ejercer sobre las normas que dicten las comunidades autónomas, sin perjuicio de la competencia de los tribunales.", "Fijan los principios, las bases y las directrices a los cuales han de someterse las normas que dicten las comunidades autónomas.", "Las respuestas b) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 56, "Las comunidades autónomas disfrutarán de autonomía financiera para el desarrollo y la ejecución de sus competencias de acuerdo con los principios de:", "Solidaridad entre todas las comunidades autónomas.", "Progresividad, reparto equitativo de la riqueza y justicia distributiva.", "Coordinación con las haciendas locales.", "Coordinación con la hacienda estatal y solidaridad entre todos los españoles."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 57, "La armonización de las disposiciones normativas de las comunidades autónomas:", "Se efectuará sólo en el caso de materias atribuidas al Estado que hayan sido transferidas o delegadas a las comunidades autónomas.", "Esta armonización no afectará las normas dictadas para el desarrollo de las materias atribuidas a la competencia de las comunidades autónomas.", "Corresponderá al Estado, que dictará leyes en las que se establecerán los principios necesarios para conseguir esta armonía.", "La armonización se efectuará cuando así lo exija el interés de la seguridad nacional."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 58, "De acuerdo con el artículo 149.1.27 de la Constitución, el Estado tiene competencia exclusiva sobre normas básicas del régimen de prensa, radio y televisión. Esto implica:", "Que corresponde al Estado el establecimiento de los criterios generales de regulación de esta materia, que han de comunes a todo el Estado.", "Un límite dentro del cual han de moverse los órganos de las comunidades autónomas en el ejercicio de sus competencias.", "La posibilidad de que el Estado atribuya esta competencia en la comunidad autónoma mediante una ley de transferencia.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 60, "¿Es posible que el Estado transfiera o delegue en las comunidades autónomas funciones correspondientes a materias de titularidad estatal?", "Sí, mediante un Real Decreto Ley, el Estado puede transferir materias de su competencia.", "No; si una materia es competencia del Estado, éste ejerce todas las funciones.", "No; la Constitución lo prohíbe.", "Sí, pero sólo en aquellas materias cuya naturaleza las haga susceptibles de transferencia o delegación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 61, "¿Qué ocurre con las materias no atribuidas expresamente al Estado por la Constitución española?", "Corresponden en todo caso a las comunidades autónomas.", "Corresponden en todo caso al Estado.", "Podrán corresponder a las comunidades autónomas en virtud de los estatutos respectivos.", "Corresponderán al Estado o a las comunidades autónomas según que la materia tenga o no interés general."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 62, "¿A quien corresponde la competencia sobre las materias que no hayan asumido los estatutos de autonomía?", "Corresponde al Estado o a las comunidades autónomas según si la materia tiene interés general o no.", "Corresponde al Estado.", "Corresponde a las comunidades autónomas en caso de tratarse de materias de ámbito autonómico.", "Ninguna de las respuestas anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 63, "La cláusula residual que establece el artículo 149.3 de la Constitución:", "Opera a favor de las comunidades autónomas sólo en el supuesto de que el Estado no asuma expresamente las competencias.", "Opera a favor del Estado sólo en el caso de que las comunidades autónomas no asuman expresamente las competencias.", "Atribuye a las comunidades autónomas las funciones legislativas y ejecutivas.", "Atribuye al Estado únicamente la función legislativa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 64, "En caso de conflicto entre las normas estatales y las de las comunidades autónomas, el artículo 149.3 de la Constitución establece que:", "Las normas estatales prevalecen sobre las de las comunidades autónomas.", "Las normas estatales prevalecen sobre las de las comunidades autónomas siempre que no se trate de competencias atribuidas en exclusiva a las comunidades autónomas.", "Es una manifestación de la supremacía del derecho estatal sobre el autonómico.", "Debe atenderse al sistema competencial."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 65, "La cláusula de supletoriedad que establece el artículo 149.3 de la Constitución dispone expresamente que:", "En cualquier caso, el derecho estatal será supletorio del derecho de las comunidades autónomas.", "El derecho estatal será supletorio del derecho de las comunidades autónomas sólo en las materias que estas no hayan regulado.", "Las respuestas a) y b) son correctas.", "Ninguna de las respuestas es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 66, "El principio de prevalencia que establece el artículo 149.3 de la Constitución española:", "No atribuye superioridad natural del derecho estatal sobre el de las comunidades autónomas.", "No supone que en todos los conflictos entre una norma estatal y una norma autonómica tenga que aplicarse siempre el derecho estatal por ser prevalente.", "Opera junto al principio de competencia, respetándolo.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 67, "Puede una comunidad autónoma atribuirse funciones legislativas sobre las instituciones de crédito cooperativo público y territorial:", "No, porque se trata de una competencia exclusiva del Estado, de acuerdo con el artículo 149 de la Constitución.", "No, sólo puede tener competencias de ejecución.", "Sí, porque la exclusividad del Estado sólo está referida en las bases de la ordenación del crédito.", "Sí; es una materia sobre la cual la Constitución no atribuye ninguna competencia en el Estado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 69, "¿El Estado y las comunidades autónomas pueden compartir funciones legislativas sobre una determinada materia de la competencia exclusiva del Estado?", "No, se trata de una competencia exclusiva; si la tiene el Estado, ya no pueden tenerla las comunidades autónomas.", "Sí, cuando las comunidades autónomas tienen competencias de desarrollo en el marco de la legislación básica del Estado.", "No, cuando el Estado tiene la competencia legislativa, las comunidades autónomas sólo pueden tener la potestad reglamentaria.", "No, esta posibilidad resultaría contradictoria."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 70, "En el supuesto de que una comunidad autónoma no haya asumido como propia la competencia sobre una de las materias que prevé el artículo 148 de la Constitución:", "La asunción de las competencias del artículo 148 por parte de las comunidades autónomas es obligatoria.", "No tiene competencia sobre la materia de que se trate, dado que rige el principio dispositivo.", "La competencia corresponderá en el Estado.", "Las respuestas b) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 71, "Indica cuál de las respuestas es la correcta en relación a la cláusula de supletoriedad:", "La cláusula de supletoriedad permite al Estado dictar normas sobre materias competencia de las comunidades autónomas a efectos de ser aplicadas por aquellas comunidades que no hayan regulado la materia de su competencia o estén pendientes de regularla.", "La supletoriedad sólo es predicable de las normas dictadas por el Estado en materias de su competencia.", "La supletoriedad permite al legislador estatal, en materias en las que tiene atribuidas competencias sobre lo básico, elaborar ex profeso una regulación sobre el desarrollo que, si se tercia, pueda completar supletoriamente las lagunas provocadas por una inactividad autonómica en el ejercicio de estas competencias.", "Ninguna de las respuestas es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 72, "El Estado puede transferir o delegar en las comunidades autónomas, mediante una ley orgánica, facultades correspondientes a materias  de titularidad estatal que por su propia naturaleza sean susceptibles de transferencia o delegación. En este caso:", "La ley preverá en cada caso la correspondiente transferencia de medios financieros y de personal, así como las formas de control que reserve a los tribunales.", "La ley preverá en cada caso la correspondiente transferencia de medios financieros, así como las formas de control que se reserve el Estado.", "El Estado no podrá reservarse medidas de control, y tendrá que prever en cada caso la correspondiente transferencia de medios financieros y de personal.", "El Estado tendrá que dictar las leyes que establezcan los principios necesarios para armonizar las disposiciones normativas de las comunidades autónomas con las estatales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 73, "Indica la respuesta incorrecta:", "Las comunidades autónomas tienen funciones legislativas en aquellas materias de las que el artículo 149 de la Constitución atribuye la competencia exclusiva al Estado.", "Las comunidades autónomas tienen funciones legislativas si la competencia exclusiva del Estado es sobre las bases de una materia determinada.", "Las comunidades autónomas no pueden dictar leyes orgánicas.", "La competencia exclusiva del Estado sobre el procedimiento administrativo común permite a las comunidades autónomas legislar sobre las especialidades derivadas de la organización propia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 74, "Señala la respuesta incorrecta. El control de la actividad de los órganos de las comunidades autónomas lo ejerce:", "El Tribunal Constitucional.", "El Gobierno de la nación.", "La jurisdicción contenciosa administrativa.", "Las Cortes Generales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 3, 75, "¿Qué órgano es el competente para conocer los conflictos de competencias entre el Estado y las comunidades autónomas?:", "El Tribunal Supremo.", "El Consejo de Estado.", "El Tribunal Constitucional,", "La Comisión Constitucional."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 1, "El Tribunal de Justicia de la Unión Europea establecerá su Reglamento de Procedimiento, el cual requerirá la aprobación:", "Del Consejo.", "Del Parlamento Europeo.", "Del Consejo Europeo.", "De la Comisión."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 2, "De acuerdo con el artículo 288 del Tratado de Funcionamiento de la Unión Europea, ¿qué norma tendrá un alcance general, será obligatoria en todos sus elementos y directamente aplicable en cada estado miembro?", "La directiva.", "El dictamen.", "El reglamento.", "La decisión cuando designe destinatarios."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 3, "Un miembro de la Comisión Europea presentará su dimisión si se lo pide:", "El presidente del Parlamento Europeo.", "El presidente del Consejo Europeo.", "El presidente de la Comisión Europea.", "El presidente del Consejo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 4, "¿En qué fecha se firmó el Tratado de Roma?", "2 de setiembre de 1951.", "25 de marzo de 1957.", "8 de abril de 1964.", "1 de julio de 1987"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 5, "Respecto de la Unión Europea, es incorrecto afirmar lo siguiente:", "Los reglamentos tendrán un alcance general. Serán obligatorios en todos sus elementos y directamente aplicables en cada estado miembro.", "Las directivas obligarán al estado miembro destinatario en cuanto al resultado que deba conseguirse, dejando, sin embargo, a las autoridades nacionales la elección de la forma y de los medios.", "Las recomendaciones son vinculantes.", "Los dictámenes no son vinculantes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 6, "El Tratado de la Unión Europea se firmó en Maastricht:", "El 15 de abril de 1988.", "El 7 de septiembre de 1990.", "El 15 de octubre de 1960.", "El 7 de febrero de 1992."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 7, "Es correcto afirmar que los reglamentos de la Unión Europea:", "Son no vinculantes.", "Son derecho comunitario primario.", "Son derecho derivado.", "Son recomendaciones y dictámenes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 8, "Es correcto afirmar que las directivas de la Unión Europea:", "Tienen un alcance general. Son obligatorias en todos sus elementos y directamente aplicables en cada estado miembro.", "Obligan al estado miembro destinatario en cuanto al resultado que deba conseguirse, dejando, sin embargo, a las autoridades nacionales la elección de la forma y de los medios.", "No son vinculantes.", "Son derecho comunitario primario."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 9, "El Tratado de París que crea la Comunidad Europea del Carbón y el Acero entró en vigor:", "El 16 de abril de 1948.", "El 18 de abril de 1961.", "El 23 de julio de 1952.", "El 2 de junio de 1960."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 10, "El Consejo Europeo está formado:", "Únicamente por los jefes de estado o de gobierno de los estados miembros de la Unión Europea.", "Por los jefes de estado o de gobierno de los estados miembros de la Unión Europea y por el presidente del Parlamento Europeo.", "Por los jefes de estado o de gobierno de los Estados Miembros de la Unión Europea, por el presidente del Consejo Europeo y por el presidente del Parlamento Europeo.", "Por los jefes de estado o de gobierno de los estados miembros de la Unión Europea, por el presidente del Consejo Europeo y por el presidente de la Comisión Europea."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 11, "¿Qué organismo de la Unión Europea elabora el anteproyecto del presupuesto?", "El Defensor del Pueblo europeo.", "El Consejo Europeo.", "La Comisión Europea.", "El Parlamento Europeo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 12, "¿En qué tratado aparece por primera vez la posibilidad de que un estado miembro pueda abandonar la Unión Europea?", "En el Tratado de Lisboa.", "En el Tratado de Ámsterdam.", "En el Tratado de Niza.", "En el Tratado de Roma."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 13, "¿Dónde se firmó la última reforma del Tratado de la Unión Europea?", "En Ámsterdam.", "No se ha producido ninguna reforma del Tratado de la Unión Europea.", "En Niza.", "En Lisboa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 14, "El 18 de abril de 1951 se firmó en París el Tratado constitutivo de la Unión Europea del Carbón y del Acero, ¿qué países firmaron dicho Tratado?", "Alemania occidental, Bélgica, Francia, Italia, Luxemburgo y los Países Bajos.", "Alemania occidental, Bélgica, Francia, Italia, Gran Bretaña y los Países Bajos.", "Alemania occidental, Francia, Gran Bretaña, Italia, Luxemburgo y Países Bajos.", "Alemania occidental, Dinamarca, Francia, Italia, Luxemburgo y Países Bajos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 15, "Los Reglamentos Europeos se caracterizan:", "Por su carácter no obligatorio, su alcance individual y su aplicabilidad directa.", "Por su carácter obligatorio, su alcance individual y su aplicación directa.", "Por su carácter vinculante, su alcance general y su no aplicabilidad directa.", "Por su carácter obligatorio, su alcance general y su aplicación directa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 16, "En relación con la Unión Europea, las recomendaciones y los dictámenes:", "No son vinculantes y van dirigidos tanto a estados miembros como a personas físicas o jurídicas.", "Son vinculantes y van dirigidos tanto a estados miembros como a personas físicas o jurídicas.", "Son vinculantes y van dirigidos a todos los estados miembros.", "No son vinculantes y solo van dirigidos a personas físicas o jurídicas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 17, "Una de las siguientes no es una función de la Comisión Europea:", "Ejecutar el presupuesto y gestionar los programas.", "Velar por la aplicación de los tratados de la UE.", "La potestad legislativa.", "La iniciativa legislativa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 18, "Señale la respuesta correcta. El Parlamento Europeo:", "Solo tiene funciones de consulta.", "Solo es un órgano de control.", "Se elige por sufragio universal directo.", "Es el órgano encargado de ejecutar el presupuesto."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 19, "La Mesa del Parlamento Europeo estará compuesta:", "Por el presidente, doce vicepresidentes y los cuestores.", "Por el presidente, diez vicepresidentes y los cuestores.", "Por el presidente, dos vicepresidentes y los cuestores.", "Por el presidente, catorce vicepresidentes y los cuestores."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 20, "Los derechos, libertades y principios reconocidos en la Unión Europea están enunciados en:", "El Tratado de Tallin.", "El Reglamento Europeo de la Ciudadanía Europea.", "La Constitución Europea.", "La Carta de los Derechos Fundamentales de la Unión Europea."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 21, "El Tribunal de Justicia de la Unión Europea se creó mediante:", "El Tratado de la CECA.", "El Tratado de Niza.", "El Tratado de Ámsterdam.", "El Tratado de Lisboa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 22, "Señale la respuesta correcta respecto de las relaciones internacionales de la Unión Europea con terceros países:", "El Consejo negocia los tratados internacionales y la Comisión los aprueba.", "La Comisión negocia los tratados internacionales y el Parlamento Europeo los sanciona.", "La Comisión negocia los tratados internacionales y el Consejo los aprueba.", "Un número indeterminado de diputados europeos negocia los tratados internacionales y la Comisión los aprueba."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 23, "De acuerdo con lo previsto en el Tratado de la Unión Europea, señale la respuesta correcta en relación a las instituciones de la Unión:", "El Consejo Europeo elige al presidente de la Comisión.", "El Consejo está compuesto por un representante de cada estado miembro, de rango ministerial.", "El Parlamento Europeo está compuesto por representantes de los ciudadanos de la Unión. Su número no debe exceder de 850, más el presidente.", "El mandato de la Comisión es de cuatro años."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 24, "Con respecto al procedimiento de revisión ordinario establecido en el Tratado de la Unión Europea para modificar los Tratados (señale la respuesta correcta):", "El Gobierno de cualquier estado miembro, el Parlamento Europeo o la Comisión pueden presentar al Consejo proyectos de revisión.", "Tiene por finalidad revisar la totalidad o parte de las disposiciones relativas a las políticas y acciones internas de la Unión.", "Tiene por finalidad solo la de aumentar competencias atribuidas a la Unión en los Tratados.", "El Gobierno de cualquier estado miembro puede presentar al Parlamento proyectos de revisión."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 25, "La delimitación de las competencias de la Unión Europea se rige:", "Por el principio de atribución.", "Por los principios de subsidiaridad y proporcionalidad.", "Por el principio de jerarquía.", "Por el principio de eficacia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 26, "Los actos legislativos de la Unión Europea podrán adoptarse únicamente a propuesta:", "De la Comisión Europea.", "Del Consejo Europeo y la Comisión Europea.", "Del Consejo de Europa.", "Del Consejo de la Unión Europea."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 27, "El proceso de integración europea comenzó:", "Con la creación de la CECA y el EURATOM.", "Con la creación de la Comunidad Económica Europea (CEE), en 1960.", "Con los Tratados de Roma de 1957.", "Con la creación de la CECA, en 1951."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 28, "El mandato de los miembros de la Comisión se establece por un período de:", "Cinco años.", "Seis años.", "Cuatro años.", "Tres años."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 29, "Ejecutar el presupuesto y gestionar los programas es una función que corresponde:", "Al Parlamento Europeo.", "A la Comisión.", "Al Consejo y al Parlamento Europeo.", "Al Consejo Europeo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 30, "La Institución de la Unión Europea que está compuesta por un ministro de cada país de la Unión Europea es:", "La Comisión Europea.", "El Comité de las Regiones.", "El Parlamento Europeo.", "El Consejo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 31, "¿Qué estados firmaron el Tratado de Roma?", "Alemania, Bélgica, Francia, Italia, Luxemburgo y los Países Bajos.", "Alemania, el Reino Unido, Bélgica, Francia, Italia y Luxemburgo.", "Alemania, Austria, Bélgica, Francia, Luxemburgo y los Países Bajos.", "Alemania, Bélgica, Francia, Dinamarca, Luxemburgo y los Países Bajos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 32, "Respecto al Consejo Europeo:", "También recibe la denominación de Consejo de Europa, pero no es el mismo órgano que el Consejo de la Unión Europea.", "Representa a los gobiernos de los Estados miembros a través de representantes de rango ministerial para adoptar legislación y coordinar políticas.", "Está integrado por los jefes de Estado o de gobierno de los Estados miembros de la Unión Europea, y se encarga de determinar la dirección y las prioridades políticas generales.", "Cada estado miembro ejerce la presidencia en turnos de seis meses."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 33, "¿A partir de qué Tratado se establece la Unión Económica y Monetaria en la Unión Europea?", "El Tratado de Roma.", "Tratado de la Unión Europea.", "Tratado de Ámsterdam.", "Tratado de París."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 34, "¿Qué órgano posee el derecho a la iniciativa legislativa en la Unión Europea?", "Los países miembros.", "El Comité de las Regiones.", "El presidente del Parlamento.", "La Comisión Europea."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 35, "De las siguientes afirmaciones relativas a la Comisión Europea, señale la correcta:", "La Comisión está integrada por 27 miembros.", "España tiene designados tres comisarios.", "La Comisión es un órgano colegiado y está integrada por 27 miembros.", "La Comisión representa los intereses de los estados miembros de la Unión Europea."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 36, "De acuerdo con el artículo 17.2 del Tratado de la Unión Europea, los actos legislativos de la Unión:", "Se adoptan por mayoría cualificada de tres quintas partes del Parlamento Europeo.", "Sólo podrán adoptarse a propuesta de la Comisión, excepto cuando los tratados dispongan otra cosa", "Únicamente podrán adoptarse a propuesta de la Comisión o de uno de los países miembros.", "Se adoptarán a propuesta del Consejo por mayoría cualificada de tres quintas partes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 37, "De acuerdo con lo establecido en el artículo 48.2 del Tratado de la Unión Europea, pueden presentar proyectos de revisión de los tratados al Consejo:", "El ministro de asuntos exteriores de cualquier estado miembro.", "El presidente de cualquier estado miembro.", "El consejo de ministros de cualquier estado miembro.", "El gobierno de cualquier estado miembro, el Parlamento Europeo o la Comisión."); 
