insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 40, "Según el Tratado de la Unión Europea, el presidente del Consejo Europeo es elegido:", "Por el Consejo Europeo, por mayoría cualificada para un mandato de dos años y medio, que podrá renovarse una sola vez.", "Por el Parlamento Europeo por mayoría cualificada.", "Por el Parlamento Europeo por mayoría simple, que podrá renovarse una sola vez.", "Ninguna de las anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 41, "De conformidad con el Tratado de la Funcionamiento de la Unión Europea, señale cuál de los siguientes actos no tiene carácter vinculante:", "El reglamento.", "La directiva.", "La decisión.", "El dictamen."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 42, "De conformidad con el Tratado de la Unión Europea, señale la opción correcta respecto de las sesiones o reuniones del Consejo:", "Deben ser públicas cuando delibere y vote sobre un proyecto de acto legislativo.", "No deben ser públicas en ningún caso.", "Deben ser públicas a excepción de las que se deliberen sobre un proyecto de acto legislativo.", "Ninguna de las anteriores es correcta."); 
