insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 47, "Los actos legislativos de la Unión Europea, podrán adoptarse únicamente a propuesta:", "De la Comisión Europea.", "Del Consejo Europeo y la Comisión Europea.", "Del Consejo de Europa.", "Del Consejo de la Unión Europea."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 48, "De acuerdo con el Tratado de la Unión Europea, la Unión Europea sustituirá y sucederá a:", "La OTAN.", "La CECA.", "La Comunidad Económica Europea.", "A ninguna de las anteriores."); 
