insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 51, "El Parlamento Europeo estará compuesto por representantes de los ciudadanos de la Unión, con un número máximo de:", "705 más el presidente.", "705, incluido el presidente.", "649 diputados.", "Representantes en una proporción igual a cada estado miembro."); 
