insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 69, "La moción de censura de la Comisión ha de ser aprobada:", "Por mayoría de un tercio de los votos emitidos que representen, a su vez, la mayoría de los diputados que componen el Parlamento Europeo", "Por mayoría de dos tercios de los votos emitidos que representen, a su vez, la mayoría de los diputados que componen el Parlamento Europeo", "Por mayoría de tres quintos de los votos emitidos que representen, a su vez, la mayoría de los diputados que componen el Parlamento Europeo", "Por mayoría de un quinto de los votos emitidos que representen, a su vez, la mayoría de los diputados que componen el Parlamento Europeo."); 
