insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 74, "El Tribunal de Justicia Europeo está compuesto:", "Por 15 jueces de reconocido prestigio.", "Por un juez por cada Estado miembro.", "Por dos jueces por cada Estado miembro.", "Por 12 jueces."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 4, 75, "Indique cuál de las siguientes no es una de las competencias exclusivas de la Unión Europea:", "La unión aduanera.", "El mercado interior.", "El establecimiento de las normas sobre competencias necesarias para el funcionamiento del mercado interior.", "La política monetaria de los estados miembros cuya moneda es el euro."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 1, "De acuerdo con el Código civil, las normas jurídicas contenidas en los tratados internacionales:", "No tienen aplicación directa en España.", "Aunque no pueden llegar a tener aplicación directa en España, tienen carácter informador del ordenamiento jurídico interno.", "Son de aplicación directa en España desde la firma del tratado internacional correspondiente.", "No son de aplicación directa en España mientras no hayan pasado a formar parte del ordenamiento interno mediante la publicación íntegra en Boletín Oficial del Estado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 2, "¿Cuál de las materias siguientes es regulable por un decreto ley?", "El régimen de las comunidades autónomas.", "El derecho electoral general.", "Los derechos, los deberes y las libertades de los ciudadanos que se regulan en el título I de la Constitución.", "Ninguna de las materias anteriores es regulable por un decreto ley."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 3, "¿Cuándo se aplica la costumbre como fuente de derecho?", "A falta de ley aplicable, siempre que no sea contraria a la moral o al orden público, y que resulte probada.", "Cuando sea de aplicación por razón de la materia.", "En cualquier caso, aunque haya una ley aplicable.", "Cuando no haya principios generales del derecho aplicables al caso."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 4, "Las disposiciones administrativas que contradigan lo que establece una norma de carácter superior:", "Son nulas de pleno derecho.", "Tienen que ser adaptadas.", "Tienen que ser recorridas ante el Tribunal Supremo.", "Son anuladas por las Cortes Generales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 5, "¿Qué artículo del Código civil establece las fuentes del derecho?", "Ninguno.", "El artículo 1.", "El artículo 18.", "El artículo 35."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 6, "De conformidad con la Constitución española, los estatutos de autonomía son:", "La norma institucional básica de cada comunidad autónoma.", "Una ley orgánica estatal.", "Parte integrante del ordenamiento jurídico del Estado.", "Todas las respuestas anteriores son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 7, "La Constitución española establece que la reforma de los estatutos se ajustará al procedimiento que se establezca y requerirá, en todo caso:", "La aprobación del Congreso, por una ley ordinaria.", "La aprobación de las Cortes Generales por mayoría simple, con un dictamen previo favorable del Consejo de Estado.", "La aprobación de las Cortes Generales, por una ley orgánica.", "La aprobación de las Cortes Generales, por una ley ordinaria."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 8, "El principio de legalidad se establece en la Constitución en:", "El artículo 2.", "El artículo 9.", "El artículo 104.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 9, "En caso de necesidad extraordinaria y urgente, el Gobierno puede dictar disposiciones legislativas provisionales que adoptan la forma de:", "Decreto legislativo.", "Ley de bases.", "Decreto ley.", "Ley marco."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 10, "Las disposiciones dictadas por los ministros se publican con la denominación:", "De orden.", "De orden ministerial.", "De decreto.", "De decreto ministerial."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 11, "El principio de jerarquía de las fuentes del derecho administrativo:", "Determina la invalidez de la norma inferior que contradiga lo que dispone la superior.", "Se regula en el artículo 9.3 de la Constitución.", "No se aplica en las relaciones entre las leyes ordinarias y las orgánicas.", "Todas las respuestas anteriores son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 12, "El principio de reserva de ley significa:", "Que la ley se sitúa en la posición más elevada de la pirámide normativa.", "Que no es posible negarse a la aplicación o el cumplimiento de la ley.", "Que el enjuiciamiento de la ley compite en exclusiva a los tribunales o les está reservado.", "Que determinadas materias establecidas por la Constitución sólo pueden ser reguladas por una norma con rango legal."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 13, "Los principios generales del derecho:", "Son fuente indirecta.", "Tienen un valor normativo superior a la costumbre.", "Son fuente de aplicación a falta de ley y costumbre, sin perjuicio de su carácter informador del ordenamiento jurídico.", "Tienen un valor normativo superior a la costumbre, sin perjuicio de su carácter informador del ordenamiento jurídico."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 14, "En relación con los decretos ley:", "Son aprobados por el Consejo de Ministros.", "Son aprobados por el Consejo de Ministros, con la autorización previa del Congreso.", "Son aprobados por el Consejo de Ministros, con la autorización previa de las Cortes Generales.", "Son aprobados por el presidente del Gobierno, con la deliberación previa del Consejo de Ministros y la consulta al Congreso."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 15, "En la ley marco:", "Se fijan los principios para armonizar las disposiciones normativas de las comunidades autónomas cuando lo exija el interés general.", "Se transfieren facultades de titularidad estatal a las comunidades autónomas, por una ley orgánica.", "Se establece la modalidad de control de las Cortes Generales sobre determinadas normas legislativas de las comunidades autónomas.", "Puede otorgarse una delegación legislativa en el Gobierno porque armonice actuaciones autonómicas cuando así lo exija el interés general."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 16, "La aprobación, modificación o derogación de una ley orgánica exige:", "La mayoría absoluta del Congreso.", "La mayoría absoluta del Senado.", "La mayoría absoluta de las Cortes.", "La mayoría simple del Congreso, en votación final sobre el conjunto del proyecto."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 17, "La delegación legislativa efectuada por las Cortes Generales a favor del Gobierno, con el fin de formar un texto articulado, tendrá que hacerse:", "A través de una ley marco.", "A través de una ley básica.", "A través de una ley ordinaria.", "A través de una ley de bases."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 18, "El Estatuto de autonomía tiene que contener:", "La delimitación del territorio de la comunidad autónoma.", "La denominación, la organización y la sede de las instituciones autonómicas propias.", "La denominación de la comunidad autónoma.", "Todas las respuestas anteriores son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 19, "De acuerdo con el artículo 149.3 de la Constitución, qué normas prevalecen en caso de conflicto entre las de una comunidad y las del Estado?", "Siempre las del Estado.", "Siempre las de la comunidad.", "Las del Estado, salvo que la materia esté atribuida exclusivamente a la comunidad.", "Las de la comunidad, salvo que la materia esté atribuida exclusivamente al Estado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 20, "De acuerdo con la Constitución, son leyes orgánicas las relativas:", "Al régimen de las comunidades autónomas.", "Al desarrollo de los derechos fundamentales y de las libertades públicas.", "Al régimen electoral general.", "Las respondidas b) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 21, "De acuerdo con la Constitución, los decretos ley:", "Tendrán que ser sometidos inmediatamente a debate y votación de la totalidad en el Congreso en el plazo de quince días desde la promulgación.", "Podrán afectar los derechos fundamentales y las libertades públicas.", "Tendrán que ser sometidos inmediatamente a debate y votación de la totalidad en el Congreso en el plazo de los veinte días siguientes a la promulgación.", "Durante el plazo para la convalidación o derogación, las Cortes podrán tramitarlos como proyecto de ley por el procedimiento de urgencia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 22, "En relación con la supletoriedad del derecho estatal respecto del autonómico, el artículo 149.3 de la Constitución establece que:", "El derecho estatal será, en todo caso, supletorio del de las comunidades autónomas.", "Sólo será supletorio del derecho de las comunidades autónomas en el caso que estas no hayan legislado sobre sus competencias asumidas.", "El derecho estatal sólo será supletorio cuando así lo establezca una norma con rango de ley.", "Será supletorio del derecho de las comunidades autónomas excepto en las materias de competencia exclusiva de estas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 23, "Según la Constitución española:", "El Congreso podrá delegar en el Gobierno la potestad de dictar normas con rango de ley sobre materias determinadas, excepto las que se tengan que aprobar con una ley orgánica.", "El Senado, como cámara de representación territorial, podrá delegar en el Gobierno la potestad de dictar normas con rango de ley sobre la distribución territorial del Estado.", "Las Cortes Generales podrán delegar en el Gobierno la potestad de dictar normas con rango de ley sobre el desarrollo de los derechos fundamentales y las libertades públicas, sobre el régimen electoral general y sobre las otras materias previstas en la Constitución.", "Las Cortes Generales podrán delegar en el Gobierno la potestad de dictar normes con rango de ley sobre materias determinadas no incluidas en el artículo 81."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 24, "De acuedo con la Ley 50/1997, de 27 de noviembre, del Gobierno, los reglamentos dictados por el presidente del Gobierno se publican con la denominación de:", "Reales decretos del presidente del Gobierno.", "Decretos del presidente.", "Decretos de Presidencia.", "Reales decretos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 25, "De acuerdo con el Código civil, con relación a las fuentes del derecho:", "La costumbre sólo regirá a falta de una ley aplicable, siempre que no sea contraria a la moral o al interés social y que resulte probada.", "La jurisprudencia complementará el ordenamiento jurídico con la doctrina que, de manera reiterada, establezca el Tribunal Supremo al interpretar y aplicar la ley y la costumbre.", "Los principios generales del derecho se aplican a falta de ley, sin perjuicio de su carácter informador del ordenamiento jurídico.", "La jurisprudencia complementará el ordenamiento jurídico con la doctrina que, de manera reiterada, establezca el Tribunal Supremo al interpretar y aplicar la ley, la costumbre y los principios generales del derecho."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 26, "Las materias que tienen que ser desarrolladas por medio de una ley orgánica se contienen en la Constitución en:", "El artículo 9.", "El artículo 82.", "El artículo 81.", "El artículo 84."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 27, "Los decretos ley son convalidados:", "Por el Congreso de los Diputados.", "Por el Senado.", "Por las Cortes Generales.", "Por el Gobierno."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 28, "El plazo para convalidar uno decreto ley es de:", "Veinte días.", "Quince días.", "Un mes.", "Treinta días."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 29, "Las disposiciones del Gobierno que contienen legislación delegada se denominan:", "Decretos leyes.", "Leyes de delegación.", "Decretos legislativos.", "Decretos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 30, "Una ley estatal que contiene los principios necesarios para armonizar las disposiciones normativas de las comunidades autónomas en una materia es:", "Una ley orgánica.", "Una ley de armonización.", "Una ley de bases.", "Una ley de delegación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 31, "En relación con el procedimiento de la elaboración de las leyes que se prevé en la Constitución:", "El rey sancionará en el plazo de quince días las leyes aprobadas por las Cortes Generales, y las promulgará y ordenará la publicación inmediata.", "El rey sancionará en el plazo de veinte días las leyes aprobadas por las Cortes Generales, y las promulgará y ordenará la publicación inmediata.", "El rey sancionará en el plazo de treinta días las leyes aprobadas por las Cortes Generales, y las promulgará y ordenará la publicación inmediata.", "El presidente del Gobierno, en nombre del rey, sancionará en el plazo de quince días las leyes aprobadas por las Cortes Generales, y las promulgará y ordenará la publicación inmediata."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 32, "En cuanto a la regulación dispuesta en la Constitución respeto de los decretos legislativos:", "La delegación legislativa tendrá que otorgarse por una ley ordinaria cuando el objeto sea la formación de textos articulados o por una ley de bases cuando se trate de refundir varios textos legales en uno sólo.", "Las Cortes Generales podrán delegar en el Gobierno la potestad de dictar normas con rango de ley, incluida la regulación de las posibles formas de colaboración financiera entre las comunidades autónomas y el Estado.", "La delegación legislativa tendrá que otorgarse en el Gobierno de forma expresa para una materia concreta y con fijación del plazo de ejercicio. La delegación se agota por el uso que haga el Gobierno mediante la publicación de la norma correspondiente.", "La delegación legislativa tendrá que otorgarse por una ley orgánica cuando el objeto sea la formación de textos articulados o por una ley de bases cuando se trate de refundir varios textos legales en uno sólo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 33, "Indicad la respuesta correcta:", "Las Cortes Generales, en materia de competencia estatal, podrán atribuir a todas o a alguna de las comunidades autónomas la facultad de dictar, para sí mismas, normas legislativas en el marco de los principios, las bases y las directrices que fije una ley estatal.", "Las Cortes Generales, en materia de competencia estatal, podrán atribuir a todas o a alguna de las comunidades autónomas la facultad de dictar, para sí mismas, normas legislativas en el marco de los principios, las bases y las directrices que fije una ley de bases.", "El Gobierno, en materia de competencia estatal, podrá atribuir a todas o a alguna de las comunidades autónomas la facultad de dictar, para sí mismas, normas legislativas en el marco de los principios, las bases y las directrices que fije una ley estatal.", "El Congreso, en materia de competencia estatal, podrá atribuir a todas o a alguna de las comunidades autónomas la facultad de dictar, para sí mismas, normas legislativas en el marco de los principios, las bases y las directrices que fije una ley estatal."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 34, "Según lo que dispone la Constitución, las leyes de bases podrán:", "Autorizar la modificación de la ley de bases.", "Facultar para dictar normas con carácter retroactivo.", "Facultar para refundir varios textos legales en uno sólo.", "Facultar para la formación de textos articulados."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 35, "Las resoluciones de los ministros se denominan:", "Resoluciones ministeriales.", "Órdenes ministeriales.", "Decretos ministeriales.", "Todas las respuestas anteriores son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 36, "Señalad la respuesta incorrecta:", "La iniciativa legislativa la ejercerán los órganos de gobierno de las comunidades autónomas en los términos que establecen la Constitución y sus correspondientes estatutos de autonomía.", "El Gobierno de la Nación podrá aprobar reales decretos ley y reales decretos legislativos en los términos que prevé la Constitución.", "Los órganos de gobierno de las comunidades autónomas no podrán aprobar normas equivalentes a reales decretos leyes y reales decretos legislativos en su ámbito territorial.", "La iniciativa popular no procederá en materias propias de ley orgánica, tributarias o de caracter internacional, ni en lo relativo a la prerrogativa de gracia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 37, "Los reglamentos independientes se caracterizan para ser:", "Los que regulen materias sobre las cuales la Constitución ha previsto expresamente una reserva reglamentaria.", "Aquellos que regulen materias en que no se ha producido una regulación previa por ley y que no están protegidas por reserva material de ley.", "Los que regulen materias sobre las cuales la Constitución ha previsto expresamente una reserva reglamentaria, así como aquellos que regulen materias en que no se ha producido una regulación previa por ley y que no están protegidas por reserva material de ley.", "En España no pueden haber reglamentos independientes, dado que la Constitución no ha previsto expresamente una reserva reglamentaria."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 38, "Los reglamentos ejecutivos son los que:", "Regulan materias en las cuales no se ha producido una regulación previa por ley y que no están protegidas por reserva material de ley.", "Desarrollan y complementan una ley.", "Dicta la Administración para hacer frente a riesgos extraordinarios, suspendiendo la vigencia de las leyes a los que contradicen mientras dure la situación de emergencia.", "Los que regulan materias sobre las cuales la Constitución española ha previsto una reserva reglamentaria."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 39, "La autorización en el Gobierno de la Nación para dictar un texto refundido tiene que efectuarse a través:", "De una ley ordinaria.", "De un decreto legislativo.", "De una ley orgánica.", "De un decreto ley."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 40, "Un decreto ley del Gobierno de la Nación no puede afectar:", "El sistema tributario.", "Los presupuestos generales del Estado.", "El régimen de derechos, deberes y libertades del título I de la Constitución española.", "Ninguna de las respuestas anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 41, "Para aplicar una costumbre a falta de un principio general del derecho:", "No puede atentar contra la moral.", "Tiene que ser probado.", "No puede ir en contra del orden público.", "Ninguna de las respuestas anteriores son correctas, porque se aplica siempre antes de que el principio general del derecho."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 42, "De conformidad con la Constitución española, las administraciones públicas no actúan de acuerdo con el principio de:", "Coordinación.", "Jerarquía.", "Desconcentración.", "Delegación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 43, "Los reglamentos son disposiciones normativas:", "De carácter general.", "De rango inferior a la Ley.", "Que emanan del poder ejecutivo en virtud de su potestad reglamentaria.", "Todas las respuestas anteriores son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 44, "Indicad cuál de las respuestas siguientes es la incorrecta con relación a los reglamentos:", "El control de las normas reglamentarias dictadas por la Administración de la Comunidad Autónoma de las Illes Balears corresponde a la jurisdicción contenciosa administrativa.", "La entrada en vigor de los reglamentos aprobados por el Gobierno de la Nación requiere la publicación íntegra en Boletín Oficial del Estado.", "De acuerdo con la Ley 1/2019, de 31 de enero, de Gobierno de las Illes Balears, en casos de urgencia y de forma excepcional, la entrada en vigor de determinados reglamentos aprobados por el Consejo de Gobierno requiere únicamente la publicación de un extracto en el Boletín Oficial de las Illes Balears.", "Los reglamentos dictados por las entidades locales se tienen que publicar en el boletín oficial que corresponda."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 45, "Los reglamentos se pueden definir como:", "Cualquier disposición jurídica de carácter singular dictada por la Administración pública y subordinada a la ley.", "Cualquier disposición jurídica dictada por el Gobierno y la Administración en virtud de la delegación normativa efectuada a su favor por las Cortes Generales.", "Cualquier disposición jurídica de carácter general dictada por el Gobierno y la Administración pública, subordinada a la ley.", "Cualquier disposición administrativa dictada en el seno de un procedimiento, con efecto erga omnes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 46, "De acuerdo con la Ley 1/2019, de 31 de enero, de Gobierno de las Illes Balears, señalad el orden jerárquico correcto:", "Primero los decretos aprobados por el Consejo de Gobierno, y segundo las órdenes de los consejeros.", "Primero los decretos de los consejeros, y segundo las resoluciones de los consejeros.", "Primero los decretos aprobados por el Consejo de Gobierno o por el presidente, y segundo las órdenes de los consejeros.", "Ninguna de las respuestas anteriores es la correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 47, "Las normas se pueden ordenar jerárquicamente de la forma siguiente:", "Constitución, leyes y normas con rango de ley, reglamentos, principios generales del derecho y costumbres.", "Constitución, leyes y normas con rango de ley, reglamentos, costumbres y principios generales del derecho.", "Constitución, reglamentos, leyes y normas con rango de ley y costumbres.", "Constitución, leyes, reglamentos, normas con rango de ley y costumbres."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 48, "Señalad cuál de las siguientes frases es la incorrecta:", "La supremacía formal implica que la Constitución no puede ser modificada ni derogada por ninguna otra norma.", "En cuanto a la norma, la Constitución disfruta de una posición de supremacía normativa en un doble plano, material y formal.", "La Constitución se sobrepone a los ciudadanos, a todos los poderes públicos y, por lo tanto, a todas las normas de cualquier naturaleza que de estos dimanen.", "La Constitución es un poder constituido, los otros poderes son meros poderes constituyentes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 49, "¿Qué artículo de la Constitución está dedicado a la irretroactividad de las disposiciones sancionadoras desfavorables o restrictivas de derechos individuales?", "El artículo 9.3.", "El artículo 9.2.", "El artículo 9.4.", "El artículo 10."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 50, "¿Cuántos componentes debe tener la delegación autonómica encargada de la defensa de una proposición de ley autonómica en el Congreso?", "Mínimo dos.", "Tres.", "Cuatro.", "Máximo tres."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 51, "¿Cuál es el número de firmas necesario para el ejercicio de la iniciativa legislativa popular?", "No menos de 500.000 firmas acreditadas.", "500.000 firmas acreditadas.", "Más de 600.000 firmas acreditadas.", "600.000 firmas acreditadas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 52, "¿En cuál de las siguientes materias es procedente la iniciativa legislativa popular?", "En materias tributarias.", "En materias de carácter internacional.", "En materias relativas a la prerrogativa de gracia.", "Ninguna de las materias anteriores pueden ser objeto de una iniciativa legislativa popular."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 53, "¿Puede el Gobierno subdelegar la facultad de dictar legislación delegada?", "En ningún caso.", "Sí, siempre que lo autorice la ley de delegación.", "Sí, siempre que delegue en autoridades administrativas.", "No, salvo que delegue en órganos administrativos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 54, "Un estatuto de autonomía tiene que ser aprobado:", "Por ley ordinaria.", "Por ley orgánica.", "Por real decreto.", "Por decreto ley."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 55, "Indicad la respuesta incorrecta relativa al reglamento de necesidad:", "El reglamento de necesidad implica la suspensión de la legalidad establecida.", "El reglamento de necesidad tiene carácter transitorio en el ordenamiento jurídico.", "El reglamento de necesidad sólo se puede dictar por razón de la concurrencia de circunstancias extraordinarias.", "El reglamento de necesidad tiene carácter de permanencia en el ordenamiento jurídico."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 56, "¿Qué otro principio, además del de jerarquía normativa, debemos tener en cuenta para explicar la relación entre las diferentes fuentes del ordenamiento?", "Principio de cooperación.", "Principio de colaboración.", "Principio de coordinación.", "Principio de competencia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 57, "No tiene que ser regulado por ley orgánica:", "El derecho de propiedad.", "El derecho de reunión.", "El régimen electoral general.", "El derecho de huelga."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 58, "Jerárquicamente, la ley orgánica:", "Es superior a la ley ordinaria.", "Tiene el mismo rango que la ley ordinaria.", "Tiene el mismo rango que la Constitución.", "Tiene rango inferior al decreto ley."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 59, "¿Pueden las asambleas de las comunidades autónomas remitir a las Cortes Generales proposiciones de ley?", "No, en ningún caso.", "Sí, en el Congreso y en el Senado.", "Sí, pero sólo a la Mesa del Senado, que es la cámara de representación territorial.", "Sí, pero sólo a la Mesa del Congreso."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 60, "De acuerdo con la Constitución española, la apreciación de la necesidad de dictar leyes que establezcan los principios necesarios para armonizar las disposiciones normativas de las comunidades autónomas corresponde:", "En el Congreso, por mayoría de tres quintas partes de sus miembros.", "Al Consejo de Ministros.", "En el Senado, en calidad de cámara de representación territorial.", "A las Cortes Generales, por mayoría absoluta de cada cámara."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 61, "¿Qué mayoría se necesita en el Senado para interponer un veto a una proposición de ley aprobada en el Congreso de los Diputados?", "Mayoría simple.", "Mayoría absoluta.", "Mayoría de dos tercios.", "El Senado no puede vetar materias aprobadas por el Congreso."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 62, "¿Qué otro nombre reciben los decretos legislativos?", "Legislación ejecutiva.", "Legislación delegada.", "Legislación delegando.", "Legislación secundaria."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 63, "¿De acuerdo con las clasificaciones doctrinales clásicas de los reglamentos, como se denomina el reglamento que se dicta sin una habilitación o una remisión específica de una ley?", "Reglamento ejecutivo.", "Reglamento independiente.", "Reglamento de necesidad.", "Ninguna de las respuestas es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 64, "¿Cuál de estas normas tiene un procedimiento especial de aprobación?", "Las leyes orgánicas.", "Las leyes armonizadoras.", "Los decretos ley.", "Todas las respuestas anteriores son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 65, "¿Qué se entiende por inderogabilidad singular de los reglamentos?", "Que las resoluciones administrativas de carácter particular pueden vulnerar los reglamentos cuando procedan de un órgano de igual o superior jerarquía al que dictó la disposición general.", "Que las resoluciones administrativas de carácter particular pueden vulnerar los reglamentos únicamente cuando procedan del Gobierno en casos de extraordinaria y urgente necesidad.", "Que las resoluciones administrativas de carácter particular no pueden vulnerar las disposiciones reglamentarias aunque procedan de un órgano de igual o superior jerarquía al que dictó la disposición general.", "Que la vulneración de una disposición de alcance general por una de carácter particular requiere el acuerdo del Consejo de Ministros o del Consejo de Gobierno."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 66, "La posibilidad del Gobierno de regularizar, aclarar y armonizar los textos legales es posible cuando dicte:", "Textos articulados.", "Textos refundidos.", "Reales decretos.", "Reglamentos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 67, "Indicad cuál de las materias siguientes no se regula por una ley orgánica:", "Las condiciones y el procedimiento de las diferentes modalidades de referéndum previstas en la Constitución.", "Las funciones, los principios básicos de actuación y los estatutos de las fuerzas y los cuerpos de seguridad.", "La composición y las competencias del Consejo de Estado.", "Los colegios profesionales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 68, "El derecho administrativo:", "Es un derecho público.", "Es un derecho común.", "Es un derecho limitativo.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 69, "Al hablar de los límites formales de los reglamentos se puede afirmar:", "Que el reglamento sólo está sujeto a la Constitución y a las leyes orgánicas por el principio de jerarquía.", "Que las relaciones entre la ley y el reglamento son de competencia y no de jerarquía.", "Que el reglamento está jerárquicamente subordinado a la Constitución y a la ley, de acuerdo con el artículo 97 de la Constitución y el artículo 128 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas.", "Que no hay jerarquía normativa entre reglamentos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 70, "¿Los principios generales del derecho operan como límite material de los reglamentos?", "Sólo los principios que recoge el artículo 103 de la Constitución.", "Sí.", "No; los límites materiales de los reglamentos son la Constitución, los estatutos de autonomía y las normas con rango de ley.", "Sólo opera como límite el principio de no arbitrariedad de los poderes públicos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 71, "Un reglamento que vulnere otro reglamento de rango superior:", "Puede ser convalidado.", "Es anulable.", "Es nulo de pleno derecho.", "Es nulo de pleno derecho; no obstante, el plazo para declarar la nulidad o impugnarlo es de un año, de acuerdo con lo que prevé la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 72, "¿Qué tienen que hacer los jueces y los magistrados ante un reglamento ilegal?", "Aplicarlo hasta que el Tribunal Constitucional declare la nulidad.", "No aplicarlo, atendida la obligación que establece la Ley orgánica del poder judicial de no aplicar los reglamentos o cualquier otra disposición contraria a la Constitución, a la ley o al principio de jerarquía normativa.", "Puede no aplicarlo, debido a la independencia del poder judicial.", "No aplicarlo siempre que lo haya alegado la parte recurrente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 73, "¿Qué tiene que hacer un funcionario ante un reglamento ilegal?", "Aplicarlo hasta que el Tribunal Constitucional declare la nulidad.", "No aplicarlo, dado que los funcionarios están sujetos a la Constitución y a la ley.", "Aplicarlo si así lo impone una instrucción o una orden de servicio.", "Las respondidas b) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 74, "Ante un reglamento ilegal, la Administración puede:", "Convalidarlo, reparando los vicios que presente.", "Revisarlo de oficio, con un dictamen previo del Consejo Consultivo.", "Revisarlo de oficio, con audiencia previa e información pública.", "Revocarlo, siempre que sean normas desfavorables."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 8, 75, "Las disposiciones reglamentarias deben estar encabezadas:", "Con una exposición de motivos, que exprese la finalidad de las medidas adoptadas en la regulación y el marco normativo en que se inserta.", "Con un preámbulo, que exprese la finalidad de las medidas adoptadas en la regulación y el marco normativo en que se inserta.", "Con una exposición motivada, que exprese la finalidad de las medidas adoptadas en la regulación y el marco normativo en que se inserta.", "Con unos antecedentes, que expresen la finalidad de las medidas adoptadas en la regulación y el marco normativo en que se inserta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 1, "Los consejos insulares deben adecuar su funcionamiento a:", "Lo dispuesto en el título VI de la Ley 4/2022, de 28 de junio, de consejos insulares, y el respectivo reglamento orgánico.", "Lo que disponen el título V de la Ley 4/2022, de 28 de junio, de consejos insulares, y el reglamento orgánico respectivo.", "Lo que disponen el Estatuto de autonomía, el título V de la Ley 4/2022, de 28 de junio, de consejos insulares, y el respectivo reglamento orgánico.", "Lo que disponen el Estatuto de autonomía, el título VI de la Ley 4/2022, de 28 de junio, de consejos insulares, y el respectivo reglamento orgánico."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 2, "El catalán es la lengua:", "De uso normal y preferente en la Administración insular y en las entidades que dependen de la misma.", "De uso normal y exclusivo en la Administración insular y en las entidades dependientes.", "De uso normal y general en la Administración insular y en las entidades que dependen.", "De uso formal y habitual en la Administración insular y en las entidades que dependen de la misma."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 3, "Según establece la Ley 4/2022, de 28 de junio, de consejos insulares:", "Los consejos insulares deben adoptar medidas para la normalización de la lengua catalana en cualquier ámbito y deben velar por la calidad del lenguaje administrativo.", "Los consejos insulares deben adoptar medidas para la normalización de la lengua catalana en cualquier ámbito y deben velar por la estandarización del lenguaje administrativo.", "Los consejos insulares deben adoptar medidas para la normalización de la lengua catalana en el ámbito de sus competencias y deben velar por la calidad del lenguaje administrativo.", "Los consejos insulares deben adoptar medidas para la normalización de la lengua catalana en el ámbito de sus competencias y deben velar por la estandarización del lenguaje administrativo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 4, "Los consejeros ejecutivos no electos del Consell Insular:", "Pueden intervenir en las sesiones del Pleno y las comisiones, con voz y sin voto, en asuntos relacionados con el departamento respectivo.", "Pueden intervenir en las sesiones del Pleno y las comisiones, con voz y voto, en asuntos relacionados con el respectivo departamento.", "Pueden intervenir en las sesiones del Pleno y las comisiones, con voz y sin voto, en asuntos relacionados con las competencias insulares.", "Pueden intervenir en las sesiones del Pleno y las comisiones, con voz y voto, en asuntos relacionados con las competencias insulares."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 5, "En las sesiones del Consejo Ejecutivo se pueden adoptar acuerdos sobre otros asuntos que no figuren en el orden del día:", "Por decisión de la presidencia, en cualquier caso.", "Por razones de urgencia, siempre que ésta sea acordada por la mayoría absoluta de los miembros del Consejo Ejecutivo.", "Por razones de urgencia, siempre que ésta sea acordada por la mayoría simple de los miembros del Consejo Ejecutivo.", "Por razones de oportunidad, siempre que ésta sea acordada por la mayoría absoluta de los miembros del Consejo Ejecutivo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 6, "El Pleno del Consell Insular ejerce el control y la fiscalización de la actuación del presidente y del Consell Insular, entre otros, por los siguientes medios:", "Moción de censura, cuestión de confianza, comisiones informativas.", "Moción de confianza, comisiones de investigación, preguntas.", "Moción de censura, comisiones informativas, preguntas.", "Moción de censura, cuestión de confianza, comisiones de investigación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 7, "La cuestión de confianza puede plantearla al Pleno del Consell Insular:", "El presidente sobre su programa en su conjunto, sobre una declaración de política especial o sobre la aprobación de cualquier asunto de trascendencia general.", "El presidente sobre su programa en su conjunto, sobre una declaración de política general o sobre la aprobación de cualquier asunto de trascendencia especial.", "Cualquier grupo político sobre su programa en su conjunto, sobre una declaración de política general o sobre la aprobación de cualquier asunto de trascendencia especial.", "El presidente o cualquier grupo político sobre su programa en su conjunto, sobre una declaración de política general o sobre la aprobación de cualquier asunto de trascendencia especial."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 8, "Los debates sobre la actuación de política general que debe llevar a cabo el Pleno del Consell Insular son:", "Al menos dos debates anuales.", "Al menos un debate en cada mandato corporativo.", "Un mínimo de dos debates en cada mandato corporativo.", "Al menos un debate anual."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 9, "El Pleno puede acordar celebrar una sesión extraordinaria que tenga por objeto debatir la gestión del Consejo Ejecutivo en áreas determinadas:", "A propuesta del presidente oa solicitud de al menos una cuarta parte de sus miembros.", "A propuesta del presidente oa solicitud de al menos una tercera parte de sus miembros.", "A propuesta del presidente oa solicitud de al menos dos grupos políticos que representen a una tercera parte de sus miembros.", "A propuesta del presidente oa solicitud de al menos dos grupos políticos que representen a una cuarta parte de sus miembros."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 10, "Las interpelaciones:", "Deben versar sobre la actuación del presidente, del Consejo Ejecutivo o de algún departamento en cuestiones de política general.", "Tienen que versar sobre la actuación del Pleno, del presidente, del Consejo Ejecutivo o de algún departamento en cuestiones de política general.", "Tienen que versar sobre la actuación del presidente, del Consejo Ejecutivo o de algún departamento en cuestiones de política insular.", "Tienen que versar sobre la actuación del pleno, del presidente, del Consejo Ejecutivo o de algún departamento en cuestiones de política insular."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 11, "Las preguntas:", "Tienen una respuesta oral o una respuesta escrita.", "Tienen una respuesta oral y una respuesta escrita.", "Tienen una respuesta únicamente oral.", "Tienen una respuesta únicamente escrita."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 12, "El Pleno puede acordar la creación de comisiones de investigación sobre la actuación de los órganos de gobierno insulares o de sus miembros en un asunto o materia determinados:", "A propuesta de un grupo político que represente al menos la tercera parte de sus miembros.", "A propuesta de un grupo político que representen al menos la cuarta parte de sus miembros.", "A propuesta de dos grupos políticos que representen al menos la cuarta parte de sus miembros.", "A propuesta de dos grupos políticos que representen al menos la tercera parte de sus miembros."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 13, "Las comparecencias del presidente o de los miembros del Consejo Ejecutivo ante el Pleno o ante una comisión:", "Pueden llevarse a cabo a petición únicamente del presidente, pero también si lo solicitan al menos dos grupos políticos o el número de miembros del Pleno que fije el reglamento orgánico.", "Se pueden llevar a cabo a petición del presidente o de los miembros del Consejo Ejecutivo, así como si lo solicitan al menos dos grupos políticos o el número de miembros del Pleno que fije el reglamento orgánico.", "Pueden llevarse a cabo a petición del presidente, así como si lo solicita un grupo político o el número de miembros del Pleno que fije el reglamento orgánico.", "Pueden llevarse a cabo a petición del presidente o de los miembros del Consejo Ejecutivo, así como si lo solicita un grupo político o el número de miembros del Pleno que fije el reglamento orgánico."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 14, "Los actos dictados por el presidente adoptan la forma de:", "Resoluciones de la presidencia.", "Banes de la presidencia.", "Reglamentos de la Presidencia.", "Decretos de la presidencia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 15, "Contra los actos dictados por el Consejo Ejecutivo se puede interponer:", "Un recurso de alzada ante el Pleno.", "Un recurso de alzada ante la Comisión de Gobierno.", "Un recurso de alzada ante la Presidencia.", "No existe ningún recurso de alzada contra los actos dictados por el Consejo Ejecutivo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 16, "Son competentes para resolver los procedimientos de revisión de oficio de disposiciones y actas:", "El Pleno y el presidente.", "El Pleno y el Consejo Ejecutivo.", "El Pleno y la Comisión de Gobierno.", "El Consejo Ejecutivo y el presidente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 17, "La resolución de los procedimientos de revisión de oficio en materia tributaria corresponde:", "Al Pleno.", "En los servicios de intervención.", "En el Consejo Ejecutivo.", "Al presidente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 18, "El ejercicio de la potestad sancionadora corresponde:", "A los órganos insulares determinados legal o reglamentariamente por razón de la materia o, en su defecto, al presidente.", "A los órganos insulares determinados legal o reglamentariamente por razón de la materia o, en su defecto, al Consejo Ejecutivo.", "A los órganos insulares determinados legal o reglamentariamente por razón de la materia o, en su defecto, al consejero ejecutivo competente.", "A los órganos insulares determinados legal o reglamentariamente por razón de la materia o, en su defecto, al Pleno."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 19, "La potestad reglamentaria de los consejos insulares se ejerce mediante las disposiciones aprobadas:", "Por el Pleno.", "Por el Gobierno.", "Por el Parlamento.", "Por el Consejo Ejecutivo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 20, "Las disposiciones generales del Pleno responden a la siguiente tipología:", "Reglamento orgánico, reglamento ordinario, ordenanza fiscal y otros reglamentos.", "Reglamento orgánico, reglamento ejecutivo, ordenanza fiscal y reglamentos organizativos.", "Reglamento organizativo, reglamento ejecutivo, ordenanza fiscal y otros reglamentos.", "Reglamento orgánico, reglamento ejecutivo, ordenanza fiscal y otros reglamentos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 21, "Los presupuestos generales y los instrumentos de planificación general y sectorial y de ordenación territorial y urbanística tienen rango de:", "Disposición especial.", "Disposición reglamentaria.", "Disposición legal.", "Disposición especializada."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 22, "La potestad reglamentaria en las materias del artículo 70 del Estatuto de Autonomía corresponde:", "En los consejos insulares y en el Gobierno.", "En los consejos insulares y, supletoriamente, en el Gobierno.", "En los consejos insulares, sin posibilidad de intervención del Gobierno.", "A los consejos insulares, sin perjuicio de la facultad del Gobierno de establecer los principios generales en la materia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 23, "En el ejercicio de la potestad reglamentaria, los consejos insulares deben actuar de acuerdo con los principios de:", "Oportunidad, eficacia, proporcionalidad, seguridad jurídica, transparencia y eficiencia.", "Necesidad, eficacia, proporcionalidad, seguridad jurídica, transparencia y eficiencia.", "Necesidad, oportunidad, eficacia, proporcionalidad, seguridad jurídica, transparencia y eficiencia.", "Necesidad, eficacia, progresividad, seguridad jurídica, transparencia y eficiencia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 24, "Las relaciones entre los reglamentos de cada consejo insular se rigen por los principios de:", "Competición y especialidad.", "Competencia y transparencia.", "Competición y transparencia.", "Competencia y especialidad."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 25, "Para que los reglamentos entren en vigor y produzcan efectos jurídicos:", "Se publicará su acuerdo en el Boletín Oficial de las Illes Balears.", "Se publicarán íntegramente en el Boletín Oficial del Estado.", "Se publicará su acuerdo en el Boletín Oficial del Estado.", "Se publicarán íntegramente en el Boletín Oficial de las Illes Balears."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 26, "La consulta pública previa al inicio del procedimiento de elaboración de disposiciones reglamentarias y en los supuestos previstos en la normativa básica estatal no será preceptiva cuando se trate de iniciativas:", "De reglamentos técnicos y de organización.", "De reglamentos orgánicos.", "De reglamentos ejecutivos.", "De reglamentos de despliegue."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 27, "La elaboración de los reglamentos ejecutivos es iniciada:", "Por acuerdo plenario.", "Por el presidente.", "Por acuerdo del Consejo Ejecutivo.", "Por el consejero ejecutivo competente por razón de la materia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 28, "El proyecto de reglamento ejecutivo debe ser adoptado por:", "El Consejo Ejecutivo.", "El consejero ejecutivo competente por razón de la materia.", "El presidente.", "El Pleno."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 29, "El plazo de los trámites de audiencia, consultas e información pública para la aprobación de reglamentos ejecutivos debe ser adecuado a la naturaleza de la disposición y, en todo caso:", "No inferior a cuarenta días.", "No inferior a treinta días.", "No inferior a veinte días.", "No inferior a diez días."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 30, "Las medidas provisionales adecuadas y necesarias para asegurar la eficacia de la regulación que se pretenda establecer con un reglamento ejecutivo, pueden ser adoptadas por:", "El Consejo Ejecutivo.", "El consejero ejecutivo competente por razón de la materia.", "El presidente.", "El Pleno."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 31, "La propuesta previa del reglamento ejecutivo que se someta a aprobación definitiva debe ir acompañada de:", "La última versión del proyecto, la memoria de análisis de impacto normativo y el dictamen del Consejo Consultivo.", "La última versión del proyecto, la memoria de análisis de impacto de género y el dictamen del Consell Consultiu.", "La última versión del proyecto, la memoria de análisis de impacto normativo y el dictamen del Govern.", "La última versión del proyecto, la memoria de análisis de impacto de género y el dictamen del Govern."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 32, "Para la elaboración del reglamento orgánico deben seguirse, en cualquier caso, los siguientes trámites:", "Información pública por plazo no inferior a un mes, informe sobre alegaciones, informe de los servicios jurídicos, dictamen del Consejo Consultivo y aprobación definitiva por el Pleno.", "Aprobación inicial por el Pleno, información pública por plazo no inferior a 45 días, informe sobre alegaciones, informe de los servicios jurídicos, dictamen del Consejo Consultivo y aprobación definitiva por el Pleno.", "Aprobación inicial por el Pleno, información pública por un plazo no inferior a un mes, informe sobre alegaciones, informe de los servicios jurídicos y aprobación definitiva por el Pleno.", "Aprobación inicial por el Pleno, información pública por plazo no inferior a un mes, informe sobre alegaciones, informe de los servicios jurídicos, dictamen del Consejo Consultivo y aprobación definitiva por el Pleno."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 33, "¿Qué órgano de los consejos insulares ejerce la iniciativa legislativa prevista en el Estatuto de Autonomía?", "El Consejo Ejecutivo.", "El Pleno.", "La Presidencia.", "La Junta de Portavoces."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 34, "¿Pueden los consejos insulares representar protocolariamente al Gobierno de la comunidad autónoma en un acto oficial que tenga lugar en la isla?", "Sí, por medio de cualquier consejero ejecutivo.", "Sí, por medio de su presidencia.", "No, debe representarle el presidente del Gobierno.", "No, debe representarlo cualquiera de los miembros del Gobierno."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 35, "¿Las políticas de género, la conciliación de la vida familiar y laboral, y la mujer son materias de competencia de los consejos insulares?", "No, son competencia del Gobierno de las Islas Baleares.", "Sí, son competencias propias de los consejos insulares.", "Sí, son competencias delegadas de los consejos insulares.", "No, son competencias del Estado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 36, "¿Qué potestad tiene el Gobierno de las Islas Baleares respecto a las competencias propias de los consejos insulares?", "La potestad de coordinar la actuación de los consejos insulares en el ejercicio de las competencias.", "La potestad reglamentaria.", "La función ejecutiva y de gestión.", "La potestad de adoptar políticas propias en cada sector de la acción pública."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 37, "Las proposiciones de ley de los consejos insulares deben aprobarse:", "Por mayoría simple de los miembros asistentes al Pleno.", "Por mayoría absoluta del Pleno.", "Por mayoría simple del Consejo Ejecutivo.", "Por mayoría simple del número de miembros del Pleno."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 38, "En relación con los planes insulares de cooperación, indique la respuesta incorrecta:", "Es un instrumento para contribuir a la financiación de las inversiones de carácter prioritario que propongan las entidades locales.", "Tiene carácter anual.", "Tiene carácter plurianual.", "El Gobierno de la comunidad autónoma debe colaborar en la dotación económica de los planes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 39, "De acuerdo con el art 112 de la Ley 4/2022 de consejos insulares, ¿qué facultad se reserva el Gobierno de la comunidad autónoma respecto de las competencias delegadas a los consejos insulares?", "Dictar instrucciones técnicas de carácter particular.", "Instruir expedientes sancionadores de los servicios objeto de la delegación.", "Designar asesores.", "Nombrar personal técnico."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 40, "Las propuestas de delegación de competencias municipales en los consejos insulares deben someterse a información pública por un plazo mínimo de:", "Un mes.", "Quince días.", "Dos meses.", "Tres meses."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 41, "En caso de incumplimiento del decreto de delegación por parte de un consejo insular, el Gobierno de la comunidad autónoma podrá adoptar la siguiente medida:", "Suspensión parcial o total de la delegación por un período no superior a seis meses.", "Suspensión parcial o total de la delegación por un período no superior a un mes.", "Suspensión parcial o total de la delegación por un período no superior a tres meses.", "Suspensión parcial o total de la delegación por un período no superior a un año."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 42, "La delegación de competencias en los consejos insulares debe acordarse mediante:", "Un decreto aprobado en el Consejo de Gobierno.", "Un acuerdo de Pleno de los consejos insulares adoptado por mayoría simple.", "Una ley del Gobierno de la comunidad autónoma.", "Un reglamento del consejo insular correspondiente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 43, "Cuando un instrumento de planificación de la comunidad autónoma afecta a ámbitos materiales en los que los consejos insulares tengan competencias, éstos deben disponer de la información adecuada y deben ser oídos en un plazo:", "De un mes.", "De quince días.", "De tres meses.", "Adecuado y suficiente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 44, "¿Quién debe resolver los recursos administrativos contra los actos de la Administración de la comunidad autónoma dictados antes de la transferencia de la competencia a los consejos insulares, presentados posteriormente a ésta?", "Los órganos competentes de los consejos insulares.", "Los órganos competentes de la Administración de la comunidad autónoma.", "El Tribunal Administrativo Central de Recursos.", "Pueden resolver los recursos tanto los órganos competentes de los consejos insulares como los órganos competentes de la Administración de la comunidad autónoma."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 45, "En relación con los consorcios, indique la respuesta correcta:", "Las entidades instrumentales de los consejos insulares no pueden constituir consorcios con otras administraciones públicas.", "Pueden constituirse cuando la cooperación no se puede llevar a cabo mediante un convenio.", "Los consejos insulares no pueden constituir consorcios con entidades privadas.", "Las entidades instrumentales de los consejos insulares no pueden constituir consorcios con entidades públicas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 46, "Los consejos insulares coordinan o asumen la prestación de los servicios municipales en los municipios con una población:", "Inferior a 25.000 habitantes.", "Inferior a 30.000 habitantes.", "Inferior a 15.000 habitantes.", "Inferior a 20.000 habitantes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 47, "¿Pueden los entes instrumentales de los consejos insulares suscribir convenios con ciudadanos particulares?", "Los entes instrumentales de los consejos insulares no pueden suscribir ningún tipo de convenios.", "Los entes instrumentales de los consejos insulares no pueden suscribir convenios con sujetos de derecho privado.", "Sí, si implica cesión de la titularidad de la competencia.", "Sí, de acuerdo con la legislación básica del Estado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 48, "¿Cuáles son los órganos superiores de administración de los consejos insulares?", "Directores insulares", "El/la presidente/a", "Los consejeros ejecutivos", "Todas las respuestas anteriores son correctas"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 49, "La sesión pública constitutiva del Pleno de los consejos insulares se celebra:", "En el período comprendido entre los días veintidós y cuarenta y cinco desde la fecha de las elecciones.", "En el período comprendido entre los días veintiuno y cuarenta y seis desde la fecha de las elecciones.", "En el período comprendido entre los días veinte y cuarenta y cinco desde la fecha de las elecciones.", "En el período comprendido entre los días veintiuno y cuarenta y cinco desde la fecha de las elecciones."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 50, "¿Cuál de las siguientes funciones no corresponde a las comisiones del Pleno?", "En el caso de la Comisión Especial de Cuentas, las previstas en la legislación de haciendas locales.", "El seguimiento de la gestión del presidente, del Consejo Ejecutivo y de sus miembros, sin perjuicio del control que corresponde al Pleno.", "El informe o consulta de los asuntos que deban ser sometidos a la decisión del Pleno.", "El ejercicio de las competencias asignadas en el reglamento orgánico y de las competencias delegadas por el Pleno de acuerdo con la Ley de consejos insulares."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 51, "¿Cuáles de estas atribuciones no requieren el voto favorable de la mayoría absoluta del número legal de miembros del Pleno de los consejos insulares?", "Ejercer la iniciativa legislativa de acuerdo con el Estatuto de Autonomía.", "Crear, modificar y suprimir los servicios públicos de competencia del Consell Insular, determinar sus formas de gestión y aprobar la prestación de servicios públicos y actividades económicas en régimen de monopolio de acuerdo con la legislación sobre la competencia.", "Alterar la calificación jurídica de los bienes de dominio público y autorizar la cesión gratuita de bienes inmuebles a otras entidades públicas o privadas.", "Aprobar la creación y supresión de municipios, así como la alteración de términos municipales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 52, "¿Por cuál de estas causas no cesa el presidente del Consell Insular?", "La pérdida de la condición de miembro del Consell Insular.", "Cuando la incapacidad física o psíquica sea apreciada motivadamente por dos quintas partes de los miembros del Pleno, y aprobada por mayoría simple.", "La terminación del mandato de acuerdo con la legislación electoral.", "La renuncia comunicada por escrito al Pleno."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 53, "¿Cuál de estas afirmaciones se incorrecta?", "El Consejo Ejecutivo es el órgano de gobierno al frente de la administración insular.", "El Consejo Ejecutivo está integrado por el presidente, el vicepresidente o vicepresidentes y los consejeros ejecutivos que tienen la condición de electos.", "El Consejo Ejecutivo responde políticamente ante el Pleno de su gestión de forma solidaria.", "El presidente asigna la secretaría del Consejo Ejecutivo a uno de sus miembros o al secretario general del Consejo Insular. Si lo hace en uno de sus miembros, éste podrá contar con la asistencia de un funcionario del grupo A."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 54, "Los consejos insulares amparan los derechos de los ciudadanos, mediante:", "Los instrumentos y procedimientos adecuados para recibir la información institucional y administrativa para el ejercicio de sus derechos y participación en la organización de la Administración insular.", "La asistencia a las sesiones del Pleno en uso de las facultades determinadas por el reglamento orgánico.", "Las consultas en los procedimientos de planificación sectorial y elaboración normativa.", "Todas las respuestas anteriores son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 55, "Los entes del sector público instrumental de los consejos insulares se rigen por:", "Para la elaboración y aprobación de los presupuestos, cuentas anuales, tesorería y fiscalización, por la legislación de haciendas locales.", "El patrimonio, por la legislación de patrimonio, en su caso.", "Por el reglamento orgánico del consejo insular correspondiente.", "Todas las respuestas anteriores son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 56, "La Ley de consejos insulares prevé que las notificaciones, citaciones y otras comunicaciones judiciales, para que se entiendan hechas con validez, deben practicarse:", "En la sede de los servicios jurídicos de los consejos insulares.", "De conformidad con el vigente régimen electrónico de comunicaciones.", "En la persona de uno de sus letrados o abogados.", "Todas las respuestas anteriores son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 57, "Las retribuciones de las personas titulares de los órganos directivos se fijan y serán públicas cuando:", "El Decreto de Presidencia fije las retribuciones de los órganos directivos.", "Según lo previsto en la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno.", "La normativa presupuestaria fije las retribuciones de los órganos directivos.", "Las respuestas b) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 58, "Los miembros de los consejos insulares tienen el derecho y el deber de:", "Disfrutar de los derechos, honores y distinciones propios del cargo.", "Asistir a las sesiones del Pleno.", "Percibir las retribuciones e indemnizaciones que determine el Pleno.", "El deber de realizar la declaración de actividades y bienes sólo los consejeros electos, pero no el resto de miembros."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 59, "El Consejo Ejecutivo, como órgano de gobierno de los consejos insulares, ¿cuál de estas atribuciones puede ejercer?", "Aprobar su plantilla de personal.", "Aprobar el plan insular de Cooperación.", "Resolver los conflictos de atribuciones que puedan plantearse entre los consejeros ejecutivos.", "Reconocer las obligaciones derivadas de responsabilidad patrimonial en los supuestos previstos en el reglamento orgánico."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 60, "¿Cuál de estas atribuciones corresponde a los directores insulares?", "Cuidar la ejecución del presupuesto.", "Dar asistencia técnica y administrativa al consejero ejecutivo.", "Realizar la gestión de los servicios comunes y del personal de su departamento.", "Velar por la utilización racional y eficiente de los medios materiales a su cargo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 61, "¿Cuáles de las entidades que forman el sector público instrumental de los consejos insulares tienen personalidad pública?", "Entidades públicas empresariales.", "Sociedades mercantiles públicas.", "Consorcios insulares.", "Fundaciones del sector público."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 62, "En los términos establecidos en el reglamento orgánico de los consejos insulares, el asesoramiento jurídico a los órganos de la Administración insular no corresponde:", "A los letrados integrantes de los servicios jurídicos de los consejos insulares.", "A los funcionarios con habilitación nacional.", "A los letrados o abogados del Gobierno de las Islas Baleares.", "A los abogados integrantes de los servicios jurídicos de los consejos insulares."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 63, "¿Cuál de estas afirmaciones, en relación a los órganos directivos, es incorrecta?", "Los órganos directivos se integran en la estructura de los departamentos de acuerdo con lo que disponga el decreto de la presidencia correspondiente.", "Los titulares de los órganos directivos serán nombrados y separados por el Consejo Ejecutivo.", "Los titulares de los órganos de dirección ejercen su cargo en régimen de dedicación exclusiva.", "Cuando se produzca el nombramiento de los nuevos miembros del Consejo Ejecutivo, los titulares de los órganos directivos deben continuar en el cargo hasta que no se disponga expresamente su cese."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 64, "¿Por cuál de estas causas el presidente debe continuar en el ejercicio del cargo hasta que el sucesor haya tomado posesión del mismo?", "La denegación de la cuestión de confianza.", "La declaración de incompatibilidad adoptada por el Pleno.", "La terminación del mandato de acuerdo con la legislación electoral.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 7, 65, "La condición de vicepresidente se pierde por, además de por el cese:", "Por la pérdida de la condición de miembro del Consell Insular.", "Por la renuncia expresa comunicada por escrito.", "Por la incapacidad física o psíquica permanente que le imposibilite para ejercer el cargo.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 1, "El Decreto 12/2014, de 28 de febrero, de la Comunidad Autónoma de las Illes Balears (modificado por el Decreto 12/2017 de 31 de marzo), creó:", "La Comisión Técnica de Seguimiento del Plan de Igualdad y la Comisión de Igualdad.", "La Comisión Técnica de Evaluación del Plan de Igualdad y la Comisión de Igualdad.", "La Comisión de Seguimiento de las Políticas de Igualdad.", "La Comisión de Evaluación de las Políticas de Igualdad."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 2, "De conformidad con el artículo 3 de la Ley orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres:", "El principio de igualdad de trato entre mujeres y hombres supone la ausencia de toda discriminación, directa o indirecta, por razón de sexo.", "El principio de igualdad de trato entre mujeres y hombres supone un trato no igualitario y no discriminatorio entre mujeres y hombres.", "El principio de igualdad de trato entre mujeres y hombres supone un retroceso en la convivencia en nuestra sociedad.", "El principio de igualdad de trato entre mujeres y hombres supone un reto importante por nuestra sociedad."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 3, "Indique la respuesta correcta en relación con las acciones positivas que establece la Ley orgánica3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres:", "Los poderes públicos adoptarán medidas específicas en favor de las mujeres para corregir situaciones patentes de desigualdad de hecho respecto de los hombres.", "Las medidas tienen que ser aplicables en tanto que subsistan las situaciones de desigualdad.", "Las medidas tienen que ser razonables y proporcionadas en relación con el objetivo perseguido en cada caso.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 4, "Indique la respuesta incorrecta en relación con el fomento de la igualdad, que regula el artículo 6 de la Ley orgánica 1/2004, de 28 de diciembre, de medidas de protección integral contra la violencia de género:", "Las administraciones educativas velarán para que en todos los materiales educativos se eliminen los estereotipos sexistas.", "Las administraciones educativas velarán para que todos los materiales educativos fomenten el igual valor de hombres y de mujeres.", "Las administraciones educativas fomentarán la educación desagregada por sexos.", "Las administraciones educativas velarán para que en todos los materiales educativos se eliminen los estereotipos discriminatorios."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 5, "Las acreditaciones de víctimas de violencia de género, que regula la Ley orgánica1/2004, de 28 de diciembre, de medidas de protección integral contra la violencia de género:", "Se podrán realizar mediante documentos sanitarios oficiales de comunicación a la Fiscalía o al órgano judicial.", "Se podrán realizar mediante declaraciones de otros menores de edad ante las fuerzas y cuerpos de seguridad del Estado.", "Se podrán realizar mediante declaraciones de familiares ante las fuerzas y cuerpos de seguridad del Estado.", "Las personas menores de edad no pueden ser víctimas de violencia de género."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 6, "Diseñar los procedimientos básicos que permiten poner en marcha los sistemas de acreditación de las situaciones de violencia de género regulados por la Ley orgánica 1/2004, de 28 de diciembre, de medidas de protección integral contra la violencia de género, es una competencia que corresponde:", "Al Gobierno central.", "A las administraciones autonómicas.", "A las comisiones de igualdad de cada administración autonómica.", "Al Gobierno central y a las comunidades autónomas, de mutuo acuerdo, en el marco de la conferencia sectorial de igualdad."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 7, "De acuerdo con la Ley orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres:", "Constituye discriminación directa por razón de sexo cualquier trato desfavorable relacionado con el embarazo o la maternidad.", "Constituye discriminación indirecta por razón de sexo cualquier trato desfavorable relacionado con el embarazo o la maternidad.", "Constituye acción directa cualquier trato favorable relacionado con el embarazo o la maternidad.", "El embarazo y la maternidad no tienen nada que ver con la discriminación por razón de sexo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 8, "Según la Ley 11/2016, de 28 de julio, de igualdad de mujeres y hombres:", "Las mujeres víctimas de violencia de género serán consideradas colectivos prioritarios en el acceso a viviendas de protección oficial.", "Las mujeres víctimas de violencia de género serán consideradas colectivos prioritarios en el acceso a residencias públicas por gente mayor.", "Las mujeres víctimas de violencia de género solo tendrán prioridad para acceder a residencias privadas.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 9, "De acuerdo con la Ley 11/2016, de 28 de julio, de igualdad de mujeres y hombres:", "Las administraciones públicas de las Illes Balears tienen que tomar medidas con el objeto de fomentar la corresponsabilidad en la vida laboral, la familiar y la personal de las mujeres y los hombres.", "Las administraciones públicas de las Illes Balears tienen que tomar medidas con el objeto de fomentar la corrseponsabilitat en la vida laboral, la familiar y la personal de las mujeres y los hombres, teniendo en cuenta los nuevos modelos de familia.", "Las administraciones públicas tienen que tomar medidas de conciliación solo en casos de familias numerosas.", "Las administraciones públicas tienen que tomar medidas de conciliación solo en casos de familias monoparentales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 10, "Según la Ley 11/2016, de 28 de julio, de igualdad de mujeres y hombres:", "También se consideran víctimas de violencia las personas que convivan con la víctima.", "También se consideran víctimas de violencia las personas que tengan parentesco con la víctima.", "También se consideran víctimas las hijas y los hijos de la madre víctima de la violencia.", "solo se consideran víctimas las mujeres."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 11, "Según la Ley 11/2016, de 28 de julio, de igualdad de mujeres y hombres, ¿cuál es el máximo órgano de participación de carácter autonómico que tiene la finalidad de favorecer el asociacionismo y la participación de las mujeres en los temas que les puedan afectar?", "El Consejo de Participación de la Mujer Trabajadora.", "El Consejo de Participación de la Mujer.", "El Observatorio de Participación de las Mujeres.", "La Comisión de Participación de la Mujer."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 12, "Indique la respuesta correcta en relación con el V Plan Estratégico de Igualdad entre Mujeres y Hombres de las Illes Balears (2021-2023):", "El Instituto Balear de la Mujer es el órgano encargado de elaborarlo, con la colaboración de las consejerías correspondientes.", "Tienen que participar en él los consejos insulares y las entidades locales.", "Tienen que participar en él los agentes sociales y económicos y las asociaciones en defensa de los derechos de las mujeres de las Illes Balears.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 13, "De acuerdo con la Ley 11/2016, de 28 de julio, de igualdad de mujeres y hombres:", "Las administraciones públicas de las Illes Balears tienen que garantizar un uso no sexista del lenguaje.", "Las administraciones públicas de las Illes Balears podrán garantizar un uso no sexista del lenguaje.", "Las administraciones públicas de las Illes Balears podrán fomentar el uso del lenguaje sexista.", "Las administraciones públicas de las Illes Balears no pueden interferir en el uso del lenguaje sexista."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 14, "Según la Ley orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres:", "El principio de igualdad de trato y de oportunidades entre mujeres y hombres informará la actuación de todos los poderes públicos.", "El principio de igualdad de trato y de oportunidades entre mujeres y hombres informará, con carácter transversal, la actuación de todos los poderes públicos.", "El principio de igualdad de trato y de oportunidades entre mujeres y hombres no hace falta que se integre, de forma activa, en la adopción y la ejecución de disposiciones normativas.", "El principio de igualdad de trato y de oportunidades entre mujeres y hombres no está regulado en esta normativa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 15, "Indique la respuesta correcta en relación con la definición de planes de igualdad de las empresas en conformidad con la Ley orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres:", "Son un conjunto ordenado de medidas, adoptadas después de realizar un diagnóstico de situación, con la intención de lograr la igualdad de trato y de oportunidades entre mujeres y hombres.", "Son un conjunto ordenado de medidas, adoptadas después de realizar un diagnóstico de situación, con la intención de eliminar la discriminación por razón de sexo.", "Son un conjunto ordenado de medidas con la intención de hacer una evaluación de las conductas sexistas de las empresas.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 16, "Indique la respuesta correcta en relación con la obligatoriedad de las empresas de disponer de un plan de igualdad según la normativa en vigor:", "Están obligadas a disponer de planes de igualdad las empresas de cincuenta o más personas trabajadoras.", "Están obligadas a disponer de planes de igualdad las empresas entre cien y ciento cincuenta personas trabajadoras.", "Están obligadas a disponer de planes de igualdad las empresas de más de ciento cincuenta personas trabajadoras.", "No existe ningún tramo relacionado con el número de personas trabajadoras."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 17, "Señale la respuesta incorrecta en relación con los derechos de las mujeres víctimas de violencia de género, que regula la Ley orgánica 1/2004, de 28 de diciembre, de medidas de protección integral contra la violencia de género:", "Las mujeres víctimas de violencia de género tienen derecho a servicios sociales de atención.", "Las mujeres víctimas de violencia de género tienen derecho a servicios de apoyo, de acogida y de recuperación integral.", "Las mujeres víctimas de violencia de género no tienen derecho a servicios de emergencia.", "Las mujeres víctimas de violencia de género tienen derecho a recibir información plena y asesoramiento adecuado a su situación personal."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 18, "El Convenio del Consejo de Europa sobre prevención y lucha contra la violencia contra la mujer y la violencia doméstica:", "Se firmó en Estambul el 11 de mayo de 2011.", "Fue ratificado por España en marzo del 2014.", "Todavía no está ratificado por España.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 19, "La Carta de los Derechos Fundamentales de la Unión Europea:", "Contiene un artículo sobre no discriminación.", "Contiene un artículo sobre no estigmatización.", "Contiene un artículo sobre buen trato.", "No contiene ninguno de los artículos anteriores."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 20, "La Directiva 2004/113/CE del Consejo de Europa, de 13 de diciembre de 2004, por la que se aplica el principio de igualdad de trato entre hombres y mujeres en el acceso a los bienes y servicios y a su suministro:", "Establece la distinción entre discriminación directa y discriminación indirecta.", "Establece la distinción entre discriminación múltiple y orden de discriminar.", "Establece la distinción entre acoso y acoso sexual.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 21, "Indique la respuesta incorrecta de acuerdo con el Estatuto de autonomía de las Illes Balears, cuando establece que las administraciones públicas de las Illes Balears se tienen que centrar, primordialmente, en los ámbitos siguientes:", "La igualdad de derechos de mujeres y hombres en todos los ámbitos.", "La protección social contra la violencia, especialmente contra la violencia de género.", "El desarrollo sostenible del turismo.", "La protección específica y la tutela social del menor."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 22, "Según dispone el Estatuto de autonomía de las Illes Balears en el artículo 17 «no discriminación por razón de sexo»:", "Todas las mujeres y hombres tienen derecho al libre desarrollo de su personalidad y capacidad personal.", "Todas las mujeres y hombres tienen derecho a vivir con dignidad, seguridad y autonomía.", "Todas las personas tienen derecho a no ser discriminadas por razón de su orientación sexual.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 23, "Indique la respuesta correcta en relación con la definición de perspectiva de género que establece la Ley 11/2016, de 28 de julio, de igualdad de mujeres y hombres:", "Es la toma en consideración de las diferencias entre mujeres y hombres en un a?mbito o una actividad para el análisis, la planificación, el diseño y la ejecución de poli?ticas.", "Es la toma en consideración de las similitudes entre hombres y mujeres para la ejecución de las políticas.", "Es tener en cuenta la manera en que las diversas actuaciones, situaciones y necesidades afectan a los hombres.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 24, "Indique la respuesta incorrecta de acuerdo con lo que la Ley 11/2016, de 28 de julio, de igualdad de mujeres y hombres establece como violencia machista:", "La violencia económica, que incluye la privación intencionada, y no justificada legalmente, de recursos para el bienestar físico o psicológico.", "La violencia simbólica, que incluye los iconos, representaciones, narrativas, imágenes, etc., que reproducen o transmiten relaciones de dominación de los hombres respecto de las mujeres, así como desigualdades de poder entre sexos y de segregación.", "La violencia institucional, producida desde los servicios públicos y que revictimitza las víctimas.", "El feminicidio, asesinato de mujeres por el hecho de ser mujeres, al margen de que haya o haya habido relacio?n de pareja."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 25, "Señale la respuesta correcta en relación con el informe de evaluación de impacto de género, regulado por la Ley 11/2016, de 28 de julio, de igualdad de mujeres y hombres:", "La Administración de la Comunidad Autónoma de las Illes Balears tiene que aprobar las directrices en que se establezcan las pautas que se deben seguir para realizar el informe de evaluación de impacto de género.", "La Administración de la Comunidad Autónoma de las Illes Balears, a propuesta del Instituto Balear de la Mujer, tiene que aprobar las directrices en que se establezcan las pautas que se deben seguir para realizar el informe de evaluación de impacto de género.", "La Comisión de Paridad tiene que aprobar las pautas que se deben seguir para realizar el informe de evaluación de impacto de género.", "El Observatorio para la Equidad tiene que aprobar las directrices que se deben seguir para realizar el informe de evaluación de impacto de género."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 26, "El órgano colegiado encargado de coordinar las poli?ticas y los programas que realizan las administraciones autonómica, insular y local en materia de igualdad de mujeres y hombres, es:", "La Comisión de Igualdad.", "El Observatorio para la Igualdad.", "La Comisión para la Igualdad de G èneres.", "La Comisión para la Igualdad de S exes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 27, "El Observatorio para la Igualdad, regulado por el Decreto 1/2018, de 2 de febrero, tiene, entre otras, las funciones siguientes:", "Proponer un sistema de indicadores para tomar conocimiento de manera actualizada de la evolución de las desigualdades entre hombres y mujeres y la violencia machista, y para realizar su seguimiento y su evaluación.", "Analizar la evolución y los motivos de la persistencia de las desigualdades entre sexos y sexualidades y la violencia machista.", "Promover la elaboración de estudios, informes técnicos y evaluaciones comparables.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 28, "Señale la respuesta incorrecta en relación con cuáles son las áreas de intervención del Observatorio para la Igualdad, regulado por el Decreto 1/2018, de 2 de febrero:", "La violencia machista.", "El techo de cristal en el acceso al mercado de trabajo.", "La imagen pública de las mujeres.", "La sexualidad y la salud de las mujeres."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 29, "Señale la respuesta correcta en relación con el Decreto de traspaso de competencias en materia de políticas de género y mujer:", "Es el Decreto 26/2004, de 21 de diciembre, de traspaso a los consejos insulares de las funciones y los servicios inherentes a las competencias propias de estos consejos insulares que actualmente ejerce la Administración de la Comunidad Autónoma de las Illes Balears en materia de políticas de género y mujer.", "Es el Decreto 46/2018, de 21 de diciembre, de traspaso a los consejos insulares de las funciones y los servicios inherentes a las competencias propias de estos consejos insulares que actualmente ejerce la Administración de la Comunidad Autónoma de las Illes Balears en materia de políticas de género y mujer.", "Es el Decreto 46/2018, de 21de diciembre, de traspaso a los consejos insulares de las funciones y los servicios inherentes a las competencias propias de estos consejos insulares que actualmente ejerce la Administración de la Comunidad Autónoma de las Illes Balears en materia de políticas de corresponsabilidad.", "No se han transferido todavía estas competencias a los consejos insulares."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 30, "Señale cuál de las normas de ámbito estatal siguientes se ha aprobado recientemente en materia de no discriminación:", "La Ley 15/2022, de 12 de julio, integral para la igualdad de trato y la no discriminación.", "La Ley 15/2022, de 12 de julio, para la discriminación y la igualdad de trato.", "La Ley 16/2022, de 18 de noviembre, para combatir la desigualdad de género y la no discriminación.", "La Ley 17/2021, de 20 de diciembre, para atender las desigualdades y las discriminaciones."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 31, "Indique la respuesta correcta en relación con la Ley 6/2022, de 31 de marzo, de modificación del Texto refundido de la Ley general de derechos de las personas con discapacidad y de su inclusión social:", "Introduce un nuevo artículo para establecer las condiciones básicas de accesibilidad cognitiva, así como para prever su desarrollo normativo posterior mediante un reglamento específico.", "Establece las condiciones básicas de accesibilidad cognitiva sin prever ningún desarrollo normativo posterior.", "La modificación no prevé establecer ninguna condición básica de accesibilidad cognitiva.", "La modificación solo afecta el apartado de la inclusión social."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 32, "El artículo 14 de la Constitución española proclama el derecho a la igualdad y a la no discriminación por motivos de:", "Nacimiento, raza, sexo, nacionalidad y opinión.", "Nacimiento raza, sexo, religión y opinión.", "Nacimiento, raza, sexo, religión, opinión o cualquier otra circunstancia personal o social.", "Lugar de origen, etnia, espiritualidad, opinión y cualquier otra circunstancia personal o social."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 33, "Indique la respuesta correcta en relación con los derechos de las funcionarias públicas víctimas de violencia de género según el que establece la Ley orgánica 1/2004, de 28 de diciembre, de medidas de protección integral contra la violencia de género:", "La funcionaria víctima de violencia de género tendrá derecho a la reducción o a la reordenación de su tiempo de trabajo.", "La funcionaria víctima de violencia de género tendrá derecho a la movilidad geográfica del centro de trabajo.", "La funcionaria víctima de violencia de género tendrá acceso a servicios específicos de atención.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 34, "La Estrategia para la igualdad de las personas Lesbianas, Gays, Bisexuals, Trans, Intersexuales y Queer (LGTBIQ) de la Unión Europea:", "Tiene previsto integrar la lucha contra la discriminación que afecta a las personas LGTBIQ en todas las políticas que se realicen en la Unión Europea.", "Está pensada para el periodo 2020-2025.", "Está basada, entre otras fuentes, en el informe sobre los derechos fundamentales de la Agencia Europea de Derechos Fundamentales (FRA) del 2020.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 35, "Indique la respuesta correcta en relación con el objeto de la Ley 8/2016, de 30 de mayo, para garantizar los derechos de lesbianas, gays, trans, bisexuales e intersexuales y para erradicar la LGTBI-fobia:", "Establecer y regular los principios, los medios y las medidas para garantizar plenamente la igualdad real y efectiva en el ejercicio de los derechos de las personas lesbianas, gays, trans (transexuales y transgèneres), bisexuales e intersexuales (LGTBI).", "Establecer y regular los principios para garantizar los derechos de las personas no heterosexuales.", "Establecer y regular los principios para fomentar los derechos de las personas gays y lesbianas.", "Establecer y regular los principios para promover los derechos de las personas trans e intersexuales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 36, "Indique la respuesta correcta en relación con la evaluación de impacto sobre orientación sexual e identidad de género que establece la Ley 8/2016, de 30 de mayo, para garantizar los derechos de lesbianas, gays, trans, bisexuales e intersexuales y para erradicar la LGTBI-fobia:", "Esta evaluación se tiene que incorporar sobre todas las disposiciones legales o reglamentarias que se impulsen dentro del territorio de la comunidad autónoma.", "Esta evaluación se tiene que incorporar sobre algunas disposiciones legales o reglamentarias concretas que se impulsen dentro del territorio de la comunidad autónoma.", "Esta evaluación tiene que garantizar la integración del principio de igualdad y no discriminación de las personas LGTBI.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 37, "De acuerdo con la Ley 8/2016, de 30 de mayo, para garantizar los derechos de lesbianas, gays, trans, bisexuales e intersexuales y para erradicar la LGTBI-fobia y la discriminación por asociación es:", "La situacio?n en que una persona o un grupo de personas son objeto de discriminación por orientación sexual, identidad de género o expresión de género como consecuencia de una apreciación errónea.", "La situación en que una persona es objeto de discriminación por orientación sexual, identidad de género o expresión de género como consecuencia de su relacio?n con una persona o un grupo LGTBI.", "La situación en que una persona activista por los derechos de las personas gays es discriminada.", "La situación en que un grupo de personas activistas por los derechos de las personas lesbianas son discriminadas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 38, "¿Qué Tratado marcó un hito en la lucha contra la discriminación en la Unión Europea cuando empezó a vigir el 1 de mayo de 1999?", "El Tratado de Maastricht.", "El Tratado de Amsterdam.", "El Tratado de Oslo.", "El Tratado de Milán."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 39, "¿Qué directiva del Consejo de Europa prohíbe la discriminación por origen racial o étnico en cualquier ámbito?", "La Directiva 1998/53/CE, de 18 de mayo de 1996.", "La Directiva 2000/43/CE, de 29 de junio de 2000.", "La Directiva 2020/32/CE, de 29 de abril de 2019.", "No hay ninguna directiva que prohíba esta discriminación a la Unión Europea."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 40, "¿En qué Ley se transpuso en España la Directiva del Consejo de Europa que prohíbe la discriminación por origen racial o étnico?", "Mediante la Ley 62/2003, de 30 de diciembre, de medidas fiscales, administrativas y de orden social.", "Mediante la Ley 62/2011, de 30 de diciembre, de medidas fiscales, administrativas y de orden social.", "Mediante la Ley 17/2014, de 30 de diciembre, de medidas fiscales, administrativas y de orden social.", "Mediante la Ley 19/2015, de 30 de diciembre, de medidas fiscales, administrativas y de orden social."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 41, "La entrada en vigor del Tratado de Lisboa el 1 de diciembre de 2009 ha reforzado en la Unión Europea:", "La protección de los derechos fundamentales.", "La protección de los derechos sociales.", "La protección de los derechos civiles.", "La protección de los derechos a la infancia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 42, "El Consejo de la Unión Europea, por unanimidad, y previa aprobación del Parlamento Europeo, podrá adoptar acciones adecuadas para luchar:", "La discriminación por motivos de género, lugar de nacimiento, nacionalidad o discapacidad.", "La discriminación por motivos de sexo, país de origen, color de piel o capacidad.", "La discriminación por motivos de sexo, de origen racial o étnico, religión o convicciones, discapacidad, edad u orientación sexual.", "La discriminación por motivos de raza, religión, ideología y condición sexual."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 43, "Indique la respuesta correcta en relación con lo que dispone la Recomendación CM/Rec (2019) del Comité de Ministros a los Estados miembros para prevenir y combatir el sexismo, adoptada el 27 de marzo de 2019:", "Afirma que el sexismo se refuerza por los estereotipos de género que afectan a mujeres y hombres, niñas y niños, e impide la consecución de la igualdad de género y el establecimiento de sociedades inclusivas.", "Recuerda que el sexismo es una manifestación de las relaciones de poder históricamente desiguales entre mujeres y hombres, que provoca discriminación y que impide el pleno avance de las mujeres en la sociedad.", "Observa que mujeres y niñas pueden ser objeto de discriminación múltiple e interseccional y que pueden enfrentarse a un sexismo combinado con otras normas o comportamientos discriminatorios, de odio o nocivos.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 44, "¿En qué ley de ámbito autonómico está reconocido el derecho a la no discriminación de las personas menores de edad?", "En la Ley 9/2019, de 19 de febrero, de la atención y los derechos de la infancia y la adolescencia de las Illes Balears.", "En la Ley 9/2019, de 19 de febrero, de protección a jóvenes menores de edad de las Illes Balears.", "En la Ley 6/2018, de 18 de marzo, de no discriminación de niños y de adolescentes en las Illes Balears.", "Este derecho no está reconocido en ninguna normativa autonómica en vigor."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 45, "¿Qué ley de ámbito autonómico tiene por objeto garantizar la igualdad de oportunidades, la no discriminación y la accesibilidad universal para permitir la autonomía personal de todas las personas y, particularmente, de las personas con discapacidad?", "La Ley 8/2017, de 3 de agosto, para la accesibilidad de las personas con discapacidades de las Illes Balears.", "La Ley 8/2017, de 3 de agosto, de accesibilidad universal de las Illes Balears.", "La Ley 4/2020, de 8 de mayo, para mejorar la accesibilidad de todas las personas de las Illes Balears.", "La Ley 5/2021, de 10 de abril, de no discriminación de las personas con diversidad funcional de las Illes Balears."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 46, "¿Qué ley de ámbito autonómico tiene un título de medidas para garantizar la igualdad real y efectiva de las personas atendiendo a su identidad y a la expresión de género?", "La Ley 11/2016, de 28 de julio, de igualdad de mujeres y hombres.", "La Ley 5/2003, de 4 de abril, de salud de las Illes Balears.", "La Ley 8/2016, de 30 de mayo, para garantizar los derechos de lesbianas, gays, trans, bisexuales e intersexuals y para erradicar la LGTBI-fobia.", "La Ley 8/2018, de 31 de julio, de apoyo a las familias."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 47, "¿De qué ministerio depende el Pacto de Estado contra la Violencia de Género?", "Del Ministerio de Igualdad.", "Del Ministerio de Trabajo y Economía Social.", "Del Ministerio de Sanidad.", "Del Ministerio de Justicia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 48, "El Gobierno, mediante la Delegación del Gobierno para la Violencia de Género, desarrolla el Pacto de Estado contra la Violencia de Género impulsando:", "Medidas de coordinación con el resto de ministerios y organismos autónomos que dependen de estos.", "Medidas de coordinación con las comunidades autónomas.", "Medidas de coordinación con las entidades locales representadas por la Federación Española de Municipios y Provincias.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 49, "El Convenio europeo para la protección de los derechos humanos y de las libertades fundamentales, más conocido como la Convención europea de derechos humanos (CEDH), establece una prohibición general de discriminación, entre otros, por razones de sexo en relación con:", "El disfrute de algunos de los derechos laborales", "El disfrute de todos los derechos reconocidos por ley", "El disfrute de derechos del ámbito público", "El disfrute de algunos derechos reconocidos por ley"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 50, "El Convenio del Consejo de Europa sobre prevención y lucha contra la violencia contra las mujeres y la violencia doméstica establece como delito todas las formas de violencia contra la mujer. Esto implica para los estados miembros que:", "Pueden desarrollar estos delitos en sus sistemas jurídicos", "Ya no es necesario que introduzcan estos delitos en sus sistemas jurídicos", "Pueden introducir estos delitos en sus sistemas jurídicos.", "Deben introducir estos delitos en sus sistemas jurídicos"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 51, "La Convención sobre la eliminación de todas las formas de discriminación contra la mujer, aprobada por la Asamblea General de Naciones Unidas en diciembre de 1979, proclama el principio de igualdad de mujeres y hombres. En su art. 2 los miembros se comprometen a:", "Asegurar por ley u otros medios apropiados la realización práctica de este principio", "Instruir por ley u otros medios apropiados la realización de este principio", "Asegurar por ley u otros medios apropiados la valoración práctica de este principio", "Instruir por los medios que se consideren apropiados la realización teórica de este principio."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 52, "El Tratado de Amsterdam formaliza el objetivo marcado explícitamente de que todas las actividades de la Unión Europea deben dirigirse a:", "Eliminar las desigualdades y promover la igualdad entre personas diferentes.", "Denunciar las desigualdades y promover la igualdad entre hombres y mujeres", "Eliminar las desigualdades y promover la igualdad entre hombres y mujeres.", "Evaluar las desigualdades existentes entre hombres y mujeres y promover la igualdad social."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 53, "El Convenio del Consejo de Europa sobre prevención y lucha contra la violencia contra las mujeres y la violencia doméstica establece que se entenderán por @violencia doméstica@:", "Todos los actos de violencia física, sexual, psicológica o económica que se producen en la familia o en el hogar o entre cónyuges o parejas de hecho antiguos o actuales, independientemente de que el autor del delito comparta o haya compartido el domicilio con la víctima.", "Todos los actos de violencia física, sexual, psicológica o económica que se producen en la familia o en el hogar o entre cónyuges o parejas de hecho actuales, independientemente de que el autor del delito comparta o haya compartido el domicilio con la víctima.", "Todos los actos de violencia física, sexual, psicológica o económica que se producen en la familia o en el hogar o entre cónyuges o parejas de hecho antiguos o actuales cuando el autor del delito comparta o haya compartido el domicilio con la víctima.", "Todos los actos de violencia física, sexual, psicológica o económica que se producen en la familia entre cónyuges o parejas de hecho actuales, independientemente de que el autor del delito comparta o haya compartido el domicilio con la víctima."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 54, "El objetivo de la Directiva (UE) 2019/1158 del Parlamento Europeo y del Consejo, de 20 de junio de 2019, relativa a la conciliación de la vida familiar y la vida profesional de los progenitores y cuidadores es:", "Establecer requisitos mínimos destinados a alcanzar la igualdad entre hombres y mujeres con respecto a las oportunidades en el mercado laboral y en el trato al trabajo, facilitando a todos los trabajadores la conciliación de la vida personal.", "Establecer una serie de normas de obligado cumplimiento destinadas a alcanzar la igualdad entre todos los hombres con respecto a las oportunidades en el mercado laboral y en el trato al trabajo, facilitando a los trabajadores que sean progenitores o cuidadores la conciliación de la vida familiar y profesional.", "Establecer requisitos mínimos destinados a alcanzar la igualdad entre hombres y mujeres con respecto a las oportunidades en el mercado laboral y en el trato al trabajo, facilitando a los trabajadores que sean progenitores o cuidadores la conciliación de la vida familiar y profesional.", "Establecer una serie de normas de obligado cumplimiento destinadas a alcanzar la igualdad entre hombres y mujeres con respecto a las oportunidades en el mercado laboral y en el trato al trabajo, facilitando a los trabajadores que sean progenitores o cuidadores la conciliación de la vida familiar y profesional"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 55, "El Convenio del Consejo de Europa sobre prevención y lucha contra la violencia contra las mujeres y la violencia doméstica establece que se entiende por @violencia contra la mujer por razones de género@:", "Toda violencia contra una mujer porque es una mujer y que afecta a las mujeres de manera proporcionada.", "Toda violencia contra una mujer porque es una mujer y que afecta a las mujeres de manera desproporcionada.", "La violencia física y psíquica contra una mujer porque es una mujer o que afecta a las mujeres de manera desproporcionada.", "Toda violencia contra una mujer porque es una mujer o que afecta a las mujeres de manera desproporcionada."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 56, "¿Cuál de los siguientes no es un objetivo del Convenio del Consejo de Europa sobre prevención y lucha contra la violencia contra las mujeres y la violencia doméstica?:", "Proteger a las mujeres contra todas las formas de violencia y prevenir, y perseguir y eliminar la violencia contra la mujer y la violencia doméstica.", "Contribuir a eliminar toda forma de discriminación contra la mujer y promover la igualdad real entre mujeres y hombres, incluyendo el empoderamiento de las mujeres.", "Concebir un sistema penal específico, sistemas de detección y de medidas de asistencia legal a todas las víctimas de violencia contra la mujer y la violencia doméstica.", "Dar apoyo a las organizaciones y las fuerzas y cuerpos de seguridad para cooperar de manera eficaz para adoptar un enfoque integrado con vistas a eliminar la violencia contra la mujer y la violencia doméstica."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 57, "Señalad cuál de los enunciados siguientes es falso:", "La Constitución española propugna como valores superiores de su ordenamiento jurídico la libertad, la justicia, la igualdad y el pluralismo político.", "La Constitución española establece que todos los españoles son iguales ante la ley, sin que pueda prevalecer discriminación alguna por razón de nacimiento, raza, sexo, religión, opinión o cualquier otra condición o circunstancia personal o social.", "La Constitución española ordena la sucesión al trono siguiendo el orden regular de primogenitura y representación, y será preferida siempre la línea anterior a las posteriores; en la misma línea, el grado más próximo al más remoto; en el mismo grado, la persona mayor, y en la misma edad, el hombre a la mujer.", "La Constitución española dicta que el hombre y la mujer tienen derecho a contraer matrimonio con plena igualdad jurídica."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 58, "La finalidad de las medidas de protección integral establecidas por la Ley orgánica 1/2004, de 28 de diciembre, de medidas de protección integral contra la violencia de género es:", "Prevenir, sancionar y erradicar la violencia de género y prestar asistencia a las mujeres, a sus hijos menores y a los menores sujetos a su tutela, o guarda y custodia, que la sufran.", "Evaluar, sancionar y erradicar las desigualdades acaecidas por razón de género, y prestar asistencia a las mujeres, a sus hijos menores y a los menores sujetos a su tutela, o guarda y custodia, que la sufran.", "Prevenir, sancionar y erradicar la violencia de género y prestar asistencia a las mujeres, a sus hijos y a los menores sujetos a su tutela, o guarda y custodia, que la sufran.", "Evaluar, estructurar y erradicar la violencia de género y prestar asistencia a las mujeres, a sus hijos y a los menores sujetos a su tutela, o guarda y custodia, que la sufran."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 59, "De acuerdo con la Ley orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres, la igualdad de trato y de oportunidades entre mujeres y hombres es un principio informador del ordenamiento jurídico y como tal:", "Debe integrarse y observarse en la aplicación de las normas jurídicas", "Se puede integrar y observar en la interpretación y aplicación de las normas jurídicas.", "Debe integrarse y observarse en la interpretación y aplicación de las normas jurídicas.", "Se debe integrar y observar en la interpretación y aplicación de las sentencias"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 60, "¿Qué se considera discriminación indirecta por razón de sexo?:", "La situación en que se encuentra una persona que sea, haya sido o pueda ser tratada, teniendo en cuenta su sexo, de manera menos favorable que otra en situación comparable.", "La situación en que una disposición, un criterio o una práctica aparentemente neutras pone a personas de un sexo en desventaja particular respecto de personas del otro sexo, salvo que esta disposición, criterio o práctica se pueda justificar objetivamente en atención a una finalidad legítima y que los medios para alcanzar esta finalidad sean necesarios y adecuados.", "La situación en que se encuentra una persona que sea, haya sido o pueda ser tratada, sin tener en cuenta su sexo, de manera menos favorable que otra en situación comparable.", "La situación en que una disposición, un criterio o una práctica aparentemente neutras pone a personas de diferentes sexos en desventaja particular respecto de personas de los otros sexos, teniendo en cuenta que esta disposición, criterio o práctica se pueda justificar objetivamente en atención a una finalidad legítima y que los medios para alcanzar esta finalidad sean necesarios y adecuados."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 61, "¿Cuál es el órgano responsable de adoptar planes y programas conjuntos de actuación para que la AGE y las administraciones de las comunidades autónomas cooperen para integrar el derecho de igualdad entre mujeres y hombres en el ejercicio de las competencias respectivas?:", "La Conferencia Sectorial de la Mujer.", "El Instituto de la Mujer.", "El Observatorio Estatal de Igualdad.", "La Conferencia Estatal de la Mujer."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 62, "¿Cuál de estas acciones no se prevé como un deber de las administraciones públicas, en el ámbito de las competencias respectivas y en aplicación del principio de igualdad entre mujeres y hombres?:", "Remover los obstáculos que implican la pervivencia de cualquier tipo de discriminación con el fin de ofrecer condiciones de igualdad efectiva entre mujeres y hombres al acceso al empleo público y en el desarrollo de la carrera profesional.", "Facilitar la conciliación de la vida personal, familiar y laboral, sin detrimento de la promoción profesional.", "Fomentar la formación en igualdad, tanto en el acceso al empleo público como a lo largo de la carrera profesional.", "Promover la presencia equilibrada de mujeres de todas las edades en los órganos de selección y valoración."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 63, "¿En qué casos no es necesario que se adjunte un informe de impacto de género a la aprobación de convocatorias de pruebas selectivas para el acceso al empleo público?:", "Si se trata de profesiones neutras", "En casos de urgencia y siempre sin perjuicio de la prohibición de discriminación por razón de sexo", "En casos en que en convocatorias similares ya haya cualquier prohibición de discriminación por razón de sexo.", "En casos de urgencia, si no hay una prohibición de discriminación por razón de sexo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 64, "¿En qué casos se puede establecer en las bases de los concursos para la provisión de puestos de trabajo que el tiempo de excedencia por cuidado de un hijo se compute a efectos de valoración del trabajo desarrollado y de los méritos correspondientes?:", "En cualquier caso.", "Cuando el aspirante sea una mujer", "Cuando el aspirante sea un hombre", "En cualquier caso, si se trata de una familia monoparental."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 65, "¿Cuáles de estos principios es imperativo en un protocolo de actuación para la prevención del acoso sexual y del acoso por razón de sexo de una administración pública?:", "El compromiso político de prevenir y no tolerar el acoso sexual y el acoso por razón de sexo.", "La instrucción a todo el personal sobre su deber de respetar la dignidad de las personas y el derecho a la intimidad, así como la igualdad de trato entre mujeres y hombres.", "El tratamiento público de las denuncias de hechos que puedan constituir acoso sexual o acoso por razón de sexo, sin perjuicio de lo que establece la normativa de régimen disciplinario.", "El anonimato de las personas responsables de atender a quienes formulan una queja o denuncia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 66, "¿Cuál es el objetivo de las acciones de responsabilidad social en materia de igualdad que pueden realizar las empresas?:", "Promover condiciones de igualdad entre las mujeres y los hombres en el seno de la empresa o en su entorno social.", "Velar para que se cumplan las condiciones de igualdad entre las mujeres y los hombres implantadas por la administración de cada comunidad autónoma en el seno de la empresa o en su entorno social.", "Promover condiciones de igualdad para las mujeres en el seno de la empresa o en su entorno social.", "Concertar con la comunidad autónoma condiciones de igualdad entre las mujeres y los hombres en el seno de la empresa o en su entorno social."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 67, "¿Qué es el Consejo de Participación de la Mujer?:", "Es una secretaría general de consulta, vigilancia y asesoramiento, con la finalidad esencial de participar mediante diferentes vías en la consecución efectiva del principio de igualdad de trato.", "Es una secretaría general de consulta y asesoramiento, con la finalidad esencial de servir de vía para la participación de las mujeres en la consecución efectiva del principio de igualdad de trato y de oportunidades entre mujeres y hombres, y de luchar contra la discriminación por razón de sexo.", "Es un órgano colegiado de consulta, asesoramiento y vigilancia, con la finalidad esencial de servir de vía para la participación de las mujeres en la consecución efectiva del principio de igualdad de trato y de oportunidades entre mujeres y hombres, y de luchar contra la discriminación por razón de sexo.", "Es un órgano colegiado de consulta y asesoramiento, con la finalidad esencial de servir de vía para la participación de las mujeres en la consecución efectiva del principio de igualdad de trato y de oportunidades entre mujeres y hombres, y de luchar contra la discriminación por razón de sexo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 68, "¿De acuerdo con la Ley 11/2016, del 28 de julio, de igualdad de mujeres y hombres, ¿qué requisito tienen que tener las empresas para obtener los beneficios derivados de la elaboración de un plan de igualdad?:", "El visado previo del Gobierno de las Islas Baleares, en los términos establecidos reglamentariamente.", "El visado previo de la Inspección de Trabajo, en los términos establecidos reglamentariamente.", "El visado previo del Instituto Balear de la Mujer, en los términos establecidos reglamentariamente.", "El visado previo del Observatorio para la Igualdad de las Islas Baleares, en los términos establecidos reglamentariamente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 69, "¿Cuáles de estas medidas tienen que incluir las normas que regulan los procesos selectivos de acceso, provisión y promoción en la ocupación pública, sin perjuicio otros que se consideren oportunas?:", "Una cláusula por la cual, si hay igualdad de capacitación, se dé prioridad a las mujeres en los cuerpos, las escalas, los niveles y las categorías de la Administración en que su representación sea inferior al 40%, salvo que se den en otro candidato circunstancias que no sean discriminatorias por razón de sexo y que justifiquen la no aplicación de la medida.", "Una cláusula por la cual, si hay igualdad de capacitación, se dé prioridad a las mujeres en los cuerpos, las escalas, los niveles y las categorías de la Administración en que su representación sea inferior al 60%, salvo que se den en otro candidato circunstancias que no sean discriminatorias por razón de sexo y que justifiquen la no aplicación de la medida.", "Una cláusula por la cual, si hay igualdad de capacitación, se dé prioridad a las mujeres en los cuerpos, las escalas, los niveles y las categorías de la Administración en que su representación sea inferior al 40%, a pesar de que se den en otro candidato circunstancias discriminatorias diferentes a las que sean por razón de sexo.", "Una cláusula por la cual, si hay igualdad de capacitación, se dé prioridad a las mujeres en los cuerpos, las escalas, los niveles y las categorías de la Administración en que su representación sea inferior al 60%, a pesar de que se den en otro candidato circunstancias discriminatorias diferentes a las que sean por razón de sexo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 70, "¿Cuáles de estas características tienen que tener los planes de igualdad del personal al servicio de las administraciones públicas de las Islas Baleares?:", "Tienen que tener una vigencia mínima de cuatro años, se tienen que evaluar cada dos años y, si procede, tienen que establecer medidas correctoras.", "Tienen que tener una vigencia máxima de cuatro años, se tienen que evaluar cada dos años y, si procede, tienen que establecer medidas correctoras.", "Tienen que tener una vigencia máxima de cuatro años, se tienen que evaluar cada dos años y se tienen que establecer medidas correctoras", "Tienen que tener una vigencia mínima de cuatro años, se tienen que evaluar cada dos años y se tienen que establecer medidas correctoras."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 71, "¿De qué instrumentos disponen las administraciones públicas para evitar el acoso sexual y el acoso por razón de sexo?:", "Protocolos de actuación que contienen las medidas de prevención y protección necesarias ante las consecuencias derivadas de estas modalidades de acoso.", "Protocolos de detección que contienen las medidas para obtener la información y la protección necesarias ante las consecuencias derivadas de estas modalidades de acoso.", "Protocolos de actuación que contienen las medidas de prevención y protección necesarias ante las consecuencias derivadas del acoso laboral.", "Protocolos de detección que contienen las medidas para obtener la información y la protección necesarias ante las consecuencias derivadas del acoso laboral."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 72, "¿Cuáles de estas opciones no concuerda con las definiciones de violencia machista recogidas a la Ley 11/2016, del 28 de julio, de igualdad de mujeres y hombres?:", "Violencia simbólica: violencia que incluye iconos, representaciones, narrativas, imágenes, etc. que reproducen o transmiten relaciones de dominación de los hombres respecto de las mujeres, así como desigualdades de poder entre sexos y de segregación.", "Mutilación genital femenina: cualquier procedimiento que implica o puede implicar una eliminación total o parcial de los genitales femeninos o  produce lesiones, aunque haya consentimiento expreso o tácito de la mujer o de la muñeca.", "Feminicidio: asesinato de mujeres por el hecho de ser mujeres, siempre que haya habido relación de pareja.", "Violencia económica: violencia que incluye la privación intencionada, y no justificada legalmente, de recursos para el bienestar físico o psicológico de las mujeres y de las hijas y los hijos o la discriminación en la disposición de los recursos compartidos en el ámbito de la convivencia de pareja."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 73, "¿Cuáles de las siguientes informaciones se tiene que tener en cuenta para llevar a cabo un estudio cuantitativo de la situación en materia de igualdad de género en la hora de elaborar un plan de igualdad?:", "Movimientos del personal de los últimos tres años: incorporaciones de excedencias y bajas, incorporaciones de personal temporal, incorporaciones del último año por tipo de contrato, incorporaciones por categorías y bajas definitivas.", "Características de la ordenación del tiempo de trabajo y conciliación de la representación legal de los trabajadores y trabajadoras.", "Promoción y carrera: qué tiempos se ha tardado a promocionar dependiente del género.", "Formación: número de cursos hechos por el personal los últimos tres años y de qué tipo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 74, "¿Cuáles de estas acciones no se prevé como herramienta de capacitación en materia de igualdad del personal al servicio de las administraciones públicas?:", "Establecer requisitos específicos de conocimiento en materia de igualdad para acceder a lugares que tenguin, entre otras, las funciones de impulsar y diseñar programas de igualdad de oportunidades y de dar asesoramiento técnico en materia de igualdad entre mujeres y hombres.", "Establecer programas específicos de actualización y reciclaje del personal adscrito a los organismos responsables en materia de igualdad, que se tienen que llevar a cabo preferentemente en horario laboral y que en este caso son obligatorios.", "Incluir contenidos relativos en la legislación de igualdad de mujeres y hombres y su aplicación a la actividad administrativa en los temarios de los procesos de selección para el acceso a la función pública.", "Incentivar miembros de los diferentes equipos de trabajo con conocimientos demostrados en materia de igualdad porque actúen desde su lugar de trabajo como apoyo para supervisar la implantación de las diferentes medidas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 18, 75, "¿En qué modo las administraciones públicas tienen que impulsar la transversalització de género en el marco de sus competencias?:", "Como instrumento para integrar la perspectiva de género en el diseño, la ejecución, el seguimiento y la evaluación de las políticas de ocupación que se desarrollen en las Islas Baleares, incluyendo, si procede, las medidas específicas y necesarias.", "Como instrumento para integrar la perspectiva de género en el diseño, la ejecución, el seguimiento y la evaluación de las políticas de ocupación que se desarrollen en las Islas Baleares, incluyendo , si procede, las medidas específicas y necesarias", "Como obligación para integrar la perspectiva de género en el diseño, la ejecución, el seguimiento y la evaluación de las políticas de ocupación que se desarrollen en las Islas Baleares, incluyendo , si procede, las medidas específicas y necesarias", "Como instrumento para valorar la perspectiva de género en el diseño, la ejecución, el seguimiento y la evaluación de las políticas de ocupación que se desarrollen en las Islas Baleares, incluyendo , si procede, las medidas específicas y necesarias"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 1, "¿Quién dirige la acción del Gobierno y coordina las funciones de los demás miembros del Gobierno:", "El ministro de la Presidencia.", "El presidente del Gobierno.", "El Consejo de ministros.", "La Comisión General de Secretarios de Estado y Subsecretarios."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 2, "El Gobierno ejerce:", "La función legislativa y la potestad reglamentaria de acuerdo con la Constitución y las leyes.", "La función ejecutiva y la potestad legislativa de acuerdo con la Constitución y las leyes.", "La función ejecutiva y la potestad reglamentaria de acuerdo con la Constitución y las leyes.", "La función ejecutiva y la potestad reglamentaria y administrativa de acuerdo con la Constitución y las leyes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 3, "El candidato a la Presidencia del Gobierno lo propone:", "El presidente del Congreso, previa consulta al rey y a los representantes designados por los grupos políticos con representación parlamentaria.", "El presidente del Congreso, previa consulta con los representantes designados por los grupos políticos con representación parlamentaria.", "El rey, previa consulta con los portavoces de los grupos políticos que concurrieron a las elecciones.", "El rey, previa consulta con los representantes designados por los grupos políticos con representación parlamentaria."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 4, "El candidato a la Presidencia del Gobierno propuesto conforme a lo previsto en el artículo 99.1 de la Constitución:", "Expondrá al rey el programa político del Gobierno que pretenda formar.", "Expondrá ante las Cortes Generales el programa político del Gobierno que pretenda formar.", "Expondrá al Congreso de los Diputados el programa político del Gobierno que pretenda formar.", "Expondrá ante las Mesas de las Cámaras el programa político del Gobierno que pretenda formar."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 5, "El candidato a la Presidencia del Gobierno propuesto conforme a lo previsto en el artículo 99.1 de la Constitución:", "Solicitará la confianza del pueblo español.", "Solicitará la confianza de las Cortes Generales.", "Solicitará la confianza del Congreso de los Diputados.", "Solicitará la confianza de su Grupo Parlamentario."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 6, "En segunda votación, a tenor de lo previsto en el artículo 99 de la Constitución, la confianza al candidato a la Presidencia del Gobierno se entiende otorgada:", "Con la mayoría absoluta de los miembros del Congreso de los Diputados.", "Con la mayoría simple de los miembros del Congreso de los Diputados.", "Con la mayoría de dos tercios de los miembros del Congreso de los Diputados.", "Con la mayoría de tres quintos de los miembros del Congreso de los Diputados."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 7, "Si en segunda votación el candidato a la Presidencia del Gobierno no obtiene la confianza del Congreso de los Diputados:", "El rey nombrará presidente del Gobierno al representante del Grupo Parlamentario con mayor representación en el Congreso de los Diputados.", "Se disolverán las Cámaras y se procederá a la convocatoria de nuevas elecciones.", "Se tramitarán sucesivas propuestas en la forma prevista en la Constitución.", "Se procederá a una tercera y última votación, entendiéndose otorgada la confianza si obtiene la mayoría de los votos de los miembros presentes del Congreso de los Diputados."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 8, "Los miembros del Gobierno distintos del presidente son nombrados y separados:", "Por el presidente del Congreso de los Diputados.", "Por el rey.", "Por el presidente del Gobierno.", "Por el Consejo de ministros."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 9, "Conforme al artículo 101 de la Constitución, el Gobierno cesa:", "Por incapacidad de su presidente.", "Tras la convocatoria de elecciones generales.", "Tras la celebración de elecciones generales.", "Tras la proclamación de los resultados electorales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 10, "En el ejercicio de sus funciones, la acusación por traición o por cualquier delito contra la seguridad del Estado de los miembros del Gobierno:", "Deberá ser aprobada por la mayoría absoluta de las Cortes Generales.", "Deberá ser aprobada por la mayoría absoluta del Congreso de los Diputados.", "Deberá ser planteada por la mayoría absoluta de las Cortes Generales.", "Deberá ser aprobada por la mayoría simple del Congreso de los Diputados."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 11, "Conforme el artículo 103 de la Constitución, la Administración Pública sirve los intereses  generales:", "Con tolerancia.", "Con eficiencia.", "Con objetividad.", "Con eficacia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 12, "La Administración Pública actúa:", "Con sometimiento pleno a la Constitución, a la ley y al Derecho.", "Con sometimiento pleno a la ley y al Derecho.", "Con sometimiento único a la ley y al Derecho.", "Con sometimiento pleno a la Constitución."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 13, "Según el artículo 103 de la Constitución, se regularán por ley:", "El régimen de nombramientos de los funcionarios públicos.", "Todas las respuestas son correctas.", "Las peculiaridades del régimen sanitario del personal laboral.", "El sistema de incompatibilidades y las garantías para la imparcialidad en el ejercicio de sus funciones de los funcionarios públicos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 14, "Las Fuerzas y Cuerpos de Seguridad tienen como misión:", "Garantizar la soberanía e independencia de la Nación.", "Garantizar la seguridad de las instituciones.", "Todas las respuestas son correctas.", "Proteger el libre ejercicio de los derechos y libertades."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 15, "Señala la respuesta correcta. Conforme al artículo 105 de la Constitución, la ley regulará:", "El procedimiento, a través del cual deben producirse los actos administrativos, garantizando, cuando proceda, la audiencia al interesado.", "El procedimiento, a través del cual deben producirse los actos administrativos, garantizando, en todo caso, la audiencia al interesado.", "El procedimiento, a través del cual deben producirse los actos legislativos, garantizando, en todo caso, la audiencia al interesado.", "El procedimiento, a través del cual deben producirse los actos que afecten a los ciudadanos, garantizando, cuando proceda la audiencia al interesado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 16, "Señala la respuesta correcta. Conforme al artículo 105 de la Constitución, la ley regulará:", "La audiencia de los ciudadanos y empresarios en el procedimiento de elaboración de las disposiciones administrativas que les afecten.", "La audiencia de los ciudadanos, directamente o a través de las organizaciones y asociaciones reconocidas por la ley en el procedimiento de elaboración de las disposiciones administrativas que les afecten.", "La audiencia de los ciudadanos en el procedimiento de elaboración de todo tipo de disposiciones administrativas.", "La audiencia de los empresarios en el procedimiento de elaboración de las disposiciones administrativas que les afecten."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 17, "La ley regulará el acceso de los ciudadanos a los archivos y registros administrativos:", "Salvo en lo que afecte a la seguridad y defensa del Estado.", "Salvo en lo que afecte a la averiguación de los delitos.", "Salvo en lo que afecte a la intimidad de las personas.", "Todas las respuestas anteriores son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 18, "¿Quiénes tendrán derecho a ser indemnizados por toda lesión que sufran en cualquiera de sus bienes y derechos como consecuencia del funcionamiento de los servicios públicos?:", "Los ciudadanos.", "Los particulares.", "Los ciudadanos y las empresas.", "Los funcionarios públicos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 19, "Los particulares tendrán derecho a ser indemnizados por toda lesión que sufran en cualquiera de sus bienes y derechos como consecuencia del funcionamiento de los servicios públicos:", "En los términos establecidos por una ley orgánica.", "Mediante la correspondiente reclamación.", "Salvo en los casos de fuerza mayor.", "Todas las respuestas anteriores son correctas."); 
