insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 35, "¿Quién preside el Consejo de ministros?", "El ministro de la Presidencia.", "El presidente del Gobierno.", "El presidente del Gobierno, salvo en los supuestos de presencia del rey.", "El ministro de la Presidencia, en ausencia del presidente del Gobierno."); 
