insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 38, "Al Consejo de ministros le corresponde, según la Ley 50/1997, de 27 de noviembre, del Gobierno:", "Resolver los conflictos de atribuciones que puedan surgir entre los diferentes Ministerios.", "Crear, modificar y suprimir los órganos directivos de los Departamentos Ministeriales.", "Crear, modificar y suprimir, por Real Decreto, los Departamentos Ministeriales y las Secretarías de Estado.", "Proponer al rey la convocatoria de un referéndum consultivo, previa autorización del Congreso de los Diputados."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 39, "Los Reales Decretos-leyes los aprueba:", "El Consejo de ministros.", "El Consejo de ministros, previa autorización del Congreso de los Diputados.", "El Consejo de ministros, previa autorización de las Cortes Generales.", "El Consejo de ministros, previa delegación del Congreso de los Diputados."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 40, "Según dispone el artículo 26 de la Ley 50/1997, la Memoria del Análisis de Impacto Normativo, en el procedimiento de elaboración de normas con rango de Ley y de los reglamentos, incluirá:", "El impacto por razón de género.", "El impacto sobre los derechos de la infancia.", "El análisis sobre la adecuación de la norma aprobada al orden legalmente establecido en base a criterios nacionales e internacionales.", "Todas las respuestas anteriores son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 41, "Según el artículo 26.6 de la Ley 50/1997, del Gobierno, en el procedimiento de elaboración de reglamentos, el trámite audiencia a los ciudadanos será no inferior a:", "Veinte días naturales.", "Quince días hábiles.", "Quince días naturales.", "Veinte días hábiles."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 42, "En relación con la Comisión General de Secretarios de Estado y Subsecretarios:", "Está integrada por los titulares de las Secretarías de Estado y de los órganos que tengan rango de Subsecretario.", "Su presidencia corresponde al Director de Gabinete del presidente del Gobierno", "No puede adoptar decisiones propuestas por las delegaciones del Gobierno en las comunidades autónomas.", "Es un órgano de gobierno cuyo objeto es resolver los asuntos que, afectando a más de un Ministerio, no requieren ser elevados al Consejo de ministros."); 
