insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 44, "Según el artículo 4 de la Ley 50/1997, de 27 de noviembre, del Gobierno, los ministros sin cartera:", "Se les atribuirá la responsabilidad de determinadas funciones gubernamentales.", "Asumirán el cargo de vicepresidente.", "No son miembros del Gobierno.", "Dependen orgánicamente de la Presidencia del Gobierno y funcionalmente del Ministerio al que figuran adscritos."); 
