insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 46, "Según la Ley 50/1997, del Gobierno, las disposiciones de entrada en vigor de las leyes o reglamentos, cuya aprobación o propuesta corresponda al Gobierno o a sus miembros, y que impongan nuevas obligaciones a las personas físicas o jurídicas que desempeñen una actividad económica o profesional como consecuencia del ejercicio de ésta, preverán el comienzo de su vigencia el 2 de enero o el 1 de julio siguientes a su aprobación. Lo previsto anteriormente:", "No será de aplicación cuando el cumplimiento del plazo de transposición de directivas europeas así lo aconsejen.", "No será de aplicación a los reales decretos leyes.", "Todas las respuestas son correctas.", "No será de aplicación cuando razones justificadas así lo aconsejen."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 47, "Los Directores de los Gabinetes del presidente, de los vicepresidentes y de los ministros serán nombrados:", "Por Real Decreto aprobado en Consejo de ministros.", "Por el presidente del Gobierno.", "Por Orden Ministerial.", "Por el rey, a propuesta del presidente del Gobierno."); 
