insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 50, "Según el artículo 3 de la Ley 50/1997, del Gobierno, el vicepresidente que asuma la titularidad de un Departamento Ministerial:", "No podrá ostentar la condición de ministro.", "Ostentará, además, la condición de ministro.", "Podrá, excepcionalmente, asumir la condición de ministro de la Presidencia.", "Podrá, excepcionalmente, asumir la condición de ministro de Administraciones Públicas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 51, "Según la Ley 50/1997, del Gobierno, entre las funciones del Secretariado del Gobierno no se encuentra:", "Velar por la correcta publicación de las disposiciones y normas emanadas del Gobierno que deban insertarse en el Boletín Oficial del Estado", "La colaboración con las Secretarías Técnicas de las Comisiones Delegadas del Gobierno.", "La asistencia al ministro-Secretario del Consejo de ministros.", "Asistir a los Ministerios en el control de su eficacia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 52, "Conforme dispone la Ley 50/1997, del Gobierno:", "Los conflictos de atribuciones entre Ministerios se resuelven por Acuerdo del Consejo de ministros.", "Los Secretarios de Estado son miembros del Gobierno.", "La Comisión General de Secretarios de Estado y Subsecretarios estará integrada por los titulares de las Secretarías de Estado y por los Subsecretarios de los diferentes Departamentos Ministeriales.", "Los vicepresidentes, cuando existan, no pueden ostentar simultáneamente la condición de ministros."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 53, "De su gestión política, el Gobierno responde:", "Individualmente ante las Cámaras.", "Solidariamente ante las Cortes Generales.", "Solidariamente ante el Congreso de los Diputados.", "Mancomunadamente ante las Cortes Generales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 54, "Según el artículo 109 de la Constitución podrán recabar la información y ayuda que precisen del Gobierno y de sus Departamentos:", "Únicamente el Congreso de los Diputados y sus Comisiones.", "Únicamente, las Cámaras y sus Comisiones.", "Únicamente las Cámaras.", "Únicamente el Senado y sus Comisiones."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 55, "En relación con los miembros del Gobierno y según el texto del artículo 110 de la Constitución Española:", "Tienen la facultad de hacerse oír en las Cámaras y sus Comisiones.", "Sólo tienen la facultad de hacerse oír en las Cámaras pero no en sus Comisiones.", "No podrán solicitar que informen ante las Cámaras el personal funcionario de sus Departamentos.", "Tienen derecho a voto en las Cámaras y en las Comisiones."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 56, "El Gobierno estará sometido a las interpelaciones y preguntas que se le formulen en las Cámaras. Para esta clase de debate:", "Los Reglamentos establecerán un tiempo mínimo en cada Sesión.", "Los Reglamentos establecerán un tiempo mŽínimo mensual.", "Los Reglamentos establecerán un tiempo mínimo semanal.", "Los Reglamentos establecerán un tiempo mínimo por cada período de sesiones."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 57, "¿Quién puede plantear la cuestión de confianza, conforme al artículo 112 de la Constitución?:", "El presidente del Gobierno, previa deliberación del Consejo de Estado.", "El presidente del Gobierno, previa deliberación del Consejo de ministros.", "El Consejo de ministros, a través del presidente del Gobierno.", "El presidente del Gobierno, bajo su exclusiva responsabilidad."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 58, "El presidente del Gobierno puede plantear la cuestión de confianza:", "Sobre una situación política especial.", "Sobre una declaración de política especial.", "Sobre una declaración de política general.", "Sobre un asunto de interés público."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 59, "De acuerdo con el artículo 113 de la Constitución, la moción de censura deberá incluir:", "Los candidatos a ocupar todos los Ministerios.", "Los candidatos a ocupar los puestos de vicepresidente o vicepresidentes, si existieran.", "Un candidato a la Presidencia del Gobierno.", "Todas las respuestas anteriores son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 60, "De acuerdo con la Constitución, la moción de censura será votada:", "No antes de que transcurran tres días desde su presentación.", "A los cinco días de su presentación.", "No antes de que transcurran cinco días desde su presentación.", "A los tres días de su presentación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 61, "¿Qué ocurre si una moción de censura no fuera aprobada por el Congreso?:", "Sus signatarios no podrán presentar otra durante el mismo período de sesiones.", "Sus signatarios no podrán presentar otra durante la misma legislatura.", "No se podrá presentar otra durante el mismo período de sesiones.", "No se podrá presentar otra durante la misma legislatura."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 62, "Señala la respuesta correcta. Si el Congreso de los Diputados adopta una moción de censura:", "El candidato incluido en la moción de censura se entenderá investido de la confianza de la Cámara a los efectos previstos en el artículo 99.", "El Gobierno presentará su dimisión al rey.", "Todas las respuestas son correctas.", "El rey nombrará presidente del Gobierno al candidato incluido en la moción de censura."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 63, "¿Quién puede decretar la disolución del Congreso, del Senado o de las Cortes Generales, de acuerdo con el artículo 115 de la Constitución?:", "El presidente del Gobierno, previa deliberación del Consejo de ministros.", "El rey.", "El presidente del Gobierno, bajo su exclusiva responsabilidad.", "El Consejo de ministros, a propuesta del presidente del Gobierno."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 64, "Señala la respuesta correcta. En relación con la disolución del Congreso, del Senado o de las Cortes Generales del artículo 115 de la Constitución:", "No procederá una nueva disolución antes de que transcurra un año desde la anterior, salvo lo dispuesto en el artículo 99.5 o durante la vigencia de los estados de alarma, excepción o de sitio.", "En ningún caso procederá nueva disolución hasta que transcurra  antes de que transcurra un año desde la anterior.", "No procederá una nueva disolución antes de que transcurra un año desde la anterior, salvo lo dispuesto en el artículo 99.5.", "En ningún caso procederá nueva disolución antes de que transcurran seis meses desde la anterior."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 65, "Los estados de alarma, de excepción y de sitio se regularán mediante una Ley orgánica, así como:", "La suspensión de alguno de los poderes del Estado.", "Las competencias y limitaciones correspondientes.", "Las funciones asumidas por los órganos estatales durante su vigencia.", "Todas las respuestas anteriores son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 66, "El estado de alarma será declarado:", "Por un plazo máximo de veinte días.", "Por un plazo máximo de quince días.", "Por un plazo máximo de diez días.", "Sin plazo máximo de duración."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 67, "El Decreto que acuerde el estado de alarma determinará:", "Los derechos y libertades que quedarán suspendidos durante el tiempo de la declaración.", "El ámbito territorial a que se extienden los efectos de la declaración.", "La autoridad que ejercerá los poderes del Estado en el ámbito territorial afectado.", "Todas las respuestas anteriores son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 68, "La autorización y proclamación del estado de excepción deberá determinar expresamente:", "Los efectos del mismo.", "Todas las respuestas son correctas.", "Su duración.", "El ámbito territorial a que se extiende."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 69, "El estado de sitio será declarado:", "Por la mayoría absoluta del Congreso de los Diputados, a propuesta exclusiva del Gobierno.", "Por la mayoría simple del Congreso de los Diputados, a iniciativa propia.", "Por el Gobierno, a propuesta del Congreso de los Diputados.", "Por la mayoría absoluta del Congreso de los Diputados, a iniciativa propia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 70, "Durante la vigencia de los estados definidos en el artículo 116 de la Constitución:", "El funcionamiento de todos los poderes constitucionales pasará a ser ejercido por el Congreso de los Diputados.", "No podrá interrumpirse el funcionamiento de ambas Cámaras ni el de los demás poderes constitucionales del Estado.", "El funcionamiento de todos los poderes constitucionales pasará a ser ejercido por el Senado.", "El funcionamiento de todos los poderes constitucionales pasará a ser ejercido por las Cortes Generales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 71, "¿Qué órgano tiene competencia para mantener relaciones con las comunidades autónomas y convocar Conferencias Sectoriales?:", "El Delegado del Gobierno.", "El ministro.", "El Secretario de Estado.", "El Subsecretario de Estado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 72, "La Jefatura del Estado, ¿es un órgano de la Administración del Estado?:", "Si, es el órgano supremo.", "No, ya que es ejercida por la Corona.", "Si, pero jerárquicamente depende de la Presidencia del Gobierno.", "No, ya que es un órgano inexistente en la actualidad."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 74, "La creación o modificación de las Comisiones Delegadas del Gobierno se acordará mediante:", "Real Decreto acordado en Consejo de ministros.", "Ley ordinaria.", "Ley orgánica.", "Orden de Comisiones Delegadas de gobierno."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 75, "La representación de un Ministerio, por delegación de un ministro, corresponde:", "Al Subsecretario del Departamento.", "Al Secretario de Estado del Departamento.", "Al Director General del Departamento que designe el ministro.", "Al Secretario General Técnico."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 76, "En la Administración General del Estado, pueden dictar circulares e instrucciones a los inferiores a su Departamento:", "Los Directores Generales.", "Los Subsecretarios.", "Los Secretarios de Estado.", "Todas las respuestas anteriores son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 77, "Señala la respuesta correcta. El Subdelegado del Gobierno, donde exista:", "Asume la representación del Gobierno en el territorio de la Comunidad Autónoma.", "Depende directamente de la Presidencia del Gobierno.", "Es nombrado por un período máximo de dos años entre personas de reconocida competencia profesional.", "Todas las respuestas anteriores son incorrectas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 2, 78, "En las comunidades autónomas uniprovinciales, suple al Delegado del Gobierno en su ausencia:", "El Subdelegado del Gobierno más antiguo.", "El Subdelegado del Gobierno que designe el Delegado del Gobierno.", "El Secretario General si no existe el subdelegado.", "El Director Insular."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 5, 1, "Según el artículo 2 del Estatuto de autonomía de las Illes Balears, el territorio de la comunidad autónoma de las Islas Baleares está formado :", "Por las Islas de Mallorca, Menorca, Ibiza, Formentera y Cabrera.", "Por las Islas de Mallorca, Menorca, Ibiza, Formentera y Cabrera y por el de las otras islas menores adyacentes.", "Por las islas de Mallorca, Menorca, Ibiza y Formentera.", "Por las Islas de Mallorca, Menorca, Ibiza y Formentera y por el de las otras islas menores adyacentes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 5, 2, "Según el artículo 4 del Estatuto de autonomía de las Illes Balears, sobre la lengua propia de las Islas Baleares:", "La lengua catalana, propia de las Islas Baleares, tendrá, juntamente con la castellana, el carácter de idioma oficial.", "Todos tienen el derecho de conocerla y de usarla, y nadie podrá ser discriminado por causa del idioma.", "Las instituciones de las Islas Baleares garantizarás el uso normal y oficial de los dos idiomas.", "Las respuestas a), b) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 5, 3, "Según el artículo 6 del Estatuto de autonomía de las Illes Balears, el día de las Islas Baleares es:", "El 1 de marzo.", "El 2 de marzo.", "El 1 de mayo.", "El 2 de mayo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 5, 4, "Según el artículo 8 del Estatuto de autonomía de las Illes Balears, la comunidad autónoma articula su organización territorial:", "En consejos insulares y ayuntamientos.", "En islas.", "En gobierno balear, consejos insulares y ayuntamientos.", "En islas y municipios."); 
