insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 5, 41, "¿Se puede crear un cuerpo de policía propio de las Islas Baleares?", "No.", "Sí, de acuerdo con la Ley de seguridad pública.", "Sí, de acuerdo con el Estatuto de autonomía de las Illes Balears dependiendo del Ministerio de Interior.", "Sí, de acuerdo con el Estatuto de autonomía de las Illes Balears en el marco de la legislación estatal."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 5, 42, "Según el artículo 33 del Estatuto de autonomía de las Illes Balears, el mando de la policía de las Islas Baleares corresponde:", "A la Comunidad Autónoma.", "Al ayuntamiento de Palma.", "Al ministerio del Interior.", "Al consejo insular."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 5, 43, "Según el artículo 35 del Estatuto de autonomía de las Illes Balears, institución oficial consultiva para todo lo que se refiere a la lengua catalana, corresponde:", "A  la consejería competente en materia de educación.", "A  la consejería competente en materia de cultura.", "A  la dirección general competente en materia lingüística.", "A  la Universidad de las Islas Baleares."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 5, 44, "Según el artículo 37 del Estatuto de autonomía de las Illes Balears, el ejercicio de las competencias de la Comunidad Autónoma:", "Se lleva a cabo bajo el estricto control del Estado.", "Se lleva a cabo de acuerdo con los términos que se disponen en la Constitución.", "Se lleva a cabo con la tutela del Estado.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 5, 45, "Según el artículo 39 del Estatuto de autonomía de las Illes Balears, las instituciones de la Comunidad Autónoma de las Islas Baleares son:", "El Parlamento y el Gobierno.", "El Parlamento, el Gobierno y el presidente de la comunidad autónoma.", "El Parlamento, el Gobierno, el presidente de la comunidad autónoma y los consejos insulares de Mallorca, Menorca, Ibiza y Formentera.", "El Parlamento, el Gobierno, el presidente de la comunidad autónoma y los ayuntamientos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 5, 46, "Según el artículo 35 del Estatuto de autonomía de las Illes Balears, ¿qué institución representa al pueblo de las Islas Baleares?", "El Gobierno.", "El presidente de la comunidad autónoma.", "El presidente del Parlamento.", "El Parlamento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 5, 47, "Según el artículo 35 del Estatuto de autonomía de las Illes Balears, ¿dónde radica la sede del Parlamento de las Islas Baleares?", "En la ciudad de Palma.", "En la isla de Mallorca.", "El Estatuto de autonomía de las Illes Balears no indica dónde radica la sede del Parlamento.", "En la ciudad de Ibiza."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 5, 48, "Según el artículo 41 del Estatuto de autonomía de las Illes Balears, ¿cuándo se constituye el Parlamento después de la celebración de las elecciones?", "Dentro del término máximo de veinte días.", "Dentro del término máximo de treinta días.", "Dentro del término mínimo de veinte días.", "Dentro del término mínimo de treinta días."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 5, 49, "Según el artículo 40 del Estatuto de autonomía de las Illes Balears, ¿qué institución aprueba los presupuestos de la Comunidad Autónoma?", "El Consejo Insular.", "El Gobierno.", "El Parlamento.", "El presidente de la comunidad autónoma."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 5, 50, "Según el artículo 40 del Estatuto de autonomía de las Illes Balears, ¿qué institución controla la acción del gobierno?", "El presidente de la comunidad autónoma.", "El presidente del Parlamento.", "El Gobierno del Estado.", "El Parlamento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 5, 51, "Según el artículo 41 del Estatuto de autonomía de las Illes Balears, ¿cómo son elegidos los diputados del Parlamento?", "Por sistema electoral.", "Por sufragio universal, igual, libre, directo y secreto.", "Mediante un sistema de representación proporcional.", "Las respuestas b) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 5, 52, "Según el artículo 41 del Estatuto de autonomía de las Illes Balears, ¿qué dura el mandato de los diputados del Parlamento?", "Dos años.", "Tres años.", "Cuatro años.", "Cinco años."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 5, 53, "Según el artículo 44 del Estatuto de autonomía de las Illes Balears, ¿qué órgano judicial puede exigir la responsabilidad penal a los diputados del Parlamento de les Illes Balears, en caso de flagrante delito?", "El Tribunal Constitucional.", "El Tribunal Superior de Justícia de les Illes Balears,  dentro del ámbito territorial de la comunidad autònoma.", "La Sala Penal del Tribunal Supremo, fuera del ámbito territorial de la comunidad autónoma.", "El órgano jurisdiccional predeterminado por la ley."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 5, 54, "Según el artículo 45 del Estatuto de autonomía de las Illes Balears, el Parlamento tiene:", "Diputados.", "Un presidente y diputados.", "Un presidente, diputados y una diputación permanente.", "Un presidente, una mesa y una diputación permanente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 5, 55, "Según el artículo 45 del Estatuto de autonomía de las Illes Balears, ¿qué norma regulará la composición y las reglas de elección del Parlamento?", "Un reglamento del Parlamento.", "Una ley ordinaria del Gobierno.", "Un decreto del Gobierno.", "Una ley ordinaria del Estado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 5, 56, "Según el artículo 45 del Estatuto de autonomía de las Illes Balears, el Parlamento funciona:", "En pleno.", "En pleno y con una mesa permanente.", "En pleno y en comisiones.", "En pleno y en comisiones especiales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 5, 57, "Según el artículo 46 del Estatuto de autonomía de las Illes Balears, el presidente de la Diputación Permanente es:", "Un diputado.", "El presidente del Gobierno.", "El presidente del Parlamento.", "El vicepresidente del Parlamento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 5, 58, "Según el artículo 47 del Estatuto de autonomía de las Illes Balears, la iniciativa para el ejercicio de la potestad legislativa corresponde:", "A los diputados.", "Al Gobierno de las Islas.", "Al presidente del Parlamento.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 5, 59, "Según el artículo 48 del Estatuto de autonomía de las Illes Balears, ¿qué órgano ejerce la potestad legislativa?", "El Parlamento.", "El Gobierno de las Islas.", "El consejo insular.", "Las Cortes Generales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 5, 60, "Según el artículo 48 del Estatuto de autonomía de las Illes Balears, las leyes del Parlamento una vez promulgadas en nombre del rey por el presidente de la comunidad autónoma, se ha de ordenar  la publicación:", "En el Boletín Oficial de las Islas Baleares.", "En el Diario Oficial de la Unión Europea.", "En el Boletín Oficial del Estado.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 5, 61, "Según el artículo 49 del Estatuto de autonomía de las Illes Balears, ¿qué norma puede dictar el Consejo de Gobierno en caso de extraordinaria y urgente necesidad?", "Una ley ordinaria.", "Un decreto.", "Un decreto ley.", "Una ley orgánica."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 5, 62, "Según el artículo 49 del Estatuto de autonomía de las Illes Balears, ¿qué materias, entre otras, no pueden ser modificadas mediante un decreto ley?", "Educación y salud.", "La reforma del Estatuto.", "Los presupuestos generales de la Comunidad Autónoma.", "Las respuestas b) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 5, 63, "Según el artículo 50 del Estatuto de autonomía de las Illes Balears, ¿qué órgano designa el senador o senadores que han de representar a la comunidad autónoma de las Islas Baleares en el Senado?", "El Gobierno de les Illes Balears.", "El Parlamento.", "El presidente del Gobierno.", "La Diputación Permanente del Parlamento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 5, 64, "Según el artículo 54 del Estatuto de autonomía de las Illes Balears, ¿quién elige al presidente de las Islas Baleares?", "El rey.", "El Consejo de Gobierno.", "El Parlamento ,de entre sus miembros.", "Los ciudadanos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 5, 65, "Según el artículo 55 del Estatuto de autonomía de las Illes Balears, ¿quién puede acordar la disolución del Parlamento de las Islas Baleares con anticipación al plazo natural de la legislatura?", "El presidente del Gobierno.", "El Consejo de Gobierno.", "El rey.", "El presidente del Parlamento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 5, 66, "Según el artículo 56 del Estatuto de autonomía de las Illes Balears, ¿quién nombra y separa a los miembros que han de formar el Gobierno?", "El rey.", "El presidente del Parlamento.", "El Parlamento.", "El presidente del Gobierno."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 5, 67, "Según el artículo 57 del Estatuto de autonomía de las Illes Balears, ¿qué tipo de funciones ejerce el Gobierno de las Islas Baleares?", "Únicamente funciones ejecutivas.", "Funciones ejecutivas y administrativas.", "Funciones ejecutivas y legislativas.", "Funciones administrativas y legislativas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 5, 68, "Según el artículo 58 del Estatuto de autonomía de las Illes Balears, ¿qué órgano elabora los presupuestos de la Comunidad Autónoma?", "El Gobierno de las Islas Baleares.", "El Parlamento.", "La consejería competente en materia de presupuestos.", "La comisión permanente en materia de presupuestos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 5, 69, "Según el artículo 61 del Estatuto de autonomía de las Illes Balears, ¿cuál es la institución de gobierno de cada una de las Islas?", "El Gobierno de las Islas Baleares.", "Los ayuntamientos.", "Los consejos insulares.", "La Delegación del Gobierno."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 5, 70, "Según el artículo 75 del Estatuto de autonomía de las Illes Balears, ¿cuál es la entidad local básica de la organización territorial de las Islas Baleares?", "La isla.", "La provincia.", "La comunidad autónoma.", "El municipio."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 5, 71, "Según el artículo 76 del Estatuto de autonomía de las Illes Balears, ¿cuál es el órgano superior de consulta de la Comunidad Autónoma de las Islas Baleares?", "El Consejo Consultivo de las Islas Baleares.", "La Abogacía del Gobierno.", "El Consejo Económico y Social.", "La Sindicatura de Cuentas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 5, 72, "Según el artículo 82 del Estatuto de autonomía de las Illes Balears, la Sindicatura de Cuentas será formada:", "Por cinco síndicos.", "Por cuatro síndicos.", "Por tres síndicos.", "Por seis síndicos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 5, 73, "Según el artículo 93 del Estatuto de autonomía de las Illes Balears, el órgano jurisdiccional quel culmina la organización judicial de las Islas Baleares dentro de su ámbito territorial es:", "El Tribunal Superior de Justicia de las Islas Baleares.", "El Tribunal Supremo.", "La Audiencia provincial.", "El Tribunal Constitucional."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 5, 74, "Según el artículo 139 del Estatuto de autonomía de las Illes Balears, ¿a quién corresponde la iniciativa de reforma del Estatuto de autonomía?", "Únicamente al Parlamento.", "Únicamente al Gobierno de la Comunidad Autónoma.", "Únicamente al Parlamento y al Gobierno de la Comunidad Autónoma.", "Al Parlamento, al Gobierno de la Comunidad Autónoma y a las Cortes Generales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 5, 75, "La Ley Orgánica 1/2007, de 28 de febrero, de reforma del Estatuto de autonomía de las Illes Balears consta:", "una exposición de motivos, un preámbulo, siete títulos y disposiciones.", "De una exposición de motivos, un preámbulo, ocho títulos y disposiciones.", "De una exposición de motivos, un preámbulo, nueve títulos y disposiciones.", "De una exposición de motivos, un preámbulo, diez títulos y disposiciones."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 1, "En materia de actuación y funcionamiento del sector público por medios electrónicos, señale la respuesta incorrecta en relación al concepto de registro electrónico:", "Las Administraciones Públicas dispondrán de registros electrónicos para la recepción y remisión de solicitudes, escritos y comunicaciones, que deberán ser plenamente interoperables de manera que se garantice su compatibilidad informática e interconexión en los términos previstos en el artículo 16 de la Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas, y el artículo 60 del Real Decreto 203/2021, de 30 de marzo, por el que se aprueba el Reglamento de actuación y funcionamiento del sector público por medios electrónicos.", "Cada Administración dispondrá de un Registro Electrónico Central en el que hará asiento de todo documento que sea presentado o que se reciba en cualquier órgano administrativo, organismo público o entidad de derecho público vinculado o dependiente.", "Los organismos públicos y entidades de derechos público vinculados o dependientes de cada Administración podrán disponer de su propio registro electrónico plenamente interoperable e interconectado con el Registro Electrónico General de la Administración a la que estén vinculados o de la que dependan.", "Los registros electrónicos admitirám documentos electrónicos normalizados correspondientes a los servicios, procedimientos y trámites que se especifiquen conforme a lo dispuesto en la norma de creación del registro, cumplimentados de acuerdo con formatos preestablecidos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 2, "En materia de registro electrónico, el Registro Electrónico General es:", "Un registro electrónico del que dispondrá cada Administración Pública y en el que se realizará el asiento de cualquier documento que se presente o se reciba en cualquier órgano administrativo de esta administración. Aquellos organismos públicos o entidades de derecho público vinculado o dependiente de esta administración, dispondrán de su propio registro electrónico, plenamente interoperable e interconectado con el registro electrónico general de cuya administración dependan.", "Un registro electrónico del que dispondrá cada Administración Pública y en el que se realizará el asiento de cualquier documento que se presente o se reciba en cualquier órgano administrativo de esta administración, así como también en cualquier organismo público o entidad de derecho público vinculado o dependiente.", "Un registro electrónico del que dispondrá cada Administración Pública y en el que se realizará el asiento de cualquier documento que se presente o se reciba en cualquier órgano administrativo de esta administración. Aquellos organismos públicos o entidades de derecho público vinculado o dependiente de esta administración, podrán disponer de su propio registro electrónico, totalmente independiente del registro electrónico general de cuya administración dependan.", "Un registro electrónico del que dispondrá cada Administración Pública y en el que se realizará el asiento de cualquier documento que se presente o se reciba en cualquier órgano administrativo de esta administración, así como también en cualquier organismo público o entidad de derecho privado vinculado o dependiente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 3, "Si un organismo público o entidad de derecho público opta por disponer de su propio registro electrónico, este registro debe ser:", "Plenamente interoperable e interconectado con el Registro Electrónico General de la Administración General del Estado.", "Plenamente interoperable, exportable en formato de datos abiertos e interconectado con el Registro Electrónico General de la Administración General del Estado.", "Plenamente interoperable e interconectado con el Registro Electrónico General de la Administración a la que esté vinculado o de la que dependa.", "Plenamente interoperable, exportable en formato de datos abiertos e interconectado con el Registro Electrónico General de la Administración a la que esté vinculado o de la que dependa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 4, "En materia de actuación y funcionamiento del sector público por medios electrónicos, ¿qué documentos admitirán los registros electrónicos?", "Documentos electrónicos interoperables correspondientes a los servicios, procedimientos y trámites que se especifiquen conforme a lo dispuesto en la norma de creación de registro, cumplimentados de acuerdo con formatos abiertos.", "Documentos electrónicos normalizados correspondientes a los servicios, procedimientos y trámites que se especifiquen conforme a lo dispuesto en la norma de creación de registro, cumplimentados de acuerdo con formatos abiertos.", "Documentos electrónicos digitalizados correspondientes a los servicios, procedimientos y trámites que se especifiquen  conforme a lo dispuesto en la norma de creación de registro, cumplimentados de acuerdo con formatos preestablecidos.", "Todas las respuestas son incorrectas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 5, "Si un interesado presenta en el Registro Electrónico General del Gobierno de las Illes Balears un documento, cuyo régimen especial establezca otra forma de presentación, ¿se tendrá por presentado?", "No, tal y como lo establecen el artículo 16.9 de la Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas, y el artículo 37.4 del Real Decreto 203/2021, de 30 de marzo, por el que se aprueba el Reglamento de actuación y funcionamiento del sector público por medios electrónicos.", "Sí, tal y como lo establecen el artículo 16.8 de la Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas, y el artículo 37.4 del Real Decreto 203/2021, de 30 de marzo, por el que se aprueba el Reglamento de actuación y funcionamiento del sector público por medios electrónicos.", "Sí, tal y como establece el artículo 37.4 del Real Decreto 203/2021, de 30 de marzo, por el que se aprueba el Reglamento de actuación y funcionamiento del sector público por medios electrónicos, que deroga el artículo 16.9 de la Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas.", "No, tal y como establece el artículo 37.4 del Real Decreto 203/2021, de 30 de marzo, por el que se aprueba el Reglamento de actuación y funcionamiento del sector público por medios electrónicos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 6, "De acuerdo con el artículo 37.4 del Real Decreto 203/2021, de 30 de marzo, por el que se aprueba el Reglamento de actuación y funcionamiento del sector público por medios electrónicos, no se tendrán por presentados en el registro aquellos documentos e información cuyo régimen especial establezca otra forma de presentación. En estos supuestos:", "El órgano ejecutivo competente para la tramitación del procedimiento notificará esta circunstancia al interesado y le informará de los requerimientos exigidos por la legislación específica aplicable.", "El órgano administrativo competente para la tramitación del procedimiento notificará esta circunstancia al interesado y le informará de los requisitos exigidos por la legislación específica aplicable.", "El órgano ejecutivo competente para la tramitación del procedimiento comunicará esta circunstancia al interesado y le informará de los requerimientos exigidos por la legislación específica aplicable.", "El órgano administrativo competente para la tramitación del procedimiento comunicará esta circunstancia al interesado y le informará de los requisitos exigidos por la legislación específica aplicable."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 7, "¿Qué significa que los registros de todas y cada una de las Administraciones Públicas deben ser plenamente interoperables?", "Que garantizarán su compatibilidad informática e interconexión.", "Que garantizarán la transmisión telemática de los asientos registrales.", "Que garantizarán la transmisión telemática de los documentos que se presenten en cualquiera de los registros.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 8, "De acuerdo con el artículo 38 del Real Decreto 203/2021, de 30 de marzo, por el que se aprueba el Reglamento de actuación y funcionamiento del sector público por medios electrónicos, la presentación por medio del servicio electrónico para la presentación de solicitudes, escritos y comunicaciones que no dispongan de modelos normalizados de presentación, independientemente de las Administraciones Públicas u organismos públicos o entidades de derecho público vinculados o dependientes a las que vayan dirigidos:", "No genera ninguna anotación en el Registro Electrónico General de la Administración General del Estado. Este servicio electrónico es una pasarela de interconexión con el Registro Electrónico General de la administración u organismo al que va dirigido el asiento, registro al que se genera la anotación.", "Genera una anotación en el Registro Electrónico General de la Administración General del Estado.", "Este servicio electrónico debe ser accesible desde la sede electrónica del PAGe de la Administración General del Estado.", "Las respuestas b) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 9, "De acuerdo con la Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas, ¿qué ámbito del sector público dispondrá de un registro electrónico de apoderamientos?", "El ámbito estatal.", "El ámbito autonómico.", "El ámbito local.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 10, "Los asientos que se efectúen en los registros electrónicos generales y particulares de apoderamientos deben tener un contenido mínimo de información. Señale cuál de las siguientes opciones no forma parte de este contenido mínimo obligatorio:", "Nombres y apellidos o la denominación o razón social, documento nacional de identidad, número de identificación fiscal o documento equivalente del apoderado.", "Tipo de poder.", "Archivo notarial.", "Periodo de tiempo por el que se otorga el poder."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 11, "De acuerdo con el artículo 6.3 de la Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas, uno de los datos obligatorios que deben contener los asientos que se realicen en los registros electrónicos generales y particulares de apoderamientos es:", "Fecha de caducidad del poder.", "Identificación del funcionario habilitado que registra el asiento.", "Fecha de inscripción.", "Número de días naturales por los que se otorga el poder."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 12, "¿Cuál es la actuación correcta en caso de que se detecte un código malicioso susceptible de afectar a la integridad o la seguridad del sistema en documentos que hayan sido registrados?", "Se anulará el asiento registral y se comunicará esta circunstancia al interesado para que pueda realizar la enmienda.", "No existe la posibilidad de registrar un código malicioso, ya que el registro electrónico general cumple con el Esquema Nacional de Seguridad, y no permite la recepción de documentos que no sigan formatos preestablecidos por la Norma Técnica de Interoperabilidad correspondiente.", "Se anulará el asiento registral y se notificará esta circunstancia al interesado para que pueda realizar la enmienda.", "Se debe requerir la subsanación al interesado que los haya aportado, de acuerdo con lo previsto en el artículo 14.3 del Real Decreto 203/2021, de 30 de marzo, por el que se aprueba el Reglamento de actuación y funcionamiento del sector público por medios electrónicos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 13, "De acuerdo con el artículo 32 del Real Decreto 203/2021, de 30 de marzo, por el que se aprueba el Reglamento de actuación y funcionamiento del sector público por medios electrónicos, la representación puede acreditarse mediante cualquier medio válido en Derecho que deje constancia fidedigna de su existencia, entre otros:", "Mediante el apoderamiento efectuado por comparecencia electrónica en las oficinas de asistencia en materia de registros o comparecencia personal en la correspondiente sede electrónica o sede electrónica asociada.", "Mediante la acreditación de su inscripción en el registro electrónico de apoderamientos de la Administración Pública competente o en sus registros particulares de apoderamientos.", "Mediante un certificado electrónico de representante.", "Mediante un documento privado cuya matriz conste en un archivo notarial o una inscripción practicada en un registro mercantil."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 14, "¿Qué reglamento regula el Registro Electrónico General de la Administración General del Estado?", "La Orden PCM/1382/2021, de 9 de diciembre.", "El Real Decreto 203/2021, de 30 de marzo, por el que se aprueba el Reglamento de actuación y funcionamiento del sector público por medios electrónicos.", "El Real Decreto 113/2003, de 5 de noviembre.", "No existe ninguna normativa que lo regule."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 15, "Los registros electrónicos de todas y cada una de las Administraciones Públicas:", "Serán plenamente interoperables, de forma que se garantice su compatibilidad informática e interconexión, así como la transmisión telemática de los asientos registrales y de los documentos que se presenten en cualquiera de los registros.", "Estarán plenamente interconectados, de forma que se garantice su compatibilidad informática e intermediación, así como la transmisión telemática de los asientos registrales y de los documentos que se presenten en cualquiera de los registros.", "Serám plenamente interoperables, de forma que se garantice su compatibilidad informática e interconexión, así como la transmisión telemática de los asientos registrales y de los documentos que se presenten en un registro de la Administración u Organismo al que se dirijan.", "Estarán plenamente interconectados, de forma que se garantice su compatibilidad informática e intermediación, así como la transmisión telemática de los asientos registrales y de los documentos que se presenten en un registro de la Administración u Organismo al que se dirijan."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 16, "El derecho a comunicarse con las administraciones públicas a través de un Punto de Acceso General electrónico de la Administración es propio de:", "Quienes de conformidad con el artículo 3 de la Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas, tienen capacidad jurídica frente a las administraciones públicas.", "Quienes de conformidad con el artículo 3 de la Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas, tienen capacidad de obrar ante las administraciones públicas.", "Quienes de conformidad con el artículo 3 de la Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas, tienen capacidad jurídica y capacidad de obrar ante las administraciones públicas.", "Todas las respuestas son incorrectas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 17, "El derecho a ser asistido en el uso de medios electrónicos en sus relaciones con las administraciones públicas es titularidad de:", "Las personas físicas, en general.", "Las personas físicas mayores de edad.", "Los ciudadanos y ciudadanas con capacidad jurídica.", "Todas las respuestas son incorrectas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 18, "¿Cuál de estos sujetos está obligado a recibir por medios electrónicos las notificaciones generadas por la Agencia Tributaria de las Illes Balears en el ejercicio de sus funciones?", "Las personas jurídicas.", "Los registradores de la propiedad, cuando deben relacionarse con la administración en ejercicio de su actividad profesional.", "Las comunidades de bienes.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 19, "Las notificaciones que la Consejería de Agricultura, Pesca y Alimentación debe practicar en el marco de un procedimiento administrativo a una comunidad de bienes, ¿se deben realizar por medios electrónicos?", "Verdadero.", "Sólo si el interesado lo solicita.", "Falso.", "Verdadero, dado que una comunidad de bienes tiene personalidad jurídica."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 20, "¿Pueden las personas físicas elegir en todo momento si se comunican con las administraciones públicas para ejercer sus derechos y obligaciones a través de medios electrónicos?", "Sí, salvo en determinados casos.", "Sí, siempre.", "No siempre.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 21, "¿Está obligado un notario a relacionarse electrónicamente con las administraciones públicas?", "Sí, siempre.", "Sólo si debe realizar trámites en el ejercicio de su actividad profesional.", "Sí, siempre que esté colegiado.", "No."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 22, "Cuando una persona física no obligada a relacionarse electrónicamente con las administraciones públicas comunica su derecho a relacionarse por medios electrónicos, los efectos de la comunicación se producen:", "A partir del día siguiente a aquel en que el órgano competente para tramitar el procedimiento tenga constancia de la comunicación.", "A partir del quinto día hábil siguiente a aquel en que el órgano competente para tramitar el procedimiento tenga constancia de la comunicación.", "A partir del tercer día hábil siguiente a aquel en que el órgano competente para tramitar el procedimiento tenga constancia de la comunicación.", "Todas las respuestas son incorrectas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 23, "En caso de que una persona jurídica tenga que recibir una notificación de un procedimiento que debe iniciar de oficio la administración pública y ésta no tiene los datos de contacto electrónicos para hacer el aviso de la puesta a disposición, como debe efectuarse la notificación?", "En papel.", "Por medios electrónicos, poniendo la notificación a su disposición en la sede electrónica.", "Por medios electrónicos, poniendo la notificación a su disposición en la carpeta ciudadana.", "Todas las respuestas son incorrectas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 24, "En todo caso, están obligados a relacionarse a través de medios electrónicos con las administraciones públicas para realizar cualquier trámite de un procedimiento administrativo los siguientes sujetos:", "Quienes representan a un interesado que no esté obligado a relacionarse electrónicamente con la Administración.", "Las comunidades de propietarios.", "Los empleados de las administraciones públicas para realizar trámites y actuaciones personales.", "Todas las respuestas son incorrectas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 25, "De acuerdo con el artículo 14 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas:", "Las administraciones públicas pueden establecer la obligación de relacionarse con ellas a través de medios electrónicos para determinados procedimientos y para determinados colectivos de personas físicas que, por razón de su capacidad económica, técnica, dedicación profesional u otros motivos quede acreditado que tienen acceso y disponibilidad de los medios electrónicos necesarios.", "Las administraciones públicas pueden establecer reglamentariamente la obligación de relacionarse con ellas a través de medios electrónicos para determinados colectivos de personas físicas que, por razón de su capacidad económica, técnica y dedicación profesional quede acreditado que tienen acceso y disponibilidad de los medios electrónicos necesarios.", "Las administraciones públicas pueden establecer reglamentariamente la obligación de relacionarse con ellas a través de medios electrónicos para determinados procedimientos y para determinados colectivos de personas físicas que, por razón de su capacidad económica, técnica, dedicación profesional o otros motivos quede acreditado que tienen acceso y disponibilidad de los medios electrónicos necesarios.", "Todas las respuestas son incorrectas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 26, "¿En cuál de estas actividades profesionales es obligatorio relacionarse electrónicamente con las administraciones públicas en el ejercicio de sus funciones?", "Medicina.", "Farmacia.", "Notaría.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 27, "¿Las personas físicas están obligadas a relacionarse electrónicamente con las administraciones públicas?", "No, en general.", "En determinados casos sí.", "Algunos colectivos sí lo están.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 28, "Indique la respuesta correcta:", "Las personas interesadas que se relacionen con las administraciones públicas a través de medios electrónicos tienen derecho a consultar en el Punto de Acceso General electrónico el estado de la tramitación de los procedimientos.", "Las personas interesadas que se relacionen con las administraciones públicas a través de medios electrónicos tienen derecho a consultar en el Punto de Acceso General electrónico el órgano competente para instruir el procedimiento.", "Las personas interesadas que se relacionen con las administraciones públicas a través de medios electrónicos tienen derecho a consultar en el Punto de Acceso General electrónico los actos de trámite que se han dictado en el procedimiento.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 29, "¿Cuál de esta información tiene derecho a consultar en el Punto de Acceso General electrónico la persona interesada que se relaciona electrónicamente con las administraciones públicas?", "La identificación de las autoridades y personal al servicio de las administraciones públicas bajo cuya responsabilidad se tramita el procedimiento administrativo.", "Los actos de trámite dictados en el procedimiento.", "Los requisitos jurídicos o técnicos que las disposiciones vigentes impongan a los proyectos, actuaciones o solicitudes que se propongan realizar.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 30, "¿En qué caso la Administración puede obligar a las personas físicas a relacionarse con ella por medios electrónicos?", "En los procedimientos de concesión de subvenciones, para determinados colectivos, cuando esté previsto en un reglamento.", "Cuando lo establezca por ley para determinados colectivos de personas físicas.", "Cuando lo establezca por reglamento para determinados colectivos de personas físicas y procedimientos", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 31, "¿Cuál de estos principios generales no rige en las actuaciones y funcionamiento del sector público por medios electrónicos?", "El principio de facilidad de uso.", "El principio de personalización.", "El principio de planificación.", "El principio de proactividad."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 32, "En relación con la actuación y funcionamiento del sector público por medios electrónicos, se entiende por el principio de personalización y proactividad:", "La capacidad de las administraciones públicas para proporcionar servicios precumplimentados y de anticiparse a las posibles necesidades de los usuarios finales del servicio, partiendo del conocimiento adquirido por éstos.", "La capacidad para diseñar los servicios electrónicos centrándose en las personas usuarias.", "No existe este principio general.", "Todas las respuestas son incorrectas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 33, "¿Están obligadas las comunidades autónomas a dar el servicio de información telefónica 012?", "Sí.", "No.", "Solo en el caso de los ayuntamientos.", "No, se trata de un servicio que debe ofrecer la Administración general del Estado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 34, "¿Cuál de estas administraciones públicas no está obligada a ofrecer el servicio de información telefónica 012?", "No hay ninguna administración pública obligada a dar este servicio.", "Las comunidades autónomas.", "Los ayuntamientos.", "La Administración general del Estado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 35, "¿Qué órgano directivo de la Administración de la Comunidad Autónoma de las Illes Balears desempeña las funciones en materia de atención a la ciudadanía?", "La Dirección General de Participación, Transparencia y Voluntariado.", "La Oficina de Atención en Materia de Registro.", "La Dirección General de Calidad y Servicios.", "Todas las respuestas son incorrectas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 36, "En relación con la atención a la ciudadanía, indique la respuesta correcta:", "La atención e información ciudadana es una competencia que ejerce la Consejería de Presidencia.", "La atención e información ciudadana es una competencia que ejerce la Dirección General de Calidad de los Servicios.", "La atención e información ciudadana es una competencia que ejerce la Consejería de Salud y Consumo.", "Todas las respuestas son incorrectas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 37, "Indique la respuesta correcta en relación con la asistencia en el uso de medios electrónicos:", "Las administraciones públicas deben garantizar que los interesados se puedan relacionar con la Administración a través de medios electrónicos, para lo que pondrán a su disposición los canales de acceso que sean necesarios.", "Las administraciones públicas deben garantizar que los ciudadanos puedan relacionarse con la Administración a través de medios electrónicos, para lo que pondrán a su disposición los canales de acceso que sean necesarios.", "Las administraciones públicas deben garantizar que las personas físicas puedan relacionarse con la Administración a través de medios electrónicos, para lo que pondrán a su disposición los canales de acceso que sean necesarios.", "Las administraciones públicas deben garantizar que las personas jurídicas se puedan relacionar con la Administración a través de medios electrónicos, para lo que pondrán a su disposición los canales de acceso que sean necesarios."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 38, "¿A quiénes deben asistir en el uso de medios electrónicos las administraciones públicas?", "A la ciudadanía.", "A los interesados, en determinados casos.", "A las personas físicas.", "A las personas jurídicas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 39, "Indique la respuesta correcta. Si un ciudadano se presenta ante una oficina de asistencia en materia de registros para presentar una solicitud en una convocatoria de subvenciones:", "Será atendido en el uso de medios electrónicos, dependiendo del funcionario.", "Será asistido en el uso de medios electrónicos, especialmente en el caso de una empresa que carece de los medios electrónicos adecuados.", "Será asistido en el uso de medios electrónicos, salvo que el interesado sea una persona jurídica, entre otros casos.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 40, "Si una persona presenta una solicitud en una convocatoria de ayudas ante una oficina de asistencia en materia de registros de la Administración autonómica y no dispone de firma electrónica:", "La oficina de asistencia en materia de registros no es un canal de atención a la ciudadanía si el procedimiento está publicado en la Sede Electrónica.", "La firma electrónica la podrá hacer cualquier funcionario, siempre que el interesado no sea una sociedad anónima.", "Las administraciones públicas deben garantizar que los interesados se puedan relacionar con la Administración a través de medios electrónicos.", "Las respuestas b) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 41, "Indique la respuesta correcta en relación con el Punto de Acceso General electrónico (PAGe):", "El PAGe dispondrá, al menos, de una sede electrónica, a través de la que se podrá acceder a determinados servicios.", "El PAGe debe facilitar el acceso a los servicios, trámites e información de los órganos, organismos públicos y entidades vinculados o dependientes de la Administración Pública correspondiente.", "La Sede Electrónica dispondrá de un Punto de Acceso General electrónico (PAGe), a través del que se podrán acceder a los servicios y trámites.", "Todas las respuestas son incorrectas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 42, "En relación con los canales de atención a la ciudadanía indique la respuesta correcta:", "Un canal es una estructura o medio de difusión de los contenidos y servicios, incluyendo el canal telefónico y el electrónico, así como otros que existan en la actualidad.", "Un canal es una estructura o medio de difusión de los contenidos y procedimientos, incluyendo el canal presencial y el electrónico, así como otros que existan en la actualidad o puedan existir en el futuro (dispositivos móviles, etc.).", "Un canal es una estructura o medio de difusión de los contenidos y servicios, incluyendo el canal presencial, el telefónico y el electrónico, así como otros que existan en la actualidad.", "Un canal es una estructura o medio de difusión de los contenidos y servicios, incluyendo el canal presencial, el telefónico y el electrónico, así como otros que existan en la actualidad o puedan existir en el futuro (dispositivos móviles, etc.)."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 43, "¿En qué tipo de canal debe ponerse a disposición de los interesados la información sujeta a las obligaciones de transparencia según la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno?", "A través de los canales electrónicos, en particular en la página web.", "En la carpeta ciudadana.", "A través de los canales electrónicos, en particular la sede electrónica o página web.", "A través de los canales electrónicos, en particular la sede electrónica."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 44, "Indique la respuesta correcta en relación con la atención a la ciudadanía por medios electrónicos:", "Las administraciones públicas deben asistir en el uso de medios electrónicos a los interesados de un procedimiento administrativo si no disponen de los medios electrónicos necesarios.", "Las administraciones públicas deben asistir en el uso de medios electrónicos a la ciudadanía cuando así lo solicite.", "Las administraciones públicas deben asistir en el uso de medios electrónicos a determinados interesados de un procedimiento administrativo.", "Las administraciones públicas deben asistir en el uso de medios electrónicos a todos los interesados de un procedimiento administrativo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 45, "¿La Administración pública debe asistir en el uso de medios electrónicos a una persona jurídica que tiene la condición de interesada en el procedimiento?", "Sí, dado que es una obligación de las administraciones públicas.", "Sólo si no dispone de los medios electrónicos necesarios.", "No.", "En determinados casos, como por ejemplo en lo referente a la identificación y firma electrónica."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 46, "¿Qué hito marca la transformación de las oficinas de registro en oficinas de asistencia en materia de registros?", "La entrada en vigor de las previsiones de registro electrónico de apoderamientos, registro electrónico, registro de empleados públicos habilitados, punto de acceso general electrónico de la Administración y archivo único electrónico.", "El 2 de abril de 2002.", "La entrada en vigor de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 47, "Cuando un ciudadano comparece ante una oficina de asistencia en materia de registros (OAMR) para presentar una solicitud de una convocatoria de subvenciones:", "El empleado público digitalizará el documento.", "El OAMR no digitalizará el documento si la normativa aplicable exige que se presente el documento en un soporte específico no susceptible de digitalización.", "No se tendrán por presentados aquellos documentos cuyo régimen especial establezca otra forma de presentar los documentos.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 48, "¿Qué órgano superior de la Administración de la Comunidad Autónoma de las Illes Balears tiene las funciones de ordenación y coordinación de las oficinas de asistencia en materia de registros (OAMR)?", "La Consejería de Presidencia, Función Pública e Igualdad.", "La Dirección General de Modernización y Administración Digital.", "La consejería competente en materia de administración digital.", "La Dirección General de Calidad de los Servicios."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 49, "Según la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, ¿qué nuevas funciones en materia de administración electrónica han pasado a asumir las oficinas de registro?", "La anotación electrónica de los asientos de entrada y salida.", "El cotejo y expedición de copias compulsadas de documentos originales.", "La digitalización de documentos presentados en papel.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 50, "En relación con las funciones de las oficinas de asistencia en materia de registros (OAMR), ¿qué debe hacerse si, una vez digitalizado un documento, éste no puede ser devuelto al interesado?", "Debe conservarse durante tres meses.", "Debe enviarse al interesado a través del NOTIB.", "Debe conservarse durante seis meses.", "Todas las respuestas son incorrectas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 51, "Cuando un documento se presenta ante una oficina de asistencia en materia de registros:", "Se hará el correspondiente asiento de todo documento que sea presentado. También se anotará la salida de documentos oficiales dirigidos a otros órganos o particulares.", "Se hará el correspondiente asiento de todo documento que sea presentado. También podrá anotarse la salida de los documentos oficiales dirigidos a otros órganos o particulares.", "Se hará el correspondiente asiento de todo documento que sea presentado. También se anotará la salida de documentos oficiales dirigidos a particulares.", "No se realizará ningún asentamiento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 52, "¿Cuál de estas funciones no está asignada a las oficinas de asistencia en materia de registros según el Real decreto 203/2021?", "La anotación, en su caso, de los asientos de salida de los documentos.", "La anotación de los documentos en el registro electrónico.", "La práctica de notificaciones mediante la aplicación NOTIB.", "La identificación o firma electrónica del interesado, salvo en el caso de personas jurídicas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 53, "Indique la respuesta correcta. Los documentos en soporte no electrónico presentados a través de las oficinas de asistencia en materia de registros:", "Se digitalizarán y se devolverán los documentos originales.", "Se digitalizarán y se incorporarán al expediente administrativo electrónico.", "Se digitalizarán y se custodiarán si en ese momento no es posible devolver el documento original.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 54, "¿Qué debe hacer una oficina de asistencia en materia de registros si debe enviar un documento a otra Administración y el tamaño de éste excede la capacidad que permite el Sistema de Interconexión de Registros (SIR)?", "El envío puede sustituirse por la puesta a disposición de los documentos, previamente depositados en un repositorio de intercambio de ficheros.", "El documento debe archivarse dentro de un dispositivo interno de memoria USB (pen drive) y enviarse a través de un ordenanza.", "El envío debe sustituirse por la puesta a disposición de los documentos, previamente depositados en un repositorio de intercambio de ficheros.", "Todas las respuestas incorrectas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 55, "Entre las funciones de las nuevas oficinas de asistencia en materia de registros (OAMR), ¿se encuentra la de recibir la documentación presentada por una persona jurídica?", "No, porque las personas jurídicas no pueden presentar documentos en papel.", "Sí.", "No, sus funciones son las previstas en el artículo 16 de la Ley 39/2015, de 1 de octubre.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 56, "Si ante una oficina de asistencia en materia de registros (OAMR) alguno de los sujetos obligados a relacionarse electrónicamente con la Administración presenta su solicitud presencialmente:", "El OAMR no debe permitirle presentar documentación en papel.", "El OAMR le registrará la documentación, pero se le requerirá para que subsane la documentación.", "El OAMR tiene como función expresa asistir a los interesados en general.", "Todas las respuestas son incorrectas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 57, "¿Cuál de estas funciones es de las oficinas de asistencia en materia de registros (OAMR)?", "La digitalización de los documentos presentados de forma presencial.", "La asistencia en la identificación y firma electrónica a los interesados en general.", "La práctica de notificaciones a los interesados que comparecen espontáneamente en una OAMR y así lo soliciten.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 58, "Indique la respuesta correcta. Las administraciones públicas deben asistir en el uso de medios electrónicos a los interesados no incluidos en los apartados 2 y 3 del artículo 14 de la Ley 39/2015, de 1 de octubre:", "Cuando así lo soliciten, especialmente en lo referente a firma electrónica.", "Cuando así lo soliciten, especialmente en lo referente a obtener copias auténticas.", "Cuando así lo soliciten, especialmente en lo referente a digitalización de documentos.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 59, "Entre las funciones de las oficinas de asistencia en materia de registros (OAMR), ¿se encuentra la de practicar notificaciones electrónicas a las personas interesadas?", "En determinados casos, sí.", "No.", "Sí, a todos los efectos.", "Todas las respuestas son incorrectas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 60, "Una vez digitalizado un documento presentado por un interesado, ¿qué debe hacer la oficina de asistencia en materia de registros (OAMR)?", "Devolver una copia auténtica al interesado.", "Devolver el documento al interesado.", "Archivar el documento presentado.", "Destruir el documento presentado, en caso de que sea en papel."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 61, "La práctica de notificaciones electrónicas, ¿es una función de las oficinas de asistencia en materia de registros prevista en la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas?", "Sí.", "Siempre que dispongan de los medios electrónicos para su práctica.", "No.", "En determinados casos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 62, "Si después de registrar una queja o sugerencia se concluye que se refiere a otra administración o entidad pública del Estado español:", "La dirección general competente en materia de calidad de los servicios debe remitirla a la entidad objeto de la queja, comunicándoselo a la persona interesada.", "La unidad administrativa correspondiente debe remitirla a la entidad objeto de la queja y debe comunicarlo a la persona interesada.", "La unidad administrativa correspondiente inadmitirá la queja o sugerencia y lo comunicará a la persona interesada.", "Todas las respuestas son incorrectas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 63, "Cuáles de estos aspectos no regula la Orden de la consejera de Administraciones Públicas de 1 de agosto de 2014 por la que se desarrolla el Decreto 82/2009, de 13 de noviembre, por el que se regula la gestión de quejas y sugerencias sobre el funcionamiento de los servicios públicos de la Administración de la Comunidad Autónoma de las Illes Balears:", "El modelo de la hoja de quejas y sugerencias.", "La forma y los medios de presentación de las quejas y sugerencias.", "La tramitación de las quejas y sugerencias mediante la aplicación de uso general QSSI.", "La información sobre el derecho y los sistemas de quejas y sugerencias."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 64, "Señale la respuesta incorrecta. La Orden de la consejera de Administraciones Públicas de 1 de agosto de 2014 por la que se desarrolla el Decreto 82/2009, de 13 de noviembre, por el que se regula la gestión de quejas y sugerencias sobre el funcionamiento de los servicios públicos de la Administración de la Comunidad Autónoma de las Illes Balears se aplica a los servicios que prestan:", "Los consorcios en los que participa la Comunidad Autónoma de las Illes Balears.", "Las personas jurídicas adjudicatarias de contratos de servicios públicos.", "El sector público instrumental de la Comunidad Autónoma de las Illes Balears.", "Los ayuntamientos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 65, "En caso de que la respuesta a una queja o sugerencia presentados por un ciudadano no sea satisfactoria, este ciudadano puede:", "Interponer un recurso de alzada.", "Interponer una reclamación en vía administrativa.", "Dirigirse a la Inspección General de Calidad, Organización y Servicios.", "Todas las respuestas son incorrectas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 66, "El plazo de que dispone la Administración de la Comunidad Autónoma de las Illes Balears para resolver una queja o sugerencia es de:", "Quince días hábiles en el caso de las quejas; no existe plazo en el caso de las sugerencias.", "Quince días hábiles.", "Quince días naturales.", "Todas las respuestas son incorrectas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 67, "¿Es aplicable el Decreto 82/2009, de 13 de noviembre, por el que se regula la gestión de quejas y sugerencias sobre el funcionamiento de los servicios públicos de la Administración de la Comunidad Autónoma de las Illes Balears a las personas jurídicas privadas?", "No.", "Sí, en determinados casos.", "Sí.", "Sólo en lo que se refiere a las quejas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 68, "Según el artículo 2 del Decreto 82/2009, de 13 de noviembre, por el que se regula la gestión de quejas y sugerencias sobre el funcionamiento de los servicios públicos de la Administración de la Comunidad Autónoma de las Illes Balears una queja es:", "Una manifestación o declaración efectuada por una persona física para hacer constar la disconformidad con la prestación de un servicio público.", "Una manifestación o declaración efectuada por una persona física o jurídica para hacer constar la disconformidad con la prestación de un servicio público o privado.", "Una manifestación o una declaración efectuada por los ciudadanos y ciudadanas para hacer constar la disconformidad con la prestación de un servicio público.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 69, "¿Quién es el órgano competente para resolver una queja o sugerencia dirigidas al Hospital Mateu Orfila?", "La Gerencia del IB-Salut.", "La Dirección del Hospital.", "La dirección general competente en materia de salud.", "El Departamento de Bienestar Social del Consejo Insular de Menorca."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 70, "¿Cuál es el órgano competente para resolver una queja o sugerencia según el Decreto 82/2009, de 13 de noviembre, por el que se regula la gestión de quejas y sugerencias sobre el funcionamiento de los servicios públicos de la Administración de la Comunidad Autónoma de las Illes Balears?", "El órgano superior competente por razón de la materia, a excepción de quienes hagan referencia a la prestación de servicios sanitarios y asistenciales.", "La dirección general competente en materia de calidad de los servicios.", "La Dirección de los centros sanitarios, educativos, sociosanitarios y asistenciales en caso de que la queja o sugerencia haga referencia a la prestación de servicios de estos centros.", "Todas las respuestas son incorrectas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 72, "Señale la respuesta correcta según indica el Decreto 82/2009, de 13 de noviembre, por el que se regula la gestión de las quejas y sugerencias sobre el funcionamiento de los servicios públicos de la Administración de la Comunidad Autónoma de las Illes Balears:", "Si transcurrido el plazo de quince días la persona interesada no ha obtenido una respuesta, puede dirigirse a la Inspección General de Calidad, Organización y Servicios, para que, como órgano inspector, lleve a cabo las actuaciones necesarias para conocer los motivos que hayan podido ocasionar falta de contestación y adoptar las medidas pertinentes.", "Si transcurrido el plazo de quince días naturales la persona interesada no ha obtenido una respuesta, puede dirigirse a la Inspección General de Calidad, Organización y Servicios, para que, como órgano inspector, lleve a cabo las actuaciones necesarias para conocer los motivos que hayan podido ocasionar la falta de contestación y adoptar las pertinentes medidas.", "Si transcurrido el plazo de quince días hábiles la persona interesada no ha obtenido una respuesta, puede dirigirse a la Inspección General de Calidad, Organización y Servicios, para que, como órgano inspector, lleve a cabo las actuaciones necesarias para conocer motivos que hayan podido ocasionar la falta de contestación y adoptar las medidas pertinentes.", "Si transcurrido el plazo de un mes la persona interesada no ha obtenido una respuesta, puede dirigirse a la Inspección General de Calidad, Organización y Servicios, para que, como órgano inspector, lleve a cabo las actuaciones necesarias para conocer los motivos que hayan podido ocasionar la falta de contestación y adoptar las pertinentes medidas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 73, "Señale la respuesta correcta en relación con las quejas y sugerencias relativas a servicios públicos de la Administración de la Comunidad Autónoma:", "La presentación de una queja no impide el ejercicio del derecho genérico de petición reconocido en el artículo 29 de la Constitución.", "La formulación de una queja tiene la calificación de recurso administrativo si cumple los requisitos del artículo 115 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas.", "La Ley orgánica 4/2001, de 12 de noviembre, reguladora del derecho de petición se aplica subsidiariamente en defecto de previsión del Decreto 82/2009, de 13 de noviembre, por el que se regula la gestión de quejas y sugerencias sobre el funcionamiento de los servicios públicos de la Administración de la Comunidad Autónoma de las Illes Balears.", "La formulación de una queja o sugerencia en ejercicio del derecho de petición se tramita de conformidad con la Ley orgánica 4/2001, de 12 de noviembre, reguladora del derecho de petición."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 74, "En relación con las quejas y sugerencias, los órganos o entes que utilizan una aplicación distinta a la de uso general (QSSI) deben remitir a la dirección general competente en materia de atención e información ciudadana la siguiente información:", "Tiempo máximo de respuesta.", "Número de sugerencias que se han presentado.", "Materia o motivo de la queja o de la sugerencia.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 16, 75, "Indique la respuesta correcta en relación con las quejas y sugerencias:", "En cada consejería deben constituirse equipos de mejora encargados de analizar todas las quejas y sugerencias.", "En cada consejería y ente del sector público instrumental deben constituirse equipos de mejora encargados de analizar todas las quejas y sugerencias.", "Los equipos de mejora deben constituirse en el seno de los órganos y entes a los que les es de aplicación el Decreto 82/2009, de 13 de noviembre, por el que se regula la gestión de quejas y sugerencias sobre el funcionamiento de los servicios públicos de la Administración de la Comunidad Autónoma de las Illes Balears.", "En cada consejería y ente del sector público instrumental deben constituirse equipos de mejora o unidades administrativas especializadas encargados de analizar todas las quejas y sugerencias."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 1, "Según el art. 35.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, deben ser motivados:", "Los actos que se separen del criterio seguido en actuaciones precedentes o del dictamen de órganos consultivos.", "Los actos que propongan pruebas propuestas por los interesados.", "Los acuerdos de aplicación de la tramitación ordinaria.", "Los actos que reconozcan derechos subjetivos o intereses legítimos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 2, "Indique cuál de las siguientes afirmaciones es correcta según el art. 36.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas:", "Los actos administrativos no pueden refundirse en un único acto.", "Los órganos administrativos pueden ejercer su competencia de forma verbal.", "Los actos administrativos se producirán siempre por escrito.", "Los actos administrativos de distinta naturaleza podrán refundirse en un único acto."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 3, "Según el art. 37.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, la inderogabilidad singular implica que las resoluciones administrativa de carácter particular:", "No podrán vulnerar lo establecido en una disposición de carácter general, aunque aquéllas procedan de un órgano de igual o superior jerarquía al que dictó la disposición general.", "Podrán vulnerar lo establecido en una disposición de carácter general cuando provengan de un órgano de superior jerarquía al que dictó la disposición general.", "No podrán vulnerar lo establecido en una disposición de carácter general, salvo que aquéllas procedan de un órgano de igual o superior jerarquía al que dictó la disposición general.", "Podrán vulnerar lo establecido en una disposición de carácter general cuando procedan del mismo órgano que dictó la disposición general."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 4, "Según el art. 39.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, la eficacia de un acto quedará demorada:", "Cuando así lo disponga el órgano competente.", "Cuando así lo exija el contenido del acto o esté supeditada a su notificación, publicación o aprobación superior.", "Cuando lo soliciten las personas interesadas en el procedimiento.", "Cuando el acto sea firme."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 5, "Según el art. 40.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, las notificaciones deben contener:", "Un extracto de la resolución, con indicación de si pone fin o no a la vía administrativa.", "La expresión de los recursos que procedan, en su caso, en vía administrativa y judicial, el órgano ante el que hubieran de presentarse, y el plazo para interponerlos.", "Los medios de pago que se establezcan a favor de los administrados.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 6, "Según el art. 42.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, cuando la notificación se practica en el domicilio del interesado y el primer intento de notificación resulta infructuoso:", "Se repetirá el intento por una sola vez en una hora distinta dentro de los tres días siguientes.", "Se repetirá el intento dentro de las quince horas siguientes.", "Se publicará el acto de la forma prevista en el art. 44.", "Se repetirá el intento dentro de las tres horas siguientes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 7, "Indique cuál de las siguientes afirmaciones es correcta según el art. 42.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, relativo al segundo intento de notificación administrativa en el domicilio del interesado:", "El segundo intento deberá realizarse siempre después de las quince horas.", "El segundo intento deberá realizarse siempre antes de las quince horas.", "Se dejará un margen de diferencia de menos de doce horas entre ambos intentos de notificación.", "Se dejará en todo caso al menos un margen de diferencia de tres horas entre ambos intentos de notificación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 8, "Según el art. 43.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, cuando la notificación por medios electrónicos sea de carácter obligatorio, o haya sido expresamente elegida por el interesado, se entenderá rechazada cuando:", "Hayan transcurrido diez días naturales desde la puesta a disposición de la notificación sin que se acceda a su contenido.", "Haya transcurrido un mes desde la puesta a disposición de la notificación sin que se acceda a su contenido.", "Hayan transcurrido diez días hábiles desde la puesta a disposición de la notificación sin que se acceda a su contenido.", "Hayan transcurrido cinco días hábiles desde la puesta a disposición de la notificación sin que se acceda a su contenido."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 9, "Indique cuál de las siguientes afirmaciones es correcta según el art. 45.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, relativo a la publicación de actos administrativos:", "Se publicarán en el Diario Oficial de la Unión Europea los actos y comunicaciones que, por disposición legal o reglamentaria, deban publicarse en el «Boletín Oficial del Estado».", "La publicación de una convocatoria de un procedimiento selectivo en el tablón de edictos sustituye la publicación en el boletín oficial correspondiente.", "En los supuestos de publicaciones de actos que contengan elementos comunes, podrán publicarse de forma conjunta los aspectos coincidentes, especificándose solamente los aspectos individuales de cada acto.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 10, "Según el art. 47.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, los actos que tengan un contenido imposible son:", "Nulos de pleno derecho.", "Anulables.", "Anulables cuando sean dictados por el órgano competente y nulos cuando sean dictados por un órgano manifiestamente incompetente.", "Nulos o anulables en función de la jerarquía del órgano que haya dictado la disposición."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 11, "El art. 49.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, dispone que:", "La nulidad o anulabilidad de un acto no implicará la de los sucesivos en el procedimiento que sean independientes del primero.", "La nulidad o anulabilidad de un acto implicará la de los sucesivos en el procedimiento que sean independientes del primero.", "La nulidad de un acto no implicará la de los sucesivos en el procedimiento que sean independientes del primero.", "La anulabilidad de un acto no implicará la de los sucesivos en el procedimiento que sean independientes del primero."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 12, "El art. 49.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, dispone que:", "La nulidad o anulabilidad en parte del acto administrativo implicará en todo caso la de las partes del mismo independientes de aquélla.", "La nulidad del acto administrativo no implicará la de las partes del mismo independientes de aquélla, salvo que la parte viciada sea de tal importancia que sin ella el acto administrativo no hubiera sido dictado.", "La nulidad o anulabilidad en parte del acto administrativo no implicará la de las partes del mismo independientes de aquélla, salvo que la parte viciada sea de tal importancia que sin ella el acto administrativo no hubiera sido dictado.", "La anulabilidad del acto administrativo no implicará la de las partes del mismo independientes de aquélla, salvo que la parte viciada sea de tal importancia que sin ella el acto administrativo no hubiera sido dictado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 13, "Según el art. 55.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, el objetivo del período de información o actuaciones previas es:", "Conocer las circunstancias del caso concreto, la conveniencia o no de iniciar el procedimiento y asegurar la eficacia de la resolución que pudiera recaer.", "Conocer las circunstancias del caso concreto y la conveniencia o no de iniciar el procedimiento.", "Conocer las circunstancias del caso concreto y la conveniencia o no de dictar una resolución sancionadora.", "Conocer las circunstancias del caso concreto, asegurar la eficacia de la resolución que pudiera recaer, y la conveniencia o no de dictar una resolución sancionadora."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 14, "Según el art. 56.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, las medidas provisionales deberán ser confirmadas, modificadas o levantadas:", "En el acuerdo de finalización del procedimiento, que deberá efectuarse dentro de los quince días siguientes a su adopción, el cual podrá ser objeto del recurso que proceda.", "En el acuerdo de iniciación del procedimiento, que deberá efectuarse dentro de los quince días siguientes a su adopción, contra el cual no será procedente ningún recurso administrativo.", "En el acuerdo de finalización del procedimiento, que deberá efectuarse dentro de los quince días siguientes a su adopción, contra el cual no será procedente ningún recurso administrativo.", "En el acuerdo de iniciación del procedimiento, que deberá efectuarse dentro de los quince días siguientes a su adopción, el cual podrá ser objeto del recurso que proceda."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 15, "Indique cuál de las siguientes respuestas es correcta según el art. 56.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas:", "Las medidas provisionales no pueden ser modificadas a instancia de parte.", "Se prohíbe la adopción de la medida provisional de suspensión temporal de actividades.", "Las medidas provisionales solo se extinguen cuando la resolución es firme en vía administrativa.", "Las medidas provisionales adoptadas antes de la iniciación del procedimiento quedarán sin efecto cuando el acuerdo de iniciación no contenga un pronunciamiento expreso acerca de las mismas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 16, "Según el art. 57 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, ¿qué recurso es procedente contra el acuerdo de acumulación de procedimientos?", "Recurso de reposición.", "No es procedente ningún recurso.", "Recurso administrativo o bien recurso contencioso administrativo.", "Recurso de alzada."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 17, "El art. 58 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, dispone que los procedimientos se iniciarán:", "De oficio por acuerdo del órgano competente, como consecuencia de orden superior, a petición razonada de otros órganos o por denuncia.", "De oficio o a instancia de parte por acuerdo del órgano competente, bien por propia iniciativa o como consecuencia de orden superior, a petición razonada de otros órganos o por denuncia.", "De oficio por acuerdo del órgano competente, bien por propia iniciativa o como consecuencia de orden superior, a petición razonada de otros órganos o por denuncia.", "De oficio o a instancia de parte por acuerdo del órgano competente, bien por propia iniciativa o como consecuencia de una orden de otros órganos, o por denuncia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 18, "Según el art. 61.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, se entiende por petición razonada de otros órganos:", "La propuesta de iniciación del procedimiento formulada por cualquier órgano administrativo que no tiene competencia para iniciar el mismo y que ha tenido conocimiento de las circunstancias, conductas o hechos objeto del procedimiento, bien ocasionalmente o bien por tener atribuidas funciones de inspección, averiguación o investigación.", "La orden emitida por un órgano administrativo superior jerárquico del competente para la iniciación del procedimiento.", "El acto por el que cualquier persona, en cumplimiento o no de una obligación legal, pone en conocimiento de un órgano administrativo la existencia de un determinado hecho que pudiera justificar la iniciación de oficio de un procedimiento administrativo.", "La actuación derivada del conocimiento directo o indirecto de las circunstancias, conductas o hechos objeto del procedimiento por el órgano que tiene atribuida la competencia de iniciación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 19, "El art. 61.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, relativo al inicio del procedimiento por petición razonada de otros órganos, dispone que:", "La petición vincula al órgano competente para iniciar el procedimiento, si bien deberá comunicar al órgano que la hubiera formulado los motivos por los que, en su caso, procede la iniciación.", "La petición no vincula al órgano competente para iniciar el procedimiento, si bien deberá comunicar al órgano que la hubiera formulado los motivos por los que, en su caso, no procede la iniciación.", "La petición vincula al órgano competente para iniciar el procedimiento, si bien deberá comunicar al órgano que la hubiera formulado los motivos por los que, en su caso, no procede la iniciación.", "La petición no vincula al órgano competente para iniciar el procedimiento, si bien deberá comunicar al órgano que la hubiera formulado los motivos por los que, en su caso, procede la iniciación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 20, "Según el art. 62.4 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, el denunciante que haya participado en la comisión de una infracción quedará eximido de la sanción:", "Cuando no existan otros infractores y aporte elementos de prueba que permitan iniciar el procedimiento o comprobar la infracción, siempre y cuando en el momento de aportarse aquellos no se disponga de elementos suficientes para ordenar la misma y se repare el perjuicio causado.", "Cuando existan otros infractores y el denunciante facilite elementos de prueba que aporten un valor añadido significativo.", "Cuando existan otros infractores y sea el primero en aportar elementos de prueba que permitan iniciar el procedimiento o comprobar la infracción, siempre y cuando en el momento de aportarse aquellos no se disponga de elementos suficientes para ordenar la misma y se repare el perjuicio causado.", "Cuando no existan otros infractores y el denunciante facilite elementos de prueba que aporten un valor añadido significativo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 21, "Indique cuál de las siguientes afirmaciones es correcta según el art. 63.3 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas:", "Los procedimientos sancionadores se iniciarán de oficio o a instancia de parte y establecerán la debida separación entre la fase instructora y la sancionadora.", "No se podrán iniciar nuevos procedimientos de carácter sancionador por hechos o conductas tipificadas como infracciones en cuya comisión el infractor persista de forma continuada, en tanto no haya recaído una primera resolución sancionadora, con carácter ejecutivo.", "La calificación jurídica definitiva de la infracción siempre debe quedar fijada en la resolución de inicio.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 22, "Según el art. 64.3 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, cuando en el momento de dictar el acuerdo de iniciación de un procedimiento sancionador no existan elementos suficientes para la calificación inicial de los hechos:", "La calificación podrá realizarse en una fase posterior mediante la elaboración de un Pliego de cargos, que deberá ser notificado a los interesados.", "Se deberá abrir una fase de información previa con la finalidad de determinar los hechos que motivan la instrucción del procedimiento.", "La calificación podrá realizarse en el acuerdo de apertura del período de prueba, que deberá ser notificado a los interesados.", "Se deberá archivar el procedimiento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 23, "Indique cuál de las siguientes respuestas es correcta según el art. 65.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, que regula las especialidades en el inicio de oficio de los procedimientos de responsabilidad patrimonial:", "Es un requisito para iniciar un procedimiento de responsabilidad patrimonial que haya prescrito el derecho a la reclamación del interesado.", "Se deberá archivar el procedimiento cuando los particulares presuntamente lesionados no se personen en el plazo establecido.", "El acuerdo de iniciación del procedimiento se comunicará a los interesados concediéndoles un plazo de quince días para que presenten alegaciones.", "El procedimiento iniciado se instruirá aunque los particulares presuntamente lesionados no se personen en el plazo establecido."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 24, "Según el art. 68.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, el plazo de subsanación y mejora de la solicitud:", "Deberá ser ampliado prudencialmente, hasta cinco días, siempre que no se trate de procedimientos selectivos o de concurrencia competitiva.", "Podrá ser ampliado prudencialmente, hasta cinco días, siempre que no se trate de procedimientos selectivos o de concurrencia competitiva.", "Deberá ser ampliado en cinco días en los procedimientos selectivos o de concurrencia competitiva.", "Podrá ser ampliado prudencialmente, hasta cinco días, en los procedimientos selectivos o de concurrencia competitiva."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 25, "Indique cuál de las siguientes afirmaciones es correcta según el art. 69.3 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, que regula la declaración responsable y la comunicación:", "Se entenderá por declaración responsable aquel documento mediante el que los interesados ponen en conocimiento de la Administración Pública competente sus datos identificativos o cualquier otro dato relevante para el inicio de una actividad o el ejercicio de un derecho.", "La comunicación deberá presentarse dentro de un plazo posterior al inicio de la actividad.", "Las declaraciones responsables y las comunicaciones permitirán, el reconocimiento o ejercicio de un derecho o bien el inicio de una actividad, desde el día de su presentación.", "Debe exigirse la presentación simultánea de la declaración responsable y la comunicación salvo que la legislación sectorial lo prohíba."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 26, "Indique cuál de las siguientes afirmaciones es correcta según el art. 69.3 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común:", "Las declaraciones responsables y las comunicaciones permitirán, el reconocimiento o ejercicio de un derecho o bien el inicio de una actividad, desde el día de la autorización.", "La declaración responsable podrá presentarse dentro de un plazo posterior al inicio de la actividad cuando la legislación correspondiente lo prevea expresamente.", "Como regla general la comunicación se presentará después del inicio de la actividad.", "La comunicación podrá presentarse dentro de un plazo posterior al inicio de la actividad cuando la legislación correspondiente lo prevea expresamente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 27, "Según el art. 70.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, formará parte del expediente administrativo:", "La información contenida en aplicaciones, ficheros y bases de datos informáticas.", "Las diligencias encaminadas a ejecutar la resolución administrativa.", "Las notas, borradores, opiniones y resúmenes.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 28, "De acuerdo con el principio de simplificación administrativa consagrado en el art. 72.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas:", "Se acordarán en un solo acto todos los trámites que, por su naturaleza, admitan un impulso simultáneo y no sea obligado su cumplimiento sucesivo.", "Se podrán acordar en un solo acto todos los trámites que, por su naturaleza, admitan un impulso simultáneo y sea obligado su cumplimiento sucesivo.", "Se acordarán en un solo acto todos los trámites que, por su naturaleza, admitan un impulso simultáneo y sea obligado su cumplimiento sucesivo.", "Se podrán acordar en un solo acto todos los trámites que, por su naturaleza, admitan un impulso simultáneo y no sea obligado su cumplimiento sucesivo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 29, "Según el art. 72.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, al solicitar los trámites que deban ser cumplidos por otros órganos:", "Podrá consignarse en la comunicación cursada el plazo legal establecido al efecto.", "Deberá consignarse en la comunicación cursada el plazo legal establecido al efecto.", "Se consignará en la comunicación cursada la suspensión del plazo para dictar y notificar la resolución.", "Podrá consignarse en la comunicación cursada la suspensión del plazo para dictar y notificar la resolución."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 30, "Según el art. 73.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, los trámites que deban ser cumplimentados por los interesados:", "Deberán realizarse en el plazo de diez días a partir del siguiente al de la notificación del correspondiente acto, salvo en el caso de que en la norma correspondiente se fije plazo distinto.", "Deberán realizarse en el plazo de diez días a partir del siguiente al de la notificación del correspondiente acto.", "Deberán realizarse en el plazo de quince días a partir del siguiente al de la notificación del correspondiente acto, salvo en el caso de que en la norma correspondiente se fije plazo distinto.", "Deberán realizarse en el plazo de quince días a partir del siguiente al de la notificación del correspondiente acto."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 31, "Según el art. 73.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, en cualquier momento del procedimiento, cuando la Administración considere que alguno de los actos de los interesados no reúne los requisitos necesarios:", "Lo pondrá en conocimiento de su autor, concediéndole un plazo no inferior a diez días ni superior a quince para cumplimentarlo.", "Se considerará que el interesado desiste de su petición, previa resolución que deberá ser dictada en los términos previstos en el artículo 21.", "Lo pondrá en conocimiento de su autor, concediéndole un plazo de diez días para cumplimentarlo.", "Se considerará que el interesado desiste de su petición, previa resolución que deberá ser dictada en el plazo de diez días."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 32, "Según el art. 75.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, los actos de instrucción:", "Se realizarán de oficio o a instancia de parte.", "Se realizarán de oficio o a instancia de parte y a través de medios electrónicos.", "Se realizarán de oficio y a través de medios electrónicos.", "Se realizarán de oficio o a instancia de parte, en papel y a través de medios electrónicos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 33, "Según el art. 77.3 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, se podrán rechazar las pruebas propuestas por los interesados:", "Cuando el órgano instructor lo considere oportuno.", "Cuando sean manifiestamente improcedentes o innecesarias.", "Cuando haya razones imperiosas de interés general.", "Cuando sean manifiestamente pertinentes y necesarias."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 34, "Según el art. 80.4 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, si el informe debiera ser emitido por una Administración Pública distinta de la que tramita el procedimiento en orden a expresar el punto de vista correspondiente a sus competencias respectivas, y transcurriera el plazo sin que aquél se hubiera emitido:", "Deberán proseguir las actuaciones.", "Se podrán proseguir las actuaciones.", "No deben proseguir las actuaciones.", "Se deberá suspender la instrucción del procedimiento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 35, "Según el art. 81.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, en los procedimientos de responsabilidad patrimonial el plazo para la emisión del informe del servicio cuyo funcionamiento haya ocasionado la presunta lesión indemnizable:", "No podrá exceder de diez días.", "No podrá ser inferior a diez días ni superior a quince.", "No podrá ser inferior a diez días ni superior a treinta.", "No podrá ser inferior a diez días."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 36, "Según el art. 83.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, ¿cómo se lleva a cabo el trámite de información pública?", "Se notificará a los interesados y se publicará un anuncio en el Diario oficial correspondiente a fin de que puedan presentar alegaciones en un plazo no inferior a treinta días.", "Se publicará un anuncio en el Diario oficial correspondiente a fin de que cualquier persona física o jurídica pueda examinar el expediente.", "Se publicará un anuncio en el Diario oficial correspondiente a fin de que los interesados puedan examinar el expediente.", "Se publicará un anuncio en el Diario oficial correspondiente a fin de que cualquier persona física o jurídica pueda examinar el expediente en un plazo no inferior a diez días ni superior a quince."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 37, "Según el art. 86.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, los pactos y acuerdos que suscriban las Administraciones Públicas:", "Requerirán siempre la aprobación expresa del Consejo de Ministros u órgano equivalente de las Comunidades Autónomas.", "Se publicarán en el Boletín Oficial del Estado o en el diario oficial correspondiente.", "Podrán establecer el ámbito personal, funcional y territorial, y el plazo de vigencia.", "Se deberán publicar o no según su naturaleza y las personas a las que estuvieran destinados."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 38, "Indique cuál de las siguientes afirmaciones es correcta según el art. 87 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, relativo a la práctica de actuaciones complementarias:", "Las actuaciones complementarias serán acordadas por el instructor del procedimiento.", "Se concederá un plazo no superior a quince días para formular alegaciones.", "Las actuaciones complementarias deberán practicarse en un plazo no superior a quince días.", "El órgano instructor podrá suspender el plazo para resolver el procedimiento hasta la terminación de las actuaciones complementarias."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 39, "Según el art. 87 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas:", "Antes de dictar resolución, el órgano competente para resolver debe realizar las actuaciones complementarias indispensables para resolver el procedimiento.", "Antes de dictar resolución, el órgano instructor podrá decidir, mediante acuerdo motivado, la realización de las actuaciones complementarias indispensables para resolver el procedimiento.", "Antes de dictar resolución, el órgano competente para resolver podrá decidir, mediante acuerdo motivado, la realización de las actuaciones complementarias indispensables para resolver el procedimiento.", "Antes de dictar resolución, el órgano instructor debe realizar las actuaciones complementarias indispensables para resolver el procedimiento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 40, "Indique cuál de las siguientes afirmaciones es correcta según el art. 88.5 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, relativo al contenido de la resolución:", "La aceptación de informes o dictámenes no servirá de motivación a la resolución aunque se incorporen al texto de la misma.", "La resolución del procedimiento se podrá dictar electrónicamente.", "Podrá acordarse la inadmisión de las solicitudes de reconocimiento de derechos no previstos en el ordenamiento jurídico o manifiestamente carentes de fundamento.", "La resolución que ponga fin al procedimiento solo podrá decidir sobre las cuestiones planteadas por los interesados."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 41, "Según el art. 89.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, el órgano instructor resolverá la finalización del procedimiento sancionador con archivo de las actuaciones:", "Cuando no figuren en el procedimiento ni sean tenidos en cuenta en la resolución otros hechos ni otras alegaciones y pruebas que las aducidas por el interesado.", "Cuando la sanción tenga carácter pecuniario y se haya repuesto la situación alterada.", "Cuando los hechos probados no constituyan, de modo manifiesto, infracción administrativa.", "Cuando considere que la infracción o la sanción revisten mayor gravedad que la determinada en resolución de inicio."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 42, "Según el art. 94.5 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, la Administración podrá limitar los efectos del desistimiento o la renuncia al interesado:", "Cuando se personen en el procedimiento terceros interesados e insten su continuación en el plazo de diez días.", "Cuando la cuestión suscitada por la incoación del procedimiento entrañase interés general o fuera conveniente sustanciarla para su definición y esclarecimiento.", "Cuando se produzca la paralización del procedimiento por causa imputable al interesado.", "Cuando razones de interés público o la falta de complejidad del procedimiento así lo aconsejen."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 43, "El art. 95.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, dispone que:", "Deberá acordarse la caducidad por la simple inactividad del interesado en la cumplimentación de trámites, siempre que no sean indispensables para dictar resolución.", "No podrá acordarse la caducidad por la simple inactividad del interesado en la cumplimentación de trámites, siempre que no sean indispensables para dictar resolución.", "Podrá acordarse la caducidad por la simple inactividad del interesado en la cumplimentación de trámites, siempre que no sean indispensables para dictar resolución.", "No deberá acordarse la caducidad por la simple inactividad del interesado en la cumplimentación de trámites, siempre que sean indispensables para dictar resolución."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 44, "Según el art. 96.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, ¿cuándo se podrá acordar el procedimiento de tramitación simplificada?", "Cuando así lo autoricen las Leyes, y en la forma y cuantía que éstas determinen.", "Cuando razones de interés público o la falta de complejidad del procedimiento así lo aconsejen.", "Cuando no exista o no se haya podido identificar a la persona o personas responsables.", "Cuando lo requiera la naturaleza del procedimiento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 45, "Según el art. 96.6 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, ¿cuál es el plazo para resolver el procedimiento de tramitación simplificada?", "Tres meses, a contar desde el siguiente al que se notifique al interesado el acuerdo de tramitación simplificada del procedimiento.", "Tres meses, a contar desde la fecha que se dicta la resolución de inicio del procedimiento.", "Treinta días, a contar desde el siguiente al que se notifique al interesado el acuerdo de tramitación simplificada del procedimiento.", "Treinta días, a contar desde la fecha que se dicta la resolución de inicio del procedimiento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 46, "Según el art. 100.3 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, cuando las Administraciones Públicas necesiten entrar en el domicilio del afectado:", "Deberán obtener siempre la oportuna autorización judicial.", "Deberán obtener el consentimiento del mismo o, en su defecto, la oportuna autorización judicial.", "Deberán obtener el consentimiento del mismo y la oportuna autorización judicial.", "Deberán instruir el procedimiento que corresponda de acuerdo con el Título IV de esta Ley."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 47, "Según el art. 102.4 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, la exigencia de los gastos de la ejecución subsidiaria:", "Se deberá liquidar de forma definitiva una vez ejecutado el acto, a través del procedimiento de apremio.", "Podrá liquidarse de forma provisional y realizarse antes de la ejecución, a reserva de la liquidación definitiva.", "Deberá liquidarse de forma provisional y podrá realizarse antes de la ejecución, a reserva de la liquidación definitiva.", "Se deberá liquidar de forma definitiva una vez ejecutado el acto, con la autorización judicial previa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 48, "¿En cuál de los supuestos siguientes puede imponerse la multa coercitiva según el art. 103.1, letra a), de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas?", "Actos personalísimos en que no proceda la compulsión directa sobre la persona del obligado.", "Cuando en virtud de acto administrativo hubiera de satisfacerse cantidad líquida.", "Actos cuya ejecución no se pueda encargar a otra persona.", "Cuando así lo exija el contenido del acto o esté supeditada a su notificación, publicación o aprobación superior."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 49, "Según el art. 106 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, es necesario solicitar el dictamen del Consejo de Estado:", "En los procesos de revisión de actos nulos.", "En los procesos de revisión de disposiciones nulas.", "En los procesos de revisión de actos nulos y disposiciones nulas.", "En los procesos de revisión de actos nulos, de disposiciones nulas y de declaración de lesividad de disposiciones anulables."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 50, "Según el art. 106.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, ¿qué carácter tiene el dictamen del Consejo de Estado en los procedimientos de revisión de actos nulos?", "Facultativo y no vinculante.", "Preceptivo y vinculante.", "Preceptivo y no vinculante.", "Facultativo y vinculante."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 51, "Según el art. 106.5 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, ¿cuándo se produce la caducidad de los procedimientos de revisión de disposiciones y actos nulos iniciados de oficio?", "Transcurrido el plazo de seis meses desde su inicio sin dictarse resolución.", "Transcurrido el plazo de tres meses desde su inicio sin dictarse resolución.", "Transcurrido el plazo de seis meses desde que se dictó el acto o la disposición nula.", "Transcurrido el plazo de tres meses desde que se dictó el acto o la disposición nula."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 52, "Según el art. 107.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, la declaración de lesividad afecta a:", "Los actos favorables para los interesados que sean anulables.", "Los actos desfavorables para los interesados que sean anulables.", "Los actos favorables para los interesados que sean nulos.", "Los actos desfavorables para los interesados que sean nulos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 53, "El art. 107.3 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, dispone que:", "Transcurrido el plazo de cuatro años desde la iniciación del procedimiento sin que se hubiera declarado la lesividad, se producirá la caducidad del mismo.", "Transcurrido el plazo de seis meses desde la iniciación del procedimiento sin que se hubiera declarado la lesividad, se producirá la caducidad del mismo.", "Transcurrido el plazo de cuatro años desde la iniciación del procedimiento sin que se hubiera declarado la lesividad, se podrá entender la misma desestimada por silencio administrativo.", "Transcurrido el plazo de seis meses desde la iniciación del procedimiento sin que se hubiera declarado la lesividad, se podrá entender la misma desestimada por silencio administrativo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 54, "¿Qué limite temporal establece el art. 109.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, para rectificar los errores materiales, de hecho o aritméticos?", "No se establece ningún límite.", "Cuatro años desde que se dictó el acto administrativo.", "Un mes desde que se dictó el acto administrativo.", "Seis meses desde que se dictó el acto administrativo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 55, "Según el art. 112.3 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas:", "Los recursos administrativos contra una disposición general que se funden únicamente en la nulidad de la misma podrán interponerse directamente ante el órgano que dictó dicha disposición.", "Los recursos contra un acto administrativo que se funden únicamente en la nulidad de alguna disposición administrativa de carácter general podrán interponerse directamente ante el órgano que dictó dicha disposición.", "Los recursos contra un acto administrativo que se funden únicamente en la nulidad de alguna disposición administrativa de carácter general deberán interponerse ante el órgano que dictó dicha disposición.", "Los recursos administrativos contra una disposición general que se funden únicamente en la nulidad de la misma deberán interponerse directamente ante el órgano que dictó dicha disposición."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 56, "Indique cuál de las siguientes afirmaciones sobre los recursos administrativos es correcta según el art. 115.3 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas:", "Los vicios y defectos que hagan anulable un acto no podrán ser alegados por quienes los hubieren causado.", "El error o la ausencia de la calificación del recurso por parte del recurrente es siempre una causa de inadmisión.", "La falta de legitimación no es una causa de inadmisión del recurso.", "Si ha transcurrido el plazo para interponer el recurso, la Administración debe requerir al interesado para que subsane su escrito."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 57, "Según el art. 116 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, ¿cuál de las siguientes es una causa de inadmisión de los recursos administrativos?", "Tener legitimación.", "Que el acto sea susceptible de recurso.", "Carecer el recurso manifiestamente de fundamento.", "Que el órgano disponga de competencia para resolver el recurso."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 58, "Según el art. 117.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, cuando la impugnación se fundamente en alguna de las causas de nulidad de pleno derecho previstas en el artículo 47.1 de esta Ley, el órgano a quien competa resolver el recurso:", "Podrá dejar sin efecto el acto impugnado.", "Deberá suspender la ejecución del acto impugnado.", "Podrá suspender la ejecución del acto impugnado.", "Deberá dejar sin efecto la ejecución del acto impugnado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 59, "Según el art. 119.3 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, la resolución de un recurso administrativo:", "Requiere un trámite de audiencia por un plazo no inferior a diez días ni superior a quince cuando deba agravarse la situación del recurrente.", "Debe ir precedida siempre de un trámite de audiencia.", "Será congruente con las peticiones formuladas por el recurrente, sin que en ningún caso pueda agravarse su situación inicial.", "Solo debe resolver las cuestiones de fondo planteadas por los interesados."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 60, "Indique cuál de las siguientes afirmaciones es correcta según el art. 120.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, relativo a la suspensión del plazo para resolver un recurso administrativo hasta que recaiga pronunciamiento judicial:", "El acuerdo de suspensión podrá ser notificado a los interesados.", "El acuerdo de suspensión deberá ser notificado a los interesados, quienes podrán recurrirlo.", "El acuerdo de suspensión, contra el cuál no podrá interponerse ningún recurso, deberá ser notificado a los interesados.", "El acuerdo de suspensión no debe notificarse a los interesados."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 61, "Indique cuál de las siguientes afirmaciones es correcta según el art. 121.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas:", "Los actos que no pongan fin a la vía administrativa pueden ser recurridos en alzada y en reposición.", "Puede interponerse recurso de reposición y recurso extraordinario de revisión contra los actos firmes en vía administrativa.", "Los actos que pongan fin a la vía administrativa pueden ser recurridos en alzada.", "Los actos que no pongan fin a la vía administrativa podrán ser recurridos en alzada ante el órgano superior jerárquico del que los dictó."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 62, "Según el art. 123.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, los actos administrativos que pongan fin a la vía administrativa:", "Deberán ser recurridos en reposición ante el mismo órgano que los hubiera dictado como requisito previo para la impugnación ante el orden jurisdiccional contencioso-administrativo.", "Podrán ser recurridos potestativamente en reposición ante el mismo órgano que los hubiera dictado o ser impugnados directamente ante el orden jurisdiccional contencioso-administrativo.", "Deberán ser recurridos en alzada ante el órgano superior jerárquico como requisito previo para la impugnación ante el orden jurisdiccional contencioso-administrativo.", "Podrán ser recurridos potestativamente en reposición ante el órgano superior jerárquico o ser impugnados directamente ante el orden jurisdiccional contencioso-administrativo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 63, "Según el art. 125.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, ¿contra qué actos se puede interponer el recurso extraordinario de revisión?", "Contra las disposiciones generales, los actos definitivos, los actos de trámite cualificados y los actos firmes en vía administrativa.", "Contra los actos definitivos, los actos de trámite cualificados y los actos firmes en vía administrativa.", "Contra los actos definitivos y los actos firmes en vía administrativa.", "Contra los actos firmes en vía administrativa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 64, "Según el art. 42 de la Ley 3/2003, de 26 de marzo, de régimen jurídico de la administración de la Comunidad Autónoma de las Illes Balears, los actos dictados por el vicepresidente adoptan la forma de:", "Decreto.", "Resolución", "Acuerdo.", "Orden."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 65, "Según el art. 42 de la Ley 3/2003, de 26 de marzo, de régimen jurídico de la administración de la Comunidad Autónoma de las Illes Balears, adoptan la forma de decreto:", "Los actos dictados por el presidente.", "Los actos dictados por el presidente y por el Gobierno.", "Los actos dictados por el presidente y por las comisiones delegadas.", "Los actos dictados por el presidente, por el Gobierno y por las comisiones delegadas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 66, "Según el art. 48.1 de la Ley 3/2003, de 26 de marzo, de régimen jurídico de la administración de la Comunidad Autónoma de las Illes Balears, las actuaciones que sean de interés para la tramitación del expediente se harán constar mediante:", "Resolución.", "Acuerdo.", "Diligencia.", "Orden."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 67, "Según el art. 50.1 de la Ley 3/2003, de 26 de marzo, de régimen jurídico de la administración de la Comunidad Autónoma de las Illes Balears, los plazos máximos para dictar y notificar la resolución expresa en los procedimientos de competencia de la comunidad autónoma:", "Son los que fije la norma reguladora del procedimiento correspondiente y no podrán exceder de seis meses.", "Son los que fije la norma reguladora del procedimiento correspondiente y no podrán exceder de seis meses, salvo que una ley establezca uno más amplio o así se prevea en la normativa comunitaria europea.", "Son los que fije la norma reguladora del procedimiento correspondiente y no podrán exceder de tres meses.", "Son los que fije la norma reguladora del procedimiento correspondiente y no podrán exceder de tres meses, salvo que una ley establezca uno más amplio o así se prevea en la normativa comunitaria europea."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 68, "Según el art. 50.3.b de la Ley 3/2003, de 26 de marzo, de régimen jurídico de la administración de la Comunidad Autónoma de las Illes Balears, el plazo máximo para dictar y notificar la resolución expresa en los procedimientos sancionadores abreviados respecto de los cuales la comunidad autónoma dispone de competencia normativa es de:", "Un año.", "Seis meses.", "Tres meses.", "Un mes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 69, "Según el art. 53.1.a de la Ley 3/2003, de 26 de marzo, de régimen jurídico de la administración de la Comunidad Autónoma de las Illes Balears, agotan la vía administrativa:", "Los actos dictados por el presidente.", "Los actos dictados por el presidente y por el Consejo de Gobierno.", "Los actos dictados por el presidente, por el Consejo de Gobierno y por los órganos directivos de las Consejerías.", "Los actos dictados por el presidente y por el Consejo de Gobierno, salvo que una ley establezca lo contrario."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 70, "Según el art. 53.1.b de la Ley 3/2003, de 26 de marzo, de régimen jurídico de la administración de la Comunidad Autónoma de las Illes Balears, los acuerdos de las comisiones delegadas del Gobierno:", "Agotan la vía administrativa.", "Agotan la vía administrativa, salvo que una ley establezca lo contrario.", "No agotan la vía administrativa.", "No agotan la vía administrativa, salvo que una ley establezca lo contrario."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 71, "Indique cuál de las siguientes afirmaciones es correcta según el art. 54.1 de la Ley 3/2003, de 26 de marzo, de régimen jurídico de la administración de la Comunidad Autónoma de las Illes Balears:", "La competencia para resolver los procedimientos de revisión de actos nulos corresponde siempre al órgano que haya dictado el acto.", "La declaración de nulidad requerirá el dictamen previo y favorable del Consejo Económico y Social de las Islas Baleares.", "La competencia para resolver los procedimientos de revisión de actos nulos corresponde al Consejo de Gobierno.", "Los procedimientos de revisión de actos nulos se iniciarán de oficio por el órgano autor del acto o a solicitud de persona interesada."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 72, "Según el art. 54.2 de la Ley 3/2003, de 26 de marzo, de régimen jurídico de la administración de la Comunidad Autónoma de las Illes Balears, en los procedimientos de revisión de oficio de disposiciones administrativas:", "La competencia para su inicio corresponde al órgano que las hubiera aprobado y la resolución al órgano superior jerárquico.", "La competencia para su inicio y resolución corresponde al superior jerárquico del órgano que las hubiera aprobado.", "La competencia para su inicio y resolución corresponderá al órgano que las hubiera aprobado.", "La competencia para su inicio corresponde al órgano superior jerárquico y la resolución al órgano que las hubiera aprobado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 73, "De acuerdo con el art. 55.1 de la Ley 3/2003, de 26 de marzo, de régimen jurídico de la administración de la Comunidad Autónoma de las Illes Balears, ¿qué órgano es el competente para iniciar los procedimientos para la declaración de lesividad?", "El órgano autor del acto.", "El consejero competente por razón de la materia, salvo que el acto provenga de una comisión delegada o del Consejo de Gobierno, en cuyo caso corresponderá a éste último su declaración.", "El consejero competente por razón de la materia.", "El órgano autor del acto, salvo que el acto provenga del Presidente, en cuyo caso la declaración corresponderá al Consejo de Gobierno."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 74, "Según el art. 56.1 de la Ley 3/2003, de 26 de marzo, de régimen jurídico de la administración de la Comunidad Autónoma de las Illes Balears, ¿cuál es el órgano competente para revocar los actos de gravamen o desfavorables?", "El consejero competente por razón de la materia.", "El órgano que hubiera dictado el acto o la disposición.", "El consejero competente por razón de la materia, salvo que el acto provenga de una comisión delegada o del Consejo de Gobierno, en cuyo caso corresponderá a éste último su declaración.", "El superior jerárquico del órgano que hubiera dictado el acto o la disposición."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 10, 75, "Según el art. 56.3 de la Ley 3/2003, de 26 de marzo, de régimen jurídico de la administración de la Comunidad Autónoma de las Illes Balears, las erratas en el texto publicado, respecto del texto recibido, en el Butlletí Oficial de les Illes Balears:", "Podrán ser corregidas por el órgano encargado del boletín, aunque previamente lo debe comunicar al Consejo de Gobierno.", "Podrán ser corregidas por Consejo de Gobierno, aunque previamente lo debe comunicar al órgano encargado del boletín.", "Podrán ser corregidas por el órgano encargado del boletín, que deberá comunicarlo posteriormente al órgano del cual haya emanado el acto o la disposición objeto de corrección.", "Podrán ser corregidas por el órgano encargado del boletín, aunque previamente lo debe comunicar al órgano del cual haya emanado el acto o la disposición objeto de corrección."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 1, "Según el artículo 16 de la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, ¿cuáles son las funciones del secretario de un órgano colegiado?", "Únicamente garantizar que las reglas de constitución de los órganos se cumplen adecuadamente.", "Velar por la legalidad formal y material de las actuaciones del órgano colegiado, certificar las actuaciones del mismo y garantizar que los procedimientos y reglas de constitución y adopción de acuerdos son respetadas.", "Establecer los procedimientos que se tienen que seguir para la adopción de acuerdos.", "Solo asistir a las sesiones de los órganos colegiados."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 2, "¿Quién puede solicitar al secretario de un órgano colegiado la expedición de la certificación de sus acuerdos?", "Quienes acrediten la titularidad de un interés legítimo.", "Cualquier persona.", "Nadie.", "Solo los miembros del órgano."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 3, "Señale la respuesta correcta. Según lo dispuesto en el artículo 18 de la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, en el acta de la sesión de un órgano colegiado se incluirá:", "Solo los asistentes y el contenido de los acuerdos adoptados.", "Los asistentes, el orden del día de la reunión, las circunstancias del lugar y tiempo en que se ha celebrado, los puntos principales de las deliberaciones, así como el contenido de los acuerdos adoptados.", "Únicamente el orden del día y el contenido de los acuerdos adoptados.", "Solo los asistentes y las circunstancias del lugar y tiempo en que se ha celebrado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 4, "Señale la respuesta correcta respecto del acta de cada sesión:", "Deberá aprobarse en la misma reunión.", "Solo podrá aprobarse en la reunión siguiente.", "Podrá aprobarse en la misma reunión o en la inmediata siguiente", "Deberá aprobarse en la última reunión."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 5, "¿Cuál de las siguientes funciones no corresponde al presidente de los órganos colegiados de la Administración General del Estado y de las Entidades de Derecho Público vinculadas o dependientes de ella?", "Visar las actas y las certificaciones de los acuerdos del órgano.", "Asegurar el cumplimiento de las leyes.", "Acordar la convocatoria de las sesiones ordinarias y extraordinarias y la fijación del orden del día, teniendo en cuenta, en su caso, las peticiones de los demás miembros, siempre que hayan sido formuladas con la suficiente antelación.", "Expedir certificaciones de las consultas, dictámenes y acuerdos aprobados."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 6, "¿Cuál de las siguientes funciones no corresponde al secretario de los órganos colegiados de la Administración General del Estado y de las Entidades de Derecho Público vinculadas o dependientes de ella?", "Ostentar la representación del órgano.", "Expedir certificaciones de las consultas, dictámenes y acuerdos aprobados.", "Preparar el despacho de los asuntos, redactar y autorizar las actas de las sesiones.", "Recibir los actos de comunicación de los miembros con el órgano, sean notificaciones, peticiones de datos, rectificaciones o cualquiera otra clase de escritos de los que deba tener conocimiento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 7, "Señale la respuesta incorrecta. Según el artículo 19 de la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, los miembros de los órganos colegiados de la Administración General del Estado y de las Entidades de Derecho Público vinculadas o dependientes de ella:", "Tienen que recibir, con una antelación mínima de dos días, la convocatoria conteniendo el orden del día de las reuniones.", "Tienen que la información precisa para cumplir las funciones asignadas.", "Tienen que participar en los debates de las sesiones.", "Tienen que recibir, con una antelación mínima de una semana, la convocatoria conteniendo el orden del día de las reuniones."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 8, "¿En qué casos los miembros titulares del órgano colegiado de la Administración General del Estado y de las Entidades de Derecho Público vinculadas o dependientes de ella serán sustituidos por sus suplentes, si los hubiera?", "En casos de ausencia o enfermedad.", "Siempre que lo soliciten.", "Cuando lo soliciten las organizaciones representativas.", "En general, aunque no exista causa justificada."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 9, "Si alguna disposición atribuye la competencia a una Administración, sin especificar el órgano que debe ejercerla, se entenderá que la facultad de instruir y resolver los expedientes corresponde:", "A los órganos superiores competentes por razón de la materia.", "A los órganos inferiores competentes por razón de la materia y el territorio.", "A los órganos inferiores que tengan competencia únicamente por razón del territorio.", "A los órganos superiores competentes por razón del territorio y la materia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 10, "¿A quién podrán delegar los órganos de las diferentes Administraciones Públicas el ejercicio de las competencias que tengan atribuidas?", "En otros órganos de la misma Administración, aun cuando no sean jerárquicamente dependientes, o en los Organismos públicos o Entidades de Derecho Público vinculados o dependientes de aquéllas.", "En otros órganos de la misma Administración, siempre que sean jerárquicamente dependientes.", "Siempre deberán delegar en órganos de otra Administración.", "Solo en los Organismos públicos o Entidades de Derecho Público vinculados o dependientes de aquéllas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 11, "¿Dónde deberá publicarse la delegación de competencias y su revocación?", "Únicamente en el Boletín Oficial del Estado.", "Únicamente en el Boletín de la Comunidad Autónoma o en el de la Provincia.", "En el Boletín Oficial del Estado, en el de la Comunidad Autónoma o en el de la Provincia, según la Administración a que pertenezca el órgano delegante, y el ámbito territorial de competencia de éste.", "No es necesaria su publicación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 12, "Señale la respuesta incorrecta en relación a la delegación de competencias:", "Las resoluciones administrativas que se adopten por delegación indicarán expresamente esta circunstancia y se considerarán dictadas por el órgano delegante.", "Salvo autorización expresa de una Ley, no podrán delegarse las competencias que se ejerzan por delegación.", "La delegación no será revocable en ningún caso por el órgano que la haya conferido.", "El acuerdo de delegación de aquellas competencias atribuidas a órganos colegiados, para cuyo ejercicio se requiera un quórum o mayoría especial, deberá adoptarse observando, en todo caso, dicho quórum o mayoría."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 13, "¿En qué casos la realización de actividades de carácter material o técnico de la competencia de los órganos administrativos o de las Entidades de Derecho Público podrá ser encomendada a otros órganos o Entidades de Derecho Público de la misma o de distinta Administración?", "Siempre que entre sus competencias estén esas actividades, por razones de eficacia o cuando no se posean los medios técnicos idóneos para su desempeño.", "Siempre que entre sus competencias estén esas actividades, por razones de eficacia, aunque se posean los medios técnicos idóneos para su desempeño.", "Por razones técnicas y siempre que no se posean los medios para su desempeño.", "Siempre por razones de eficiencia y eficacia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 14, "¿Dónde deberá publicarse la encomienda de gestión entre órganos y Entidades de Derecho Público de distintas Administraciones?", "Únicamente en el Boletín Oficial del Estado.", "Únicamente en el Boletín de la Comunidad Autónoma o en el de la Provincia.", "En el Boletín Oficial del Estado, en el de la Comunidad Autónoma o en el de la Provincia, según la Administración a que pertenezca el órgano encomendante, salvo en el supuesto de la gestión ordinaria de los servicios de las Comunidades Autónomas por las Diputaciones Provinciales o en su caso Cabildos o Consejos insulares, que se regirá por la legislación de Régimen Local", "No es necesaria su publicación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 15, "Señale la respuesta incorrecta en relación a la suplencia prevista en el artículo 13 de la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público:", "Si no se designa suplente, la competencia del órgano administrativo se ejercerá por quien designe el órgano administrativo inmediato superior de quien dependa.", "La suplencia no implicará alteración de la competencia.", "Los titulares de los órganos administrativos podrán ser suplidos temporalmente en los supuestos de vacante, ausencia o enfermedad, así como en los casos en que haya sido declarada su abstención o recusación", "Para su validez es necesaria su publicación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 16, "¿Qué deberá hacer el órgano administrativo que se estime incompetente para la resolución de un asunto?", "Deberá remitir directamente las actuaciones al órgano que considere competente, debiendo notificar esta circunstancia a los interesados.", "Deberá remitir a través de un superior jerárquico las actuaciones al órgano que considere competente.", "Deberá remitir directamente las actuaciones al órgano que considere competente, sin necesidad de notificar esta circunstancia a los interesados.", "Deberá dictar una resolución en la que se declare incompetente y notificarla a los interesados."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 17, "Señale la respuesta correcta en relación con la competencia:", "Los interesados tanto si son parte en el procedimiento como si no, podrán dirigirse al órgano que se encuentre conociendo de un asunto para que decline su competencia y remita las actuaciones al órgano competente.", "Los conflictos de atribuciones sólo podrán suscitarse entre órganos de una misma Administración no relacionados jerárquicamente, y respecto a asuntos sobre los que no haya finalizado el procedimiento administrativo.", "Los interesados no podrán dirigirse al órgano que estimen competente para que requiera de inhibición al que esté conociendo del asunto.", "Los conflictos de atribuciones sólo podrán suscitarse entre órganos de una misma Administración que estén relacionados jerárquicamente, y respecto a asuntos sobre los que haya finalizado el procedimiento administrativo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 18, "Señale la respuesta incorrecta. Los convenios suscritos por las Administraciones Públicas, sus organismos públicos y entidades de derecho público vinculados o dependientes y las Universidades públicas, deberán incluir:", "El régimen de recursos.", "Los sujetos que suscriben el convenio y la capacidad jurídica con que actúa cada una de las partes.", "El régimen de modificación del convenio.", "El objeto del convenio y actuaciones a realizar por cada sujeto para su cumplimiento, indicando, en su caso, la titularidad de los resultados obtenidos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 19, "Señale la respuesta correcta en relación con el plazo de vigencia de un convenio de acuerdo con la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público:", "No podrá ser superior a cuatro años, salvo que normativamente se prevea un plazo superior.", "En ningún caso podrá ser superior a cuatro años.", "No podrá ser superior a 5 años, salvo que normativamente se prevea un plazo superior.", "No podrá ser superior a 3 años."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 20, "¿Cuál de las siguientes causas no se contempla en el artículo 51 de la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, como una causa de resolución de un convenio?", "El transcurso del plazo de vigencia del convenio sin haberse acordado la prórroga del mismo.", "El acuerdo unánime de todos los firmantes.", "El incumplimiento de las obligaciones y compromisos asumidos por parte de alguno de los firmantes.", "La renuncia verbal por parte de alguno de los firmantes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 21, "En el ámbito de la Administración General del Estado, la designación de suplente podrá efectuarse:", "En los reales decretos de estructura orgánica básica de los Departamentos Ministeriales o en los estatutos de sus Organismos públicos y Entidades vinculados o dependientes según corresponda.", "Únicamente en los estatutos de sus Organismos públicos y Entidades vinculados o dependientes según corresponda.", "En las resoluciones del Gobierno.", "Mediante una ley."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 22, "Según el artículo 6 de la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, los órganos administrativos podrán dirigir las actividades de sus órganos jerárquicamente dependientes mediante:", "Instrucciones y circulares", "Circulares", "Instrucciones y órdenes de servicio", "Reglamentos"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 23, "¿Cuándo se publicarán en el boletín oficial que corresponda las instrucciones y órdenes de servicio, de conformidad con el artículo 6 de la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público?", "Cuando una disposición específica así lo establezca, o se estime conveniente por razón de los destinatarios o de los efectos que puedan producirse, sin perjuicio de su difusión de acuerdo con lo previsto en la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno.", "Siempre.", "Nunca.", "Solo cuando una disposición específica así lo establezca."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 24, "Señale la respuesta correcta. Según el artículo 7 de la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, la Administración consultiva podrá articularse mediante órganos específicos dotados de autonomía orgánica y funcional con respecto a la Administración activa, o a través de los servicios de esta última que prestan asistencia jurídica. Señale la respuesta correcta en relación con dichos servicios:", "No pueden estar sujetos a dependencia jerárquica, ya sea orgánica o funcional.", "Pueden estar sujetos a dependencia jerárquica.", "Solo pueden estar sujetos a dependencia jerárquica funcional.", "Solo pueden estar sujetos a dependencia jerárquica orgánica."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 25, "Señale la respuesta correcta. El artículo 47.1 de la Ley 40/2015, de 1 de octubre de Régimen Jurídico del Sector Público, establece que:", "Son convenios los acuerdos con efectos jurídicos adoptados por las Administraciones Públicas, los organismos públicos y entidades de derecho público vinculados o dependientes o las Universidades públicas entre sí o con sujetos de derecho privado para un fin común.", "No tienen la consideración de convenios, los Protocolos Generales de Actuación o instrumentos similares que comporten meras declaraciones de intención de contenido general o que expresen la voluntad de las Administraciones y partes suscriptoras para actuar con un objetivo común, siempre que no supongan la formalización de compromisos jurídicos concretos y exigibles.", "Los convenios no podrán tener por objeto prestaciones propias de los contratos. En tal caso, su naturaleza y régimen jurídico se ajustará a lo previsto en la legislación de contratos del sector público.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 26, "¿Qué requisitos se requieren para la creación de un órgano administrativo de acuerdo con la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público?", "Delimitación de sus funciones y competencias.", "Determinación de forma de integración en la Administración Pública de que se trate y su dependencia jerárquica.", "Dotación de los créditos necesarios para su puesta en marcha y funcionamiento.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 27, "Según la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, en los casos previstos como motivos de abstención, podrá? promoverse recusación por los interesados:", "En cualquier momento de la tramitación del procedimiento.", "En cualquier momento anterior al trámite de audiencia.", "En cualquier momento anterior a la propuesta de resolución.", "En cualquier momento anterior al inicio del procedimiento"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 28, "Según la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, las Administraciones Públicas deberán respetar en su actuación y relaciones los siguientes principios (señale la respuesta incorrecta):", "Eficiencia en la asignación y utilización de los recursos públicos.", "Servicio efectivo a los ciudadanos.", "Participación, discrecionalidad y transparencia de la actuación administrativa.", "Responsabilidad por la gestión pública."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 29, "En relación con los órganos colegiados y de acuerdo con la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, no podrá ser objeto de deliberación o acuerdo ningún asunto que no figure incluido en el orden del día:", "Salvo que asista la mayoría de los miembros del órgano colegiado y sea declarada la urgencia del asunto por el voto favorable de todos los presentes.", "Salvo que asistan todos los miembros del órgano colegiado y sea declarada la urgencia del asunto por el voto favorable de todos ellos.", "Salvo que asista la mayoría de los miembros del órgano colegiado y sea declarada la urgencia del asunto por el voto favorable de la mayoría de los presentes.", "Salvo que sistan todos los miembros del órgano colegiado y sea declarada la urgencia del asunto por el voto favorable de la mayoría."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 30, "De acuerdo con el art. 9.5 de la ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, si la norma reguladora de un procedimiento prevé, como trámite preceptivo, la emisión de un dictamen o informe (señale la opción correcta):", "No podrá delegarse la competencia para resolver dicho procedimiento en ningún caso.", "Sólo podrá delegarse después de haberse emitido el informe o dictamen preceptivo si no fuera vinculante.", "No podrá delegarse la competencia para resolver dicho procedimiento una vez que se haya emitido el dictamen o informe preceptivo.", "Sólo podrá delegarse la competencia para resolver dicho procedimiento una vez se haya dictado el dictamen o informe preceptivo si fuera vinculante."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 31, "Indique la respuesta incorrecta en relación con el régimen previsto para las encomiendas de gestión regulades en el artículo 11 de la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público:", "Las encomiendas de gestión no podrán tener por objeto las prestaciones propias de los contratos regulados en la legislación de contratos del sector público.", "La encomienda de gestión no supone cesión de la titularidad de la competencia del órgano o de la entidad encomendante.", "La encomienda de gestión conlleva la cesión de los elementos esenciales del ejercicio de la competencia del órgano o de la entidad encomendante.", "Para su eficacia, el instrumento de formalización de la encomienda de gestión entre órganos administrativos pertenecientes a la misma Administración y su resolución deberán ser publicadas en el Diario oficial a que corresponda el órgano encomendante."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 32, "Señale la opción correcta en materia de órganos colegiados de las distintas administraciones públicas de acuerdo con la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público:", "El secretario tendrá siempre la condición de miembro del órgano colegiado.", "Corresponderá al presidente velar por la legalidad formal y material de las actuaciones del órgano colegiado.", "No podrá ser objeto de deliberación o acuerdo ningún asunto que no figure incluido en el orden del día, salvo que asistan todos los miembros del órgano colegiado y sea declarada la urgencia del asunto por el voto favorable de la mayoría.", "Para la válida constitución del órgano colegiado, a efectos de adopción de acuerdos, se requerirá únicamente la asistencia de la mitad más uno de sus miembros."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 33, "De acuerdo con el artículo 5 de la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, tendrán la consideración de órganos administrativos:", "Las unidades administrativas a las que se les atribuyan funciones que tengan efectos jurídicos frente a terceros, o cuya actuación tenga carácter preceptivo.", "Cualquier unidad administrativa independientemente de si tiene atribuidas funciones que tenga efectos jurídicos a terceros o cuya actuación tenga carácter preceptivo.", "Las unidades administrativas a las que se les atribuyan funciones que tengan efectos jurídicos frente a terceros y cuya actuación tenga carácter preceptivo, debiendo reunir ambas condiciones.", "Ninguna de las anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 34, "De conformidad con la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, señale la afirmación correcta en relación a los convenios:", "Son convenios los acuerdos con efectos jurídicos adoptados por las Administraciones Públicas, los organismos públicos y entidades de derecho público vinculados o dependientes o las Universidades públicas entre sí o con sujetos de derecho privado para un fin común.", "Es causa de resolución de los convenios el cumplimiento de las actuaciones que constituyen su objeto.", "Los convenios podrán tener por objeto prestaciones propias de los contratos.", "Toda la regulación sobre convenios será de aplicación a las encomiendas de gestión."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 35, "La Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, establece y regula lo siguiente:", "Las bases del régimen jurídico de las Administraciones Públicas.", "Los principios de la potestad sancionadora.", "La organización y funcionamiento del sector público institucional para el desarrollo de sus actividades.", "Todas las respuestas anteriores son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 36, "La Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, se aplica a los siguientes entes:", "Únicamente a la Administración General del Estado.", "Exclusivamente a las Administraciones de las Comunidades Autónomas.", "A la Administración General del Estado, a las Administraciones de las Comunidades Autónomas, a las Entidades que integran la Administración Local y al sector público institucional.", "Exclusivamente a la Administración General del Estado y a las Administraciones de las Comunidades Autónomas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 37, "Conforme al artículo 9 de la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, ¿cuál de las siguientes competencias podría ser objeto de delegación?", "Los asuntos que se refieran a relaciones la Jefatura del Estado o la Presidencia del Gobierno.", "La adopción de disposiciones de carácter general.", "La resolución de un recurso de alzada en el órgano administrativo que haya dictado el acto objeto de recurso.", "Ninguna de las respuestas anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 38, "Señale la opción correcta en relación con el régimen que prevé el artículo 8 de la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, en relación con la irrenunciabilidad de la competencia:", "La competencia es irrenunciable salvo los casos de delegación o avocación, cuando se efectúen en los términos previstos en esta u otras leyes.", "La competencia es irrenunciable sin excepción alguna.", "La competencia es irrenunciable salvo los casos de ausencia del titular, cuando se efectúe en los términos previstos en esta u otras leyes.", "La competencia es irrenunciable salvo los casos de vacante, cuando se efectúe en los términos previstos en esta u otras leyes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 39, "Indique la respuesta correcta en relación con lo dispuesto en la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, en relación a la delegación de firma:", "Ningún titular de órgano administrativo puede delegar su firma.", "Solo puede delegar su firma un director general.", "La delegación de firma no alterará la competencia del órgano delegante y para su validez no será necesaria su publicación.", "Un director general solo puede delegar su firma en el titular de la consejería a la que pertenezca."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 40, "¿Qué entes tienen la consideración de Administraciones Públicas de acuerdo con el artículo 2 de la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público?:", "Las entidades que integran la Administración Local.", "Las Administraciones de las Comunidades Autónomas.", "Los organismos públicos y las entidades de derecho público vinculados o dependientes de las Administraciones Públicas.", "Todas las anteriores son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 41, "Señale la opción correcta en relación con la suplencia de acuerdo con la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público:", "La suplencia implicará alteración de la competencia y para su validez no será necesaria su publicación.", "Los titulares de los órganos administrativos podrán ser suplidos temporalmente en los supuestos de vacante, ausencia o enfermedad, así como cuando se haya declarado su abstención o recusación.", "La suplencia implicará alteración de la competencia y para su validez será necesaria su publicación.", "Ninguna de las anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 42, "De acuerdo con la ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, la realización de una actividad de carácter técnico de la competencia de un órgano administrativo que, por no poseer los medios técnicos idóneos para su desempeño, haya sido encomendada a otro órgano de la misma administración entre cuyas competencias también estén estas actividades, se denomina:", "Avocación.", "Desconcentración.", "Delegación de competencias.", "Encomienda de gestión."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 43, "Conforme a la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, tienen la consideración de convenios, los acuerdos con efectos jurídicos siguientes:", "Los adoptados entre organismos públicos y entidades de derecho público o privado.", "Los Protocolos Generales de Actuación.", "Los adoptados por universidades públicas con sujetos de derecho privado para un fin común.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 44, "Según la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, cuál de las siguientes afirmaciones no es correcta:", "Las Administraciones Públicas sirven con objetividad los intereses generales.", "Las Administraciones Públicas deberán respetar en su actuación y relaciones el principio de participación, objetividad y transparencia de la actuación administrativa.", "Las Universidades Públicas tienen la consideración de Administración Pública.", "Corresponde a cada Administración Pública delimitar, en su respectivo ámbito competencial las unidades administrativas que configuran los órganos administrativos propios de las especialidades derivadas de su organización."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 45, "Señale la afirmación correcta respecto a los órganos consultivos regulados en la ley 40/2015, de 1 de octubre, de régimen jurídico del sector público:", "Estarán sujetos a la dependencia jerárquica, orgánica o funcional, de los órganos que hayan elaborado las disposiciones objeto de consulta.", "Podrán recibir las directrices e indicaciones de los órganos que hayan producido los actos objeto de consulta.", "Carecen de autonomía orgánica y funcional.", "Actuarán de forma colegiada."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 46, "De conformidad con lo dispuesto en el artículo 17 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, estarán exentos de la responsabilidad que, en su caso, pudiera derivarse de los acuerdos adoptados por los órganos colegiados:", "Los miembros del órgano que emitan su voto por medios electrónicos o por correo.", "Los miembros del órgano que voten a favor.", "Los miembros del cuerpo que voten en contra o que se abstengan.", "Ninguna de las anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 47, "De conformidad con lo dispuesto en el artículo 6 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, ¿cuál es la consecuencia del incumplimiento de instrucciones u órdenes de servicio?", "La nulidad jurídica plena de los actos emitidos por los órganos administrativos.", "La nulidad de los actos emitidos por los órganos administrativos.", "No afecta por sí mismo la validez de los actos emitidos por los órganos administrativos.", "La anulabilidad de los actos emitidos por los órganos administrativos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 48, "Según la Ley 40/2015, de 1 de octubre de Régimen Jurídico del Sector Público ¿cuándo exigirá la Administración, de oficio, de sus autoridades y demás personal a su servicio la responsabilidad patrimonial en que hubieran podido incurrir?", "Siempre.", "Cuando hubieran incurrido en ella por dolo o culpa o negligencia muy graves.", "Cuando hubieran incurrido en ella por dolo o culpa o negligencia graves.", "Cuando hubieran incurrido en ella no por culpa o negligencia graves, sino por dolo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 49, "Según la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, las Administraciones Públicas deberán respetar en su actuación y relaciones los siguientes principios (señale la respuesta incorrecta):", "Eficiencia en la asignación y utilización de los recursos públicos.", "Servicio efectivo a los ciudadanos.", "Participación y discrecionalidad.", "Responsabilidad por la gestión pública."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 50, "Según el principio de proporcionalidad de la potestad sancionadora que regula la Ley 40/2015, de 1 de octubre de Régimen Jurídico del Sector Público (señale la respuesta correcta):", "Será sancionable, como infracción continuada, la realización de una pluralidad de acciones u omisiones que infrinjan el mismo precepto administrativo, en ejecución de un plan preconcebido o aprovechando distinta ocasión.", "Será sancionable, como infracción continuada, la realización de una pluralidad de acciones u omisiones que infrinjan el mismo o semejantes preceptos administrativos, en ejecución de un plan preconcebido o aprovechando idéntica ocasión.", "No será sancionable, como infracción continuada, la realización de una pluralidad de acciones u omisiones que infrinjan el mismo precepto administrativo, en ejecución de un plan preconcebido o aprovechando idéntica ocasión.", "Será sancionable, como infracción intermitente, la realización de una pluralidad de acciones u omisiones que infrinjan el mismo o semejantes preceptos administrativos, en ejecución de un plan preconcebido o aprovechando distinta ocasión."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 51, "Según la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, señale la respuesta correcta respecto a los datos de carácter personal a los que se pudiera tener acceso en ejecución de la encomienda de gestión:", "La entidad u órgano encomendado no tiene la condición de responsable del fichero o tratamiento.", "La entidad u órgano encomendado tiene la condición de encargado del tratamiento.", "La entidad u órgano encomendante tiene la condición de encargado del tratamiento.", "La entidad u órgano encomendante debe dictar una resolución para determinar qué órgano será el responsable del trataminento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 52, "De acuerdo con la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, deberán remitirse electrónicamente al Tribunal de Cuentas u órgano externo de fiscalización de la Comunidad Autónoma, según corresponda los convenios cuyos compromisos económicos superen:", "Los 600.000 euros dentro de los tres meses siguientes a su suscripción.", "Los 600.000 euros dentro de los tres meses siguientes a contar desde la finalización de la vigencia del convenio.", "Los 300.000 euros dentro de los tres meses siguientes a su suscripción.", "Los 300.000 euros dentro de los tres meses siguientes a contar desde la finalización de la vigencia del convenio."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 53, "Según la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, en los casos previstos como motivos de abstención, los interesados podrán promover la recusación en los siguientes casos (señale la respuesta correcta):", "En cualquier momento de la tramitación del procedimiento.", "En cualquier momento anterior al trámite de audiencia.", "En cualquier momento anterior a la propuesta de resolución.", "En cualquier momento anterior al inicio del procedimiento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 54, "Según la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, con el fin de contribuir a la más correcta identificación de las conductas o a la más precisa determinación de las sanciones correspondientes, las disposiciones reglamentarias de desarrollo podrán introducir especificaciones o graduaciones al cuadro de las infracciones o sanciones establecidas legalmente:", "Que constituyan nuevas infracciones o sanciones, o alteren la naturaleza o límites de las que la ley contempla.", "Que no constituyan nuevas infracciones o sanciones, pero alteren la naturaleza o límites de las que la ley contempla.", "Que no constituyan nuevas infracciones o sanciones, ni alteren la naturaleza o límites de las que la ley contempla.", "Que constituyan nuevas infracciones o sanciones, pero no alteren la naturaleza o límites de las que la ley contempla."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 55, "Según la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, las leyes reguladoras de los distintos regímenes sancionadores (señale la respuesta correcta):", "Podrán prever los supuestos en que determinadas personas responderán del pago de las sanciones no pecuniarias impuestas a quienes de ellas dependan o estén vinculadas.", "Podrán prever los supuestos en que determinadas personas responderán del pago de las sanciones pecuniarias impuestas a quienes de ellas dependan o estén vinculadas.", "No podrán prever los supuestos en que determinadas personas responderán del pago de las sanciones no pecuniarias impuestas a quienes de ellas dependan o estén vinculadas.", "No podrán prever los supuestos en que determinadas personas responderán del pago de las sanciones pecuniarias impuestas a quienes de ellas dependan o estén vinculadas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 56, "Según la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, la graduación de la sanción considerará especialmente los siguientes criterios (señale la respuesta incorrecta):", "El grado de culpabilidad o la existencia de intencionalidad", "La continuidad o persistencia en la conducta infractora", "La naturaleza de los perjuicios causados", "La reincidencia, por comisión en el término de dos años de más de una infracción de la misma naturaleza cuando así haya sido declarado por resolución firme en vía administrativa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 57, "Según la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, la responsabilidad patrimonial del Estado por el funcionamiento de la Administración de Justicia se regirá por:", "La Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas.", "La propia Ley 40/2015.", "Las Leyes 39/2015 y 40/2015.", "La Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 58, "Según la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, la Administración correspondiente, cuando hubiere indemnizado a los lesionados, exigirá de sus autoridades y demás personal a su servicio la responsabilidad en que hubieran incurrido por dolo, o culpa o negligencia graves. ¿Cómo efectuará la Administración dicho requerimiento?", "De oficio, en vía penal.", "De oficio, en vía administrativa, previa instrucción del correspondiente procedimiento.", "De oficio en vía administrativa.", "De oficio, en vía penal, previa instrucción del correspondiente procedimiento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 59, "De conformidad a la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, señale la respuesta incorrecta respecto a las sedes electrónicas:", "El establecimiento de una sede electrónica conlleva la responsabilidad del titular respecto de la integridad, veracidad y actualización de la información y los servicios a los que pueda accederse a través de la misma", "Dispondrán de sistemas que permitan el establecimiento de comunicaciones seguras siempre que sean necesarias", "La publicación en las sedes electrónicas de informaciones, servicios y transacciones respetará los principios de accesibilidad y uso, de acuerdo con las normas establecidas al respecto, estándares abiertos y, en su caso, aquellos otros que sean de uso generalizado por los ciudadanos.", "La Administración General del Estado determinará las condiciones e instrumentos de creación de todas las sedes electrónicas, con sujeción a los principios de transparencia, publicidad, responsabilidad, calidad, seguridad, disponibilidad, accesibilidad, neutralidad e interoperabilidad."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 60, "Según la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, cuando los participantes en las comunicaciones a que hace referencia su artículo 44, pertenezcan a distintas Administraciones, ¿cómo se establecen las condiciones y garantías por las que se rigen?", "Las establece la Administración que inicie el envío de las comunicaciones.", "Se establecen mediante convenio suscrito entre aquéllas.", "Las establece la Administración jerárquicamente superior.", "Serán las que establece la Ley 40/2015."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 61, "Según la Ley 40/2015, de 1 de octubre de Régimen Jurídico del Sector Público, ¿cómo se almacenarán todos los documentos utilizados en las actuaciones administrativa?", "Por medios electrónicos o medios no electrónicos de forma discrecional.", "Siempre por medios electrónicos.", "Por medios electrónicos, salvo cuando no sea posible.", "En papel con copia digitalizada."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 62, "Señale la respuesta incorrecta respecto de los requisitos de validez y eficacia de los convenios según la ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público:", "Se requiere que los convenios que incluyan compromisos financieros deberán ser financieramente sostenibles.", "Las aportaciones financieras que se comprometan a realizar los firmantes pueden ser superiores a los gastos derivados de la ejecución del convenio.", "La suscripción de convenios debe cumplir con la legislación de estabilidad presupuestaria y sostenibilidad financiera.", "Los convenios se perfeccionan por la prestación del consentimiento de las partes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 63, "Según la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, la suscripción de convenios (señale la respuesta incorrecta):", "Deberá mejorar la eficiencia de la gestión pública", "Deberá facilitar la utilización conjunta de medios y servicios públicos", "Deberá contribuir a la realización de actividades de utilidad pública y privada", "Deberá cumplir con la legislación de estabilidad presupuestaria y sostenibilidad financiera"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 64, "Señale la respuesta correcta respecto de las normas del Capítulo VI del Título Preliminar de la Ley 40/2015, de 1 de octubre de Régimen Jurídico del Sector Público:", "Serán de aplicación a las encomiendas de gestión, pero no a los acuerdos de terminación convencional de los procedimientos administrativos.", "No serán de aplicación a las encomiendas de gestión ni a los acuerdos de terminación convencional de los procedimientos administrativos.", "Serán de aplicación a las encomiendas de gestión y los acuerdos de terminación convencional de los procedimientos administrativos.", "Serán de aplicación a los acuerdos de terminación convencional de los procedimientos administrativos, pero no a las encomiendas de gestión."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 65, "Según la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, sin perjuicio de las especialidades que la legislación autonómica pueda prever, será necesario que el convenio se acompañe de una memoria justificativa donde se analice lo siguiente (señale la respuesta incorrecta):", "El impacto económico.", "La necesidad y oportunidad.", "El carácter contractual de la actividad en cuestión.", "El cumplimiento de lo previsto en la citada Ley 40/2015."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 66, "El Título preliminar de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público se denomina:", "Título preliminar.", "De los entes del sector público.", "Disposiciones generales, principios de actuación y funcionamiento del sector público.", "Sector público institucional."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 67, "Según la Ley 40/2015, de 1 de octubre de Régimen Jurídico del Sector Público, señale la respuesta correcta en relación con la competencia para la resolución de los recursos administrativos:", "Podrá delegarse en órganos superiores.", "Podrá delegarse en órganos inferiores, en todo caso.", "En ningún caso podrá ser objeto de delegación.", "No podrá delegarse en los órganos administrativos que hayan dictado los actos objeto de recurso."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 68, "Según la Ley 40/2015, de 1 de octubre de Régimen Jurídico del Sector Público, señale la respuesta incorrecta en relación con los supuestos en los que no puede delegarse la competencia:", "Los asuntos que se refieran a relaciones con la Jefatura del Estado, la Presidencia del Gobierno de la Nación, las Cortes Generales, las Presidencias de los Consejos de Gobierno de las Comunidades Autónomas y las Asambleas Legislativas de la Comunidades Autónomas.", "La resolución de recursos en los órganos administrativos que hayan dictado los actos objeto de recurso.", "La adopción de disposiciones de carácter especial.", "Las materias en que así se determine por norma con rango de Ley."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 69, "De acuerdo con lo previsto en la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, la avocación se realizará mediante acuerdo motivado. ¿En qué momento se notificará a los interesados si los hubiere?", "Con anterioridad o simultáneamente a la resolución final que se dicte.", "Simultáneamente a la resolución final que se dicte.", "Con posterioridad a la resolución final que se dicte.", "Simultáneamente o con posterioridad a la resolución final que se dicte."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 70, "¿En cuántos capítulos se divide el Título preliminar de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público?", "En tres capítulos.", "En dos capítulos.", "En cinco capítulos.", "En seis capítulos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 71, "De acuerdo con el artículo 157 de la Ley 40/2015, de Régimen Jurídico del Sector Público, señale la respuesta correcta en relación con el directorio general de aplicaciones:", "Constarán tanto las aplicaciones disponibles de la Administración General del Estado como las disponibles en los directorios integrados de aplicaciones del resto de Administraciones.", "Constarán únicamente las aplicaciones disponibles de las Administraciones de las Comunidades Autónomas.", "Constarán las aplicaciones no disponibles de todas las Administraciones Públicas.", "Todas las respuestas son incorrectas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 72, "Según el artículo 93 de la Ley 40/2015 de 1 de octubre, de Régimen Jurídico del Sector Público, ¿qué regularán los estatutos de los organismos públicos estatales?", "Las funciones y competencias del organismo, con indicación de las potestades administrativas que pueda ostentar.", "El régimen relativo a recursos humanos, patrimonio, presupuesto y contratación.", "La facultad de participación en sociedades mercantiles cuando ello sea imprescindible para la consecución de los fines asignados.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 73, "Según el artículo 11 de la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, cuando la encomienda de gestión se realice entre órganos administrativos o entidades de derecho público pertenecientes a la misma administración deberá formalizarse en los términos que establezca su normativa propia y, en su defecto, por acuerdo expreso de los órganos o entidades de derecho público intervinientes. En este sentido (señale la respuesta correcta):", "Cada Administración podrá regular los requisitos necesarios para la validez de tales acuerdos que incluirán, al menos, expresa mención de la actividad o actividades a las que afecten, pero no la justificación de la necesidad de la encomienda ni el plazo de vigencia.", "Cada Administración podrá regular los requisitos necesarios para la validez de tales acuerdos que incluirán, al menos, expresa mención de la actividad o actividades a las que afecten, el plazo de vigencia y la naturaleza y alcance de la gestión encomendada.", "Cada Administración debe dictar una disposición reglamentaria que regule los requisitos necesarios para la validez de tales acuerdos que incluirán, únicamente, expresa mención de la actividad o actividades a las que afecten.", "Las administraciones no pueden regular los requisitos necesarios para la validez de tales acuerdos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 74, "De acuerdo con la Ley 40/2015, de 1 de octubre de Régimen Jurídico del Sector Público, señale la respuesta correcta en relación con la estructura de la Administración General del Estado:", "En la organización territorial de la Administración General del Estado son órganos directivos tanto los delegados del Gobierno en las Comunidades Autónomas, que tendrán rango de secretario de Estado, como los subdelegados del Gobierno en las provincias, los cuales tendrán nivel de subdirector general.", "En la Administración General del Estado en el exterior son órganos directivos los embajadores y representantes permanentes ante Organizaciones internacionales.", "En la organización central de la Administración General del Estado son órganos directivos los secretarios de Estado y subsecretarios, los secretarios generales técnicos, directores generales y los subdirectores generales.", "Corresponde a los órganos directivos establecer los planes de actuación de la organización, así como su desarrollo y ejecución."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A2", 9, 75, "De conformidad al artículo 16 de la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público señale la respuesta incorrecta en relación al secretario de un órgano colegiado:", "El secretario podrá ser un miembro del propio órgano.", "El secretario podrá ser una persona al servicio de la Administración Pública correspondiente.", "En caso de que el secretario no miembro sea suplido por un miembro del órgano colegiado, éste conservará todos sus derechos como tal.", "En caso de que el secretario no miembro sea suplido por un miembro del órgano colegiado, éste perderá todos sus derechos como tal."); 
